import api from "@ORGANIZATION/PROJECT-api";

/**
 * Validate error handling when deleting a non-existent category-tag assignment.
 *
 * This test ensures that the API returns a not found error when an administrator attempts
 * to delete a category-tag assignment record that does not exist (either an invalid or already deleted ID).
 *
 * 1. Attempt to delete a category-tag assignment using a random UUID (which is unlikely to exist).
 * 2. Confirm that a not found error (404) is raised, validating correct business rule enforcement and error response.
 *
 * Edge Cases:
 * - The selected UUID is not present in the database (never created assignment record).
 * - Attempting again with a previously deleted ID (if known) should also produce 404.
 *
 * Implementation focuses on using a random UUID for simplicity and maximum reliability of test outcome.
 */
export async function test_api_discussionBoard_admin_categoryTags_test_admin_delete_nonexistent_category_tag_assignment(
  connection: api.IConnection,
) {
  // 1. Attempt to delete a category-tag assignment with a random UUID (likely non-existent)
  const nonExistentCategoryTagId = typia.random<string & tags.Format<"uuid">>();

  // 2. Confirm that the API returns a not found error (404)
  await TestValidator.error("non-existent category-tag assignment deletion should fail")(
