import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * This test verifies the authorization enforcement for updating discussion board comments.
 *
 * Business context:
 * Only the original author of a comment (or privileged moderators/admins, not present in this case) should be able to update a comment. This test covers the scenario where a non-author attempts an update and should receive an authorization error.
 *
 * Workflow Steps:
 * 1. Register two discussion board members (memberAuthor, memberNonAuthor), each with distinct emails and display names.
 * 2. Log in as memberAuthor (if login is required by API session, otherwise member context is inferred during comment/post creation).
 * 3. memberAuthor creates a discussion post using the member posts endpoint.
 * 4. memberAuthor creates a comment on this post.
 * 5. Now, attempt to update this comment as memberNonAuthor, calling the update endpoint for the commentId created above with new body content.
 * 6. The API should reject this request with an authorization/permission error. The test should assert that an error is thrown (business logic, not TypeScript error) and NOT that the operation succeeds.
 * 7. Optionally, confirm that the comment body has not changed (if your framework permits querying the state).
 */
export async function test_api_discussionBoard_test_update_comment_as_non_author(
  connection: api.IConnection,
) {
  // 1. Register first member (author)
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorDisplay = RandomGenerator.name();
  const author = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: authorDisplay,
      email: authorEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
    },
  });
  typia.assert(author);

  // 2. Register second member (non-author)
  const nonAuthorEmail = typia.random<string & tags.Format<"email">>();
  const nonAuthorDisplay = RandomGenerator.name();
  const nonAuthor = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: nonAuthorDisplay,
      email: nonAuthorEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
    },
  });
  typia.assert(nonAuthor);

  // 3. Use author session context to create a post
  // (If per-member auth is required, switch session here)
  // (Assume context allows acting as this member now)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      parent_id: null,
    },
  });
  typia.assert(post);

  // 4. Author creates a comment on the post
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // 5. Switch to non-author session/context if required
  // (Assume per-member session as needed for RBAC)
  // Attempt to update the comment as the non-author member
  await TestValidator.error("Non-author should not be able to update comment")(
    async () => {
      await api.functional.discussionBoard.member.comments.update(connection, {
        commentId: comment.id,
        body: {
          body: RandomGenerator.paragraph()(),
        },
      });
    },
  );
}

