  const memberAEmail: string = typia.random<string & tags.Format<"email">>();
  const memberA: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberAEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);

  // 2. Register Member B
  const memberBEmail: string = typia.random<string & tags.Format<"email">>();
  const memberB: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberBEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. Member A creates a post
  // Simulate login as Member A if required by system; assume registration gives Member A's session.
  // (If login API is needed, would go here but is not present in the provided functions.)
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(2)(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Member A creates a comment
  const comment: IDiscussionBoardComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      body: RandomGenerator.content()(1)(),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. Member A upvotes the comment
  const vote: IDiscussionBoardCommentVote = await api.functional.discussionBoard.member.comments.commentVotes.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
