  if (createdReport.discussion_board_post_id) {
    const byPostId = await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { discussion_board_post_id: createdReport.discussion_board_post_id } }
    );
    typia.assert(byPostId);
    TestValidator.predicate("by post id contains")(byPostId.data.some(r => r.id === createdReport.id));
