  const wideFrom = new Date(new Date(createdReport.reported_at).getTime() - 1000 * 60 * 60 * 24).toISOString();
  const wideTo = new Date(new Date(createdReport.reported_at).getTime() + 1000 * 60 * 60 * 24).toISOString();
  const byDateRange = await api.functional.discussionBoard.moderator.contentReports.search(
    connection,
    { body: { date_from: wideFrom, date_to: wideTo } },
  );
  typia.assert(byDateRange);
  TestValidator.predicate("by date range contains")(byDateRange.data.some(r => r.id === createdReport.id));

  // 10. Pagination: use limit=1 and page=1, data length should be <= 1, pagination matches
  const paged = await api.functional.discussionBoard.moderator.contentReports.search(
    connection,
    { body: { pagination: { page: 1, limit: 1 } } },
