/**
 * Validate error handling for admin comment retrieval with invalid or not found UUID.
 *
 * This test ensures that when an administrator attempts to fetch details for a comment using either an invalid UUID format or a well-formed, non-existent comment ID,
 * the API responds appropriately with either a validation error or a not found error. It confirms that no sensitive details about comment existence are leaked
 * under error conditions, upholding security and privacy expectations. No comment data should ever be exposed for a missing or invalid ID.
 *
 * Steps:
 * 1. Attempt to retrieve a comment using an invalid (malformed) UUID string and assert that a validation error occurs without leaking resource data.
 * 2. Attempt to retrieve a comment using a syntactically valid but non-existent UUID and assert that a not found error occurs, also without leaking any comment data.
 *    The API must not reveal whether the specific ID exists or not in its error details.
 */
export async function test_api_discussionBoard_admin_comments_get_comment_not_found_error_invalid_id(
  connection: api.IConnection,
) {
  // 1. Attempt to get a comment using an improperly formatted UUID
  await TestValidator.error("invalid UUID rejects without leaking info")(
    async () => {
      // Intentionally pass a malformed string (not a UUID)
      return api.functional.discussionBoard.admin.comments.at(connection, {
        commentId: "not-a-uuid" as unknown as string & tags.Format<"uuid">,
      });
    },
  );

  // 2. Attempt to get a comment with a well-formed but non-existent UUID
  await TestValidator.error("non-existent UUID gives not found, leaks nothing")(
    async () => {
      // Generate a syntactically valid UUID that is extremely unlikely to exist
