 * and ensures correct ordering and pagination are handled.
 *
 * The workflow requires several setup steps to ensure the post exists and is populated with comments. 
 *
 * Step-by-step process:
 * 1. Register a member for posting and commenting
 * 2. Create a new post as this member
 * 3. Add several comments (3+) to that post via the member-comment API
 * 4. Retrieve the comments list via GET /discussionBoard/posts/{postId}/comments
 * 5. Validate the following:
 *    - The number of comments matches the created comments (unless some are soft-deleted)
 *    - Each comment is present in the expected order (should be recent-first or as required by the API contract)
 *    - No deleted comments are present in the result (if one is soft-deleted manually, it should not be returned in the list)
 *    - Pagination metadata (current, limit, total records/pages) appears justified by the data
 */
export async function test_api_discussionBoard_test_get_comments_for_post_success(
  connection: api.IConnection,
) {
