  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: passwordHash,
    },
  });
  typia.assert(member);

  // 2. Create a discussion board post as that member (assume authentication/routing by context)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(3),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 3. Add several comments (at least 3) to that post
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 4; ++i) {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        body: `[${i + 1}] ${RandomGenerator.paragraph()()}`,
