import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Validate the edge case for moderator searching members with zero matches.
 *
 * This test simulates a scenario where a moderator performs a member search
 * using criteria that should yield no results. It validates that:
 *
 * - The search returns an empty data array.
 * - Pagination metadata accurately reflects zero total records.
 *
 * This is critical to verify the system does not return false positives,
 * handles empty result sets gracefully, and returns correct pagination info for
 * reporting and audit tools.
 *
 * Step-by-step process:
 *
 * 1. Create a moderator using the admin API.
 * 2. Assume the API automatically authenticates the created moderator (since we
 *    lack a login endpoint).
 * 3. As the moderator, perform a member search with highly specific filters
 *    (randomized display_name + email + registered window in the far past) to
 *    guarantee zero matches.
 * 4. Assert that the search response contains:
 *
 *    - An empty data array.
 *    - Pagination object shows total records 0.
 *    - No errors.
 */
export async function test_api_discussionBoard_test_search_members_as_moderator_with_no_results(
  connection: api.IConnection,
) {
  // 1. Create a moderator (and assume connection is now for the moderator)
  const moderatorInput: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
    is_active: true,
  };
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderatorInput,
    });
  typia.assert(moderator);

  // 2. Prepare a search filter that cannot possibly match any members
  const impossibleFilter: IDiscussionBoardMember.IRequest = {
    display_name: RandomGenerator.alphaNumeric(32), // improbable random string
    email: `nonexistent.${RandomGenerator.alphaNumeric(12)}@nowhere.test`, // valid format, but guaranteed unused
    is_verified: false,
    status: "nonexistent_status_value_for_e2e_test", // assuming this is an unused status
    registered_after: "2000-01-01T00:00:00.000Z",
    registered_before: "2000-01-02T00:00:00.000Z",
    pagination: { page: 1, limit: 10 },
  };

  // 3. Perform the search as the moderator
  const result = await api.functional.discussionBoard.moderator.members.search(
    connection,
    { body: impossibleFilter },
  );
  typia.assert(result);

  // 4. Assert response expectations
  TestValidator.equals("empty result array")(result.data)([]);
  TestValidator.equals("zero records")(result.pagination.records)(0);
  TestValidator.equals("page is one")(result.pagination.current)(1);
  TestValidator.equals("pages is zero")(result.pagination.pages)(0);
}

