 * 5. Attempt retrieval of member A's notification with member B: expect forbidden or not found error.
 * 6. (If possible) try retrieval as guest or unregistered: expect error.
 * 7. (If possible) create a notification for admin or moderator, try access as member: expect forbidden/not found error.
 * 8. Attempt to access a notification using a random invalid notificationId: expect not found error.
 */
export async function test_api_discussionBoard_member_notifications_test_retrieve_member_notification_and_block_foreign_access(
  connection: api.IConnection,
) {
  // 1. Create member A
  const memberA = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(32),
    }
  });
  typia.assert(memberA);

  // 2. Create notification for member A (admin-level function)
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: memberA.id,
      type: "in-app",
      category: "test",
      message: "This is a test notification for member A.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    }
  });
  typia.assert(notification);
  TestValidator.equals("notification.member_id targets memberA")(notification.member_id)(memberA.id);

  // 3. Retrieve notification details as member A
  const notificationRecord = await api.functional.discussionBoard.member.notifications.at(connection, {
    notificationId: notification.id,
  });
  typia.assert(notificationRecord);
  TestValidator.equals("correct notification returned")(notificationRecord.id)(notification.id);
