import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validates that an authenticated member can cast both upvote and downvote on a discussion board post,
 * adheres to the one-vote-per-post-per-member (upsert) policy, and that the vote is properly associated to the post and member.
 *
 * Business context:
 * The discussion board voting system allows authenticated members to vote on posts (one per post). Voting twice should update the prior vote (upsert behavior).
 *
 * Test steps:
 * 1. Register a new discussion board member account (using valid display name, unique email, and a password hash).
 * 2. (Assume member is now authenticated / session established for the following steps.)
 * 3. Member creates a new post (title and body required).
 * 4. Member casts an upvote (upvote: true) on the created post. Verify response: upvote==true, member & post association correct, and correct types/formats.
 * 5. Member then casts a downvote (upvote: false) on the same post. Verify that the response has upvote==false and the returned vote record is for the same (post, member) as before. This proves upsert logic: casting a new vote changes the prior.
 * 6. Optionally, verify by casting the same upvote again: should update again and not error. (Demonstrate idempotent upsert behavior.)
 */
export async function test_api_discussionBoard_test_create_post_vote_as_member_success(connection: api.IConnection) {
  // 1. Register a new discussion board member
  const email: string = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. (Authentication assumed / session established; proceed as the member for all steps)

  // 3. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Upvote the post
  const upvote = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
    postId: post.id,
    body: { upvote: true } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(upvote);
  TestValidator.equals("upvote record points to post")(upvote.discussion_board_post_id)(post.id);
  TestValidator.equals("upvote record points to member")(upvote.discussion_board_member_id)(member.id);
  TestValidator.equals("vote is upvote")(upvote.upvote)(true);

  // 5. Downvote the same post and verify upsert/update effect
  const downvote = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
    postId: post.id,
    body: { upvote: false } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(downvote);
  TestValidator.equals("downvote record points to post")(downvote.discussion_board_post_id)(post.id);
  TestValidator.equals("downvote record points to member")(downvote.discussion_board_member_id)(member.id);
  TestValidator.equals("vote is downvote")(downvote.upvote)(false);
  TestValidator.equals("upsert: same vote id reused or replaced")(downvote.id)(upvote.id);

  // 6. Optionally, cast upvote again to reconfirm upsert/idempotent update
  const upvote2 = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
    postId: post.id,
    body: { upvote: true } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(upvote2);
  TestValidator.equals("upvote idempotent: record points to post")(upvote2.discussion_board_post_id)(post.id);
  TestValidator.equals("upvote idempotent: record points to member")(upvote2.discussion_board_member_id)(member.id);
  TestValidator.equals("upvote idempotent: upvote true")(upvote2.upvote)(true);
}

