import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validate RBAC: prevent non-admins from deleting discussion board post votes via admin endpoint.
 *
 * This test ensures a member cannot use the admin endpoint to delete a post vote they cast.
 * It follows this process:
 *
 * 1. Create a member post (as prerequisite).
 * 2. As the same member, cast a vote (e.g., upvote) on the post.
 * 3. Attempt to delete the vote using the admin endpoint, while authenticated as a non-admin member
 *    (simulate regular user trying to escalate privileges).
 * 4. Assert that a permission error (RBAC denial) is thrown; deletion does not occur.
 * 5. Verify the vote still exists (e.g., by attempting another operation that would fail if the vote was deleted).
 */
export async function test_api_discussionBoard_test_delete_vote_by_non_admin_forbidden(
  connection: api.IConnection,
) {
  // Step 1: Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // Step 2: Member casts a vote on the post
  const vote = await api.functional.discussionBoard.member.posts.postVotes.create(
    connection,
    {
      postId: post.id,
      body: { upvote: true } satisfies IDiscussionBoardPostVote.ICreate,
    },
  );
  typia.assert(vote);

  // Step 3: Without admin privileges, attempt to delete the vote via admin endpoint
  await TestValidator.error("Non-admin user cannot delete vote via admin endpoint")(
    async () => {
      await api.functional.discussionBoard.admin.posts.postVotes.erase(
        connection,
        {
          postId: post.id,
          postVoteId: vote.id,
        },
      );
    },
  );

  // Step 4: Verify the vote still exists by re-casting (should update, not create new)
  const vote2 = await api.functional.discussionBoard.member.posts.postVotes.create(
    connection,
    {
      postId: post.id,
      body: { upvote: false } satisfies IDiscussionBoardPostVote.ICreate,
    },
  );
  typia.assert(vote2);
  TestValidator.equals("Same vote record is updated (not deleted)")(vote2.id)(vote.id);
}

