import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering of discussion board category-tag assignments by category ID.
 *
 * This test sets up several categories and tags, assigns tags to categories, and verifies that the category-tag assignment search
 * endpoint's filter for a specific category ID works correctly. Additionally, it validates that pagination metadata and response
 * integrity are correct, and that error cases (invalid category IDs, lack of privilege) are handled as expected.
 *
 * Steps:
 * 1. Create multiple categories to ensure variety in assignment.
 * 2. Create multiple tags for assignments.
 * 3. Assign tags to categories with at least one assignment per category (ensuring some categories have multiple tags).
 * 4. Select one of the categories and search for assignments using the PATCH /discussionBoard/admin/categoryTags endpoint with
 *    a filter for the chosen category.
 * 5. Confirm that only assignments for that category are returned, with all fields matching expectations.
 * 6. Verify pagination fields (current, limit, records, pages) are present and logical.
 * 7. Attempt search with an invalid (non-existent) category ID and confirm no assignments are returned.
 * 8. (If possible given API) Attempt search with insufficient permissions and verify access is denied (skipped if not feasible).
 */
export async function test_api_discussionBoard_admin_categoryTags_test_filter_category_tag_assignments_by_category_id(connection: api.IConnection) {
  // 1. Create multiple categories
  const categories = await Promise.all(
    ArrayUtil.repeat(3)(() =>
      api.functional.discussionBoard.admin.categories.create(connection, {
        body: {
          name: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardCategory.ICreate,
      })
    )
  );
  categories.forEach(typia.assert);

  // 2. Create multiple tags
  const tags = await Promise.all(
    ArrayUtil.repeat(4)(() =>
      api.functional.discussionBoard.admin.tags.create(connection, {
        body: {
          label: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
          color: "#" + typia.random<string>().slice(2, 8),
        } satisfies IDiscussionBoardTag.ICreate,
      })
    )
  );
  tags.forEach(typia.assert);

  // 3. Assign tags to categories (at least one tag per category, some multiple)
  const assignments: IDiscussionBoardCategoryTag[] = [];
  for (const category of categories) {
    // assign 1-2 tags randomly to each category
    const numTags = typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<2>>();
    const chosenTags = RandomGenerator.sample(tags)(numTags);
    for (const tag of chosenTags) {
      const assignment = await api.functional.discussionBoard.admin.categoryTags.create(connection, {
        body: {
          discussion_board_category_id: category.id,
          discussion_board_tag_id: tag.id,
        } satisfies IDiscussionBoardCategoryTag.ICreate,
      });
      typia.assert(assignment);
      assignments.push(assignment);
    }
  }

  // 4. Select a category for filtering
  const filterCategory = RandomGenerator.pick(categories);

  // 5. Search assignments filtered by category ID
  const searchResult = await api.functional.discussionBoard.admin.categoryTags.search(connection, {
    body: {
      discussion_board_category_id: filterCategory.id,
    } satisfies IDiscussionBoardCategoryTag.IRequest,
  });
  typia.assert(searchResult);

  // 6. Verify only assignments for the selected category are returned
  TestValidator.equals("filtered all assignments are for selected category")(
    searchResult.data.every(x => x.discussion_board_category_id === filterCategory.id)
  )(true);
  // Also validate returned assignments are a subset of our created assignments
  const expectedIds = assignments.filter(a => a.discussion_board_category_id === filterCategory.id).map(a => a.id);
  const actualIds = searchResult.data.map(a => a.id);
  TestValidator.equals("all returned assignments are those assigned in test")(
    actualIds.sort()
  )(expectedIds.sort());

  // 7. Validate pagination fields
  typia.assert(searchResult.pagination);
  TestValidator.predicate("pagination limit >= data length")(searchResult.pagination.limit >= searchResult.data.length);
  TestValidator.predicate("pagination current page positive")(searchResult.pagination.current > 0);
  TestValidator.predicate("pagination records >= data length")(searchResult.pagination.records >= searchResult.data.length);
  TestValidator.predicate("pagination pages >= 1")(searchResult.pagination.pages >= 1);

  // 8. Search with invalid (random) category ID -- must yield no results
  const invalidCategoryId = typia.random<string & tags.Format<"uuid">>();
  const invalidResult = await api.functional.discussionBoard.admin.categoryTags.search(connection, {
    body: { discussion_board_category_id: invalidCategoryId } satisfies IDiscussionBoardCategoryTag.IRequest,
  });
  typia.assert(invalidResult);
  TestValidator.equals("search with invalid category returns empty data")(invalidResult.data.length)(0);
}

