 * Test advanced search for threaded comments by parent_id in moderator panel
 *
 * This test ensures the backend correctly filters and pages replies to a specific parent comment. To do so:
 * 1. Create a root/top-level comment (no parent).
 * 2. Create several direct replies to the root comment (these should have parent_id = root.id).
 * 3. Create additional replies to one of those child comments (testing deeper thread nesting; parent_id = child.id).
 * 4. Perform a moderator search using /discussionBoard/moderator/comments (PATCH) with filter parent_id = root.id. Verify returned comments are exactly the direct children of root (not deeper descendants).
 * 5. Then perform a search with parent_id = one of the child comment's id. Verify results are the next layer of direct descendants.
 * 6. Ensure paging (limit) and ordering works as expected.
 * 7. Check for empty results on parent_id that should have no direct replies.
 */
export async function test_api_discussionBoard_test_search_comments_by_parent_id_and_threading_moderation_panel(connection: api.IConnection) {
  // 1. Create a root/top-level comment
  const postId = typia.random<string & tags.Format<"uuid">>();
  const rootComment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {discussion_board_post_id: postId, body: "Root comment"} satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(rootComment);

  // 2. Create direct replies to root
  const childComments = await ArrayUtil.asyncRepeat(3)(async () => {
    const child = await api.functional.discussionBoard.member.comments.create(connection, {
      body: {discussion_board_post_id: postId, parent_id: rootComment.id, body: RandomGenerator.paragraph()()} satisfies IDiscussionBoardComment.ICreate
    });
    typia.assert(child);
    return child;
  });

  // 3. Create replies to one child (deepen the thread)
  const grandChildComments = await ArrayUtil.asyncRepeat(2)(async () => {
    const grandchild = await api.functional.discussionBoard.member.comments.create(connection, {
      body: {discussion_board_post_id: postId, parent_id: childComments[0].id, body: RandomGenerator.paragraph()()} satisfies IDiscussionBoardComment.ICreate
    });
    typia.assert(grandchild);
    return grandchild;
  });

  // 4. Moderator advanced search for direct replies to root
  const listDirect = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {parent_id: rootComment.id, discussion_board_post_id: postId, limit: 10, sort: "created_at_asc"} satisfies IDiscussionBoardComment.IRequest
  });
  typia.assert(listDirect);
  TestValidator.equals("should only return direct children of root")(listDirect.data.map((c) => c.id).sort())(childComments.map((c) => c.id).sort());
