 * 1. Register a member (for post authorship).
 * 2. Register Admin A (the original post editor).
 * 3. Register Admin B (who will attempt the unauthorized update).
 * 4. Member creates a new post.
 * 5. Admin A creates a post edit event (on that post).
 * 6. Attempt to update *that* post edit event as Admin B (who does not have moderator/override privileges).
 * 7. Confirm the update attempt is forbidden and returns an error.
 */
export async function test_api_discussionBoard_test_forbid_post_edit_update_by_non_editor_admin(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPassword,
    },
  });
  typia.assert(member);

  // 2. Register Admin A (original editor)
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAUsername = RandomGenerator.alphabets(8);
  const adminAPassword = RandomGenerator.alphaNumeric(10);
  const adminA = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminAUsername,
      email: adminAEmail,
      password_hash: adminAPassword,
      is_active: true,
    },
  });
  typia.assert(adminA);

  // 3. Register Admin B (not original editor, no moderator rights)
  const adminBEmail = typia.random<string & tags.Format<"email">>();
  const adminBUsername = RandomGenerator.alphabets(8);
  const adminBPassword = RandomGenerator.alphaNumeric(10);
  const adminB = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminBUsername,
      email: adminBEmail,
      password_hash: adminBPassword,
      is_active: true,
    },
  });
  typia.assert(adminB);

  // 4. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. Admin A creates a post edit event
  // (simulate as Admin A -- in real test, ensure connection represents Admin A)
  const editEvent = await api.functional.discussionBoard.admin.posts.postEdits.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id, // for test, use actual editor logic
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date().toISOString() as string & tags.Format<"date-time">,
      rationale: "Typo correction",
    },
  });
  typia.assert(editEvent);

  // 6. Attempt to update this edit event with Admin B -- expect forbidden
  await TestValidator.error("forbidden update by non-editor admin")(() =>
    api.functional.discussionBoard.admin.posts.postEdits.update(connection, {
      postId: post.id,
      postEditId: editEvent.id,
      body: {
        new_title: RandomGenerator.paragraph()(),
        new_body: RandomGenerator.content()()(),
        rationale: "Unauthorized edit attempt",
      },
    }),
  );
