  // 1. Create a moderation report
  const createInput: IDiscussionBoardContentReport.ICreate = {
    content_type: "post",
    category: "spam",
    reason: "Obvious spam post with repeated links.",
    discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
