 *    - No passwords or hashes are returned per DTO contract.
 *    - Business: Test is designed to catch regressions in role scoping or data masking for internal staff.
 */
export async function test_api_discussionBoard_moderator_moderators_at_test_get_moderator_details_as_moderator_on_other_moderators(connection: api.IConnection) {
  // Step 1: Create moderator A via admin endpoint
  const moderatorAUsername = `moderatorA_${RandomGenerator.alphaNumeric(8)}`;
  const moderatorAEmail = `moderatorA_${RandomGenerator.alphaNumeric(8)}@company.com`;
  const moderatorA: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: moderatorAUsername,
      password_hash: RandomGenerator.alphaNumeric(32),
      email: moderatorAEmail,
      is_active: true,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderatorA);

