  const moderatorBUsername = `moderatorB_${RandomGenerator.alphaNumeric(8)}`;
  const moderatorBEmail = `moderatorB_${RandomGenerator.alphaNumeric(8)}@company.com`;
  const moderatorB: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: moderatorBUsername,
      password_hash: RandomGenerator.alphaNumeric(32),
      email: moderatorBEmail,
