  // Step 3: moderatorA attempts to fetch details for moderatorB
  const output: IDiscussionBoardModerator = await api.functional.discussionBoard.moderator.moderators.at(connection, {
    moderatorId: moderatorB.id,
  });
  typia.assert(output);

  // Step 4: Validate business logic
