  TestValidator.equals("returned id matches moderatorB's id")(output.id)(moderatorB.id);
  TestValidator.equals("returned username matches moderatorB")(output.username)(moderatorB.username);
  TestValidator.equals("returned email matches moderatorB")(output.email)(moderatorB.email);
  TestValidator.equals("is_active matches moderatorB")(output.is_active)(moderatorB.is_active);
  TestValidator.equals("should not contain password_hash")(typeof (output as any).password_hash)("undefined");
  // Based on system policy, if access to other moderators is not allowed, an error should be raised and caught here instead (not testable in this API contract as error flow is not specified).
}

