import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a moderator can search for and retrieve soft-deleted discussion board tags.
 *
 * Business context:
 * Moderators often need to audit or potentially restore tags that have been soft-deleted (i.e., those marked by a non-null `deleted_at`). To support compliance and administration workflows, the system must let privileged users find such tags by toggling the deleted filter. This also ensures accidental deletions or recoveries are manageable.
 *
 * Step-by-step process:
 * 1. Create a new tag as an admin (required for later deletion and searching).
 * 2. Soft-delete the created tag via the admin endpoint.
 * 3. As a moderator, perform a tag search with `include_deleted` enabled, filtering for tags with the just-deleted label.
 * 4. Validate the results:
 *    - The soft-deleted tag appears in the paginated search result.
 *    - The returned tag's `deleted_at` field is set (i.e., not null).
 *    - Tag label and id match what was originally created & deleted.
 */
export async function test_api_discussionBoard_test_moderator_can_search_for_soft_deleted_tags(connection: api.IConnection) {
  // 1. Create a new tag (admin privilege).
  const label = RandomGenerator.alphabets(8);
  const createdTag = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label,
      description: RandomGenerator.paragraph()(),
      color: "#aabbcc"
    } satisfies IDiscussionBoardTag.ICreate
  });
  typia.assert(createdTag);

  // 2. Soft-delete the tag (admin privilege).
  await api.functional.discussionBoard.admin.tags.erase(connection, { tagId: createdTag.id });

  // 3. Moderator searches with include_deleted filter enabled.
  const searchOutput = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: {
      label,
      include_deleted: true
    } satisfies IDiscussionBoardTag.IRequest
  });
  typia.assert(searchOutput);

  // 4. Validate results.
  const found = searchOutput.data.find(tag => tag.id === createdTag.id);
  TestValidator.predicate("soft-deleted tag appears in search result")(!!found);
  if (found) {
    TestValidator.equals("tag has deleted_at set")(typeof found.deleted_at === "string" && !!found.deleted_at)(true);
    TestValidator.equals("tag label matches")(found.label)(label);
    TestValidator.equals("tag id matches")(found.id)(createdTag.id);
  }
}

