  // 1. Create a moderator (admin provides all required fields)
  const moderatorICreate: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphabets(8),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true
  };
  const moderator = await api.functional.discussionBoard.admin.moderators.create(connection, { body: moderatorICreate });
