/**
 * Validates uniqueness constraint by attempting to update a discussion board category's name to one that already exists.
 *
 * This test ensures that the API enforces unique category names at the update endpoint. The process involves:
 *
 * 1. Creating the first category with a unique name as an admin.
 * 2. Creating a second category with a different, also unique name as an admin.
 * 3. Attempting to update the second category's name to match the first category's name.
 * 4. Verifying that the update attempt fails due to a uniqueness constraint violation.
 *
 * Expected result: The update operation should fail and an error should be returned indicating that category names must be unique.
 */
export async function test_api_discussionBoard_test_update_category_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. Create the first category with a unique name
  const nameA = `UniqueNameA_${RandomGenerator.alphaNumeric(8)}`;
  const categoryA = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: nameA,
      description: "First unique category for duplicate-name update test",
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(categoryA);

  // 2. Create the second category with a distinct name
  const nameB = `UniqueNameB_${RandomGenerator.alphaNumeric(8)}`;
