    body: {
      name: nameB,
      description: "Second unique category for duplicate-name update test",
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(categoryB);

  // 3. Attempt to update the second category's name to the first category's name
  await TestValidator.error("should fail updating to a duplicate category name")(
    () =>
      api.functional.discussionBoard.admin.categories.update(connection, {
        categoryId: categoryB.id,
        body: {
          name: nameA,
        } satisfies IDiscussionBoardCategory.IUpdate,
