import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validates that an admin user can successfully retrieve a paginated list of all members when the board contains active members.
 *
 * ADMINISTRATIVE BUSINESS CONTEXT:
 * This test checks the key admin workflow of listing all discussion board members for monitoring and management purposes. It ensures:
 *  - The endpoint returns real, current member summaries, not just random or empty data.
 *  - Pagination metadata (current page, limit, total records) is correctly reported.
 *  - Each member summary contains required fields (id, display_name, email, status), and excludes sensitive data.
 *
 * STEP-BY-STEP TEST PROCESS:
 * 1. Register one or more members in the system via self-registration.
 * 2. As an "admin" context (assumed by test capability), send GET request to admin/members endpoint.
 * 3. Assert the server returns at least one member (matching what was registered).
 * 4. Validate every member entry contains correct id (uuid), display_name, email (format), and status fields.
 * 5. Ensure pagination metadata is present and reflects the total records (>=1).
 */
export async function test_api_discussionBoard_admin_members_index(
  connection: api.IConnection,
) {
  // 1. Register a member (ensures there is at least one member to retrieve)
  const newMember: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(16),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(newMember);

  // 2. Admin retrieves member list via admin endpoint
  const summary: IPageIDiscussionBoardMember.ISummary = await api.functional.discussionBoard.admin.members.index(
    connection,
  );
  typia.assert(summary);

  // 3. Assert at least one member is present (should include our newMember)
  TestValidator.predicate("at least one member record present")(
    summary.data.length >= 1,
  );

  // 4. Validate every member summary contains required safe fields
  summary.data.forEach((member) => {
    TestValidator.predicate("id is uuid")(
      typeof member.id === "string" && /^[0-9a-fA-F-]{36}$/.test(member.id),
    );
    TestValidator.predicate("display_name exists and is string")(
      typeof member.display_name === "string" && member.display_name.length > 0,
    );
    TestValidator.predicate("email is valid format")(
      typeof member.email === "string" && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(member.email),
    );
    TestValidator.predicate("status field exists and is string")(
      typeof member.status === "string" && member.status.length > 0,
    );
  });

  // 5. Pagination metadata asserts
  const pagination = summary.pagination;
  TestValidator.predicate("pagination current page >= 1")(
    pagination.current >= 1,
  );
  TestValidator.predicate("pagination limit >= 1")(
    pagination.limit >= 1,
  );
  TestValidator.predicate("pagination records >= number of data entries")(
    pagination.records >= summary.data.length,
  );
  TestValidator.predicate("pagination pages >= 1")(
    pagination.pages >= 1,
  );
}

