/**
 * Validate uniqueness constraint when updating a category-tag assignment.
 *
 * This test ensures that when attempting to update an existing category-tag link (assignment),
 * if the new (category, tag) pair already exists as another assignment, the system must reject the update.
 * No duplicate records are allowed on the category-tag junction table.
 *
 * Steps:
 * 1. Create two unique categories (category1, category2)
 * 2. Create two unique tags (tag1, tag2)
 * 3. Assign (category1, tag1) and (category2, tag2) via categoryTags.create
 * 4. Attempt to update assignment A (category1, tag1) to point to (category1, tag2) (should succeed)
 * 5. Attempt to update assignment A to become (category2, tag2), which already exists via assignment B
 *    (should fail due to uniqueness constraint)
 *
 * This validates admin-facing data integrity rules and proper error handling for duplicate assignment.
 */
export async function test_api_discussionBoard_admin_categoryTags_test_update_category_tag_assignment_to_duplicate_link(
  connection: api.IConnection,
) {
  // 1. Create two unique categories
  const category1 = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: `Category-${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
    }
  });
  typia.assert(category1);
  const category2 = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: `Category-${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
    }
  });
  typia.assert(category2);

  // 2. Create two unique tags
  const tag1 = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label: `Tag-${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      color: "#0077EE",
    }
  });
  typia.assert(tag1);
  const tag2 = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label: `Tag-${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
      color: "#00CC99",
    }
  });
  typia.assert(tag2);

  // 3. Assign (category1, tag1) and (category2, tag2)
  const assignmentA = await api.functional.discussionBoard.admin.categoryTags.create(connection, {
    body: {
      discussion_board_category_id: category1.id,
      discussion_board_tag_id: tag1.id,
    }
  });
  typia.assert(assignmentA);
  const assignmentB = await api.functional.discussionBoard.admin.categoryTags.create(connection, {
    body: {
      discussion_board_category_id: category2.id,
      discussion_board_tag_id: tag2.id,
    }
  });
  typia.assert(assignmentB);

  // 4. Update assignmentA: change tag to tag2 (no conflict)
  const updateResult = await api.functional.discussionBoard.admin.categoryTags.update(connection, {
    categoryTagId: assignmentA.id,
    body: {
      discussion_board_tag_id: tag2.id,
    }
  });
  typia.assert(updateResult);
  TestValidator.equals("assignmentA.category remains")(
    updateResult.discussion_board_category_id,
  )(category1.id);
  TestValidator.equals("assignmentA.tag is now tag2")(
    updateResult.discussion_board_tag_id
  )(tag2.id);

  // 5. Attempt to update assignmentA to (category2, tag2) (should fail: duplicate assignment)
  TestValidator.error("duplicate category-tag assignment should fail")(
    async () => {
      await api.functional.discussionBoard.admin.categoryTags.update(connection, {
        categoryTagId: assignmentA.id,
        body: {
          discussion_board_category_id: category2.id,
          discussion_board_tag_id: tag2.id,
        },
      });
    },
  );
}

