/**
 * Validate that the system prevents updating a member's email to one already in use by another member (uniqueness violation).
 *
 * This test covers an admin scenario: two unique member accounts are created. Then, as admin, an attempt is made to update the second member's email to match the first member's email. The update should fail due to the unique constraint on emails and a validation error should occur. This ensures backend uniqueness logic is enforced on member update.
 *
 * Test Steps:
 * 1. Register the first member (unique display name, unique email).
 * 2. Register the second member (unique display name, different unique email).
 * 3. As admin, attempt to update the second member's email to the first member's email (should fail).
 * 4. Validate that an error (uniqueness violation) is thrown and successful update is blocked.
 */
export async function test_api_discussionBoard_test_update_member_profile_with_duplicate_email(
  connection: api.IConnection,
) {
  // 1. Register the first member
  const uniqueEmail1 = typia.random<string & tags.Format<"email">>();
  const displayName1 = RandomGenerator.alphaNumeric(10);
  const member1 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: displayName1,
      email: uniqueEmail1,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  // 2. Register the second member
  let uniqueEmail2: string & tags.Format<"email">;
  do {
    uniqueEmail2 = typia.random<string & tags.Format<"email">>();
  } while (uniqueEmail2 === uniqueEmail1);
  const displayName2 = RandomGenerator.alphaNumeric(10);
  const member2 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: displayName2,
      email: uniqueEmail2,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // 3. Attempt to update second member's email to the duplicate (first member's email)
  await TestValidator.error("Should throw on duplicate email")(
    () => api.functional.discussionBoard.admin.members.update(connection, {
      memberId: member2.id,
      body: {
        email: uniqueEmail1,
      } satisfies IDiscussionBoardMember.IUpdate,
    })
  );
}

