 *  - The API returns the updated suspension object correctly
 *  - The change is visible on subsequent fetches, ensuring trace/auditability.
 *
 * Step-by-step process:
 * 1. Create a valid suspension record using POST (as an admin).
 * 2. Use the ID returned to update status (e.g., set 'revoked' or 'expired') and change 'ends_at' (either null or new date).
 * 3. Check the API response to confirm the changes are reflected in the updated object (specifically the new status and end time).
 */
export async function test_api_discussionBoard_admin_suspensions_test_update_suspension_status_and_end_time_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a valid suspension
  const now: string = new Date().toISOString();
  const suspensionToCreate: IDiscussionBoardSuspension.ICreate = {
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_admin_id: null,
    suspended_moderator_id: null,
    suspended_guest_id: null,
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_id: null,
    related_report_id: null,
    related_action_id: null,
    suspended_at: now,
    ends_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), // +1 day
    reason: "Test: original reason.",
    status: "active",
  };
  const created = await api.functional.discussionBoard.admin.suspensions.create(connection, { body: suspensionToCreate });
  typia.assert(created);

  // 2. Prepare update (set status to "revoked" and ends_at in the past)
  const updateBody: IDiscussionBoardSuspension.IUpdate = {
    status: "revoked",
    ends_at: new Date(Date.now() - 60 * 1000).toISOString() // 1 minute in the past
    // reason omitted for this test
  };
  const updated = await api.functional.discussionBoard.admin.suspensions.update(connection, {
    suspensionId: created.id,
    body: updateBody,
  });
  typia.assert(updated);

  // 3. Check that status and ends_at fields are updated
  TestValidator.equals("status changed")(updated.status)("revoked");
  TestValidator.equals("ends_at changed")(updated.ends_at)(updateBody.ends_at);
  TestValidator.equals("same id")(updated.id)(created.id);
}

