import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates that an authenticated member can retrieve a paginated list of all non-deleted discussion board comments.
 * 
 * This test ensures that only non-soft-deleted comments are returned in the member comment list, and that each returned record
 * contains the required fields for summary display, correct linkage to member and post, and complies with the business logic that deleted comments
 * must be filtered out.
 * 
 * Steps:
 * 1. Register a new member account and authenticate as that member.
 * 2. Create two distinct posts as this authenticated member.
 * 3. Under each post, create two comments (total four comments, all by the same member and spread across two posts).
 * 4. Soft-delete one comment on each post (thus, two comments out of four are soft deleted).
 * 5. Retrieve the paginated list of all comments as the authenticated member using the comment listing API.
 * 6. Confirm that only the two non-deleted comments appear in the result, and each contains all required summary fields, correct member reference, and correct post linkage.
 */
export async function test_api_discussionBoard_test_list_all_comments_as_member(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create two posts as the member
  const post1: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(6),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post1);

  const post2: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(6),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post2);

  // 3. Add two comments on each post
  const comment1_1: IDiscussionBoardComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post1.id,
    body: {
      discussion_board_post_id: post1.id,
      body: "Comment 1 on Post 1",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment1_1);

  const comment1_2: IDiscussionBoardComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post1.id,
    body: {
      discussion_board_post_id: post1.id,
      body: "Comment 2 on Post 1",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment1_2);

  const comment2_1: IDiscussionBoardComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post2.id,
    body: {
      discussion_board_post_id: post2.id,
      body: "Comment 1 on Post 2",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment2_1);

  const comment2_2: IDiscussionBoardComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post2.id,
    body: {
      discussion_board_post_id: post2.id,
      body: "Comment 2 on Post 2",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment2_2);

  // 4. Soft-delete one comment per post
  await api.functional.discussionBoard.member.comments.erase(connection, {
    commentId: comment1_1.id,
  });
  await api.functional.discussionBoard.member.comments.erase(connection, {
    commentId: comment2_1.id,
  });

  // 5. Retrieve all comments (should only retrieve two active comments)
  const result = await api.functional.discussionBoard.member.comments.index(connection);
  typia.assert(result);
  TestValidator.predicate("Only two active comments returned")(result.data.length === 2);

  // 6. Validate returned comments are correct and contain required fields
  const activeComments = [comment1_2, comment2_2];
  for (const returned of result.data) {
    TestValidator.predicate("Returned comment is one of active test comments")(
      activeComments.some((c) => c.id === returned.id),
    );

    // Required fields
    TestValidator.predicate("Returned comment has correct member id")(returned.discussion_board_member_id === member.id);
    TestValidator.predicate("Returned comment has correct post id")(activeComments.some((c) => c.discussion_board_post_id === returned.discussion_board_post_id));
    TestValidator.equals("Comment is not soft deleted")(returned.deleted_at)(null);
    TestValidator.predicate("Has non-empty body")(typeof returned.body === "string" && returned.body.length > 0);
    TestValidator.predicate("Returned comment has valid id")(typeof returned.id === "string" && returned.id.length > 0);
  }
}

