/**
 * Validate successful creation of an authentication token for a board actor.
 *
 * This test verifies the correct issuance of an authentication token for a valid actor in the discussion board system, such as an admin, moderator, member, or guest. It ensures all required fields are present and the token is correctly linked to the given actor.
 *
 * Steps:
 * 1. Prepare a valid set of input data reflecting a legitimate board actor (e.g., admin_id and actor_type 'admin').
 * 2. Call the API to create an authentication token with that data.
 * 3. Assert that the returned token object includes all expected fields, is linked to the correct actor, and respects security policy (no raw token exposure).
 * 4. Optionally, repeat for each supported actor_type variant to verify success across roles.
 */
export async function test_api_discussionBoard_test_create_auth_token_with_valid_data(
  connection: api.IConnection,
) {
  // Generate a sample admin ID and valid issued/expiry dates
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const issuedAt: string = new Date().toISOString();
  const expiresAt: string = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(); // expires in 1 day
  const tokenValue: string = typia.random<string>();

  // 1. Create an auth token for an admin actor
  const input: IDiscussionBoardAuthToken.ICreate = {
    admin_id: adminId,
    moderator_id: null,
    member_id: null,
    guest_id: null,
    actor_type: "admin",
    token: tokenValue,
    issued_at: issuedAt,
    expires_at: expiresAt,
  };

  const output: IDiscussionBoardAuthToken =
    await api.functional.discussionBoard.admin.authTokens.create(connection, {
      body: input,
    });
  typia.assert(output);
