  TestValidator.equals("actor type")(output.actor_type)("admin");
  TestValidator.equals("admin id")(output.admin_id)(adminId);
  TestValidator.equals("moderator id")(output.moderator_id)(null);
  TestValidator.equals("member id")(output.member_id)(null);
  TestValidator.equals("guest id")(output.guest_id)(null);
  TestValidator.equals("revoked status")(output.revoked)(false);
  TestValidator.predicate("issued_at ISO string")(typeof output.issued_at === "string");
  // Optionally check expires_at if not null
  if (output.expires_at !== undefined && output.expires_at !== null) {
    TestValidator.predicate("expires_at ISO string")(typeof output.expires_at === "string");
  }
}

