 * 1. Create an admin account (AdminA).
 * 2. As AdminA, create a notification addressed to AdminA (admin_id).
 * 3. Retrieve the notification via API as AdminA; validate all fields and schema.
 * 4. Create a second admin account (AdminB).
 * 5. As AdminB, attempt to access the notification for AdminA; verify forbidden or not found error.
 * 6. (Edge) Attempt to retrieve a notification targeted at a non-admin (e.g., member_id specified) as AdminA; verify forbidden/not found.
 * 7. Ensure all business rules and permission checks are strictly enforced.
 */
export async function test_api_discussionBoard_test_retrieve_admin_notification_by_id_with_permission_check(connection: api.IConnection) {
  // 1. Create AdminA
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAUsername = RandomGenerator.alphabets(10);
  const adminA = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminAUsername,
      email: adminAEmail,
      password_hash: RandomGenerator.alphaNumeric(12),
      is_active: true,
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminA);

  // 2. Create a notification for AdminA
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      admin_id: adminA.id,
      type: "in-app",
      category: "test",
      message: "Admin-only test message",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate
  });
  typia.assert(notification);
  TestValidator.equals("notification.admin_id matches AdminA")(notification.admin_id)(adminA.id);

  // 3. Retrieve notification as AdminA
  const fetched = await api.functional.discussionBoard.admin.notifications.at(connection, { notificationId: notification.id });
  typia.assert(fetched);
  TestValidator.equals("notification content matches")(fetched.id)(notification.id);
  TestValidator.equals("recipient matches")(fetched.admin_id)(adminA.id);
  TestValidator.equals("category")(fetched.category)("test");
  TestValidator.equals("type")(fetched.type)("in-app");
  TestValidator.equals("message")(fetched.message)("Admin-only test message");

  // 4. Create AdminB
  const adminBEmail = typia.random<string & tags.Format<"email">>();
