  await TestValidator.error("AdminB forbidden on AdminA notification")(
    async () => {
      await api.functional.discussionBoard.admin.notifications.at(connection, { notificationId: notification.id });
    }
  );

  // 6. (Edge) Notification for non-admin, and as AdminA cannot fetch
  const memberTargetedNotif = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      type: "in-app",
      category: "test",
      message: "Member-only notification",
      is_read: false,
      status: "pending",
