 *    f. Apply pagination (page, limit).
 * 3. For each, confirm:
 *    - Only expected reports are returned (fields match filter criteria).
 *    - Pagination metadata is correct (current page, limit, total records/pages).
 *    - No unauthorized data leaks from other reporters/categories, etc.
 *    - Requests with invalid filters (e.g., bogus ids, mismatched types) return appropriate error or empty result.
 *    - Only authorized admin role can access (simulate with bad/non-admin context and expect error).
 */
export async function test_api_discussionBoard_test_admin_advanced_search_of_content_reports_with_pagination(connection: api.IConnection) {
  // Step 1: Seed the database with diverse content reports
  // We'll create several reports with varying fields
  const createdReports: IDiscussionBoardContentReport[] = [];
  for (let i = 0; i < 5; i++) {
    const isPost = i % 2 === 0;
    const report = await api.functional.discussionBoard.member.contentReports.create(connection, {
      body: {
        discussion_board_post_id: isPost ? typia.random<string & tags.Format<"uuid">>() : undefined,
