        content_type: isPost ? "post" : "comment",
        category: ["spam", "policy", "offensive"][i % 3],
        reason: `Reason ${i}`,
      }
    });
    typia.assert(report);
    createdReports.push(report);
  }

  // Use data from one of the seeded reports to drive subsequent filter tests
  const sampleReport = createdReports[2];

  // Step 2a: Filter by reporter_member_id
  let res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
    body: { reporter_member_id: sampleReport.reporter_member_id }
  });
  typia.assert(res);
  for (const v of res.data)
    TestValidator.equals("reporter_member_id")(v.reporter_member_id)(sampleReport.reporter_member_id);

  // Step 2b: Filter by status and category (using the created report's status/category)
  res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
    body: { status: sampleReport.status, category: sampleReport.category }
  });
  typia.assert(res);
  for (const v of res.data) {
    TestValidator.equals("status")(v.status)(sampleReport.status);
    TestValidator.equals("category")(v.category)(sampleReport.category);
  }

  // Step 2c: Filter by post id and content_type
  if (sampleReport.discussion_board_post_id) {
    res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
      body: {
        discussion_board_post_id: sampleReport.discussion_board_post_id,
        content_type: "post"
      }
    });
    typia.assert(res);
    for (const v of res.data) {
      TestValidator.equals("post_id")(v.discussion_board_post_id)(sampleReport.discussion_board_post_id);
      TestValidator.equals("content_type")(v.content_type)("post");
    }
  }

  // Step 2d: Filter by comment id (if any report has comment)
  const commentReport = createdReports.find(r => r.discussion_board_comment_id);
  if (commentReport) {
    res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
      body: {
        discussion_board_comment_id: commentReport.discussion_board_comment_id,
        content_type: "comment"
      }
    });
    typia.assert(res);
    for (const v of res.data) {
      TestValidator.equals("comment_id")(v.discussion_board_comment_id)(commentReport.discussion_board_comment_id);
      TestValidator.equals("content_type")(v.content_type)("comment");
    }
  }

