  const to = createdReports[createdReports.length - 1].reported_at;
  res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
    body: { date_from: from, date_to: to }
  });
  typia.assert(res);
  for (const v of res.data)
    TestValidator.predicate("reported_at in range")(v.reported_at >= from && v.reported_at <= to);

  // Step 2f: Pagination
  res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
    body: { pagination: { page: 1, limit: 2 } }
  });
  typia.assert(res);
  TestValidator.equals("page current")(res.pagination.current)(1);
  TestValidator.equals("limit")(res.pagination.limit)(2);
  TestValidator.equals("data length")(res.data.length)(2);

  // Step 3: Invalid query (e.g. random uuid for post id)
  res = await api.functional.discussionBoard.admin.contentReports.search(connection, {
    body: { discussion_board_post_id: typia.random<string & tags.Format<"uuid">>() }
  });
  typia.assert(res);
  // Should be empty or 0 records if invalid id
  TestValidator.equals("invalid post id data len")(res.data.length)(0);
}

