  TestValidator.equals("enabled matches")(created.enabled)(createInput.enabled);
  TestValidator.equals("description matches")(created.description)(createInput.description);
  TestValidator.equals("logo_uri matches")(created.logo_uri)(createInput.logo_uri);

  // 2. Retrieve configuration by its ID
  const retrieved: IDiscussionBoardBoardSetting =
    await api.functional.discussionBoard.admin.boardSettings.at(
      connection,
