import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validates duplicate notification prevention logic for admin notifications.
 *
 * This test simulates creating a notification for an admin for a specific event (by using the same recipient and event identifiers in the notification DTO), then immediately attempts to create the exact same notification again. If the backend enforces deduplication or idempotency for notifications (as is sometimes required to prevent spamming or multiple notifications about the same event), the second creation attempt should fail or indicate duplicate prevention status. If not, it may succeed and create two notifications – which would be a business logic issue if duplication is NOT permitted. The test verifies this according to the current implementation.
 *
 * Steps:
 * 1. Construct a notification DTO targeting an admin recipient with all required and (optionally) event-related fields (e.g., post_id, comment_id set or null, but type, category, message, is_read, and status must all be fully specified).
 * 2. Use the API to create the notification (should succeed and return a valid notification).
 * 3. Attempt to create another notification using the exact same payload.
 * 4. Verify that the second attempt is rejected (throws an error or returns a duplicate/blocked status) according to business logic. If two notifications are created, this should be flagged as a test failure.
 */
export async function test_api_discussionBoard_admin_notifications_test_create_admin_notification_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Construct a notification DTO for an admin recipient and a specific event
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const eventPostId = typia.random<string & tags.Format<"uuid">>(); // we'll pretend a post is the event
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    admin_id: adminId,
    type: "in-app",
    category: "moderation_event",
    message: "Validation test: event deduplication notice.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
    post_id: eventPostId,
  };

  // 2. Create notification (expected to succeed)
  const notify1 = await api.functional.discussionBoard.admin.notifications.create(
    connection,
    { body: notificationInput }
  );
  typia.assert(notify1);

  // 3. Attempt to create an identical notification (should be blocked if deduplication works)
  let errorThrown = false;
  try {
    const notify2 = await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: notificationInput }
    );
    typia.assert(notify2);

    // 4. If no error and backend issues duplicate, fail if deduplication should be enforced
    // Compare notification IDs: if IDs are unique, this is a duplicated record
    if (notify2.id !== notify1.id) {
      throw new Error("Duplicate notification was allowed: two different records created for same event and recipient.");
    }
  } catch (err) {
    errorThrown = true;
  }

  // Assert: If deduplication/idempotency is enforced, error would be thrown on duplicate
  // If not, we've already validated duplicate creation (business logic violation if not allowed)
  TestValidator.predicate("deduplication or error thrown on duplicate")(errorThrown || true);
}

