 * 3. Search for tags with `include_deleted = true` and assert that both deleted and non-deleted tags are included in the results.
 * 4. Search with `include_deleted = false` (or omitted) and assert that only non-deleted tags appear in the results.
 * 5. Explicitly search for deleted tags using label match and `include_deleted = true`, and check that the soft-deleted tag is surfaced (and its deleted_at is non-null).
 *
 * This ensures proper functioning of tag admin inventory, and that the system state of
 * soft deletions is correctly reflected in search with appropriate filters.
 */
export async function test_api_discussionBoard_admin_tags_test_admin_can_include_soft_deleted_tags_in_results(
  connection: api.IConnection,
) {
  // 1. Create two unique tags
  const tagA = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label: RandomGenerator.alphabets(12),
      description: RandomGenerator.paragraph()(),
      color: "#3399ff",
    },
  });
