import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Validate admin search and filtering for discussion board members by email.
 *
 * This test ensures an admin can accurately search, filter, and paginate member accounts
 * using an exact and partial email filter. The scenario includes creating multiple member
 * accounts with diverse emails, then executing admin member search with both full and
 * partial email matches. Edge cases such as partial string matches, full matches, and
 * unrelated accounts are validated, along with pagination metadata.
 *
 * Steps:
 * 1. Register several members programmatically with distinct and partially-overlapping
 *    email addresses (some sharing partial strings, some unique)
 * 2. Execute search as admin with the PATCH /discussionBoard/admin/members endpoint,
 *    passing a full email (exact match) of one user as filter
 * 3. Confirm only the exact-matching member is returned; pagination reflects a single
 *    record
 * 4. Execute search as admin with a partial email substring (e.g., domain or common
 *    prefix) as filter
 * 5. Confirm all members with emails matching the substring are returned
 * 6. Validate pagination/meta data correctness for both cases (record count matches,
 *    current page, limit, pages)
 * 7. Negative case: Search with a non-existent email pattern, expect zero results and
 *    correct pagination meta data
 */
export async function test_api_discussionBoard_admin_members_test_search_members_with_email_filter_as_admin(
  connection: api.IConnection,
) {
  // 1. Register several members with varying emails
  const emails = [
    `alice${typia.random<number>()}@testmail.com`,
    `bob${typia.random<number>()}@example.com`,
    `charlie${typia.random<number>()}@testmail.com`,
    `dana${typia.random<number>()}@mailservice.com`,
    `eve${typia.random<number>()}@testmail.com`,
  ];
  const members = [];
  for (const email of emails) {
    const member = await api.functional.discussionBoard.members.create(
      connection,
      {
        body: {
          display_name: email.split("@")[0],
          email,
          password_hash: RandomGenerator.alphaNumeric(20),
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(member);
    members.push(member);
  }

  // 2. Search by exact email (should return a single user)
  const exactEmail = emails[0];
  const exactResult = await api.functional.discussionBoard.admin.members.search(
    connection,
    { body: { email: exactEmail } satisfies IDiscussionBoardMember.IRequest },
  );
  typia.assert(exactResult);
  TestValidator.equals("exact match record length")(exactResult.data.length)(1);
  TestValidator.equals("exact match email")(exactResult.data[0].email)(exactEmail);
  TestValidator.equals("pagination records")(exactResult.pagination.records)(1);

  // 3. Search by partial email (should return all *@testmail.com users)
  const partialEmail = "testmail.com";
  const partialResult = await api.functional.discussionBoard.admin.members.search(
    connection,
    { body: { email: partialEmail } satisfies IDiscussionBoardMember.IRequest },
  );
  typia.assert(partialResult);
  const expectedPartial = members.filter((m) => m.email.includes(partialEmail));
  TestValidator.equals("partial match count")(partialResult.data.length)(expectedPartial.length);
  for (const member of expectedPartial) {
    TestValidator.predicate(`member present in partial result`)(
      partialResult.data.some((r) => r.email === member.email),
    );
  }
  TestValidator.equals("pagination records")(partialResult.pagination.records)(expectedPartial.length);

  // 4. Pagination meta check: default limit is 100, current page 1
  TestValidator.equals("pagination current")(partialResult.pagination.current)(1);
  TestValidator.equals("pagination limit")(partialResult.pagination.limit)(100);

  // 5. Negative case: no matches
  const noneResult = await api.functional.discussionBoard.admin.members.search(
    connection,
    { body: { email: "nomatch" } satisfies IDiscussionBoardMember.IRequest },
  );
  typia.assert(noneResult);
  TestValidator.equals("no result count")(noneResult.data.length)(0);
  TestValidator.equals("pagination records")(noneResult.pagination.records)(0);
}

