import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostCategory";

/**
 * Validate the API behavior for fetching categories of a soft-deleted post.
 *
 * Business goal: Ensures that after soft-deleting a discussion board post, attempting to fetch its category assignments does not unexpectedly leak information—either the API should return an error (best practice) or an empty set if silent handling is desired.
 *
 * Steps:
 * 1. Register a new member using valid random data (as post owner).
 * 2. Create a post as the registered member.
 * 3. Soft-delete the created post as the same member.
 * 4. Attempt to fetch the category assignments of the now-deleted post via GET /discussionBoard/member/posts/{postId}/postCategories.
 * 5. Acceptable: The API returns an error indicating the resource is gone or forbidden, or returns an empty set of category assignments.
 * 6. Validate the response appropriately—if an error is thrown, check only that an error occurs; if a valid empty result is returned, ensure the returned categories are empty.
 *
 * This test guarantees business/data integrity by making sure deleted/hidden posts do not yield data via secondary or relational endpoints.
 */
export async function test_api_discussionBoard_test_get_categories_for_deleted_post_returns_error_or_empty(
  connection: api.IConnection,
) {
  // 1. Register member
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create post as member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(32),
      body: RandomGenerator.content()()(64),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Soft-delete the post
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post.id,
  });

  // 4. Attempt to fetch the post's categories
  // The endpoint may throw or return empty data for a soft-deleted post
  let errorOrEmpty = false;
  try {
    const categories = await api.functional.discussionBoard.member.posts.postCategories.index(connection, {
      postId: post.id,
    });
    // It succeeded: must return nothing for deleted posts
    typia.assert(categories);
    // Accept both: truly empty (undefined) or zero-element result
    if (
      categories === undefined ||
      (typeof categories === "object" && "length" in categories && categories.length === 0)
    ) {
      errorOrEmpty = true;
    } else {
      // Defensive: some implementation may return empty array directly
      TestValidator.equals("category assignments on deleted post")(categories)([]);
      errorOrEmpty = true;
    }
  } catch {
    // If we get any error, this is also acceptable for a deleted post
    errorOrEmpty = true;
  }
  TestValidator.predicate("API returns error or empty result for categories on deleted post")(errorOrEmpty);
}

