 *      and optionally update its rationale (reason field), simulating real moderation action.
 *   3. Validate that the resulting object reflects the changes, confirming audit compliance and
 *      workflow traceability.
 *
 * Step-by-step process:
 * 1. File a new content moderation report as a moderator (dependency setup)
 * 2. Update the report status, and also update the rationale (reason) to a new value
 * 3. Confirm that:
 *    - The updated fields match what was sent
 *    - Unmodified fields are preserved
 *    - Audit/reason data are present in the response and reflect changes
 */
export async function test_api_discussionBoard_moderator_contentReports_test_moderator_update_report_status_and_rationale(
  connection: api.IConnection,
) {
  // 1. Create a new moderation report (setup dependency)
  const report: IDiscussionBoardContentReport =
    await api.functional.discussionBoard.moderator.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
          discussion_board_comment_id: null,
          content_type: "post",
          category: "offensive",
          reason: "Initial offensive content report",
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(report);

  // 2. Update the report's status and reason as a moderator
