  const updated: IDiscussionBoardContentReport =
    await api.functional.discussionBoard.moderator.contentReports.update(
      connection,
      {
        contentReportId: report.id,
        body: {
          status: newStatus,
          reason: newReason,
        } satisfies IDiscussionBoardContentReport.IUpdate,
      },
    );
  typia.assert(updated);

  // 3. Validate auditing and correct change
  TestValidator.equals("preserves primary id")(updated.id)(report.id);
  TestValidator.equals("status updated")(updated.status)(newStatus);
  TestValidator.equals("reason updated")(updated.reason)(newReason);

  // Fields not updated must remain the same (category, content_type, links)
  TestValidator.equals("category preserved")(updated.category)(report.category);
  TestValidator.equals("post id preserved")(updated.discussion_board_post_id)(report.discussion_board_post_id);
  TestValidator.equals("comment id preserved")(updated.discussion_board_comment_id)(report.discussion_board_comment_id);
  TestValidator.equals("content type preserved")(updated.content_type)(report.content_type);
}

