import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate listing all moderator accounts as a logged-in moderator.
 *
 * Business context:
 * Moderators or admins need to retrieve the list of all moderator accounts for management, audit, or collaboration purposes. This list must include key information (id, username, email, is_active, created_at, updated_at, promoted_by_admin_id), but must not expose sensitive fields like password_hash. Only users with appropriate privileges ('admin' or 'moderator') are permitted to access this endpoint.
 *
 * Workflow:
 * 1. As an admin, create two moderator accounts using the admin creation API (ensuring both belong to the correct role and have unique identities).
 * 2. Simulate switching to 'moderator' role (e.g., via login or by using credentials of one created moderator if available) so that requests are made under moderator privilege.
 * 3. Call the moderator listing API.
 * 4. Validate the response contains both created moderators, that each moderator record includes only public fields, omitting any password hashes.
 * 5. Assert that the data corresponds to real moderator entities and links correctly to promotion admin when specified.
 * 6. Confirm response pagination fields make sense and are present.
 * 7. Negative: (not directly implementable since there are no auth management APIs given) – If available, attempt to call as a user without 'admin' or 'moderator' privileges and confirm proper permission error (not possible here due to missing APIs, so only positive test implemented).
 */
export async function test_api_discussionBoard_test_list_moderators_success_for_moderator(
  connection: api.IConnection,
) {
  // 1. As admin, create moderator #1
  const moderator1: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      password_hash: RandomGenerator.alphabets(32),
      email: typia.random<string & tags.Format<"email">>(),
      is_active: true,
      // promoted_by_admin_id left undefined (optional)
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator1);

  // 2. As admin, create moderator #2
  const moderator2: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      password_hash: RandomGenerator.alphabets(32),
      email: typia.random<string & tags.Format<"email">>(),
      is_active: true,
      promoted_by_admin_id: moderator1.promoted_by_admin_id ?? moderator1.id, // simulate promotion link
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator2);

  // 3. Simulate moderator context: (In real-world would re-authenticate; here continue as-is)

  // 4. Get the list of moderators as a moderator
  const moderatorsResp: IPageIDiscussionBoardModerator = await api.functional.discussionBoard.moderator.moderators.index(connection);
  typia.assert(moderatorsResp);

  // 5. Assert both moderators appear in the result data
  const moderatorIds = moderatorsResp.data.map((m) => m.id);
  TestValidator.predicate("moderator 1 present")(moderatorIds.includes(moderator1.id));
  TestValidator.predicate("moderator 2 present")(moderatorIds.includes(moderator2.id));

  // 6. Each moderator record: check public fields
  for (const mod of moderatorsResp.data) {
    // Public audit fields must exist
    TestValidator.predicate("has id")(typeof mod.id === "string" && !!mod.id);
    TestValidator.predicate("has username")(typeof mod.username === "string" && !!mod.username);
