 * 4. Assign multiple tags to the created category via category-tag assignments (admin action).
 * 5. As the member, search for category-tag assignments for this category using the member endpoint.
 * 6. Validate that all assignments for the given category are returned and no unrelated assignments are present.
 * 7. Paginate the results by limiting the number per page and validating pagination correctness.
 * 8. Also test that searching for an unassigned category ID returns an empty result set.
 */
export async function test_api_discussionBoard_test_search_category_tag_assignments_as_member_with_valid_category(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a category (admin privilege required)
  const category = await api.functional.discussionBoard.admin.categories.create(connection, {
