    TestValidator.equals("correct category")(a.discussion_board_category_id)(category.id)
  );
  // Only the created assignments are present
  const assignmentIds = assignments.map(a => a.id);
  allAssignmentsResult.data.forEach(a =>
    TestValidator.predicate("response contains expected assignment id")(assignmentIds.includes(a.id))
  );

