    TestValidator.equals("page 2 limit")(page2.pagination.limit)(2);
    TestValidator.equals("total records")(page2.pagination.records)(assignments.length);
    // Total pages asserted earlier
    // Validate non-overlapping ids between page 1 and page 2
    const ids1 = page1.data.map(a => a.id);
    const ids2 = page2.data.map(a => a.id);
    ids2.forEach(id => TestValidator.predicate("no overlap between page 1 and 2")(!ids1.includes(id)));
  }

  // 7. Searching with a random unassigned category returns an empty list
  const randomUnassignedCategoryId = typia.random<string & tags.Format<"uuid">>();
  const emptyResult = await api.functional.discussionBoard.member.categoryTags.search(connection, {
    body: {
      discussion_board_category_id: randomUnassignedCategoryId,
    } satisfies IDiscussionBoardCategoryTag.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result for unassigned category")(emptyResult.data.length)(0);
}

