import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator full comment listing, including soft-deleted comments.
 *
 * This test ensures a moderator can retrieve the full set of comments, including those that have been soft-deleted (for moderation/audit purposes). The test confirms deleted comments are present and flagged accordingly, verifying moderation workflows operate as intended.
 *
 * Business context:
 * Moderators require visibility into all community discussion comments, even those removed from public view by soft-deletion for compliance and dispute resolution. This is core for effective community management, enabling restoration or further review if needed.
 *
 * Test procedure:
 * 1. Create a regular member (for authorship)
 * 2. Register a moderator account
 * 3. As the member, create a new post
 * 4. Add several comments (e.g., 3) to the post as the member
 * 5. As the moderator, soft-delete one or more comments via moderator API
 * 6. As the moderator, retrieve the list of all comments
 * 7. Confirm the previously soft-deleted comments are included, and their `deleted_at` timestamp is present (non-null), while active comments have `deleted_at: null`
 * 8. Confirm all original comments and their properties (incl. content/post linkage) are present in the list for audit visibility
 */
export async function test_api_discussionBoard_test_list_all_comments_as_moderator_including_soft_deleted(connection: api.IConnection) {
  // 1. Create a regular member
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Register a moderator (simulate as if privileged by an admin)
  const moderator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(32),
      is_active: true,
    } satisfies IDiscussionBoardModerator.ICreate
  });
  typia.assert(moderator);

  // 3. As the member, create a new post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Add several comments as the member
  const comments = [];
  for (let i = 0; i < 3; ++i) {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        body: `Comment #${i + 1} - ${RandomGenerator.paragraph()()}`,
      } satisfies IDiscussionBoardComment.ICreate
    });
    typia.assert(comment);
    comments.push(comment);
  }

  // 5. Soft-delete one comment as the moderator (~simulate moderator priv)
  const commentToDelete = comments[1];
  await api.functional.discussionBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: commentToDelete.id
  });

  // 6. As the moderator, fetch all comments
  const page = await api.functional.discussionBoard.moderator.comments.index(connection);
  typia.assert(page);

  // 7. Confirm soft-deleted and active comments
  let foundSoftDeleted = false, foundActive = false;
  for (const createdComment of comments) {
    const found = page.data.find(c => c.id === createdComment.id);
    TestValidator.predicate("Comment must exist in moderator's list")(!!found);
    if (createdComment.id === commentToDelete.id) {
      TestValidator.predicate("Soft-deleted comment must have deleted_at != null")(!!found && found.deleted_at !== null && found.deleted_at !== undefined);
      foundSoftDeleted = true;
    } else {
      TestValidator.equals("Active comment deleted_at is null")(found?.deleted_at)(null);
      foundActive = true;
    }
  }
  TestValidator.predicate("Found at least one soft-deleted comment")(foundSoftDeleted);
  TestValidator.predicate("Found at least one active comment")(foundActive);
}

