import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that a moderator user can retrieve a paginated list of all members including correct summary details, and that no sensitive data (like password hashes) are present.
 *
 * This test covers the typical moderator workflow for member management oversight in the discussion board.
 *
 * Steps:
 * 1. Register multiple distinct member accounts for listing, ensuring each has a unique display_name and email (the creation endpoint requires hashed passwords).
 * 2. Register a moderator account (simulate admin promotion since direct login is out of scope here; just verify moderator creation so listing is possible).
 * 3. (Assume connection is granted appropriate moderator credentials after creation.)
 * 4. Use the moderator-authenticated connection to call the GET /discussionBoard/moderator/members endpoint.
 * 5. Assert that the returned list contains the newly registered members with fields matching IDiscussionBoardMember.ISummary, and includes valid pagination metadata.
 * 6. Check that password or other sensitive fields are NOT present in any returned summary entry.
 */
export async function test_api_discussionBoard_test_list_all_members_as_moderator_success(
  connection: api.IConnection,
) {
  // 1. Register several members for listing
  const memberInputs = ArrayUtil.repeat(3)(() => ({
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  } satisfies IDiscussionBoardMember.ICreate));
  const members = [] as IDiscussionBoardMember[];
  for (const input of memberInputs) {
    const member = await api.functional.discussionBoard.members.create(connection, { body: input });
    typia.assert(member);
    members.push(member);
  }

  // 2. Register a moderator account (simulate admin context)
  const moderatorInput = {
    username: RandomGenerator.alphabets(8),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
  } satisfies IDiscussionBoardModerator.ICreate;
  const moderator = await api.functional.discussionBoard.admin.moderators.create(connection, { body: moderatorInput });
  typia.assert(moderator);

  // NOTE: In a real environment, an authenticated session as this moderator would be required now.
  // For this E2E test context, assume moderator permissions are automatically applied to 'connection' after creation.

  // 3. Request member list as moderator
  const output = await api.functional.discussionBoard.moderator.members.index(connection);
  typia.assert(output);

  // 4. Assert pagination fields are present
  TestValidator.predicate("pagination fields present")(!!output.pagination && typeof output.pagination.current === 'number' && typeof output.pagination.limit === 'number');

  // 5. Ensure returned data are ISummary and contain registered members
  for (const summary of output.data) {
    typia.assert<typeof summary>(summary);
    // ISummary includes id, display_name, email, status - validate presence and data types
    TestValidator.predicate("no sensitive fields in summary")(
      !('password_hash' in summary)
    );
  }

  // 6. Verify at least the first three created members appear in the result set (by email or display_name)
  for (const member of members) {
    const found = output.data.find(s => s.email === member.email && s.display_name === member.display_name);
    TestValidator.predicate("created member present in output")(!!found);
  }
}

