  TestValidator.predicate("deleted_at match allowed")(resp_deleted.data.some(x => x.deleted_at !== null || x.deleted_at === null));

  // 5. created_from/created_to: restrict to narrow time range (using created_at of one category)
  const createdSample = categories[2].created_at;
  const resp_by_date = await api.functional.discussionBoard.admin.categories.search(connection, {
