import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate guest notification detail retrieval and access control.
 *
 * This test verifies that a guest user may retrieve only those notifications intended for their session, while being forbidden or denied access to notifications belonging to admins, members, or other guests.
 *
 * Steps:
 * 1. Register a unique guest session (with a random session token, IP, and timestamp).
 * 2. Deliver a notification via the admin notifications endpoint, addressed to this guest's guest_id (category/type/message randomized; other recipient fields null).
 * 3. Retrieve the notification details via the guest/notifications/:notificationId endpoint; verify all data mirrors what was delivered and belongs to this guest.
 * 4. Deliver a notification to a fake or unrelated guest_id, and another to a member_id and to an admin_id.
 * 5. Attempt to fetch these unrelated notifications as the original guest session; assert each access is forbidden or not found (i.e., not readable).
 * 6. Attempt to fetch using a non-existent notificationId (random UUID); expect not found.
 * 7. Simulate an invalid/expired session token scenario—(since the API exposes no session param, this may be conceptual unless a session mechanism can be represented).
 */
export async function test_api_discussionBoard_guest_notifications_test_retrieve_guest_notification_details_with_scope_and_privacy(
  connection: api.IConnection,
) {
  // 1. Register a guest session
  const guest_create_body: IDiscussionBoardGuest.ICreate = {
    guest_ip: RandomGenerator.alphaNumeric(12),
    session_token: RandomGenerator.alphaNumeric(32),
    entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const guest = await api.functional.discussionBoard.guests.create(connection, { body: guest_create_body });
  typia.assert(guest);

  // 2. Deliver notification to this guest
  const notification_create_body: IDiscussionBoardNotification.ICreate = {
    admin_id: null,
    moderator_id: null,
    member_id: null,
    guest_id: guest.id,
    post_id: null,
    comment_id: null,
    moderation_action_id: null,
    type: "in-app",
    category: "reply",
    message: RandomGenerator.paragraph()(),
    is_read: false,
    status: "sent",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    delivered_at: null,
    read_at: null,
    error_message: null,
  };
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, { body: notification_create_body });
  typia.assert(notification);

  // 3. Retrieve notification detail as this guest
  const detail = await api.functional.discussionBoard.guest.notifications.at(connection, {
    notificationId: notification.id,
  });
  typia.assert(detail);
  TestValidator.equals("notification data matches")(detail)(notification);
  TestValidator.equals("belongs to guest")(detail.guest_id)(guest.id);

  // 4. Deliver unrelated notifications (other guest, member, admin)
  const other_guest_id = typia.random<string & tags.Format<"uuid">>();
  const unrelated_guest_notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: { ...notification_create_body, guest_id: other_guest_id, message: "Unrelated guest notification" },
  });
  typia.assert(unrelated_guest_notification);

  const other_member_id = typia.random<string & tags.Format<"uuid">>();
  const member_notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: { ...notification_create_body, guest_id: null, member_id: other_member_id, message: "Member notification" },
  });
  typia.assert(member_notification);

  const other_admin_id = typia.random<string & tags.Format<"uuid">>();
  const admin_notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: { ...notification_create_body, guest_id: null, member_id: null, admin_id: other_admin_id, message: "Admin notification" },
  });
  typia.assert(admin_notification);

  // 5. Attempt to fetch unrelated notifications as this guest (should be forbidden or not found)
  await TestValidator.error("unrelated guest notification should not be visible")(() =>
    api.functional.discussionBoard.guest.notifications.at(connection, { notificationId: unrelated_guest_notification.id }),
  );
  await TestValidator.error("member notification should not be visible")(() =>
    api.functional.discussionBoard.guest.notifications.at(connection, { notificationId: member_notification.id }),
  );
  await TestValidator.error("admin notification should not be visible")(() =>
    api.functional.discussionBoard.guest.notifications.at(connection, { notificationId: admin_notification.id }),
  );

  // 6. Non-existent notificationId (random)
  await TestValidator.error("random notificationId returns not found")(() =>
    api.functional.discussionBoard.guest.notifications.at(connection, {
      notificationId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
  // 7. Simulated expired/invalid session scenario — if applicable (no session mechanism available directly)
  // Note: If session_token is enforced by headers/cookies and can be controlled, simulate its absence/malformation
  // Otherwise, this is only conceptual, as the provided API does not expose a direct session mechanism for guests.
}

