/**
 * Validate creation of a new discussion board admin account via POST /discussionBoard/admin/admins.
 *
 * Business & Security Context:
 * - Only existing admin users can create a new admin account
 * - Strong uniqueness is enforced for username and email
 * - All mandatory fields in response must be validated (id, username, email, is_active, created_at, updated_at)
 * - Sensitive password hash is never returned
 *
 * Test Workflow:
 * 1. [Assumption] The connection is authenticated as an admin (since prerequisites do not define authentication setup and no API for authenticating admin is provided).
 * 2. Attempt to create a new admin with random, unique username and email, strong password hash, and is_active=true
 * 3. Assert the response contains all required fields except password_hash, and verify response values match request (except generated fields like id/timestamps)
 * 4. Assert that repeated creation with the same username or email results in a runtime error (due to uniqueness constraints)
 * 5. [Negative Case—role] Attempting creation with a non-admin connection would result in denial (cannot test, as no such endpoint or flow is provided)
 *
 * Technical/Business Limitations & Omissions:
 * - No direct API/materials for admin authentication and role demotion are given—assume test runs with privileged credentials
 * - Password must be hash, but since plain/hash eligibility is not checked by server, use random string (min 6 chars)
 * - Only properties provided in IDiscussionBoardAdmin.ICreate and the output DTO can be validated
 * - Deletion/cleanup is omitted—no API provided
 *
 * Steps:
 * 1. Call admins.create with random unique username, unique email, random password hash (>=6 char), and is_active true
 * 2. Assert required output fields exist and validate their types/formats
 * 3. Call admins.create again with same username/email and assert error (uniqueness)
 */
export async function test_api_discussionBoard_test_create_admin_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Generate unique test data (affirming format requirements)
  const username = `admin_${RandomGenerator.alphaNumeric(8)}`;
  const email = `${RandomGenerator.alphaNumeric(8)}@business.test`;
  const password_hash = RandomGenerator.alphaNumeric(16); // >=6 chars
  const is_active = true;

  // 2. Create a new admin account
  const admin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username,
      email,
      password_hash,
      is_active,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(admin);
  // 3. Validate all expected fields
  TestValidator.equals("username matches")(admin.username)(username);
  TestValidator.equals("email matches")(admin.email)(email);
  TestValidator.equals("active state matches")(admin.is_active)(is_active);
  // ID must be a valid UUID
  TestValidator.predicate("id is uuid")(
    typeof admin.id === "string" && admin.id.length > 0,
  );
  // created_at/updated_at must be present and ISO string
  TestValidator.predicate("created_at present")(typeof admin.created_at === "string" && admin.created_at.length > 0);
  TestValidator.predicate("updated_at present")(typeof admin.updated_at === "string" && admin.updated_at.length > 0);
  // password_hash must NOT be in response
  if ((admin as any).password_hash !== undefined) { throw new Error("password_hash must not be returned in output"); }

  // 4. Attempt to create duplicate admin using same username/email (should throw)
  await TestValidator.error("duplicate admin creation should fail")(
    async () => {
      await api.functional.discussionBoard.admin.admins.create(connection, {
        body: {
          username,
          email,
          password_hash,
          is_active,
        } satisfies IDiscussionBoardAdmin.ICreate,
      });
    }
  );
}

