 * Validate that updating a comment edit with an invalid edit ID returns an error and does not alter valid records.
 *
 * Steps:
 * 1. Create a real comment as a discussion board member, getting its ID.
 * 2. Create a comment edit for that comment, and capture its edit ID.
 * 3. Attempt to update a comment edit using the correct comment ID but with a bogus edit ID.
 *    The bogus edit ID must NOT match the previously created valid edit record.
 *    The update body can be any valid IUpdate payload.
 * 4. Expect an error (e.g., not found). Validate with TestValidator.error.
 * 5. Optionally, fetch/verify the real edit record unchanged (if such an API exists, but skip if not implementable).
 */
export async function test_api_discussionBoard_test_update_comment_edit_with_invalid_edit_id_returns_error(
  connection: api.IConnection,
) {
  // 1. Create a comment for a random post
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      body: "Initial comment body",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 2. Create an initial edit to that comment
