    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      discussion_board_member_id: comment.discussion_board_member_id,
      new_body: "First edit body",
      edited_at: new Date().toISOString(),
      rationale: "Initial rationale",
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(commentEdit);

  // 3. Try to update the comment edit, but with a bogus edit ID
  const bogusEditId = typia.random<string & tags.Format<"uuid">>();
  // Make sure the bogus ID is NOT the valid one
  TestValidator.notEquals("Bogus edit ID is unique")(bogusEditId)(commentEdit.id);

  await TestValidator.error("Update with invalid edit ID should fail")(
    () =>
      api.functional.discussionBoard.member.comments.commentEdits.update(
        connection,
        {
          commentId: comment.id,
          commentEditId: bogusEditId,
          body: {
            rationale: "Some update attempt",
          } satisfies IDiscussionBoardCommentEdit.IUpdate,
        },
      ),
  );
}

