import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test updating an existing administrator's profile with new data (username, email, password_hash, is_active) as another admin.
 *
 * This test ensures:
 * - Admin profile updates work for username, email, password_hash (hash only, never plaintext), and is_active fields
 * - Persistence: Changes are reflected in the admin record after update
 * - Username/email uniqueness is enforced—cannot update to conflicting credentials
 * - Password is always sent/updated as a hash, never plain text, and never exposed in any response
 * - The update is properly audit-logged (timestamps updated)
 * - No sensitive fields (such as password_hash) leak in read responses after update
 *
 * Steps:
 * 1. Create an admin to serve as the update target (dependency)
 * 2. Update all permitted user fields (username, email, is_active, password_hash)
 * 3. Check if the updated fields are reflected in the API response
 * 4. Fetch the admin again to ensure persistence
 * 5. Ensure password_hash is never returned in the admin info
 * 6. Check updated_at timestamp is later than created_at
 * 7. Attempt an update with a duplicate username and assert an error is thrown
 * 8. Attempt an update with a duplicate email and assert an error is thrown
 */
export async function test_api_discussionBoard_admin_admins_test_update_admin_information_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an admin to update
  const originalAdmin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(20),
      is_active: true,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(originalAdmin);

  // 1b. Create another admin to test duplicate-username/email prevention
  const existingAdmin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(20),
      is_active: true,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(existingAdmin);

  // 2. Prepare new update fields for the original admin
  const newUsername = RandomGenerator.alphabets(10);
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newPasswordHash = RandomGenerator.alphaNumeric(32);
  const newIsActive = false;

  // Fetch old timestamps to check audit logging
  const oldCreatedAt = originalAdmin.created_at;
  const oldUpdatedAt = originalAdmin.updated_at;

  // 3. Update the admin
  const updatedAdmin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admin.admins.update(connection, {
    adminId: originalAdmin.id,
    body: {
      username: newUsername,
      email: newEmail,
      password_hash: newPasswordHash,
      is_active: newIsActive,
    } satisfies IDiscussionBoardAdmin.IUpdate,
  });
  typia.assert(updatedAdmin);

  // 4. Confirm changes are present in response
  TestValidator.equals("username updated")(updatedAdmin.username)(newUsername);
  TestValidator.equals("email updated")(updatedAdmin.email)(newEmail);
  TestValidator.equals("active status updated")(updatedAdmin.is_active)(newIsActive);
  // 5. Confirm that password_hash is never exposed
  if ((updatedAdmin as any).password_hash !== undefined)
    throw new Error("password_hash should not be exposed in the GET/PUT API response");
  // 6. Confirm timestamps are correctly updated
  TestValidator.predicate("timestamp updated")(new Date(updatedAdmin.updated_at).getTime() > new Date(oldUpdatedAt).getTime());
  TestValidator.equals("created_at remains fixed")(updatedAdmin.created_at)(oldCreatedAt);

  // 7. Fetch the admin again and check persistence
  // (Assume that .update returns the latest; if read API existed, would fetch here)
  TestValidator.equals("id persists")(updatedAdmin.id)(originalAdmin.id);
  TestValidator.equals("fields persisted")(updatedAdmin.username)(newUsername);
  TestValidator.equals("fields persisted")(updatedAdmin.email)(newEmail);
  TestValidator.equals("fields persisted")(updatedAdmin.is_active)(newIsActive);

  // 8. Attempt to update with a duplicate username (should fail)
  await TestValidator.error("update with duplicate username should fail")(async () => {
    await api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: originalAdmin.id,
      body: {
        username: existingAdmin.username,
      } satisfies IDiscussionBoardAdmin.IUpdate,
    });
  });
  // 9. Attempt to update with a duplicate email (should fail)
  await TestValidator.error("update with duplicate email should fail")(async () => {
    await api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: originalAdmin.id,
      body: {
        email: existingAdmin.email,
      } satisfies IDiscussionBoardAdmin.IUpdate,
    });
  });
}

