 *   - reference the post's ID
 *   - a clear category and reason (e.g., 'escalation_automation', 'Flagged automatically by system operator')
 * - Validate that:
 *   - The report is created with the correct content_type, target post id, and the provided category/reason.
 *   - The reporter_admin_id matches the created admin.
 *   - The report's status is set in accordance with admin-origin escalation (typically 'under_review' or 'pending').
 *   - Audit timestamps are present and valid ISO format.
 *   - No reporter_member_id, reporter_guest_id, or reporter_moderator_id are present.
 * - Optionally, check that improper submits (e.g., missing content_type or target ID) are rejected.
 */
export async function test_api_discussionBoard_test_admin_create_content_report_as_system_escalation(connection: api.IConnection) {
  // 1. Create a new admin (will be used as reporter)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUsername = RandomGenerator.alphabets(8);
  const adminPasswordHash = RandomGenerator.alphaNumeric(16);

  const admin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      password_hash: adminPasswordHash,
      is_active: true,
    },
  });
  typia.assert(admin);

  // 2. Create a new member post to serve as the report target
  const postTitle = RandomGenerator.paragraph()(1);
  const postBody = RandomGenerator.content()(1)(3);
  const memberPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    },
  });
  typia.assert(memberPost);

  // 3. Admin submits a content report for the post (as an escalation)
  const abuseCategory = "escalation_automation";
  const abuseReason = "Flagged automatically by system operator for compliance review.";
