 *
 * 1. Creating a notification specifically for the moderator (using the POST dependency).
 * 2. Creating control notifications for other roles (admin, member, guest) and another moderator to ensure only appropriate results are returned.
 * 3. Calling the GET endpoint as the moderator to retrieve notifications intended for them.
 * 4. Validating that:
 *    - The response includes the notification targeted to the moderator.
 *    - The response does NOT include notifications assigned to other roles or to another moderator.
 *    - All notifications in the data array have the moderator's UUID as moderator_id (and not member_id, admin_id, or guest_id).
 */
export async function test_api_discussionBoard_test_retrieve_moderator_notifications_inbox(connection: api.IConnection) {
  // Step 1: Generate a UUID for the target moderator
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Create a notification addressed to this moderator
  const moderatorNotification = await api.functional.discussionBoard.moderator.notifications.create(connection, {
    body: {
      moderator_id: moderatorId,
      type: "in-app",
      category: "moderation_event",
      message: "Moderator alert for your test inbox.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(moderatorNotification);

  // Step 3: Create notifications for other roles and another moderator for control
  const controlAdminNotification = await api.functional.discussionBoard.moderator.notifications.create(connection, {
    body: {
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      type: "in-app",
      category: "admin_notice",
      message: "Admin control notification.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(controlAdminNotification);

  const controlMemberNotification = await api.functional.discussionBoard.moderator.notifications.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      type: "in-app",
      category: "member_update",
      message: "Member control notification.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(controlMemberNotification);

  const controlGuestNotification = await api.functional.discussionBoard.moderator.notifications.create(connection, {
    body: {
      guest_id: typia.random<string & tags.Format<"uuid">>(),
      type: "in-app",
      category: "guest_notice",
      message: "Guest control notification.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(controlGuestNotification);

  const anotherModeratorId: string = typia.random<string & tags.Format<"uuid">>();
  const anotherModeratorNotification = await api.functional.discussionBoard.moderator.notifications.create(connection, {
    body: {
      moderator_id: anotherModeratorId,
      type: "in-app",
      category: "moderation_event",
      message: "Notification for another moderator.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(anotherModeratorNotification);

  // Step 4: Retrieve notifications as the moderator
  // (In a real scenario, authentication context would ensure the moderator_id is associated)
  // For this test, assume 'connection' simulates the moderator's authenticated session for moderatorId
  const page = await api.functional.discussionBoard.moderator.notifications.index(connection);
  typia.assert(page);

  // Step 5: Validate that each notification is intended for the target moderator
  page.data.forEach((notif) => {
    TestValidator.equals("notification recipient is correct moderator")(notif.moderator_id)(moderatorId);
    TestValidator.equals("notification not for admin")(notif.admin_id)(null);
    TestValidator.equals("notification not for member")(notif.member_id)(null);
    TestValidator.equals("notification not for guest")(notif.guest_id)(null);
  });

  // Step 6: Check that the created moderator notification is present
  TestValidator.predicate("created moderator notification exists")(
    page.data.some((n) => n.id === moderatorNotification.id)
  );

  // Step 7: Ensure notifications for other roles or another moderator are excluded
  TestValidator.predicate("admin notification not in result")(
    !page.data.some((n) => n.id === controlAdminNotification.id)
  );
  TestValidator.predicate("member notification not in result")(
    !page.data.some((n) => n.id === controlMemberNotification.id)
  );
  TestValidator.predicate("guest notification not in result")(
    !page.data.some((n) => n.id === controlGuestNotification.id)
  );
  TestValidator.predicate("another moderator notification not in result")(
    !page.data.some((n) => n.id === anotherModeratorNotification.id)
  );
