import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test pagination boundary conditions in the tag search API for discussion board tags.
 *
 * This test creates enough tags to meaningfully exercise pagination (at least 3 distinct tags with unique labels). It will then issue a sequence of paginated searches using the /discussionBoard/admin/tags PATCH endpoint with different combinations of the 'page' and 'limit' parameters, covering the following boundary cases:
 *
 * 1. limit=1, multiple successive pages (verifies correct single-item pagination and transitions between pages)
 * 2. page beyond the final page (should result in empty list)
 * 3. negative or zero page/index value (should default or error, as per implementation)
 * 4. limit exceeding number of records (should return all, single page)
 * 5. limit=0 (should return empty or error as per contract)
 * 6. page that exactly matches the last available page (should return only the remaining record(s))
 *
 * For each search call, the test will validate:
 * - returned pagination structure and field values
 * - number of records per page
 * - page and total page calculations
 * - correct handling of empty results
 *
 * The test will also confirm that the paginated tag records match the created source tags in correct order, by comparing labels.
 *
 * Steps:
 * 1. Create 3 tags with distinct, predictable labels
 * 2. Run paginated searches for limit=1, pages 1 through 4. Pages 1-3 should contain 1 tag each; page 4 should be empty.
 * 3. Run a search for page=0 and page=-1 (should default to page 1 or error/empty set)
 * 4. Run a search for limit=4 (expect 3 results, single page)
 * 5. Run a search for limit=0 (should be empty or error as per API contract)
 * 6. Validate structure, page info, total records, and data for all cases
 */
export async function test_api_discussionBoard_admin_tags_test_search_tags_pagination_boundary_conditions(connection: api.IConnection) {
  // 1. Create 3 tags with distinct, predictable labels
  const baseLabel = `test-pagination-tag-${typia.random<number & tags.Type<"uint32">>()}`;
  const tagsCreated = [];
  for (let i = 0; i < 3; ++i) {
    const tag = await api.functional.discussionBoard.admin.tags.create(connection, {
      body: {
        label: `${baseLabel}-${i}`,
        description: `Tag ${i} for pagination boundary test`,
        color: null,
      }
    });
    typia.assert(tag);
    tagsCreated.push(tag);
  }

  // 2. Paginated searches: limit=1, pages 1-4
  for (let page = 1; page <= 4; ++page) {
    const res = await api.functional.discussionBoard.admin.tags.search(connection, {
      body: { page, limit: 1 }
    });
    typia.assert(res);
    TestValidator.equals(`pagination.limit at page ${page}`)(res.pagination.limit)(1);
    TestValidator.equals(`records at page ${page}`)(res.pagination.records)(3);
    TestValidator.equals(`pages at page ${page}`)(res.pagination.pages)(3);
    TestValidator.equals(`current at page ${page}`)(res.pagination.current)(Math.min(page, 3));
    if (page <= 3) {
      TestValidator.equals(`data.length at page ${page}`)(res.data.length)(1);
      TestValidator.equals(`tag at page ${page}`)(res.data[0].label)(tagsCreated[page-1].label);
    } else {
      TestValidator.equals(`data.length at page ${page} (empty)`)(res.data.length)(0);
    }
  }

  // 3. Search for page=0 and page=-1 (should default to page 1 or error/empty set)
  for (const weirdPage of [0, -1]) {
    const res = await api.functional.discussionBoard.admin.tags.search(connection, {
      body: { page: weirdPage, limit: 1 }
    });
    typia.assert(res);
    // Implementation may default to page 1 or error/empty; allow lenient assertion
    TestValidator.equals(`records on weird page (${weirdPage})`)(res.pagination.records)(3);
    TestValidator.equals(`pages on weird page (${weirdPage})`)(res.pagination.pages)(3);
    // Accept current==1 or current==weirdPage (depending on system); just assert data length
    TestValidator.equals(`data.length on weird page (${weirdPage})`)(res.data.length)(1);
  }

  // 4. Search for limit=4 (expect 3 results, single page)
  const resLimit4 = await api.functional.discussionBoard.admin.tags.search(connection, {
    body: { page: 1, limit: 4 }
  });
  typia.assert(resLimit4);
  TestValidator.equals("limit 4, all tags")(resLimit4.data.length)(3);
  TestValidator.equals("limit 4, records")(resLimit4.pagination.records)(3);
  TestValidator.equals("limit 4, pages")(resLimit4.pagination.pages)(1);
  TestValidator.equals("limit 4, current")(resLimit4.pagination.current)(1);

  // 5. Search for limit=0 (should be empty or error as per contract)
  await TestValidator.error("limit=0 not allowed or returns empty")(async () => {
    const res0 = await api.functional.discussionBoard.admin.tags.search(connection, {
      body: { page: 1, limit: 0 }
    });
    typia.assert(res0);
    TestValidator.equals("limit 0 should return no data")(res0.data.length)(0);
  });
}

