import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test pagination boundary conditions in the admin tag search API.
 *
 * This test ensures the /discussionBoard/admin/tags PATCH endpoint for tag
 * search correctly handles edge cases of pagination such as: single-item pages
 * (limit=1), requests for out-of-range pages, zero and negative page inputs,
 * and limits exceeding set size or set to zero. The test guarantees correct
 * structure, boundary, and empty result responses as per API contract.
 *
 * 1. Sets up the test by creating 3 discernible tags with unique labels (for easy
 *    validation)
 * 2. Tests limit=1 paging: fetches pages 1-3 (expect 1 tag each), then page 4
 *    (expect empty)
 * 3. Tests out-of-range and negative page numbers (page=0, page=-1), expects
 *    current defaults or empty data, and valid structure
 * 4. Tests over-large limit (limit=4 for 3 records), expects all data and correct
 *    page math
 * 5. Tests limit=0, expects error or empty data depending on contract
 * 6. Validates all response structure, pagination metadata, and tag label
 *    correctness
 */
export async function test_api_discussionBoard_admin_tags_test_search_tags_pagination_boundary_conditions(
  connection: api.IConnection,
) {
  // 1. Create 3 unique tags
  const baseLabel = `test-pagination-tag-${typia.random<number & tags.Type<"uint32">>()}`;
  const createdTags: IDiscussionBoardTag[] = [];
  for (let i = 0; i < 3; ++i) {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      {
        body: {
          label: `${baseLabel}-${i}`,
          description: `Test tag #${i} for pagination boundary case`,
          color: null,
        } satisfies IDiscussionBoardTag.ICreate,
      },
    );
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 2. Test limit=1, fetch pages 1-3 (single result), then page 4 (empty)
  for (let page = 1; page <= 4; ++page) {
    const res = await api.functional.discussionBoard.admin.tags.search(
      connection,
      {
        body: { page, limit: 1 } satisfies IDiscussionBoardTag.IRequest,
      },
    );
    typia.assert(res);
    TestValidator.equals(`limit=1 at page ${page}`)(res.pagination.limit)(1);
    TestValidator.equals(`records at page ${page}`)(res.pagination.records)(3);
    TestValidator.equals(`pages for limit=1 at page ${page}`)(
      res.pagination.pages,
    )(3);
    TestValidator.equals(`current page for limit=1`)(res.pagination.current)(
      Math.min(page, 3),
    );
    if (page <= 3) {
      TestValidator.equals(`result count page ${page}`)(res.data.length)(1);
      TestValidator.equals(`tag label ordering page ${page}`)(
        res.data[0].label,
      )(createdTags[page - 1].label);
    } else {
      TestValidator.equals(`overflow page empty data`)(res.data.length)(0);
    }
  }

  // 3. Test zero and negative page inputs
  for (const oddPage of [0, -1]) {
    const res = await api.functional.discussionBoard.admin.tags.search(
      connection,
      {
        body: {
          page: oddPage,
          limit: 1,
        } satisfies IDiscussionBoardTag.IRequest,
      },
    );
    typia.assert(res);
    TestValidator.equals(`records for page=${oddPage}`)(res.pagination.records)(
      3,
    );
    TestValidator.equals(`total pages for page=${oddPage}`)(
      res.pagination.pages,
    )(3);
    // Accepts varying implementation: either defaults to page 1 or simply returns 1 result or empty
    TestValidator.predicate(`valid current for page=${oddPage}`)(
      res.pagination.current === 1 || res.pagination.current === oddPage,
    );
    TestValidator.equals(`single or empty result for odd pages`)(
      res.data.length <= 1,
    )(true);
