import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that moderator comment search correctly exposes soft-deleted comments when requested via filters, and that such comments are NOT visible to ordinary members.
 *
 * Business scenario:
 * - Create a batch of comments (by a member) under a single post, then soft-delete some (but not all) of them
 * - As a moderator, use the advanced comment search API to search for comments belonging to this post, with and without the filter that includes soft-deleted comments
 * - Confirm that, with include_deleted=true, the deleted ones (with deleted_at populated) appear in results, and those records have deleted_at fields set
 * - Confirm that as a regular member, the soft-deleted comments ARE NOT returned at all
 * - Validate RBAC: Only moderators can use the moderator search endpoint, and can see deleted comments; members cannot
 * - Check that deleted comments' deleted_at timestamps are ISO dates and non-null, and that non-deleted ones have deleted_at as null
 * 
 * Steps:
 * 1. (Data setup) Use member access to create several comments on a post.
 * 2. (Data setup) Soft-delete a subset of comments via member deletion API.
 * 3. (Moderator) Use moderator search (with include_deleted=false or omitted): only active comments visible.
 * 4. (Moderator) Use moderator search (with include_deleted=true): both active and soft-deleted visible; deleted have deleted_at set.
 * 5. (Member) As regular member, perform a search/API call: verify soft-deleted comments are excluded (if such API exists, otherwise skip)
 * 6. Validate that deleted_at sets are as expected, all returned comments are for the right post, and that RBAC boundaries are respected.
 */
export async function test_api_discussionBoard_test_search_comments_returns_soft_deleted_to_moderator(connection: api.IConnection) {
  // Step 1: Create multiple comments on a single post as a member
  const postId: string = typia.random<string & tags.Format<"uuid">>();

  // Create 4 comments, tracking their IDs
  const createdComments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 4; ++i) {
    const comment = await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_post_id: postId,
        parent_id: null,
        body: `Sample comment body #${i+1}`,
      } satisfies IDiscussionBoardComment.ICreate
    });
    typia.assert(comment);
    createdComments.push(comment);
  }

  // Step 2: Soft-delete 2 of the comments (e.g., index 1 and 2)
  for (let i of [1,2]) {
    await api.functional.discussionBoard.member.comments.erase(connection, {
      commentId: createdComments[i].id
    });
  }

  // Step 3: As a moderator, search WITHOUT include_deleted (should only see active comments)
  const modResActive = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {
      discussion_board_post_id: postId,
      include_deleted: false,
    } satisfies IDiscussionBoardComment.IRequest
  });
  typia.assert(modResActive);
  // Should only get the two non-deleted comments
  TestValidator.equals("active comments count")(modResActive.data.length)(2);
  for (const rec of modResActive.data) {
    TestValidator.equals("deleted_at is null for active")(rec.deleted_at)(null);
    TestValidator.equals("right post")(rec.discussion_board_post_id)(postId);
  }

  // Step 4: As a moderator, search WITH include_deleted=true (should see all, deleted have deleted_at set)
  const modResAll = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {
      discussion_board_post_id: postId,
      include_deleted: true,
    } satisfies IDiscussionBoardComment.IRequest
  });
  typia.assert(modResAll);
  TestValidator.equals("all comments count")(modResAll.data.length)(4);
  let deletedSeen = 0, activeSeen = 0;
  for (const rec of modResAll.data) {
    TestValidator.equals("right post")(rec.discussion_board_post_id)(postId);
    if (rec.deleted_at === null) ++activeSeen;
    else {
      ++deletedSeen;
      TestValidator.predicate("deleted_at is ISO date")(!!rec.deleted_at && !isNaN(Date.parse(rec.deleted_at||'')));
    }
  }
  TestValidator.equals("deleted count")(deletedSeen)(2);
  TestValidator.equals("active count")(activeSeen)(2);

  // Step 5: RBAC check - ensure regular member CANNOT call mod endpoint (should throw)
  TestValidator.error("member can't use moderator search")(() =>
    api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        discussion_board_post_id: postId,
        include_deleted: true,
      } satisfies IDiscussionBoardComment.IRequest
    })
  );
