/**
 * Validates advanced comment search/filter returns correct comment sets.
 *
 * This test covers these business flows:
 * 1. Registering two members (as comment authors)
 * 2. Creating a post (by one member)
 * 3. Adding multiple comments by different members, setting parent-child relationships for some
 * 4. Adjusting timestamps so we have time range variety
 * 5. Advanced search:
 *    - by member (returns only that member's comments)
 *    - by parent_id (returns direct replies to a comment)
 *    - by time range (returns only comments within that window)
 * For each filter, verifies response data contains only matching comments, and does not leak comments that should be excluded.
 */
export async function test_api_discussionBoard_test_advanced_comment_search_returns_only_filtered_results(
  connection: api.IConnection,
) {
  // 1. Register two members
  const member1 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member2);

  // 2. Create a post as member1
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(5),
      body: RandomGenerator.content()(3)(),
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 3. Add comments with different relations
  // Top-level comment by member1
  const comment1 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      body: "Parent Comment 1 by Member1",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment1);

  // Child comment by member2 replying to comment1
  const comment2 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      parent_id: comment1.id,
      body: "Reply to Comment 1 by Member2",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment2);

  // Top-level comment by member2
  const comment3 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      body: "Independent Comment 2 by Member2",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment3);

