  // (a) Search by member1 - should return only comments by member1
  const byMember1 = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      discussion_board_member_id: member1.id,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(byMember1);
  TestValidator.predicate("all comments are by member1")(byMember1.data.every(c => c.discussion_board_member_id === member1.id));

  // (b) Search by member2 - should return only comments by member2
  const byMember2 = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      discussion_board_member_id: member2.id,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(byMember2);
  TestValidator.predicate("all comments are by member2")(byMember2.data.every(c => c.discussion_board_member_id === member2.id));

  // (c) Search by parent_id (replies to comment1)
  const byParent = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      parent_id: comment1.id,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(byParent);
  TestValidator.predicate("all comments are replies to comment1")(byParent.data.every(c => c.parent_id === comment1.id));

  // (d) Search by time window: only comments created after comment1 and before comment3
  const createdFrom = comment1.created_at;
  const createdTo = comment3.created_at;
  const byTimeRange = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      created_from: createdFrom,
      created_to: createdTo,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(byTimeRange);
  TestValidator.predicate("all comments in time range")(
    byTimeRange.data.every(c => c.created_at >= createdFrom && c.created_at <= createdTo)
  );
