/**
 * Validates pagination and ordering of admin member search results for
 * discussion board.
 *
 * Business context: Admins and moderators need to view member lists with
 * pagination in order to audit, analyze, or manage large user bases. Correct
 * pagination and ordering are essential for accuracy, fairness, and usability
 * in admin dashboards.
 *
 * Test Workflow:
 *
 * 1. Register 17 unique members so that the dataset exceeds 1 page (using page
 *    size 10).
 * 2. As admin, perform paginated member searches with explicit pagination input
 *    (no sort available in API, so checks default/natural order, assumed by
 *    display_name ascending).
 * 3. For each retrieved page:
 *
 *    - Validate pagination meta (current/limit/total records/pages)
 *    - Validate data length matches page, especially last page edge-case
 *    - After all pages collected, confirm aggregate ordering matches expected
 * 4. Edge: last page should contain only the remainder (not a full page)
 */
export async function test_api_discussionBoard_test_search_members_with_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register enough members for multiple pages (total: 17, page size: 10)
  const totalMembers = 17;
  const members: IDiscussionBoardMember[] = [];
  for (let i = 0; i < totalMembers; ++i) {
    const display_name = `User${String(i).padStart(2, "0")}`;
    const email = `user${i}_${typia.random<string & tags.Format<"uuid">>()}@test.com`;
    const password_hash = typia.random<string>();
    const created = await api.functional.discussionBoard.members.create(
      connection,
      {
        body: {
          display_name,
          email,
          password_hash,
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(created);
    members.push(created);
  }

  // Reference: display_name ascending
  const sortedByDisplayName = [...members].sort((a, b) =>
    a.display_name.localeCompare(b.display_name),
  );

  // 2. Iterate through paginated admin search (no sort parameter)
  const limit = 10;
  let collected: IDiscussionBoardMember[] = [];
  let currentPage = 1;
  const totalPages = Math.ceil(totalMembers / limit);

  while (collected.length < totalMembers) {
    const res = await api.functional.discussionBoard.admin.members.search(
      connection,
      {
        body: {
          pagination: { page: currentPage, limit },
        } satisfies IDiscussionBoardMember.IRequest,
      },
    );
    typia.assert(res);
    // Validate pagination meta
    TestValidator.equals(`page ${currentPage} current`)(res.pagination.current)(
      currentPage,
    );
    TestValidator.equals(`page ${currentPage} limit`)(res.pagination.limit)(
      limit,
    );
    if (currentPage === 1)
      TestValidator.equals("total records")(res.pagination.records)(
        totalMembers,
      );
    // Validate length for page or edge
    if (currentPage < totalPages) {
      TestValidator.equals(`members on page ${currentPage}`)(res.data.length)(
        limit,
      );
    } else {
      TestValidator.equals("last page count")(res.data.length)(
        totalMembers % limit,
      );
    }
    collected.push(...res.data);
    currentPage++;
  }

  // 3. Validate ordering is correct: display_name ascending
  for (let i = 0; i < totalMembers; ++i) {
    TestValidator.equals(`member display_name order ${i}`)(
      collected[i].display_name,
    )(sortedByDisplayName[i].display_name);
  }

  // 4. Edge: last page only contains the remainder
  const lastPageRes = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        pagination: { page: totalPages, limit },
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(lastPageRes);
  TestValidator.equals("last page count")(lastPageRes.data.length)(
