  const found1 = pageEdits.data.some((edit) => edit.id === edit1.id);
  const found2 = pageEdits.data.some((edit) => edit.id === edit2.id);
  TestValidator.predicate("edit 1 visible to moderator")(found1);
  TestValidator.predicate("edit 2 visible to moderator")(found2);
