 * windows. It:
 *
 * 1. Creates two moderators with distinct timestamps (simulate gap via setTimeout)
 * 2. Searches with 'created_after' (should return only the second moderator)
 * 3. Searches with 'created_before' (should return only the first moderator)
 * 4. Searches with a between-window (should return no moderators)
 * 5. Searches with no filters (should return both moderators)
 * 6. Searches with a future window (no results expected)
 */
export async function test_api_discussionBoard_test_search_moderators_by_time_range(
  connection: api.IConnection,
) {
  // 1. Create first moderator (with controlled timestamp)
  const mod1 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        password_hash: RandomGenerator.alphaNumeric(32), // mock hash
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(mod1);
  const mod1Created = new Date(mod1.created_at);

  // Simulate time difference
  await new Promise((resolve) => setTimeout(resolve, 1200));

  // 2. Create second moderator
  const mod2 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        password_hash: RandomGenerator.alphaNumeric(32), // mock hash
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(mod2);
  const mod2Created = new Date(mod2.created_at);

  // Defensive - ensure timestamps are strictly increasing
  TestValidator.predicate("mod2 created after mod1")(
    mod2Created.getTime() > mod1Created.getTime(),
  );

  // 3. Search for moderators created AFTER mod1 (should include only mod2 among test-created ones)
  const resultAfter1 =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_after: mod1.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resultAfter1);
  // Data may contain other preexisting moderators, but we check for mod2
  TestValidator.predicate("mod2 found, mod1 not found")(
    resultAfter1.data.some((m) => m.id === mod2.id) &&
      !resultAfter1.data.some((m) => m.id === mod1.id),
  );
  // All results must have created_at > mod1's
  TestValidator.predicate("all are after mod1.created_at")(
    resultAfter1.data.every((m) => new Date(m.created_at) > mod1Created),
  );

  // 4. Search for moderators created BEFORE mod2
  const resultBefore2 =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_before: mod2.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resultBefore2);
  TestValidator.predicate("mod1 found, mod2 not found")(
    resultBefore2.data.some((m) => m.id === mod1.id) &&
      !resultBefore2.data.some((m) => m.id === mod2.id),
  );
  TestValidator.predicate("all are before mod2.created_at")(
