  const between =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_after: mod1.created_at,
          created_before: mod2.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(between);
  // None of the test moderators should appear
  TestValidator.predicate("between search empty for test mods")(
    !between.data.some((m) => m.id === mod1.id || m.id === mod2.id),
  );
