/**
 * Comprehensive E2E test for advanced audit log search endpoint as admin.
 *
 * This test case validates the advanced search functionality on the /discussionBoard/admin/auditLogs endpoint. The scenario covers:
 *   - Preparation: Ensure there is a diverse set of audit log data with various actors, action types, and timestamps by creating multiple audit log entries.
 *   - Search by actor_admin_id: Confirm that filtering returns only logs by the specified admin.
 *   - Search by action_type: Confirm that only logs of specific action types are returned.
 *   - Search by created_from/created_to (timestamp range): Confirm that filtering by date range works as intended.
 *   - Search by multiple criteria simultaneously: Ensure filter intersection works (e.g., actor + action_type).
 *   - Pagination: Set page/limit parameters and validate correct slicing and pagination metadata.
 *   - Invalid parameters: Pass out-of-range values, invalid actor/action IDs, or contradictory filters and verify graceful error or empty result handling.
 *   - Unauthorized: Simulate a non-admin/unprivileged search attempt and check for proper rejection or error.
 *
 * Key validations:
 *   - Only correct, matching logs are returned for each filter.
 *   - Pagination info matches expected slicing.
 *   - Type assertions on all responses.
 *   - Error validation and access control checks.
 */
export async function test_api_discussionBoard_test_advanced_audit_log_search_with_filters(
  connection: api.IConnection,
) {
  // 1. Prepare audit log data with several diverse entries
  //    - Different actor_admin_id, action_type, created_at timestamps
  //    - At least two distinct admins, two action_types, and a spread of timestamps
  //    - Save created log details for use in search filters
  const admin1_id = typia.random<string & tags.Format<"uuid">>();
  const admin2_id = typia.random<string & tags.Format<"uuid">>();
  const action_type1 = "edit";
  const action_type2 = "suspend";
  const now = new Date();

  const log_entries = [
    // Admin1, "edit", now - 3 days
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        action_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: admin1_id,
        action_type: action_type1,
        context: "Initial edit event",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    }),
    // Admin2, "suspend", now - 2 days
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        action_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: admin2_id,
        action_type: action_type2,
        context: "Admin2 suspend action",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    }),
    // Admin1, "suspend", now - 1 day
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        action_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: admin1_id,
        action_type: action_type2,
        context: "Admin1 suspend",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    }),
    // Admin2, "edit", now (current time)
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        action_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: admin2_id,
        action_type: action_type1,
        context: "Most recent edit",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    }),
  ];
  for (const entry of log_entries) typia.assert(entry);

  // 2. Search by actor_admin_id (admin1)
  const search_admin1 = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      actor_admin_id: admin1_id,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_admin1);
  TestValidator.predicate("admin1 filter")(search_admin1.data.every(log => log.actor_admin_id === admin1_id));

  // 3. Search by action_type ("suspend")
  const search_suspend = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      action_type: action_type2,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_suspend);
  TestValidator.predicate("action_type=suspend filter")(search_suspend.data.every(log => log.action_type === action_type2));

  // 4. Search by created_at time window (last 2 days)
  const from = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString();
  const to = now.toISOString();
  const search_window = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      created_from: from,
      created_to: to,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_window);
  TestValidator.predicate("created_at time window")(
    search_window.data.every(log => log.created_at >= from && log.created_at <= to)
  );

  // 5. Compound search by actor_admin_id + action_type
  const search_compound = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      actor_admin_id: admin1_id,
      action_type: action_type2,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_compound);
  TestValidator.predicate("compound filter")(search_compound.data.every(log => log.actor_admin_id === admin1_id && log.action_type === action_type2));

  // 6. Test pagination (page/limit)
  const search_paged = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_paged);
  TestValidator.equals("page number")(search_paged.pagination.current)(1);
  TestValidator.equals("limit")(search_paged.pagination.limit)(2);
  TestValidator.predicate("paged result <= limit")(search_paged.data.length <= 2);

  // 7. Invalid search parameter (contradictory/unlikely UUID)
  const nonsense_uuid = typia.random<string & tags.Format<"uuid">>();
  const search_invalid = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {
      action_id: nonsense_uuid,
    } satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_invalid);
  TestValidator.equals("no matching logs")(search_invalid.data.length)(0);

  // 8. Edge test: overly broad (null filter => all logs)
  const search_unfiltered = await api.functional.discussionBoard.admin.auditLogs.search(connection, {
    body: {} satisfies IDiscussionBoardAuditLog.IRequest
  });
  typia.assert(search_unfiltered);
  TestValidator.predicate("should return at least all that were created")(
    search_unfiltered.data.length >= log_entries.length
  );

  // 9. Unauthorized access: simulate non-admin (ASSUMPTION: removal of admin token means non-admin)
  // Remove or clear admin headers to simulate unauthorized access
  const non_admin_connection = { ...connection, headers: { ...connection.headers } };
  delete non_admin_connection.headers["Authorization"];
  await TestValidator.error("should reject non-admin access")(
    async () => {
      await api.functional.discussionBoard.admin.auditLogs.search(non_admin_connection, {
        body: { actor_admin_id: admin1_id } satisfies IDiscussionBoardAuditLog.IRequest
      });
    }
  );
}

