import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that soft-deleted comments are not visible to guest users in advanced comment search.
 *
 * Context: Ordinary users and guests (unauthenticated) should not see comments that have been soft-deleted (deleted_at set).
 * Moderators/admins may have broader access, but that is NOT tested here.
 *
 * Step-by-step Process:
 * 1. Register a discussion board member
 * 2. As that member, create a new post
 * 3. As that member, add several comments to the post (at least 2 for meaningful test)
 * 4. Soft-delete (erase) one of the comments (simulate member deleting their own comment)
 * 5. As an unauthenticated user, perform an advanced comment search for all comments on the post
 * 6. Validate that the erased (soft-deleted) comment does NOT appear in the result data
 * 7. Validate that remaining (non-deleted) comments ARE present in the result data
 * 8. (Edge case) Soft-delete all comments, then verify that no comments appear in search results
 */
export async function test_api_discussionBoard_test_advanced_comment_search_excludes_soft_deleted_for_guest(connection: api.IConnection) {
  // 1. Register a discussion board member
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(16),
  };
  const member = await api.functional.discussionBoard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a new post as that member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.paragraph()(2),
  };
  const post = await api.functional.discussionBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Add several comments to the post
  const commentInputs: IDiscussionBoardComment.ICreate[] = [
    { discussion_board_post_id: post.id, body: "This is comment A" },
    { discussion_board_post_id: post.id, body: "This is comment B" },
    { discussion_board_post_id: post.id, body: "This is comment C" }
  ];
  const comments: IDiscussionBoardComment[] = [];
  for (const input of commentInputs) {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, { postId: post.id, body: input });
    typia.assert(comment);
    comments.push(comment);
  }

  // 4. Soft-delete one of the comments
  const erasedComment = comments[1];
  await api.functional.discussionBoard.member.posts.comments.erase(connection, { postId: post.id, commentId: erasedComment.id });

  // 5. As unauthenticated user, perform advanced comment search for all comments on the post
  // (simulate guest by not providing any additional auth in connection)
  const searchRequest: IDiscussionBoardComment.IRequest = {
    discussion_board_post_id: post.id,
    limit: 10,
    page: 1,
  };
  const searchResult = await api.functional.discussionBoard.posts.comments.search(connection, { postId: post.id, body: searchRequest });
  typia.assert(searchResult);

  // 6. Validate that erased comment is not present
  const returnedIds = searchResult.data.map(c => c.id);
  TestValidator.notEquals("soft-deleted comment not returned")(returnedIds)([erasedComment.id]);

  // 7. Validate that the remaining comments are present
  for (const [idx, original] of comments.entries()) {
    if (idx !== 1) {
      TestValidator.predicate(`comment ${idx} exists in search result`)(returnedIds.includes(original.id));
    }
  }

  // 8. Edge case: Soft-delete all comments, then confirm search result is empty
  for (const [idx, comment] of comments.entries()) {
    if (idx !== 1) {
      await api.functional.discussionBoard.member.posts.comments.erase(connection, { postId: post.id, commentId: comment.id });
    }
  }
  const searchAfterAllDeleted = await api.functional.discussionBoard.posts.comments.search(connection, { postId: post.id, body: searchRequest });
  typia.assert(searchAfterAllDeleted);
  TestValidator.equals("no comments after all soft-deleted")(searchAfterAllDeleted.data.length)(0);
}

