      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add multiple comments as that member
  const comments: IDiscussionBoardComment[] = [];
  for (const body of ["First comment", "Second comment", "Third comment"]) {
    const created =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(created);
    comments.push(created);
  }

  // 4. Soft-delete one (middle) comment
  const erased = comments[1];
  await api.functional.discussionBoard.member.posts.comments.erase(connection, {
    postId: post.id,
    commentId: erased.id,
  });

  // 5. As unauthenticated guest, search all comments for post
  const searchResult =
    await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        limit: 10,
        page: 1,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(searchResult);

  // 6. Confirm erased comment is absent
  const searchIds = searchResult.data.map((c) => c.id);
  TestValidator.predicate("soft-deleted not present")(
    !searchIds.includes(erased.id),
  );

  // 7. Confirm remaining comments are present
  for (let i = 0; i < comments.length; ++i) {
    if (i === 1) continue;
    TestValidator.predicate(`comment ${i} returned`)(
      searchIds.includes(comments[i].id),
    );
  }

  // 8. Edge case: soft-delete all, check search yields zero
  for (let i = 0; i < comments.length; ++i) {
    if (i !== 1)
      await api.functional.discussionBoard.member.posts.comments.erase(
        connection,
        {
          postId: post.id,
          commentId: comments[i].id,
        },
      );
  }
  const afterAllErased =
    await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        limit: 10,
        page: 1,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(afterAllErased);
  TestValidator.equals("none remain")(afterAllErased.data.length)(0);
}

