import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Test searching for moderators by promoted_by_admin_id using the moderator PATCH endpoint
 *
 * This test validates the business logic that the PATCH endpoint for moderators can filter by the ID of the promoting admin (promoted_by_admin_id). Multiple moderator accounts are created, each with either the same or a different admin as the promoter. The search should only return those accounts where the promoter field matches the target admin.
 *
 * 1. Create two admin users (adminA and adminB) with different UUIDs
 * 2. Create multiple moderators with the following patterns:
 *    - several with promoted_by_admin_id set to adminA.id
 *    - several with promoted_by_admin_id set to adminB.id
 *    - at least one with promoted_by_admin_id omitted (legacy/manual case)
 * 3. Use the /discussionBoard/moderator/moderators PATCH endpoint with a filter for adminA's UUID (promoted_by_admin_id = adminA.id)
 * 4. Validate that all returned moderators have promoted_by_admin_id === adminA.id
 * 5. Ensure no returned moderator matches adminB.id or null/omitted
 * 6. Repeat by searching for adminB.id and for null (legacy/manual entries)
 */
export async function test_api_discussionBoard_test_search_moderators_by_promoter(
  connection: api.IConnection,
) {
  // 1. Prepare two fake "admin" IDs for promotion scenarios
  const adminAId: string = typia.random<string & tags.Format<"uuid">>();
  const adminBId: string = typia.random<string & tags.Format<"uuid">>();

  // 2a. Create moderators promoted by adminA
  const modA1 = await api.functional.discussionBoard.admin.moderators.create(connection, { body: { username: RandomGenerator.alphaNumeric(6), password_hash: RandomGenerator.alphaNumeric(32), email: typia.random<string & tags.Format<"email">>(), is_active: true, promoted_by_admin_id: adminAId } });
  typia.assert(modA1);
  const modA2 = await api.functional.discussionBoard.admin.moderators.create(connection, { body: { username: RandomGenerator.alphaNumeric(6), password_hash: RandomGenerator.alphaNumeric(32), email: typia.random<string & tags.Format<"email">>(), is_active: true, promoted_by_admin_id: adminAId } });
  typia.assert(modA2);

  // 2b. Create moderators promoted by adminB
  const modB1 = await api.functional.discussionBoard.admin.moderators.create(connection, { body: { username: RandomGenerator.alphaNumeric(6), password_hash: RandomGenerator.alphaNumeric(32), email: typia.random<string & tags.Format<"email">>(), is_active: true, promoted_by_admin_id: adminBId } });
  typia.assert(modB1);

  // 2c. Create moderator with no promoted_by_admin_id (legacy/manual entry)
  const modLegacy = await api.functional.discussionBoard.admin.moderators.create(connection, { body: { username: RandomGenerator.alphaNumeric(6), password_hash: RandomGenerator.alphaNumeric(32), email: typia.random<string & tags.Format<"email">>(), is_active: true } });
  typia.assert(modLegacy);

  // 3. Search moderators promoted by adminA
  const resA = await api.functional.discussionBoard.moderator.moderators.patch(connection, { body: { promoted_by_admin_id: adminAId } });
  typia.assert(resA);
  for (const mod of resA.data) {
    TestValidator.equals("promoted_by_admin_id=A")(mod.promoted_by_admin_id)(adminAId);
  }

  // 4. Ensure no moderator from adminB or legacy appears in adminA result
  TestValidator.predicate("no adminB/legacy in adminA search")(resA.data.every(m => m.promoted_by_admin_id === adminAId));

  // 5. Search moderators promoted by adminB
  const resB = await api.functional.discussionBoard.moderator.moderators.patch(connection, { body: { promoted_by_admin_id: adminBId } });
  typia.assert(resB);
  for (const mod of resB.data) {
    TestValidator.equals("promoted_by_admin_id=B")(mod.promoted_by_admin_id)(adminBId);
  }
  TestValidator.predicate("no adminA/legacy in adminB search")(resB.data.every(m => m.promoted_by_admin_id === adminBId));

  // 6. Search moderators with no promoted_by_admin_id (legacy/manual)
  const resLegacy = await api.functional.discussionBoard.moderator.moderators.patch(connection, { body: { promoted_by_admin_id: undefined } });
  typia.assert(resLegacy);
  for (const mod of resLegacy.data) {
    TestValidator.equals("promoted_by_admin_id=undefined")(mod.promoted_by_admin_id)(undefined);
  }
  TestValidator.predicate("only legacy mods in legacy search")(resLegacy.data.every(m => !m.promoted_by_admin_id));
}

