 *
 * This test ensures that the discussion board comments API enforces required business rules for editing comments. Specifically, it covers failure scenarios where the comment body is set to `null`, an empty string, or whitespace-only string. For each invalid value, the system must return a validation error indicating the body is required and must not be empty.
 *
 * Steps:
 * 1. Register a new member to serve as the comment author.
 * 2. Create a discussion post as this member.
 * 3. Create an initial valid comment on the post as this member.
 * 4. Attempt to update the comment body to each invalid value:
 *    - body: null
 *    - body: ""
 *    - body: "   "
 *    In each case, assert that the operation fails with a validation error (using TestValidator.error) and that no update occurs.
 *
 * Business context: Only valid, non-empty bodies should be allowed for comments. Validation is critical for content moderation and data integrity.
 */
export async function test_api_discussionBoard_member_comments_test_update_comment_with_invalid_body(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32); // Passwords are always hashed
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPasswordHash,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a post as this member (assume connection is authenticated as this member if necessary)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(4),
      body: RandomGenerator.content()(8)(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a valid comment on the post
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_post_id: post.id, // Associate with created post
      body: RandomGenerator.content()(4)(),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Attempt to update the comment body to each invalid value (null, empty string, whitespace)
  const invalidBodies = [null, "", "   "];
  for (const invalidBody of invalidBodies) {
    await TestValidator.error(`updating comment with invalid body (${JSON.stringify(invalidBody)})`)(async () => {
      await api.functional.discussionBoard.member.comments.update(connection, {
        commentId: comment.id,
        body: { body: invalidBody } satisfies IDiscussionBoardComment.IUpdate,
      });
    });
  }
}

