  TestValidator.equals("page metadata")(paged.pagination.current)(0);
  TestValidator.equals("page limit")(paged.pagination.limit)(2);

  // 7. Invalid query: entered_at_from > entered_at_to (should error, but not crash)
  await TestValidator.error("reversed date range gives error")(async () => {
