import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";

/**
 * Validates that an admin user can fetch the complete list of content moderation reports, including both reported posts and comments.
 *
 * Ensures regulatory and workflow compliance by confirming admin visibility to all status and metadata fields of content reports, regardless of their current workflow state or privacy.
 *
 * Test workflow:
 * 1. Register two member accounts (member1, member2).
 * 2. Have the first member create a post.
 * 3. Have the second member comment on that post.
 * 4. With the first member, file a content report regarding the post.
 * 5. With the second member, file a content report regarding the comment.
 * 6. Retrieve the full content moderation report list as an admin.
 * 7. Confirm that the returned data includes both reports, with proper linkage (post/comment), reporter/member IDs, report content type, categories, reasons, statuses, and relevant metadata fields.
 * 8. Assert that all business-required fields are present and visible.
*/
export async function test_api_discussionBoard_test_admin_fetches_all_content_reports_full_access(connection: api.IConnection) {
  // 1. Register two member accounts
  const member1_email = typia.random<string & tags.Format<"email">>();
  const member2_email = typia.random<string & tags.Format<"email">>();
  const member1 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: member1_email,
      password_hash: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: member2_email,
      password_hash: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // 2. First member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      parent_id: null,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Second member creates a comment on that post
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      body: RandomGenerator.paragraph()(),
      parent_id: null,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. First member reports the post (content_type: 'post')
  const reportOnPost = await api.functional.discussionBoard.member.contentReports.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      discussion_board_comment_id: null,
      content_type: "post",
      category: "policy",
      reason: "Suspected policy violation in the post body.",
    } satisfies IDiscussionBoardContentReport.ICreate,
  });
  typia.assert(reportOnPost);
  TestValidator.equals("Reported post id matches")(reportOnPost.discussion_board_post_id)(post.id);
  TestValidator.equals("content_type for post report")(reportOnPost.content_type)("post");

  // 5. Second member reports the comment (content_type: 'comment')
  const reportOnComment = await api.functional.discussionBoard.member.contentReports.create(connection, {
    body: {
      discussion_board_post_id: null,
      discussion_board_comment_id: comment.id,
      content_type: "comment",
      category: "offensive",
      reason: "Suspected offensive language in comment.",
    } satisfies IDiscussionBoardContentReport.ICreate,
  });
  typia.assert(reportOnComment);
  TestValidator.equals("Reported comment id matches")(reportOnComment.discussion_board_comment_id)(comment.id);
  TestValidator.equals("content_type for comment report")(reportOnComment.content_type)("comment");

  // 6. Retrieve all content reports as admin
  const reportPage = await api.functional.discussionBoard.admin.contentReports.index(connection);
  typia.assert(reportPage);

  // 7. Confirm both reports exist in result set and validate business-required fields
  const postReport = reportPage.data.find(r => r.id === reportOnPost.id);
  const commentReport = reportPage.data.find(r => r.id === reportOnComment.id);

  TestValidator.predicate("Both post and comment reports are retrievable as admin")(!!postReport && !!commentReport);

  // 8. Validate critical fields and metadata for compliance
  for (const report of [postReport, commentReport]) {
    if (!report) continue;
    TestValidator.predicate("id is uuid")(typeof report.id === "string" && /[0-9a-fA-F-]{36}/.test(report.id));
    TestValidator.predicate("Has a valid content_type")(["post","comment"].includes(report.content_type));
    TestValidator.predicate("Has non-empty category")(!!report.category);
    TestValidator.predicate("Has non-empty reason")(!!report.reason);
    TestValidator.predicate("Has status field")(typeof report.status === "string");
    TestValidator.predicate("Has reported_at timestamp")(!!report.reported_at);
    // Linkage fields (post/comment IDs) are consistent
    if (report.content_type === "post") {
      TestValidator.equals("post linkage matches")(report.discussion_board_post_id)(post.id);
      TestValidator.equals("comment absent for post")(report.discussion_board_comment_id)(null);
    } else if (report.content_type === "comment") {
      TestValidator.equals("comment linkage matches")(report.discussion_board_comment_id)(comment.id);
    }
  }
  // Pagination sanity
  TestValidator.predicate("Pagination metadata present")(!!reportPage.pagination && typeof reportPage.pagination.current === "number");
}

