  const initialBody: IDiscussionBoardBoardSetting.ICreate = {
    title: initialTitle,
    enabled: true,
    description: RandomGenerator.paragraph()(),
    logo_uri: null,
  };

  const boardSetting = await api.functional.discussionBoard.admin.boardSettings.create(connection, { body: initialBody });
