import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Moderator can create a valid suspension record for a member account.
 *
 * This test verifies that a moderator is able to suspend a member using the
 * appropriate endpoint, providing all required information and ensuring that
 * the resultant suspension record conforms to business and compliance
 * requirements. Typical use case is disciplinary action due to policy
 * violations.
 *
 * Steps:
 *
 * 1. Retrieve a valid member UUID from the admin API.
 * 2. As moderator, submit a suspension create POST using that member id, with
 *    required fields provided and proper actor/subject role fields filled.
 * 3. Verify response type and that business rules (status, actor/subject linkage,
 *    audit fields) are enforced: correct subject, actor, timestamps, rationale,
 *    and nulls for admin fields.
 */
export async function test_api_discussionBoard_test_create_suspension_by_moderator_for_member(
  connection: api.IConnection,
) {
  // 1. Retrieve a member
  const members =
    await api.functional.discussionBoard.admin.members.index(connection);
  typia.assert(members);
  const member = members.data[0];
  if (!member) throw new Error("No member accounts available for test");

  // 2. Prepare suspension request as moderator
  const now = new Date();
  const endsAt = new Date(now.getTime() + 7 * 24 * 3600 * 1000); // 1 week
  const createRequest = {
    suspended_member_id: member.id,
    suspended_admin_id: null,
    suspended_moderator_id: null,
    suspended_guest_id: null,
    admin_id: null, // action is by moderator
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    related_report_id: null,
    related_action_id: null,
    suspended_at: now.toISOString() as string & tags.Format<"date-time">,
    ends_at: endsAt.toISOString() as string & tags.Format<"date-time">,
    reason: "Violation of board rules: test suspension",
    status: "active",
  } satisfies IDiscussionBoardSuspension.ICreate;

  // 3. Create suspension
  const suspension =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      { body: createRequest },
    );
  typia.assert(suspension);

  // 4. Validate fields for compliance/audit and that input matches output
  TestValidator.equals("suspended_member_id matches")(
    suspension.suspended_member_id,
  )(member.id);
  TestValidator.equals("reason matches")(suspension.reason)(
    createRequest.reason,
  );
  TestValidator.equals("status matches")(suspension.status)("active");
  TestValidator.equals("suspended_at matches")(suspension.suspended_at)(
    createRequest.suspended_at,
  );
  TestValidator.equals("ends_at matches")(suspension.ends_at)(
    createRequest.ends_at,
  );
  TestValidator.equals("moderator_id matches")(suspension.moderator_id)(
    createRequest.moderator_id,
  );
  TestValidator.equals("admin_id is null")(suspension.admin_id)(null);
}

