  const memberPasswordHash = "hashof-password";
  const memberDisplayName = RandomGenerator.name();

  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPasswordHash,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Register moderator account
  const moderatorUsername = RandomGenerator.name();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPasswordHash = "hashof-modpassword";

  const moderator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: moderatorUsername,
      password_hash: moderatorPasswordHash,
      email: moderatorEmail,
      is_active: true,
