/**
 * Validate that moderation action update API enforces required field validation.
 *
 * This test ensures that the system rejects requests missing mandatory fields by attempting to update an existing moderation action with a payload that omits all fields. The expectation is that the API returns a validation error specifying the missing required fields, thus enforcing strict schema compliance on updates.
 *
 * Business context: Moderators may attempt to patch moderation actions, but omitting required change information must not succeed. The validation logic must be robust.
 *
 * Test Steps:
 * 1. Create a content report to be the basis for moderation actions (precondition).
 * 2. Create a moderation action linked to the above report (precondition).
 * 3. Attempt to update the moderation action by providing an empty payload (i.e., omit all updatable properties).
 * 4. Assert that the system responds with a validation error and the update is rejected.
 */
export async function test_api_discussionBoard_test_update_moderation_action_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Prepare content report to create moderation action
  const contentReport = await api.functional.discussionBoard.moderator.contentReports.create(connection, {
    body: {
      content_type: "post",
      category: "offensive",
      reason: "Spam post in forum",
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_comment_id: null
    } satisfies IDiscussionBoardContentReport.ICreate,
  });
  typia.assert(contentReport);

  // 2. Create a moderation action for this report
  const moderationAction = await api.functional.discussionBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: contentReport.id,
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "delete",
      description: "Initial moderation action."
    } satisfies IDiscussionBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 3. Attempt to update the moderation action omitting all fields (empty payload)
  await TestValidator.error("update with missing required fields fails")(
    async () => {
      // All fields are optional in IUpdate, but at least one must be provided by business logic
      await api.functional.discussionBoard.moderator.moderationActions.update(connection, {
        moderationActionId: moderationAction.id,
        body: {} satisfies IDiscussionBoardModerationAction.IUpdate
      });
    }
  );
}

