import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that an admin can search and filter all post votes, with cross-role full visibility.
 *
 * This test ensures that: 
 * - An admin can see and filter all post votes (upvotes, downvotes, and by specific members) for any post.
 * - Votes that would be hidden or privacy-protected from other members are fully visible to admins.
 *
 * Test Steps:
 * 1. Create three member accounts (voters).
 * 2. Create an admin account.
 * 3. As a member, create a discussion board post.
 * 4. Log in as each member, cast upvotes/downvotes (varied), saving each vote's member and upvote status.
 * 5. As admin, search votes for the post (no filter) and verify all are present with all data fields.
 * 6. As admin, search with upvote:true (all upvotes for this post) and verify only upvotes are returned.
 * 7. As admin, search with upvote:false and verify only downvotes are returned.
 * 8. As admin, filter with discussion_board_member_id for one voter, and check only that member's votes are returned regardless of upvote/downvote.
 * 9. (Edge case) Use pagination params (e.g., limit=2, page=1) and verify correct result slicing and pagination fields.
 */
export async function test_api_discussionBoard_test_admin_search_post_votes_cross_role_visibility(
  connection: api.IConnection,
) {
  // 1. Create three different member accounts
  const members = await Promise.all(ArrayUtil.repeat(3)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const result = await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email,
        password_hash: RandomGenerator.alphaNumeric(12),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(result);
    return result;
  }));

  // 2. Create an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      password_hash: RandomGenerator.alphaNumeric(14),
      is_active: true,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(admin);

  // 3. Use the first member account to create a post
  // (Assume the connection switches meaningfully according to authentication in real usage.)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      parent_id: null,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Log in as each member and cast votes (simulate login context switching as necessary)
  // We'll create: [upvote, downvote, upvote]
  const votes = await Promise.all([
    true,
    false,
    true,
  ].map(async (upvote, idx) => {
    // (Assume underlying connection context switches according to member identity for true E2E)
    const result = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
      postId: post.id,
      body: { upvote } satisfies IDiscussionBoardPostVote.ICreate,
    });
    typia.assert(result);
    return { ...result, expected_upvote: upvote, member_id: members[idx].id };
  }));

  // 5. Admin: search all votes for this post, confirm all present and all fields returned
  const allVotesPage = await api.functional.discussionBoard.admin.posts.postVotes.search(connection, {
    postId: post.id,
    body: { discussion_board_post_id: post.id } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(allVotesPage);
  const fetchedVotes = allVotesPage.data;
  // All three votes must be present, each with correct upvote status and member
  TestValidator.equals("all vote count")(fetchedVotes.length)(votes.length);
  for (const vote of votes) {
    const found = fetchedVotes.find(v => v.id === vote.id);
    TestValidator.predicate(`vote exists and upvote matches for voteId=${vote.id}`)(!!found && found.upvote === vote.expected_upvote);
    TestValidator.equals("vote member id")(found?.discussion_board_member_id)(vote.member_id);
  }

  // 6. Admin: filter upvotes for this post
  const upvotePage = await api.functional.discussionBoard.admin.posts.postVotes.search(connection, {
    postId: post.id,
    body: { discussion_board_post_id: post.id, upvote: true } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(upvotePage);
  for (const v of upvotePage.data)
    TestValidator.equals("upvote only")(v.upvote)(true);

  // 7. Admin: filter downvotes for this post
  const downvotePage = await api.functional.discussionBoard.admin.posts.postVotes.search(connection, {
    postId: post.id,
    body: { discussion_board_post_id: post.id, upvote: false } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(downvotePage);
  for (const v of downvotePage.data)
    TestValidator.equals("downvote only")(v.upvote)(false);

