  typia.assert(resultNoActor);
  TestValidator.equals("No results for non-existent moderator")(resultNoActor.data.length)(0);

  // 11. Exceeding page size: page past end
  const resultPagePast = await api.functional.discussionBoard.moderator.moderationActions.search(connection, { body: { pagination: { page: 999, limit: 1 } } });
  typia.assert(resultPagePast);
  TestValidator.equals("Page past end empty")(resultPagePast.data.length)(0);

  // 12. Invalid UUID
  await TestValidator.error("invalid UUID in report_id")(() =>
    api.functional.discussionBoard.moderator.moderationActions.search(connection, { body: { report_id: "invalid-uuid" as any } })
  );
  // 13. Invalid date
