 *  4. Confirming that both active and soft-deleted categories are present in the paginated result.
 *
 * Steps:
 * 1. Admin creates two categories: one active, one for soft-deletion.
 * 2. Admin soft-deletes one of the categories.
 * 3. Moderator searches for categories with filter `include_deleted: true`.
 * 4. Assert that both the active and soft-deleted categories are present in the returned data, and check the `deleted_at` property as appropriate.
 */
export async function test_api_discussionBoard_test_moderator_search_categories_includes_soft_deleted_with_permission(connection: api.IConnection) {
