 * 2. As (or on behalf of) a moderator, request the detailed profile for the newly created member by their unique memberId using the moderator's GET endpoint.
 * 3. Validate the API returns the complete profile with audit fields (id, display_name, email, is_verified, registered_at, status, last_login_at).
 * 4. Confirm that sensitive fields such as password_hash are absent from the response.
 * 5. Assert that the status is as expected, and that the data matches the registered member.
 */
export async function test_api_discussionBoard_test_get_member_details_as_moderator_with_existing_member(
  connection: api.IConnection,
) {
  // 1. Register a new member account
  const registrationData = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  } satisfies IDiscussionBoardMember.ICreate;

  const createdMember = await api.functional.discussionBoard.members.create(connection, {
    body: registrationData,
  });
  typia.assert(createdMember);

  // 2. As a moderator, fetch the member's detailed profile
  // (Assume moderator privileges are present in the connection context)
  const profile = await api.functional.discussionBoard.moderator.members.at(connection, {
    memberId: createdMember.id,
  });
  typia.assert(profile);

  // 3. Validate profile fields and absence of sensitive data
  TestValidator.equals("member id matches")(profile.id)(createdMember.id);
  TestValidator.equals("display name matches")(profile.display_name)(createdMember.display_name);
  TestValidator.equals("email matches")(profile.email)(createdMember.email);
  TestValidator.equals("is_verified default")(profile.is_verified)(createdMember.is_verified);
  TestValidator.equals("registered_at matches")(profile.registered_at)(createdMember.registered_at);
  TestValidator.equals("status matches")(profile.status)(createdMember.status);
  TestValidator.equals("last_login_at matches")(profile.last_login_at ?? null)(createdMember.last_login_at ?? null);
