/**
 * Validate that an admin can see both active and soft-deleted tags in the tag listing.
 *
 * An admin should be able to retrieve all tags, including those that are soft-deleted (have deleted_at populated), if permissions allow.
 *
 * Test Workflow:
 * 1. Create a new discussion board tag as admin (simulate admin context).
 * 2. Soft-delete the created tag using the admin erase API.
 * 3. List all tags as admin—verify both active and deleted tags appear, and confirm the deleted tag has a non-null deleted_at timestamp.
 *
 * Business scenario ensures soft-deleted tags are not truly removed and are visible to proper roles for analytics and possible restoration.
 */
export async function test_api_discussionBoard_test_admin_can_see_soft_deleted_tags_if_permitted(
  connection: api.IConnection,
) {
  // 1. Create a new tag as admin
  const createInput: IDiscussionBoardTag.ICreate = {
    label: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.alphabets(20),
