 * This test ensures a realistic workflow: (1) a guest session is registered, (2) a notification is explicitly created and delivered for this guest, and (3) the guest session invokes the update endpoint to mark its notification as read.
 *
 * Steps:
 * 1. Register a new guest session. (Needed to populate guest_id for notification)
 * 2. Create a new notification assigned to this guest (admin privilege).
 * 3. Guest marks their notification as read using the update endpoint.
 * 4. Validate the notification's is_read field and audit that the correct notification (id, guest_id) was updated.
 */
export async function test_api_discussionBoard_guest_notifications_test_update_guest_notification_mark_as_read(
  connection: api.IConnection,
) {
  // 1. Register a new guest session
  const guestCreateInput = {
    guest_ip: '203.0.113.84',
    session_token: RandomGenerator.alphaNumeric(20),
    entered_at: new Date().toISOString(),
  } satisfies IDiscussionBoardGuest.ICreate;
