  typia.assert(guest);

  // 2. Admin creates & delivers notification for this guest
  const notificationInput = {
    guest_id: guest.id,
    type: 'in-app',
    category: 'info',
    message: 'Test notification for marking as read.',
    is_read: false,
    status: 'sent',
    created_at: new Date().toISOString(),
  } satisfies IDiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, { body: notificationInput });
