/**
 * Test updating a discussion board tag as an admin user with valid data.
 *
 * This test validates that an admin can successfully update the label, description, and/or color of a discussion board tag.
 * The process covers:
 * 1. Creation of a tag with initial data as a prerequisite.
 * 2. Performing an update to the created tag's properties (label, description, color).
 * 3. Verifying the response reflects updated values, and audit fields (updated_at) have changed as expected.
 *
 * Workflow Steps:
 * 1. Use the admin API to create a new tag with random but valid properties for label, description, and color.
 * 2. Use the admin API to update the tag using its id, changing some/all updatable fields (label, description, color).
 * 3. Verify in the response that:
 *   - The id is unchanged.
 *   - The changed fields match the update request.
 *   - Audit fields (updated_at, created_at) exist and are in the correct format, and updated_at has changed compared to before the update.
 *   - No unexpected deletion (deleted_at is null or unchanged).
 */
export async function test_api_discussionBoard_test_update_tag_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new tag as an admin
  const initialTag = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      color: "#" + (Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, "0")),
    } satisfies IDiscussionBoardTag.ICreate,
  });
  typia.assert(initialTag);

  // 2. Update the tag as an admin using its id, changing label, description, color
  const updateInput: IDiscussionBoardTag.IUpdate = {
    label: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
    color: "#" + (Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, "0")),
  };
  const updatedTag = await api.functional.discussionBoard.admin.tags.update(connection, {
    tagId: initialTag.id,
    body: updateInput,
  });
  typia.assert(updatedTag);

  // 3. Validate the response reflects the updates and audit fields
  TestValidator.equals("tag id") (updatedTag.id)(initialTag.id);
  TestValidator.equals("label updated")(updatedTag.label)(updateInput.label);
  TestValidator.equals("description updated")(updatedTag.description)(updateInput.description);
  TestValidator.equals("color updated")(updatedTag.color)(updateInput.color);
  TestValidator.notEquals("updated_at changed")(updatedTag.updated_at)(initialTag.updated_at);
  TestValidator.equals("created_at unchanged")(updatedTag.created_at)(initialTag.created_at);
  // deleted_at should remain null or unchanged
  TestValidator.equals("deleted_at unchanged")(updatedTag.deleted_at)(initialTag.deleted_at);
}

