  TestValidator.equals("enabled matches")(result.enabled)(input.enabled);
  TestValidator.equals("description matches")(result.description)(input.description);
  TestValidator.equals("logo_uri matches")(result.logo_uri)(input.logo_uri);

  // 4. Ensure 'created_at' and 'updated_at' are valid ISO date strings
