/**
 * Validate admin update of allowed mutable fields (such as context) in an audit log entry while immutable fields remain unchanged.
 *
 * This test verifies that an admin (with appropriate permissions) can modify a mutable field (context) on a discussion board audit log.
 * It ensures fields disallowed by business rules remain unchanged and only permissible changes are reflected.
 * 
 * Steps:
 * 1. Create a valid audit log entry using the admin-auditLog create endpoint
 * 2. Update the context of this audit log entry using the admin-auditLog update endpoint
 * 3. Verify response includes the updated context
 * 4. Check that immutable fields (such as action_id, actor ids, created_at) retain their original values
 */
export async function test_api_discussionBoard_test_update_audit_log_entry_by_admin_with_allowed_mutable_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid audit log entry
  const createInput: IDiscussionBoardAuditLog.ICreate = {
    action_id: typia.random<string & tags.Format<"uuid">>(),
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "edit",
    context: "Initial context for audit log entry.",
  };
  const auditLog = await api.functional.discussionBoard.admin.auditLogs.create(connection, { body: createInput });
  typia.assert(auditLog);

  // 2. Update the context (a mutable field)
  const newContext = "Modified context value for audit log entry.";
  const updated = await api.functional.discussionBoard.admin.auditLogs.update(connection, {
    auditLogId: auditLog.id,
    body: {
      context: newContext,
    },
  });
  typia.assert(updated);

  // 3. Verify the context has been updated
  TestValidator.equals("context updated")(updated.context)(newContext);

  // 4. Check that immutable fields remained unchanged
