  TestValidator.equals("actor_admin_id unchanged")(updated.actor_admin_id)(auditLog.actor_admin_id);
  TestValidator.equals("action_type unchanged")(updated.action_type)(auditLog.action_type);
  TestValidator.equals("created_at unchanged")(updated.created_at)(auditLog.created_at);
}

