 * 5. Optionally verify that audit-related fields (created_at, updated_at, promoted_by_admin_id) are present and correct.
 * 6. (If supported) validate that audit logs have correctly recorded this action.
 *
 * Edge cases (like duplicate email or username) are covered in separate tests. Here we focus strictly on the happy path for properly formed, unique input values.
 */
export async function test_api_discussionBoard_admin_moderators_test_create_moderator_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare moderator creation input (all required fields, unique values)
  const moderatorInput: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    password_hash: RandomGenerator.alphaNumeric(60), // simulate 60-char hash
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
    // Optionally add promoter ID, but for minimal case can omit
  };

  // 2. Call the API to create the moderator
  const createdModerator: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    { body: moderatorInput },
  );
  typia.assert(createdModerator);

