  TestValidator.equals("username matches")(createdModerator.username)(moderatorInput.username);
  TestValidator.equals("email matches")(createdModerator.email)(moderatorInput.email);
  TestValidator.equals("is_active matches")(createdModerator.is_active)(moderatorInput.is_active);
  // 4. Confirm password_hash is not present on output
  if ((createdModerator as any).password_hash !== undefined) throw new Error("Response contains sensitive password_hash field");
  // 5. Validate audit fields present & correctly formatted
  TestValidator.predicate("Has valid id")(
    typeof createdModerator.id === "string" && createdModerator.id.length > 0
  );
