  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32);
  const memberDisplayName = RandomGenerator.alphabets(10);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPasswordHash
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // The system is expected to establish authentication automatically.

  // 2. Create a post as this member (should be authenticated already)
  const postTitle = RandomGenerator.paragraph()(1);
  const postBody = RandomGenerator.content()()();
