/**
 * Test idempotent or error behavior when attempting to delete an already soft-deleted tag.
 *
 * Business scenario: Deleting a tag already soft-deleted should either be an idempotent success (no error) or return a clear error indicating its deleted status, as per business policy. This ensures backend compliance and user/admin interface integrity in tag management workflows.
 *
 * Steps:
 * 1. Create a new discussion board tag with unique label (using random data).
 * 2. Soft-delete the tag by id (should succeed and set deleted_at timestamp).
 * 3. Attempt to soft-delete the same tag again (should be idempotent or return appropriate error).
 * 4. Validate that deletion is either silently idempotent (no error) or explicit error (business logic expected result).
 */
export async function test_api_discussionBoard_admin_tags_test_delete_already_soft_deleted_tag(connection: api.IConnection) {
  // 1. Create a new tag
  const label: string = RandomGenerator.alphabets(12);
  const tag = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label,
      description: RandomGenerator.paragraph()(),
      color: null,
    } satisfies IDiscussionBoardTag.ICreate,
  });
  typia.assert(tag);

  // 2. Soft-delete the tag (should succeed)
  await api.functional.discussionBoard.admin.tags.erase(connection, { tagId: tag.id });

  // 3. Attempt to soft-delete again (should be either success or clear error per policy)
  let deletionSucceeded = false;
  try {
    await api.functional.discussionBoard.admin.tags.erase(connection, { tagId: tag.id });
    deletionSucceeded = true; // No error: idempotent
  } catch (exp) {
    deletionSucceeded = false; // Error: clear signaling prior deletion
  }

  // 4. Validate idempotent or error path is allowed by policy
  TestValidator.predicate("idempotent or error on repeated delete")(typeof deletionSucceeded === "boolean");
}

