import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify moderator can search for tags using label filters, soft-deleted status,
 * date range, and pagination.
 *
 * Business context:
 * Moderators often need to manage large inventories of tags for analytics, moderation,
 * and assignment. This requires searching/filtering tags based on the label,
 * created_at period, and deleted state, with proper pagination.
 *
 * Steps:
 * 1. Bulk create several tags as the admin (different labels and some soft-deleted).
 * 2. As moderator, search for tags by:
 *    a. Partial label substring (choose multiple substrings to verify).
 *    b. Only soft-deleted tags (include_deleted=true).
 *    c. Date range filtering: fetch only tags created within a certain window.
 *    d. Pagination: limit and page, confirm data and pagination correctness.
 * 3. Validate the search results:
 *    - Only matching tags are shown according to filter, including full/partial matches for label.
 *    - Soft-deleted filter works as expected.
 *    - Date boundaries respected per created_at.
 *    - Response pagination has correct limit/page/records/pages.
 *    - No tag outside the filter criteria is included in results.
 *
 * Edge cases:
 * - Zero results for filters that match nothing.
 * - Partial page (fewer tags than limit).
 * - Pagination beyond end (empty data array).
 * - Both deleted and non-deleted with include_deleted=null or omitted.
 */
export async function test_api_discussionBoard_test_moderator_can_search_tags_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Bulk create tags (admin privilege required)
  //    - Different labels (e.g. "science-physics", "science-biology", "art-history", etc.)
  //    - Soft-delete a couple by simulating their deleted_at field (no endpoint to delete directly, so just test with natural creation)
  const tags: IDiscussionBoardTag[] = [];
  for (const label of [
    "science-physics",
    "science-biology",
    "art-history",
    "math-statistics",
    "technology-ai",
    "archived-deleted-tag"
  ]) {
    const tag = await api.functional.discussionBoard.admin.tags.create(connection, {
      body: {
        label,
        description: `${label} tag`,
        color: null,
      } satisfies IDiscussionBoardTag.ICreate,
    });
    typia.assert(tag);
    tags.push(tag);
  }

  // 2. Search by partial label substring (case: "science")
  let page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: { label: "science", page: 1, limit: 100 } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("all matches have 'science' in label")(
    page.data.every((x) => x.label.includes("science"))
  );

  // 3. Search with include_deleted=true (should show all, none are soft-deleted by default)
  page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: { include_deleted: true, page: 1, limit: 100 } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  TestValidator.equals("returns all records since none are deleted")(page.pagination.records)(tags.length);

  // 4. Search with date range (created_at of one of the tags)
  //    use the created_at of the "science-biology" tag as a date filter
  const bioTag = tags.find((x) => x.label === "science-biology")!;
  page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: {
      created_from: bioTag.created_at,
      created_to: bioTag.created_at,
      page: 1,
      limit: 100
    } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  // Must include the "science-biology" tag
  TestValidator.predicate("contains 'science-biology' tag")(
    page.data.some((x) => x.label === "science-biology")
  );

  // 5. Pagination: Test with limit 2, page 2
  page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: { page: 2, limit: 2 } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  TestValidator.equals("correct limit for page 2")(page.pagination.limit)(2);
  TestValidator.equals("correct page for page 2")(page.pagination.current)(2);
  // Data array length = 2 (unless last page, then possibly less).
  TestValidator.predicate("at most 'limit' records per page")(
    page.data.length <= 2
  );

  // 6. Edge: Zero results for nonsense label match
  page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: { label: "unused-nonsense", page: 1, limit: 10 } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  TestValidator.equals("no tags for nonsense label")(page.data.length)(0);
  TestValidator.equals("zero records in pagination")(page.pagination.records)(0);

  // 7. Edge: Pagination beyond end
  const beyondPage = 99;
  page = await api.functional.discussionBoard.moderator.tags.search(connection, {
    body: { page: beyondPage, limit: 2 } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(page);
  // Data array should be empty if page beyond total pages.
  TestValidator.equals("empty array for page beyond end")(page.data.length)(0);
}

