import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Validate that deleting the same post edit event twice is handled correctly.
 *
 * This test follows the scenario where a post edit event is deleted as admin,
 * and then a repeated attempt to delete the same event is made. It must return
 * an error indicating the resource is already deleted or does not exist, to prevent
 * idempotency or hidden errors in moderation workflows.
 *
 * Steps:
 * 1. Register a discussion board member
 * 2. Create a post as the registered member
 * 3. Create a post edit event for that post as the member
 * 4. Delete the post edit event as administrator
 * 5. Attempt to delete the same post edit event again and assert that an error occurs for non-existence/deletion.
 */
export async function test_api_discussionBoard_test_delete_post_edit_event_already_deleted_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPasswordHash = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPasswordHash,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a post as the registered member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      parent_id: null,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a post edit event for that post as the member
  const editEvent = await api.functional.discussionBoard.member.posts.postEdits.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date().toISOString() as string & tags.Format<"date-time">,
      rationale: "Initial revision",
    } satisfies IDiscussionBoardPostEdit.ICreate,
  });
  typia.assert(editEvent);

  // 4. Delete the post edit event as administrator
  await api.functional.discussionBoard.admin.posts.postEdits.erase(connection, {
    postId: post.id,
    postEditId: editEvent.id,
  });

  // 5. Attempt to delete the same post edit event again and assert that an error occurs
  await TestValidator.error("Deleting already-deleted post edit throws error")(
    () =>
      api.functional.discussionBoard.admin.posts.postEdits.erase(connection, {
        postId: post.id,
        postEditId: editEvent.id,
      }),
  );
}

