 */
export async function test_api_discussionBoard_test_create_category_missing_required_name_returns_validation_error(connection: api.IConnection) {
  // 1. Attempt creation with payload missing required 'name' property
  await TestValidator.error("category missing name should fail")(async () => {
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        // name is intentionally omitted
        description: "Category without name"
      } as any // type system cannot enforce missing property; this tests runtime validation
    });
  });

