import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Validate retrieval of a specific discussion board authentication token by its UUID.
 *
 * This test ensures that when an admin requests the details of a known authentication token (created just before),
 * the response includes all expected non-sensitive fields, and the data returned matches the record that was created.
 *
 * Steps performed:
 * 1. Create a new authentication token via the privileged admin endpoint with valid test data (using IDiscussionBoardAuthToken.ICreate).
 * 2. Retrieve the token using the ID from the previous step via GET /discussionBoard/admin/authTokens/{authTokenId}.
 * 3. Assert that the response contains all fields except sensitive token information, the ID and relevant linkage fields match, and timestamps are as expected.
 *
 * This test simulates the audit/retrieval workflow for RBAC, compliance, and traceability purposes, and verifies that authorization, existence, and schema correctness are enforced.
 */
export async function test_api_discussionBoard_admin_authTokens_at(
  connection: api.IConnection,
) {
  // Step 1: Create a new authentication token with valid linkage for an admin actor.
  const admin_id: string = typia.random<string & tags.Format<"uuid">>();
  const creation: IDiscussionBoardAuthToken =
    await api.functional.discussionBoard.admin.authTokens.create(connection, {
      body: {
        admin_id,
        actor_type: "admin",
        token: RandomGenerator.alphaNumeric(40),
        issued_at: new Date().toISOString(),
        expires_at: null,
      } satisfies IDiscussionBoardAuthToken.ICreate,
    });
  typia.assert(creation);

  // Step 2: Retrieve the token details by ID
  const output: IDiscussionBoardAuthToken =
    await api.functional.discussionBoard.admin.authTokens.at(connection, {
      authTokenId: creation.id,
    });
  typia.assert(output);

  // Step 3: Assert that the read data matches what was created (non-sensitive fields only)
  TestValidator.equals("id matches")(output.id)(creation.id);
  TestValidator.equals("admin_id matches")(output.admin_id)(creation.admin_id);
  TestValidator.equals("actor_type matches")(output.actor_type)(creation.actor_type);
  TestValidator.equals("issued_at matches")(output.issued_at)(creation.issued_at);
  TestValidator.equals("expires_at matches")(output.expires_at)(creation.expires_at);
  TestValidator.equals("revoked should be false for new token")(output.revoked)(false);
}

