import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Test that a moderator can update any member's post vote (approval/rejection).
 *
 * 1. Register a member (as a regular user—simulate a normal user sign up)
 * 2. Register a moderator (simulate privileged admin creation)
 * 3. Member creates a post on the board
 * 4. Member casts a vote (upvote or downvote) on the post
 * 5. Moderator updates the member's post vote (flips upvote/downvote)
 * 6. Confirm the returned postVote reflects the updated value (and has same post/member IDs)
 * 7. Confirm the auditability: at minimum, updated_at/created_at fields reflect the change
 */
export async function test_api_discussionBoard_test_moderator_updates_member_post_vote_success(connection: api.IConnection) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      username: RandomGenerator.name(),
      password_hash: RandomGenerator.alphaNumeric(32),
      email: moderatorEmail,
      is_active: true,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // 3. Member creates a post
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Member casts a vote (randomly upvote)
  const memberVote: IDiscussionBoardPostVote = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
    postId: post.id,
    body: {
      upvote: true,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(memberVote);
  TestValidator.equals("postVote: upvote matches")(memberVote.upvote)(true);
  TestValidator.equals("postVote: correct post")(memberVote.discussion_board_post_id)(post.id);
  TestValidator.equals("postVote: correct member")(memberVote.discussion_board_member_id)(member.id);

  // 5. Moderator updates the member's vote (flip to downvote)
  const updatedVote: IDiscussionBoardPostVote = await api.functional.discussionBoard.moderator.posts.postVotes.update(connection, {
    postId: post.id,
    postVoteId: memberVote.id,
    body: {
      upvote: false,
    } satisfies IDiscussionBoardPostVote.IUpdate,
  });
  typia.assert(updatedVote);
  TestValidator.equals("vote updated: now downvote")(updatedVote.upvote)(false);
  TestValidator.equals("vote updated: same post ID")(updatedVote.discussion_board_post_id)(post.id);
  TestValidator.equals("vote updated: same member ID")(updatedVote.discussion_board_member_id)(member.id);
  TestValidator.notEquals("updated_at has changed")(updatedVote.updated_at)(memberVote.created_at);
}

