 *
 * Steps:
 * 1. Register a member
 * 2. Create a post as the member
 * 3. Perform two edits to the post via the edit event endpoint
 * 4. Fetch the edit history for the post
 * 5. Confirm the response lists both edits in chronological order
 * 6. Confirm each edit references the correct post ID and member ID
 * 7. Confirm timeline and attribution fields are present and correctly populated for each edit event
 */
export async function test_api_discussionBoard_test_list_post_edits_for_member_own_post(connection: api.IConnection) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const displayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: displayName,
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(20),
    },
  });
  typia.assert(member);

  // 2. Create a post as the member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      parent_id: null,
    },
  });
  typia.assert(post);
  TestValidator.equals("post author matches member")(post.discussion_board_member_id)(member.id);

  // 3. Perform two edits to the post via the edit event endpoint
  const edit1Title = RandomGenerator.paragraph()();
  const edit1Body = RandomGenerator.content()()();
  const edit1 = await api.functional.discussionBoard.member.posts.postEdits.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      new_title: edit1Title,
      new_body: edit1Body,
      edited_at: new Date().toISOString(),
      rationale: "Initial revision"
    },
  });
  typia.assert(edit1);

  // Ensure at least a millisecond difference between edits for order
  await new Promise(res => setTimeout(res, 5));

  const edit2Title = RandomGenerator.paragraph()();
  const edit2Body = RandomGenerator.content()()();
  const edit2 = await api.functional.discussionBoard.member.posts.postEdits.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
