  const [firstEdit, secondEdit] = [history.data[0], history.data[1]];
  TestValidator.equals("first edit title matches")(firstEdit.new_title)(edit1Title);
  TestValidator.equals("second edit title matches")(secondEdit.new_title)(edit2Title);
  TestValidator.equals("first edit rationale matches")(firstEdit.rationale)("Initial revision");
  TestValidator.equals("second edit rationale matches")(secondEdit.rationale)("Second revision");
  TestValidator.equals("edit member id matches")(firstEdit.discussion_board_member_id)(member.id);
  TestValidator.equals("edit member id matches")(secondEdit.discussion_board_member_id)(member.id);

