/**
 * Test that a member can delete their own notification and confirm it is removed.
 *
 * Business context:
 * Notifications are addressed to specific participants (member/admin/moderator/guest) and are subject to user-level privacy, compliance, and user-experience requirements. Only the notification's recipient or a privileged user is authorized to remove such a notification. This test executes the end-to-end scenario where: a member is created, a notification is delivered to them, and then the notification is deleted and its deletion confirmed by attempting to access it.
 *
 * Steps:
 * 1. Register a new discussion board member (simulate member self-registration by providing a display_name, email, password_hash).
 * 2. As an admin (privileged context implied), create and deliver a notification directly to the registered member. Ensure only the member_id field is populated for recipient, and message, type, category, etc. are filled with valid data.
 * 3. As the member (assume proper session context in connection object), delete the notification by notificationId using the member's notification erase endpoint.
 * 4. Verify that any subsequent attempt to access or manipulate the deleted notification fails (typically, fetch operation should return not-found or error).
 */
export async function test_api_discussionBoard_test_member_delete_own_notification(connection: api.IConnection) {
  // 1. Register a discussion board member
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32)
  };
  const member = await api.functional.discussionBoard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Admin delivers a notification to the member
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    member_id: member.id,
    type: "in-app",
    category: "test",
    message: "Test notification for deletion.",
    is_read: false,
    status: "sent",
    created_at: new Date().toISOString(),
    delivered_at: null,
    read_at: null,
    error_message: null
  };
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, { body: notificationInput });
  typia.assert(notification);

  // 3. Member deletes the notification
  await api.functional.discussionBoard.member.notifications.erase(connection, { notificationId: notification.id });

  // 4. Attempting to delete again should error (not found)
  await TestValidator.error("notification should not be found after deletion")(async () => {
    await api.functional.discussionBoard.member.notifications.erase(connection, { notificationId: notification.id });
  });
}

