/**
 * Validates that an authoring member can retrieve details of a specific post edit event by its edit ID.
 *
 * This workflow ensures:
 * 1. A verified member is registered to serve as the post author.
 * 2. The member creates a new discussion board post.
 * 3. The member edits the post twice. Each edit results in a distinct post edit event (for the same post).
 * 4. Fetch a single post edit event by its unique event ID using GET.
 * 5. Confirm that the returned event object matches the requested edit, is linked to the correct post and member, and contains audit fields (IDs, new_title/body, rationale, edited_at).
 *
 * Business value: This test guarantees correctness and auditability of version history functionality for post authors, ensuring full traceability and access for compliance, moderation, and user UX.
 */
export async function test_api_discussionBoard_member_posts_postEdits_get_single_post_edit_event_as_author(
  connection: api.IConnection,
) {
  // 1. Register a verified member to serve as post author
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);
  TestValidator.predicate("must be verified by default")(member.is_verified === true || member.is_verified === false);

  // 2. The member creates a post
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      // parent_id omitted for top-level post
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. The member makes two edits to the same post, each with unique content/rationale
  const editPayloads = [
    {
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date(Date.now() + 1000).toISOString(),
      rationale: "Initial typo fix",
    },
    {
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date(Date.now() + 2000).toISOString(),
      rationale: "Added clarification",
    },
  ];

  const edits: IDiscussionBoardPostEdit[] = [];
  for (const payload of editPayloads) {
    const edit = await api.functional.discussionBoard.member.posts.postEdits.create(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        discussion_board_member_id: member.id,
        ...payload,
      } satisfies IDiscussionBoardPostEdit.ICreate,
