    typia.assert(edit);
    edits.push(edit);
  }

  // 4. Fetch one of the edit events by its edit ID (e.g., the first edit)
  const targetEdit: IDiscussionBoardPostEdit = await api.functional.discussionBoard.member.posts.postEdits.at(connection, {
    postId: post.id,
    postEditId: edits[0].id,
  });
  typia.assert(targetEdit);

  // 5. Assert returned event matches the expected edit and context
  TestValidator.equals("returned edit ID matches")(targetEdit.id)(edits[0].id);
  TestValidator.equals("is for the correct post")(targetEdit.discussion_board_post_id)(post.id);
  TestValidator.equals("is edited by the author")(targetEdit.discussion_board_member_id)(member.id);
  TestValidator.equals("audit: rationale")(targetEdit.rationale)(editPayloads[0].rationale);
  TestValidator.equals("audit: new_title")(targetEdit.new_title)(editPayloads[0].new_title);
  TestValidator.equals("audit: new_body")(targetEdit.new_body)(editPayloads[0].new_body);
  TestValidator.predicate("edited_at is ISO string")(targetEdit.edited_at === editPayloads[0].edited_at);
}

