  connection: api.IConnection,
) {
  // 1. Create admin account for admin operations
  const adminUsername = RandomGenerator.alphabets(8);
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphabets(12);
  const admin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      password_hash: adminPasswordHash,
      is_active: true,
    },
  });
  typia.assert(admin);

  // 2. Create member account for post creation
  const memberDisplayName = RandomGenerator.alphabets(10);
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphabets(10);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: memberDisplayName,
      email: memberEmail,
      password_hash: memberPasswordHash,
    },
  });
  typia.assert(member);

  // 3. Member creates a discussion post
  const postTitle = RandomGenerator.paragraph()(1);
  const postBody = RandomGenerator.content()()(1);
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    },
  });
  typia.assert(post);

  // 4. Admin creates a tag
  const tagLabel = RandomGenerator.alphabets(6);
  const tag = await api.functional.discussionBoard.admin.tags.create(connection, {
    body: {
      label: tagLabel,
      description: null,
      color: null,
    },
  });
  typia.assert(tag);

  // 5. Member assigns the tag to their post
  const postTag = await api.functional.discussionBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      discussion_board_tag_id: tag.id,
    },
  });
  typia.assert(postTag);

  // 6. Member soft deletes the post
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post.id,
  });

  // 7. Admin attempts to remove the tag association from the soft-deleted post. Should fail.
  await TestValidator.error("admin cannot remove tag from a soft-deleted post")(() =>
    api.functional.discussionBoard.admin.posts.postTags.erase(connection, {
      postId: post.id,
      postTagId: postTag.id,
    })
  );
