/**
 * Validate the ability for an admin to update a content report by adding a resolution note (rationale).
 *
 * Business context: Content moderation requires full reporting and auditability. After a report is created—say by a user or automated logic—an admin or moderator must resolve the case and leave rationale. This test covers that workflow from report creation, admin update, to verification of the updated fields (including proper timestamps and rationale appearing on the report object).
 *
 * Test steps:
 * 1. Create a content report (as dependency, typically via POST; reporter identity inferred by backend, simulated here by privileged session).
 * 2. As admin, update the report using PUT with a rationale in the reason field, potentially marking the report as resolved and providing a resolved_at timestamp.
 * 3. Validate that the report's reason and resolved_at fields reflect the update, and status may change to 'resolved'.
 * 4. Confirm pre/post state difference in rationale and audit timestamp fields.
 */
export async function test_api_discussionBoard_admin_contentReports_test_admin_adds_resolution_note_to_report(
  connection: api.IConnection,
) {
  // 1. Create a baseline content report
  const createdReport = await api.functional.discussionBoard.admin.contentReports.create(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussion_board_comment_id: null,
        content_type: "post",
        category: "offensive",
        reason: "Content may violate policy",
      } satisfies IDiscussionBoardContentReport.ICreate,
    },
  );
  typia.assert(createdReport);

  // 2. Update the report with a resolution rationale
  const newRationale = "Review completed. Content action: warning email sent.";
  const resolvedAt = new Date().toISOString();
  const updated = await api.functional.discussionBoard.admin.contentReports.update(
    connection,
    {
      contentReportId: createdReport.id,
      body: {
        reason: newRationale,
        status: "resolved",
        resolved_at: resolvedAt,
      } satisfies IDiscussionBoardContentReport.IUpdate,
    },
  );
  typia.assert(updated);

  // 3. Validate updated fields
  TestValidator.equals("report reason updated")(updated.reason)(newRationale);
  TestValidator.equals("report marked as resolved")(updated.status)("resolved");
  TestValidator.equals("resolved timestamp")(updated.resolved_at)(resolvedAt);

  // 4. Validate the report id and basic invariants
  TestValidator.equals("report id remains constant")(updated.id)(createdReport.id);
  TestValidator.notEquals("reason was updated")(createdReport.reason)(updated.reason);
}

