import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test creation of a discussion board guest session with valid and invalid data.
 *
 * 1. Register a new guest session with valid fields (guest_ip, session_token, entered_at); validate that all expected properties are returned and have correct types; confirm presence of id, guest_ip, session_token, entered_at.
 * 2. Register a second guest session using a different token; both should succeed, verifying no required uniqueness between tokens.
 * 3. Register another guest session using the same session_token but a different guest_ip—should still succeed (unless stricter deduplication rules are enforced later).
 * 4. Error case: try creating a guest session with missing session_token (should throw an error, as this field is required).
 * 5. Error case: try creating a guest session with an invalid (empty string) guest_ip (should throw an error).
 * 6. Error case: try creating a guest session with all fields missing or null (should throw validation errors).
 * 7. Error case: (only if business logic/rate limit is enforced) Attempt more than a reasonable number of guest creations in a very short period and ensure handling (rate limiting/policy error) if enforced; if not, ensure creation proceeds.
 */
export async function test_api_discussionBoard_test_create_guest_session_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new guest session with valid data
  const guestInput1: IDiscussionBoardGuest.ICreate = {
    guest_ip: "192.168.1.1",
    session_token: RandomGenerator.alphaNumeric(16),
    entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const output1 = await api.functional.discussionBoard.guests.create(connection, { body: guestInput1 });
  typia.assert(output1);
  TestValidator.equals("guest_ip matches")(output1.guest_ip)(guestInput1.guest_ip);
  TestValidator.equals("session_token matches")(output1.session_token)(guestInput1.session_token);

  // 2. Register a second session with a different session_token (should succeed)
  const guestInput2: IDiscussionBoardGuest.ICreate = {
    guest_ip: "192.168.1.2",
    session_token: RandomGenerator.alphaNumeric(16),
    entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const output2 = await api.functional.discussionBoard.guests.create(connection, { body: guestInput2 });
  typia.assert(output2);
  TestValidator.equals("guest_ip matches")(output2.guest_ip)(guestInput2.guest_ip);

  // 3. Register another session with same session_token but different IP (should still succeed)
  const guestInput3: IDiscussionBoardGuest.ICreate = {
    guest_ip: "10.0.0.1",
    session_token: guestInput1.session_token,
    entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const output3 = await api.functional.discussionBoard.guests.create(connection, { body: guestInput3 });
  typia.assert(output3);
  TestValidator.equals("session_token matches")(output3.session_token)(guestInput3.session_token);

  // 4. Error case: missing session_token
  await TestValidator.error("missing session_token should fail")(async () => {
    await api.functional.discussionBoard.guests.create(connection, {
      body: {
        guest_ip: "127.0.0.1",
        // session_token omitted
        entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } as any, // forcibly incorrect for error
    });
  });

  // 5. Error case: guest_ip is empty string
  await TestValidator.error("empty guest_ip should fail")(async () => {
    await api.functional.discussionBoard.guests.create(connection, {
      body: {
        guest_ip: "",
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
      },
    });
  });

  // 6. Error case: all fields missing
  await TestValidator.error("all required fields missing should fail")(async () => {
    await api.functional.discussionBoard.guests.create(connection, { body: {} as any });
  });

  // 7. Optional: (If system enforces it) rate limiting, otherwise just bulk creation
  const attemptCount = 10;
  let errors = 0;
  for (let i = 0; i < attemptCount; ++i) {
    try {
      await api.functional.discussionBoard.guests.create(connection, {
        body: {
          guest_ip: `203.0.113.${i}`,
          session_token: RandomGenerator.alphaNumeric(16),
          entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
        },
      });
    } catch {
      errors++;
    }
  }
  // If any errors occurred, it may indicate rate limiting policy – acceptable if observed
}

