  TestValidator.predicate("moderator can see all comments, including soft-deleted")(resWithDeleted.data.some((c) => c.deleted_at !== null) || resWithDeleted.data.every((c) => c.deleted_at === null));

  // 2.f) Pagination test: page size 2, fetch two pages, check boundaries
  const pagRes1 = await api.functional.discussionBoard.moderator.comments.search(connection, { body: { limit: 2, page: 1 } });
  typia.assert(pagRes1);
  TestValidator.equals("page 1")(pagRes1.pagination.current)(1);
  TestValidator.equals("limit 2")(pagRes1.pagination.limit)(2);
  TestValidator.predicate("page 1 size ")(pagRes1.data.length <= 2);

  const pagRes2 = await api.functional.discussionBoard.moderator.comments.search(connection, { body: { limit: 2, page: 2 } });
  typia.assert(pagRes2);
  TestValidator.equals("page 2")(pagRes2.pagination.current)(2);
  TestValidator.equals("limit 2")(pagRes2.pagination.limit)(2);
  TestValidator.predicate("page 2 size")(pagRes2.data.length <= 2);
}

