  const notificationInput: IDiscussionBoardNotification.ICreate = {
    guest_id: guest.id,
    type: "in-app",
    category: "test-case",
    message: RandomGenerator.paragraph()(),
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    delivered_at: null,
    read_at: null,
    error_message: null,
  };
