  TestValidator.equals("notification delivered to guest")(notification.guest_id)(guest.id);

  // 3. Guest deletes their notification
  await api.functional.discussionBoard.guest.notifications.erase(connection, { notificationId: notification.id });
  // If deletion succeeds (void), assertion is implicit.

  // 4. Deleting again should yield not found or error (permanence check)
  await TestValidator.error("notification is hard deleted, cannot delete twice")(
    () => api.functional.discussionBoard.guest.notifications.erase(connection, { notificationId: notification.id })
