/**
 * Test scenario: Guest notification settings search returns only authenticated guest's own data and cannot access others'.
 *
 * This function ensures that:
 * 1. A notification setting is created for one guest session (the 'main' session).
 * 2. (If possible) A notification setting is created for a different guest session (the 'other' session) to test access isolation.
 * 3. The main guest performs a search with various filters; only their own notification setting appears (never the other session's or any member/moderator/admin setting).
 * 4. Attempted filtered searches should never reveal or provide access to settings not belonging to the authenticated guest.
 *
 * Main steps:
 * - Register notification setting for the "main" guest session.
 * - Register a notification setting for a second guest session (for isolation check).
 * - [Main session] Search using no filters, then with various allowed filters (e.g., by in_app_enabled, email_enabled, created_at_from/to)
 *   - Each time, check that the results only include the main session's setting(s)
 *   - Results MUST never include any setting from other guest sessions.
 * - (Optional) Repeat search from the other guest session, similarly ensuring only that session's own setting is visible
 * - Try a filter that could match settings from other's session (e.g., same in_app_enabled), confirm only current session's data appears
 *
 * The test covers both basic search and cross-session (authorization/isolation) logic.
 */
export async function test_api_discussionBoard_guest_notificationSettings_test_guest_search_notification_settings_returns_own_settings_only(connection: api.IConnection) {
  // 1. Register a notification setting for this (main) guest session
