        vote_notification_enabled: true,
        created_at: now,
        updated_at: now,
        // All *_id are omitted for current guest session
      },
    }
  );
  typia.assert(mainSetting);

  // 2. Register a notification setting for a second guest (by simulating a new session)
  //    Here, we simulate this by cloning the connection without cookies/headers if possible
  //    This depends on your sdk/test framework for guest session isolation
  const connection2 = {...connection, headers: {...connection.headers} };
  // Remove any existing cookies/guest-token/session header for a new session
  delete connection2.headers["cookie"];
  delete connection2.headers["authorization"];
  const now2 = new Date(Date.now() + 1000).toISOString();
  const otherSetting = await api.functional.discussionBoard.guest.notificationSettings.create(
    connection2,
    {
      body: {
        in_app_enabled: false,
        email_enabled: true,
        moderation_notification_enabled: false,
        reply_notification_enabled: true,
        vote_notification_enabled: false,
        created_at: now2,
