 * 1. Register a member account (the comment author)
 * 2. Register an admin account (the updater)
 * 3. Create a post as the member
 * 4. Create a comment on the post as the member
 * 5. Switch identity to the admin
 * 6. As admin, update the comment's body and (optionally) parent_id
 * 7. Fetch the updated comment and assert the fields were changed as intended
 */
export async function test_api_discussionBoard_test_update_comment_as_admin(
  connection: api.IConnection,
) {
  // 1. Register a member (author of the comment)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(10),
    } satisfies IDiscussionBoardMember.ICreate,
  });
