 * 5. Verifies that after updating, the returned edit record reflects the intended changes.
 *
 * Preconditions set up a comment and an initial edit history. Business rule: only original editor or privileged roles can update. Here, test focuses on author update with valid mutation data.
 *
 * Steps:
 * 1. Create a new discussion comment (with simulated post and member association)
 * 2. Create an edit event for the comment, with known rationale/body
 * 3. Update that edit with new values (both rationale and new_body)
 * 4. Assert returned edit record matches the requested updates, and other fields are unchanged.
 */
export async function test_api_discussionBoard_member_comments_commentEdits_test_update_comment_edit_with_valid_data_by_author(connection: api.IConnection) {
  // 1. Create a comment to enable edit history
  const postId = typia.random<string & tags.Format<"uuid">>();
  const commentBody = "Initial comment, for edit test.";
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_post_id: postId,
      body: commentBody,
    } satisfies IDiscussionBoardComment.ICreate,
  });
