    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(edit);

  // 3. Update edit record with new rationale and new_body
  const updatedRationale = "Compliance improvement and phrasing clarification.";
  const updatedNewBody = "Final version of comment after compliance update.";
  const updatedEdit = await api.functional.discussionBoard.member.comments.commentEdits.update(connection, {
    commentId: comment.id,
    commentEditId: edit.id,
    body: {
      rationale: updatedRationale,
      new_body: updatedNewBody,
    } satisfies IDiscussionBoardCommentEdit.IUpdate,
  });
  typia.assert(updatedEdit);

  // 4. Assert that updated fields changed and audit fields preserved
  TestValidator.equals("edit id unchanged")(updatedEdit.id)(edit.id);
  TestValidator.equals("comment mapping unchanged")(updatedEdit.discussion_board_comment_id)(edit.discussion_board_comment_id);
  TestValidator.equals("editor unchanged")(updatedEdit.discussion_board_member_id)(edit.discussion_board_member_id);
  TestValidator.equals("rationale updated")(updatedEdit.rationale)(updatedRationale);
  TestValidator.equals("new_body updated")(updatedEdit.new_body)(updatedNewBody);
}

