  for (const params of [
    // action 1, status pending, by admin
    { action_id: actionId1, status: "pending", appellant_admin_id: adminId, appellant_moderator_id: null, appellant_member_id: null, appellant_guest_id: null },
    // action 1, status approved, by member
    { action_id: actionId1, status: "approved", appellant_admin_id: null, appellant_moderator_id: null, appellant_member_id: memberId, appellant_guest_id: null },
    // action 2, status denied, by moderator
