  const result_pending = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { status: "pending" } });
  typia.assert(result_pending);
  for (const a of result_pending.data) TestValidator.equals("status is pending")(a.status)("pending");

  // 3. Filter by specific action
  const result_action1 = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { action_id: actionId1 } });
  typia.assert(result_action1);
  for (const a of result_action1.data) TestValidator.equals("action matches")(a.action_id)(actionId1);

  // 4. Filter by actor type (member)
  const result_member = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { appellant_member_id: memberId } });
  typia.assert(result_member);
  for (const a of result_member.data) TestValidator.equals("appellant_member_id matches")(a.appellant_member_id)(memberId);

