  typia.assert(result_admin);
  for (const a of result_admin.data) TestValidator.equals("appellant_admin_id matches")(a.appellant_admin_id)(adminId);

  // 4c. Filter by actor type (moderator)
  const result_mod = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { appellant_moderator_id: moderatorId } });
  typia.assert(result_mod);
  for (const a of result_mod.data) TestValidator.equals("appellant_moderator_id matches")(a.appellant_moderator_id)(moderatorId);

  // 4d. Filter by actor type (guest)
  const result_guest = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { appellant_guest_id: guestId } });
  typia.assert(result_guest);
  for (const a of result_guest.data) TestValidator.equals("appellant_guest_id matches")(a.appellant_guest_id)(guestId);

  // 5. Combine date range filter
  // (use min and max submitted_at in created appeals)
  const minDate = appeals.reduce((min, cur) => cur.submitted_at < min ? cur.submitted_at : min, appeals[0].submitted_at);
  const maxDate = appeals.reduce((max, cur) => cur.submitted_at > max ? cur.submitted_at : max, appeals[0].submitted_at);
  const result_daterange = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { submitted_from: minDate, submitted_to: maxDate } });
  typia.assert(result_daterange);
  // all returned appeals must be within minDate/maxDate inclusively
  for (const a of result_daterange.data) {
    TestValidator.predicate("submitted_at >= minDate")(a.submitted_at >= minDate);
    TestValidator.predicate("submitted_at <= maxDate")(a.submitted_at <= maxDate);
  }

  // 6. Paginate: set limit=2, page=1
  const result_page = await api.functional.discussionBoard.admin.appeals.search(connection, { body: { limit: 2, page: 1 } });
  typia.assert(result_page);
  TestValidator.equals("limit")(result_page.pagination.limit)(2);
  TestValidator.equals("page")(result_page.pagination.current)(1);

  // 7. Error: invalid status value
  await TestValidator.error("invalid status enum")(() => api.functional.discussionBoard.admin.appeals.search(connection, { body: { status: "foo" as any } }));
}

