/**
 * Validate enforcement of authentication (RBAC) for voting on discussion board posts.
 *
 * This test ensures that a guest or unauthenticated client is properly denied when attempting to add an upvote or downvote to an existing discussion post.
 *
 * 1. Create a member post as a normal (authenticated) member, capturing the new post's ID.
 * 2. Reset the connection (remove authentication headers) to simulate a guest/unauthenticated client.
 * 3. Attempt to vote on the post (upvote or downvote) as a guest by calling the post vote create endpoint with the target post ID.
 * 4. Assert that the system rejects the request due to lack of authentication, raising an authorization error (no token, forbidden/unauthorized response).
 */
export async function test_api_discussionBoard_test_create_post_vote_unauthenticated_fail(
  connection: api.IConnection,
) {
  // 1. Create a member post as an authenticated member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Simulate guest/unauthenticated client by removing authentication header
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  if (guestConnection.headers && guestConnection.headers["Authorization"]) {
    delete guestConnection.headers["Authorization"];
  }

  // 3. Attempt to vote on the post without authentication
  await TestValidator.error("unauthenticated guest cannot vote")(
    async () => {
      await api.functional.discussionBoard.member.posts.postVotes.create(
        guestConnection,
        {
          postId: post.id,
          body: {
            upvote: true,
          } satisfies IDiscussionBoardPostVote.ICreate,
        },
      );
    },
  );
