import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccessLog";

/**
 * Test that non-admin users cannot update access log records.
 *
 * Purpose:
 * Ensures that update operations on audit/access log records are strictly privileged and only permitted to administrators. This upholds the audit trail integrity, preventing unauthorized modifications by regular users or unauthenticated actors.
 *
 * Steps:
 * 1. Attempt to update an access log record (using a random UUID and plausible update body) without admin privileges (i.e., as an unauthenticated or non-admin session).
 * 2. Confirm that the API responds with a permission error (such as 401 Unauthorized or 403 Forbidden), blocking the operation.
 * 3. (Optionally) Validate that no access log record was updated/returned on error.
 *
 * The test does NOT require prior record creation or admin authentication, as the denial of privilege is the scenario under test.
 */
export async function test_api_discussionBoard_test_update_access_log_record_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Attempt update as a non-admin (no special credentials in connection)
  const accessLogId = typia.random<string & tags.Format<"uuid">>();
  const updateBody = {
    ip_address: "203.0.113.10",
    user_agent: "UnitTest-Agent-v1.0",
  } satisfies IDiscussionBoardAccessLog.IUpdate;

  await TestValidator.error("should block unauthorized access to audit log update")(
    async () => {
      await api.functional.discussionBoard.admin.accessLogs.update(connection, {
        accessLogId,
        body: updateBody,
      });
    },
  );
}

