/**
 * Validates advanced filtering on the suspensions endpoint for admin users.
 *
 * Business context:
 * Admins should be able to efficiently search and filter suspension/ban records by a variety of criteria such as status (active/expired/revoked), subject role types (member/moderator), specific subject IDs, and pagination options. Correct filtering supports audit, compliance, and operational needs.
 *
 * Test workflow:
 * 1. Create multiple suspensions with different statuses (active, expired) and different subject types (member and moderator IDs, with realistic test UUIDs and times).
 * 2. Query for suspensions with status = 'active' only, verify only active suspensions are returned and match correct role types and IDs.
 * 3. Query for suspensions with status = 'expired' only, check only expired ones returned.
 * 4. Query for suspensions where subject is a moderator, independently of status, verify only moderator suspensions are returned.
 * 5. Query for a specific member ID, check only suspension(s) for that member are returned.
 * 6. Test pagination: create enough suspensions to cover more than one page (using limit=2), then fetch page 1 and page 2, verify correct records and counts returned per page.
 * 7. For each filter/query, assert the content and metadata (pagination) matches the parameters given, and that sorting matches expected order if applicable.
 */
export async function test_api_discussionBoard_admin_suspensions_test_search_suspensions_by_status_and_type(connection: api.IConnection) {
  // 1. Create suspensions with different subject roles and statuses
  const testMemberId = typia.random<string & tags.Format<"uuid">>();
  const testModeratorId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();

  // Suspension for a member, active
  const memberActive = await api.functional.discussionBoard.admin.suspensions.create(connection, {
    body: {
      suspended_member_id: testMemberId,
      suspended_admin_id: null,
      suspended_moderator_id: null,
      suspended_guest_id: null,
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      moderator_id: null,
      related_report_id: null,
      related_action_id: null,
      suspended_at: now.toISOString() as string & tags.Format<"date-time">,
      ends_at: null,
      reason: "Active suspension for test member",
      status: "active"
    } satisfies IDiscussionBoardSuspension.ICreate
  });
  typia.assert(memberActive);
  // Suspension for a member, expired
  const memberExpired = await api.functional.discussionBoard.admin.suspensions.create(connection, {
    body: {
      suspended_member_id: testMemberId,
      suspended_admin_id: null,
      suspended_moderator_id: null,
      suspended_guest_id: null,
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      moderator_id: null,
      related_report_id: null,
      related_action_id: null,
      suspended_at: new Date(now.getTime() - 86400000 * 10).toISOString() as string & tags.Format<"date-time">,
      ends_at: new Date(now.getTime() - 86400000 * 5).toISOString() as string & tags.Format<"date-time">,
      reason: "Expired suspension for test member",
      status: "expired"
    } satisfies IDiscussionBoardSuspension.ICreate
  });
  typia.assert(memberExpired);
  // Suspension for a moderator, active
  const moderatorActive = await api.functional.discussionBoard.admin.suspensions.create(connection, {
    body: {
      suspended_member_id: null,
      suspended_admin_id: null,
      suspended_moderator_id: testModeratorId,
      suspended_guest_id: null,
      admin_id: null,
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      related_report_id: null,
      related_action_id: null,
      suspended_at: now.toISOString() as string & tags.Format<"date-time">,
      ends_at: null,
      reason: "Active suspension for moderator",
      status: "active"
    } satisfies IDiscussionBoardSuspension.ICreate
  });
  typia.assert(moderatorActive);
  // Suspension for a moderator, expired
  const moderatorExpired = await api.functional.discussionBoard.admin.suspensions.create(connection, {
    body: {
      suspended_member_id: null,
      suspended_admin_id: null,
      suspended_moderator_id: testModeratorId,
