  const otherMemberActive = await api.functional.discussionBoard.admin.suspensions.create(connection, {
    body: {
      suspended_member_id: otherMemberId,
      suspended_admin_id: null,
      suspended_moderator_id: null,
      suspended_guest_id: null,
