      ends_at: null,
      reason: "Another active for paging",
      status: "active"
    } satisfies IDiscussionBoardSuspension.ICreate
  });
  typia.assert(otherMemberActive);

  // 2. Query for active suspensions only
  const resActive = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      status: "active",
      page: 1,
      limit: 10,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_member_id: null,
      suspended_moderator_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resActive);
  TestValidator.predicate("all suspensions are active")(resActive.data.every(s => s.status === "active"));
  // 3. Query for expired
  const resExpired = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      status: "expired",
      page: 1,
      limit: 10,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_member_id: null,
      suspended_moderator_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resExpired);
  TestValidator.predicate("all suspensions are expired")(resExpired.data.every(s => s.status === "expired"));
  // 4. Suspensions for given moderator
  const resModerator = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      suspended_moderator_id: testModeratorId,
      status: null,
      page: 1,
      limit: 10,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_member_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resModerator);
  TestValidator.predicate("all for moderatorId")(
    resModerator.data.every(s => s.suspended_moderator_id === testModeratorId)
  );
  // 5. Member-specific suspensions
  const resMember = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      suspended_member_id: testMemberId,
      status: null,
      page: 1,
      limit: 10,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_moderator_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resMember);
  TestValidator.predicate("all for memberId")(
    resMember.data.every(s => s.suspended_member_id === testMemberId)
  );
  // 6. Pagination: fetch page 1 and 2 with limit=2 (using all suspensions, status null)
  const resPage1 = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      page: 1,
      limit: 2,
      status: null,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_member_id: null,
      suspended_moderator_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resPage1);
  TestValidator.equals("pagination-page-1-limit")(resPage1.pagination.limit)(2);
  TestValidator.equals("pagination-page-1-page")(resPage1.pagination.current)(1);
  // Page 2
  const resPage2 = await api.functional.discussionBoard.admin.suspensions.search(connection, {
    body: {
      page: 2,
      limit: 2,
      status: null,
      suspended_admin_id: null,
      suspended_guest_id: null,
      suspended_member_id: null,
      suspended_moderator_id: null,
      admin_id: null,
      moderator_id: null,
      related_action_id: null,
      related_report_id: null,
      suspended_from: null,
      suspended_to: null
    } satisfies IDiscussionBoardSuspension.IRequest
  });
  typia.assert(resPage2);
  TestValidator.equals("pagination-page-2-limit")(resPage2.pagination.limit)(2);
  TestValidator.equals("pagination-page-2-page")(resPage2.pagination.current)(2);
}

