import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * Test that updating immutable fields of an audit log entry is prevented.
 *
 * Audit log entries in the discussion board are designed to be immutable to ensure
 * forensic traceability and compliance. Certain fields like the actor fields and
 * action_type must not be changed after creation, except for very rare legal or
 * reconciliation scenarios.
 *
 * This test confirms that an attempt to update these immutable fields using the
 * update endpoint is rejected by the system. The test ensures unauthorized or non-
 * compliant updates (such as changing the actor_admin_id or action_type) are not
 * permitted, enforcing auditability and business rules.
 *
 * Steps:
 * 1. Create a new audit log entry using the create API.
 * 2. Attempt to update an immutable field (e.g., actor_admin_id or action_type) of the same entry.
 * 3. Confirm the update is rejected (error is thrown).
 */
export async function test_api_discussionBoard_admin_auditLogs_test_prevent_unauthorized_update_of_immutable_audit_log_fields(
  connection: api.IConnection,
) {
  // 1. Create a new audit log entry
  const auditLog = await api.functional.discussionBoard.admin.auditLogs.create(connection, {
    body: {
      action_id: typia.random<string & tags.Format<"uuid">>(),
      actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "delete_post",
      context: "Initial creation for immutability test",
    } satisfies IDiscussionBoardAuditLog.ICreate,
  });
  typia.assert(auditLog);

  // 2. Attempt to update an immutable field (e.g., actor_admin_id or action_type)
  await TestValidator.error("Should prevent unauthorized update of immutable audit log fields")(
    async () => {
      await api.functional.discussionBoard.admin.auditLogs.update(connection, {
        auditLogId: auditLog.id,
        body: {
          // Change `actor_admin_id` and `action_type`
          actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
          action_type: "edit_post",
        } satisfies IDiscussionBoardAuditLog.IUpdate,
      });
    },
  );
}

