 * 6. Validate that the returned comment contains the updated body, and if parent_id was changed, ensure it's correct; verify the 'updated_at' timestamp is newer than the original version.
 * 7. (If feasible, check or infer that audit/compliance controls are fulfilled via the edit trail—primarily via the 'updated_at' and possibly via other evidence.)
 *
 * Post-conditions: The test verifies that the admin was able to edit another user's comment, the change is reflected in persistent data, and modification audit is traceable.
 */
export async function test_api_discussionBoard_test_admin_can_update_any_comment_on_post(
  connection: api.IConnection,
) {
  // 1. Register a member to create post/comment
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: memberEmail,
      password_hash: memberPasswordHash,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(5),
      body: RandomGenerator.content()(3)(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Member adds a comment to the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      body: RandomGenerator.content()(2)(),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUsername = RandomGenerator.alphaNumeric(8).toLowerCase();
  const adminPasswordHash = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.discussionBoard.admin.admins.create(connection, {
