 * 3. For each vote, ensure correct linkage between vote, voter, post, and upvote status.
 * 4. Retrieve the vote list for that post as an authenticated member.
 * 5. Validate:
 *    - All votes appear in the returned list
 *    - Each vote object contains member id (voter), upvote boolean, and created_at timestamp
 *    - Upvotes/downvotes are accurate and aggregated correctly
 *    - The total number of votes matches what was cast
 *    - There are no extra or missing votes
 *
 * 6. Also include an edge test where a post has no votes; ensure the API returns zero votes with appropriate structure, not an error.
 */
export async function test_api_discussionBoard_test_list_post_votes_as_member_for_post_with_votes(
  connection: api.IConnection,
) {
