  // Create additional members and cast votes via context switching (simulate login for each member)
  const voters = [
    { upvote: true },
    { upvote: false },
    { upvote: true },
  ];
  const voteRecords: { memberId: string; vote: boolean; voteObj: any }[] = [];

  for (const voter of voters) {
    // Simulate member login here (if context switching is necessary); skipped if not required
    const voteObj = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
      postId: post.id,
      body: { upvote: voter.upvote },
    });
    typia.assert(voteObj);
    voteRecords.push({ memberId: voteObj.discussion_board_member_id, vote: voter.upvote, voteObj });
  }

  // Retrieve all votes for the post
  const votesPage = await api.functional.discussionBoard.member.posts.postVotes.index(connection, {
    postId: post.id,
  });
