 * 4. Try to create a moderation action referencing a non-existent report (expect
 *    failure).
 * 5. Try to create a moderation action with both admin_id and moderator_id
 *    null/undefined (expect failure).
 * 6. Simulate submitting a request as a non-moderator to validate RBAC denial
 *    (expect failure).
 */
export async function test_api_discussionBoard_moderator_moderationActions_test_create_moderation_action_as_moderator_with_valid_and_invalid_data(
