import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

/**
 * E2E test for searching moderation actions as an admin with complex filter and pagination.
 *
 * 1. Seed the system with a diverse set of moderation action records:
 *    - Various action types, such as 'suspend', 'edit', 'delete', etc.
 *    - Different actors (admin vs moderator); ensure at least one record per actor type
 *    - Use different report_ids to allow filtering by report as well
 *    - Set acted_at to various times to allow windowed search
 * 2. Test search by action_type:
 *    - For each action_type used above, query for that specific type and verify only correct actions returned
 * 3. Test search by admin_id and moderator_id:
 *    - For a known admin actor, query by their ID and verify return set
 *    - For a known moderator, query by their ID and verify correct filtering
 * 4. Test search by report_id:
 *    - Pick a known report, query by report_id, ensure only those results are returned
 * 5. Test combined filters:
 *    - Search with multiple filters (e.g., action_type + admin_id + report_id) and verify intersection logic
 * 6. Test pagination:
 *    - Insert more actions than a single page limit (e.g., >5)
 *    - Perform paged search and verify correct paging metadata and data sliced correctly
 * 7. For every search result set, verify:
 *    - All results match filter criteria
 *    - Pagination meta fields (current, limit, records, pages) make sense
 *    - Auditing fields (admin_id/moderator_id, acted_at, action_type, description, report_id) are present and correct
 * 8. Edge case:
 *    - Query with filter combinations that match no records; result set should be empty, meta counts correct.
 */
export async function test_api_discussionBoard_admin_moderationActions_test_search_moderation_actions_with_specific_criteria(connection: api.IConnection) {
  // 1. Seed moderation actions by creating various entries
  // (a) Create action_type, actor, and report_id diversity
  //      Examples: 2 by admin, 2 by moderator, at least 2 report_ids, types: 'suspend', 'edit', 'delete'
  //      Use fixed known values for IDs so we can search later
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const reportIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const createdActions = [
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[0], admin_id: adminId, action_type: 'suspend', description: 'Admin suspended on report 1', } }),
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[0], admin_id: adminId, action_type: 'edit', description: 'Admin edited content on report 1', } }),
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[1], moderator_id: moderatorId, action_type: 'suspend', description: 'Moderator suspended on report 2', } }),
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[1], moderator_id: moderatorId, action_type: 'delete', description: 'Moderator deleted on report 2', } }),
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[1], admin_id: adminId, action_type: 'delete', description: 'Admin deleted on report 2', } }),
  ];
  // Also generate >5 total for pagination test
  for (let i = 0; i < 3; ++i) {
    await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: { report_id: reportIds[i % 2], admin_id: adminId, action_type: 'edit', description: `Paged edit action ${i}`, } });
  }
  // 2. Search by action_type ('suspend')
  const res_actionType = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { action_type: 'suspend' } });
  typia.assert(res_actionType);
  for (const act of res_actionType.data) TestValidator.equals('action_type suspend')(act.action_type)('suspend');
  // 3. Search by admin_id
  const res_byAdmin = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { admin_id: adminId } });
  typia.assert(res_byAdmin);
  for (const act of res_byAdmin.data) TestValidator.equals('admin_id matches')(act.admin_id)(adminId);
  // 4. Search by moderator_id
  const res_byMod = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { moderator_id: moderatorId } });
  typia.assert(res_byMod);
  for (const act of res_byMod.data) TestValidator.equals('moderator_id matches')(act.moderator_id)(moderatorId);
  // 5. Search by report_id
  const res_byReport = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { report_id: reportIds[0] } });
  typia.assert(res_byReport);
  for (const act of res_byReport.data) TestValidator.equals('report_id matches')(act.report_id)(reportIds[0]);
  // 6. Combined filter: action_type + admin_id + report_id
  const res_combined = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { action_type: 'edit', admin_id: adminId, report_id: reportIds[0] } });
  typia.assert(res_combined);
  for (const act of res_combined.data) {
    TestValidator.equals('action_type is edit')(act.action_type)('edit');
    TestValidator.equals('admin_id matches')(act.admin_id)(adminId);
    TestValidator.equals('report_id matches')(act.report_id)(reportIds[0]);
  }
  // 7. Pagination: limit 2/page 2 (should slice records)
  const res_paged = await api.functional.discussionBoard.admin.moderationActions.search(connection, { body: { pagination: { limit: 2, page: 2 } } });
  typia.assert(res_paged);
  TestValidator.equals('page')(res_paged.pagination.current)(2);
  TestValidator.equals('limit')(res_paged.pagination.limit)(2);
