  for (const rec of res_byActionType.data)
    TestValidator.equals("action_type = suspend")(rec.action_type)("suspend");

  // 3. Single-filter: admin_id
  const res_byAdminId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          admin_id: adminId,
        },
      },
