  typia.assert(res_byAdminId);
  for (const rec of res_byAdminId.data)
    TestValidator.equals("admin_id match")(rec.admin_id)(adminId);

  // 4. Single-filter: moderator_id
  const res_byModeratorId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          moderator_id: moderatorId,
        },
      },
    );
  typia.assert(res_byModeratorId);
  for (const rec of res_byModeratorId.data)
    TestValidator.equals("moderator_id match")(rec.moderator_id)(moderatorId);

  // 5. Single-filter: report_id
  const res_byReportId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          report_id: reportIds[0],
        },
      },
    );
  typia.assert(res_byReportId);
  for (const rec of res_byReportId.data)
    TestValidator.equals("report_id match")(rec.report_id)(reportIds[0]);

  // 6. Combined filter: action_type + admin_id + report_id
  const res_combined =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          action_type: "edit",
          admin_id: adminId,
          report_id: reportIds[0],
        },
      },
    );
  typia.assert(res_combined);
  for (const rec of res_combined.data) {
    TestValidator.equals("action_type = edit")(rec.action_type)("edit");
    TestValidator.equals("admin_id match")(rec.admin_id)(adminId);
    TestValidator.equals("report_id match")(rec.report_id)(reportIds[0]);
  }

  // 7. Pagination: page 2, limit 2
  const res_paged =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          pagination: {
            limit: 2,
            page: 2,
          },
        },
      },
    );
  typia.assert(res_paged);
  TestValidator.equals("pagination.current=2")(res_paged.pagination.current)(2);
  TestValidator.equals("pagination.limit=2")(res_paged.pagination.limit)(2);
  TestValidator.predicate("data length <= 2")(res_paged.data.length <= 2);

  // 8. Edge: Filters matching nothing
  const res_none =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          action_type: "not-a-type",
          admin_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(res_none);
  TestValidator.equals("empty result")(res_none.data.length)(0);
  TestValidator.equals("page 1 for empty")(res_none.pagination.current)(1);

  // 9. For every result set, audit field check
  for (const res of [
    res_byActionType,
    res_byAdminId,
    res_byModeratorId,
    res_byReportId,
    res_combined,
    res_paged,
  ])
    for (const rec of res.data) {
