      TestValidator.predicate("has description")(
        typeof rec.description === "string" && rec.description.length > 0,
      );
      TestValidator.predicate("has acted_at")(
        typeof rec.acted_at === "string" && rec.acted_at.length > 0,
      );
    }
}

