import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validate that an admin can retrieve the full details of a post vote, including member-identifying and audit fields.
 *
 * Business context: In a discussion board with privacy and role-based access control, individual vote records (including who voted and when) are only fully accessible to admins and moderators. Regular members may have this information hidden or anonymized. It's important to ensure that, as an admin, all audit and identifying information is returned when querying the vote details via the admin endpoint.
 *
 * Steps:
 * 1. Create an admin account (for admin privileges and access).
 * 2. Register a member account (for post and voting capability).
 * 3. As the member, create a post.
 * 4. As the member, cast a vote on the post (upvote or downvote).
 * 5. As the admin, retrieve the post vote via GET /discussionBoard/admin/posts/{postId}/postVotes/{postVoteId}.
 * 6. Assert that all expected fields are present: postVoteId, discussion_board_post_id, discussion_board_member_id (showing voter member ID), upvote, created_at.
 * 7. Optionally validate key linkage: that the referenced post and member IDs match those created in previous steps. Audit fields must be present and match expectations, e.g., created_at is a valid ISO-8601 string.
 * 8. Explicitly confirm that the admin is able to see member-identifying information not normally available to non-admins.
 */
export async function test_api_discussionBoard_test_admin_retrieve_post_vote_details_with_privacy_check(connection: api.IConnection) {
  // 1. Create an admin account
  const adminUsername = RandomGenerator.alphabets(12);
  const admin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      username: adminUsername,
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(16),
      is_active: true
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(admin);

  // 2. Register a member
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.create(connection, {
    body: {
      display_name: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(16)
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member);

  // 3. As the member, create a post
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 4. As the member, cast a vote (upvote) on the post
  const vote: IDiscussionBoardPostVote = await api.functional.discussionBoard.member.posts.postVotes.create(connection, {
    postId: post.id,
    body: {
      upvote: true
    } satisfies IDiscussionBoardPostVote.ICreate
  });
  typia.assert(vote);

  // 5. As the admin, retrieve the post vote details
  const retrieved: IDiscussionBoardPostVote = await api.functional.discussionBoard.admin.posts.postVotes.at(connection, {
    postId: post.id,
    postVoteId: vote.id,
  });
  typia.assert(retrieved);

  // 6. Check presence and values of all expected fields
  TestValidator.equals("postVote ID matches")(retrieved.id)(vote.id);
  TestValidator.equals("linked post ID matches")(retrieved.discussion_board_post_id)(post.id);
  TestValidator.equals("voter member ID matches")(retrieved.discussion_board_member_id)(member.id);
  TestValidator.equals("vote type matches")(retrieved.upvote)(true);
  TestValidator.predicate("created_at is an ISO8601 string")(!!Date.parse(retrieved.created_at));
}

