import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Validate retrieval of notification settings for a guest session.
 *
 * This test ensures that a guest (unauthenticated, session-based user) can
 * successfully retrieve their own notification settings once a valid guest
 * session has been registered. Upon guest creation, notification settings
 * should be in place (either with system defaults or empty if not yet
 * configured). The test checks the following:
 *
 * 1. Register a new guest session using
 *    api.functional.discussionBoard.guests.create.
 * 2. Use the same connection (preserving session/token) to access notification
 *    settings via
 *    api.functional.discussionBoard.guest.notificationSettings.index.
 * 3. Assert that only one record is returned and that it belongs to the created
 *    guest (matching guest_id).
 * 4. Verify initialization: settings fields have valid defaults or initial values
 *    for a new guest account.
 * 5. Edge: If for any reason no settings exist, the test expects either an empty
 *    data array or a notification settings object with proper guest_id and
 *    default values.
 */
export async function test_api_discussionBoard_test_list_notification_settings_guest_success(
  connection: api.IConnection,
) {
  // 1. Register a new guest session
  const now = new Date().toISOString();
  const guest = await api.functional.discussionBoard.guests.create(connection, {
    body: {
      guest_ip: "127.0.0.1",
      session_token: RandomGenerator.alphabets(24),
      entered_at: now,
    },
  });
  typia.assert(guest);

  // 2. Retrieve notification settings for the session (preserving guest session in connection)
  const notifPage =
    await api.functional.discussionBoard.guest.notificationSettings.index(
      connection,
    );
  typia.assert(notifPage);

  // 3. Only the current guest's settings should be returned; verify guest_id matches
  if (notifPage.data.length > 0) {
    TestValidator.equals("single guest notification setting")(
      notifPage.data.length,
    )(1);
    TestValidator.equals("notification setting for correct guest")(
      notifPage.data[0].guest_id,
    )(guest.id);
    // 4. Check that required notification setting fields are present, with boolean defaults
    for (const key of [
      "in_app_enabled",
      "email_enabled",
      "moderation_notification_enabled",
      "reply_notification_enabled",
      "vote_notification_enabled",
    ]) {
      TestValidator.predicate(`${key} exists and is boolean`)(
        typeof notifPage.data[0][key] === "boolean",
      );
    }
  } else {
    // 5. Edge: If no settings exist, pagination data must be valid and data array empty
    TestValidator.equals("no settings for new guest")(notifPage.data.length)(0);
    TestValidator.predicate("pagination fields valid")(
      typeof notifPage.pagination.current === "number",
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that an admin can filter their notification settings by notification
 * category (moderation/reply/vote) and that pagination returns correct data.
 *
 * Business context: This test checks the admin-facing API for
 * searching/filtering notification settings. An admin should be able to
 * retrieve only those notification settings entries that match chosen
 * enablement flags (moderation, reply, vote), and response pagination metadata
 * should be accurate. Both positive and negative filter cases are checked.
 *
 * Test process:
 *
 * 1. Create an admin account for testing.
 * 2. Create several notification settings entries for the admin, each enabling
 *    only a unique notification category (moderation, reply, vote).
 * 3. For each notification type (moderation, reply, vote): a. Search by that
 *    category (enabled=true), check that returned settings have the queried
 *    category enabled and admin_id correct. b. Confirm the response is paged
 *    and paging fields are sensible.
 * 4. Negative: Search for records with all categories disabled—no results should
 *    be returned.
 */
export async function test_api_discussionBoard_test_search_notification_settings_admin_by_category(
  connection: api.IConnection,
) {
  // 1. Create an admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUsername: string = RandomGenerator.alphaNumeric(10);
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: adminUsername,
        email: adminEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Create several notification settings, each enabling only one category
  const settings = [
    // Moderation enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: true,
          email_enabled: false,
          moderation_notification_enabled: true,
          reply_notification_enabled: false,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
    // Reply enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: false,
          email_enabled: true,
          moderation_notification_enabled: false,
          reply_notification_enabled: true,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
    // Vote enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: true,
          email_enabled: true,
          moderation_notification_enabled: false,
          reply_notification_enabled: false,
          vote_notification_enabled: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
  ];
  settings.forEach(typia.assert);

  // Helper to search and validate a category
  async function filterAndValidate(
    category: keyof Pick<
      IDiscussionBoardNotificationSetting,
      | "moderation_notification_enabled"
      | "reply_notification_enabled"
      | "vote_notification_enabled"
    >,
  ) {
    const searchBody: IDiscussionBoardNotificationSetting.IRequest = {
      [category]: true,
      page: 1,
      limit: 10,
    };
    const pageResult =
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: searchBody,
        },
      );
    typia.assert(pageResult);
    for (const rec of pageResult.data) {
      TestValidator.equals(category + " enabled")(rec[category])(true);
      TestValidator.equals("admin match")(rec.admin_id)(admin.id);
    }
    TestValidator.predicate("at least one result for " + category)(
      pageResult.data.length > 0,
    );
    TestValidator.equals("pagination: page 1")(pageResult.pagination.current)(
      1,
    );
    TestValidator.equals("pagination: limit 10")(pageResult.pagination.limit)(
      10,
    );
  }

  await filterAndValidate("moderation_notification_enabled");
  await filterAndValidate("reply_notification_enabled");
  await filterAndValidate("vote_notification_enabled");

  // 4. Negative: search where all categories are disabled
  const resultNone =
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: {
          moderation_notification_enabled: false,
          reply_notification_enabled: false,
          vote_notification_enabled: false,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resultNone);
  TestValidator.equals("no results for all categories false")(
    resultNone.data.length,
  )(0);
}

