/**
 * Validate error handling in the notification settings admin search endpoint
 * when supplied with invalid filters/query parameters.
 *
 * This test ensures that the API exposes proper validation errors – not
 * internal/unexpected errors – if the admin submits search queries with:
 *
 * - Non-existent category/field filter values (e.g., passing properties that are
 *   not in the schema)
 * - Malformed request body (missing fields, extra fields, or wrong data types)
 * - Incorrectly formatted date parameters (e.g., invalid ISO 8601, numeric
 *   instead of date strings)
 *
 * The API must provide informative validation errors and must not respond with
 * 500-level errors for these cases.
 *
 * Steps:
 *
 * 1. Create an admin account to obtain credentials.
 * 2. Attempt to search notification settings as admin with various deliberately
 *    malformed requests: a. Supply a request including a non-existent property
 *    (should fail validation) b. Use strings instead of booleans for boolean
 *    filter fields c. Provide non-date values for 'created_at_from' or
 *    'created_at_to' d. Provide a negative page or limit (should fail schema
 *    validation) e. Provide structurally valid but semantically incorrect data
 *    (e.g. out-of-range pagination numbers)
 * 3. For each, verify that the API returns a validation error and not an
 *    unhandled/internal server error.
 * 4. Repeat with multiple malformed scenarios to ensure robust error handling.
 */
export async function test_api_discussionBoard_test_search_notification_settings_admin_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Create an admin account (needed for role/auth if required).
  const adminInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(12),
    is_active: true,
  } satisfies IDiscussionBoardAdmin.ICreate;
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    { body: adminInput },
  );
  typia.assert(admin);

  // 2a. Send request with a non-existent property (should fail validation).
  await TestValidator.error("search fails on extra non-existent property")(
    async () => {
      // @ts-expect-error: property 'does_not_exist' not in schema
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { does_not_exist: true },
        },
      );
    },
  );

  // 2b. Use string for boolean fields
  await TestValidator.error("search fails when boolean filters are strings")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { in_app_enabled: "yes" as unknown as boolean },
        },
      );
    },
  );

  // 2c. Provide malformed date strings
  await TestValidator.error(
    "search fails on invalid created_at_from date string",
  )(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { created_at_from: "not-a-date" as any },
      },
    );
  });
  await TestValidator.error(
    "search fails on malformed created_at_to date string",
  )(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { created_at_to: "1234567890" as any },
      },
    );
  });

  // 2d. Use negative pagination
  await TestValidator.error("search fails when page is negative")(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { page: -1 },
      },
    );
  });
  await TestValidator.error("search fails when limit is negative")(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { limit: -5 },
      },
    );
  });

  // 2e. Use excessively high pagination values
  await TestValidator.error("search fails on unreasonably large page")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { page: 999999999 },
        },
      );
    },
  );
  await TestValidator.error("search fails on unreasonably large limit")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { limit: 9999999 },
        },
      );
    },
  );
}

