 *   settings, if any).
 *
 * Negative/Failure Test:
 *
 * - If the API allows searching other's data and returns at least one setting not
 *   belonging to guest session, fail the test.
 */
export async function test_api_discussionBoard_test_guest_cannot_search_other_users_notification_settings(
  connection: api.IConnection,
) {
