/**
 * Validate that a guest user can delete their own notification and that proper
 * guest-specific RBAC policies are enforced.
 *
 * Business workflow:
 *
 * 1. Create a guest session – registers the guest (anonymous, ephemeral user type)
 *    and obtain their guestId.
 * 2. As an admin, issue a notification targeting the above guestId. This creates a
 *    notification for the guest and returns its notificationId.
 * 3. As the guest, delete the notification from their own (guest) inbox via DELETE
 *    /discussionBoard/guest/notifications/{notificationId}.
 * 4. Attempt to delete the notification again, expecting a not-found or
 *    appropriate RBAC error (verifying permanence and proper access control).
 *
 * Validates:
 *
 * - Proper association between guest session and notification (recipient).
 * - Only the notification's recipient (the guest) can delete their own
 *   notification via the guest endpoint.
 * - Notification is hard deleted: a subsequent delete attempt fails.
 * - Guest-specific RBAC is enforced (no privilege escalation).
 */
export async function test_api_discussionBoard_test_guest_delete_own_notification(
  connection: api.IConnection,
) {
  // 1. Create guest session
  const guestInput: IDiscussionBoardGuest.ICreate = {
    guest_ip: RandomGenerator.ip(),
    session_token: RandomGenerator.alphabets(16),
    entered_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const guest = await api.functional.discussionBoard.guests.create(connection, {
    body: guestInput,
  });
  typia.assert(guest);

  // 2. Admin creates a notification to this guest
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    guest_id: guest.id,
    type: "in-app",
    category: "test-case",
    message: RandomGenerator.paragraph()(),
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    delivered_at: null,
    read_at: null,
    error_message: null,
  };
  const notification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: notificationInput },
    );
  typia.assert(notification);
  TestValidator.equals("notification delivered to guest")(
    notification.guest_id,
  )(guest.id);

  // 3. Guest deletes their notification
  await api.functional.discussionBoard.guest.notifications.erase(connection, {
    notificationId: notification.id,
  });
  // If deletion succeeds (void), assertion is implicit.

  // 4. Deleting again should yield not found or error (permanence check)
  await TestValidator.error(
    "notification is hard deleted, cannot delete twice",
  )(() =>
    api.functional.discussionBoard.guest.notifications.erase(connection, {
      notificationId: notification.id,
    }),
  );
}

