/**
 * Validate that an authenticated member can retrieve all votes for a comment
 * with correct pagination and structure.
 *
 * Business context: Members can upvote or downvote comments on posts in the
 * discussion board. Each vote is an auditable record. This test ensures an
 * authenticated member can list all votes for a comment and that vote data,
 * up/down polarity, and member references are correct.
 *
 * Steps:
 *
 * 1. Register and authenticate MemberA
 * 2. MemberA creates a post
 * 3. MemberA creates a comment on their own post
 * 4. Register and authenticate MemberB
 * 5. MemberB casts an upvote on the comment
 * 6. Register and authenticate MemberC
 * 7. MemberC casts a downvote on the comment
 * 8. As MemberB, retrieve all votes for the comment
 * 9. Validate the response: proper pagination, two votes, correct upvote/downvote,
 *    comment id linkage
 */
export async function test_api_discussionBoard_test_list_all_votes_for_comment_by_member(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate MemberA (assume starting connection is unauthenticated)
  const emailA = `${RandomGenerator.alphabets(8)}a@example.com`;
  const passwordA = "Test1234!";
  // (Assume helper exists to register/login a member, or use custom mechanism if not provided)
  // Here, we start as MemberA.

  // Step 2: MemberA creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(8),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // Step 3: MemberA creates a comment on their own post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // Step 4: Simulate new authenticated session for MemberB
  const connectionB = await TestHelper.createMemberAndLoginConnection();
  // Step 5: MemberB casts an upvote on the comment
  const upvote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connectionB,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  typia.assert(upvote);

  // Step 6: Simulate new authenticated session for MemberC
  const connectionC = await TestHelper.createMemberAndLoginConnection();
  // Step 7: MemberC casts a downvote on the comment
  const downvote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
