import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that creating a post fails with invalid data on the discussion
 * board.
 *
 * This test checks input validation by attempting to create a post with various
 * kinds of invalid data:
 *
 * - Required fields are missing (title, body)
 * - The member ID is invalid (random UUID that does not exist or has invalid
 *   format)
 * - Title or body constraints are violated (empty strings and strings far longer
 *   than expected)
 *
 * The test expects that all such attempts result in validation errors and do
 * not create any post. Validation error cases are tested individually and
 * error-generation is asserted via TestValidator.error().
 *
 * Steps:
 *
 * 1. Register a valid member to obtain a member id (dependency).
 * 2. Attempt to create a post with missing title.
 * 3. Attempt to create a post with missing body.
 * 4. Attempt to create a post with empty title.
 * 5. Attempt to create a post with empty body.
 * 6. Attempt to create a post with an invalid member_id format.
 * 7. Attempt to create a post with a non-existent member_id.
 * 8. Attempt to create a post with excessively long title.
 * 9. Attempt to create a post with excessively long body. Each attempt must
 *    confirm a validation error and that no post is created.
 */
export async function test_api_discussionBoard_test_create_post_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register a valid member for test context
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(64),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: memberInput,
    },
  );
  typia.assert(member);

  // Generate a valid member id for most test cases
  const validMemberId = member.id;
  const validBody = {
    title: "Valid Title",
    body: "This is a valid post body.",
  };

  // 2. Missing title (TypeScript prevents this: override type only for negative test coverage)
  await TestValidator.error("missing title")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        // title omitted
        body: validBody.body,
        discussion_board_member_id: validMemberId,
      } as any, // Only for negative test: API should raise a validation error
    }),
  );

  // 3. Missing body (TypeScript prevents this: override type only for negative test coverage)
  await TestValidator.error("missing body")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: validBody.title,
        // body omitted
        discussion_board_member_id: validMemberId,
      } as any, // Only for negative test
    }),
  );

  // 4. Empty title
  await TestValidator.error("empty title")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: "",
        body: validBody.body,
        discussion_board_member_id: validMemberId,
      },
    }),
  );

  // 5. Empty body
  await TestValidator.error("empty body")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: validBody.title,
        body: "",
        discussion_board_member_id: validMemberId,
      },
    }),
  );

  // 6. Invalid member_id format
  await TestValidator.error("invalid member_id format")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: validBody.title,
        body: validBody.body,
        discussion_board_member_id: "INVALID-UUID",
      },
    }),
  );

  // 7. Non-existent member_id (valid UUID but does not belong to any user)
  await TestValidator.error("non-existent member_id")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: validBody.title,
        body: validBody.body,
        discussion_board_member_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    }),
  );

  // 8. Excessively long title
  await TestValidator.error("excessively long title")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.alphaNumeric(500),
        body: validBody.body,
        discussion_board_member_id: validMemberId,
      },
    }),
  );

  // 9. Excessively long body
  await TestValidator.error("excessively long body")(() =>
    api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: validBody.title,
        body: RandomGenerator.alphaNumeric(10000),
        discussion_board_member_id: validMemberId,
      },
    }),
  );
}

