/**
 * Test that updating a moderation report by specifying disallowed/immutable
 * fields fails as expected.
 *
 * This test covers the case where an admin tries to update immutable fields
 * (such as reporter info or the content reference) on a moderation report using
 * the update endpoint. According to API and DTO contracts, only business
 * workflow fields (status, category, reason, resolved_at) are allowed to be
 * updated – attempting to directly update reporter fields (reporter_admin_id,
 * reporter_member_id, etc.) or target content IDs should be rejected by
 * validation logic. The API must ensure strict immutability of those columns
 * after creation so all such attempts must fail with a clear error, and the
 * original data should remain unchanged.
 *
 * Steps:
 *
 * 1. Create a moderation report via admin endpoint (this will assign immutable and
 *    audit fields)
 * 2. Attempt to update the report by providing a body with an immutable field
 *    (e.g., reporter_admin_id or discussion_board_post_id)
 * 3. Confirm the update call fails (throws error/returns failed response)
 * 4. As no GET single endpoint exists, rely on error outcome for assurance of
 *    immutability
 */
export async function test_api_discussionBoard_admin_contentReports_test_admin_update_report_with_invalid_field_rejected(
  connection: api.IConnection,
) {
  // 1. Create a moderation report with valid fields
  const created =
    await api.functional.discussionBoard.admin.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_comment_id: null,
          content_type: "post",
          category: "spam",
          reason: "This post clearly posts spam links.",
        },
      },
    );
  typia.assert(created);

  // 2. Attempt to update with an immutable field (should be rejected at TS layer)
  await TestValidator.error("Immutable field update is rejected")(async () => {
    // The IDiscussionBoardContentReport.IUpdate DTO does NOT allow any immutable fields to be set
    // but for test coverage, simulate the client error:
    const invalidUpdate = {
      // Allowed field:
      status: "resolved",
      // @ts-expect-error - forbidden field for update
      reporter_admin_id: typia.random<string & tags.Format<"uuid">>(),
    };
    // The code below won't even compile/typecheck, but demonstrates intent
    await api.functional.discussionBoard.admin.contentReports.update(
      connection,
      {
        contentReportId: created.id,
        // @ts-expect-error - forbidden property
        body: invalidUpdate,
      },
    );
  });

  // 3. No further post-update validation possible (no read API)
}

