import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validate that moderator access can list ALL votes (including sensitive audit
 * fields) for a post.
 *
 * - Ensures audit/sensitive detail fields (voter id, timestamps) are accessible
 *   to moderator.
 * - Full business flow: create post, cast votes from multiple unique members,
 *   retrieve as moderator.
 * - Critical for compliance: moderator should see ALL votes and identities
 *   (fields that might be hidden from general users).
 *
 * Steps:
 *
 * 1. Create a new member discussion post as Member A.
 * 2. Cast votes on the post from two different members (Member B and C; one
 *    upvote, one downvote).
 * 3. Retrieve votes as moderator (via GET
 *    /discussionBoard/moderator/posts/{postId}/postVotes).
 * 4. Check that the returned votes include voter member ids, created_at
 *    timestamps, upvote booleans etc.
 * 5. Cross-check the two cast votes (from member B and C) appear in the full
 *    moderator result.
 */
export async function test_api_discussionBoard_test_list_post_votes_as_moderator_including_sensitive_fields(
  connection: api.IConnection,
) {
  // 1. Create a post as Member A
  // (Assuming a join/authenticate API exists as needed, else member context is already valid)
  const memberA_email = typia.random<string & tags.Format<"email">>();
  if (api.functional.discussionBoard.member.authenticate?.join) {
    await api.functional.discussionBoard.member.authenticate.join(connection, {
      body: {
        email: memberA_email,
        password: "1234",
        nickname: RandomGenerator.name(),
      },
    });
  }
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.content()(5)(3),
      },
    },
  );
  typia.assert(post);

  // 2. Cast votes from two other members (Member B: upvote, Member C: downvote)
  const memberB_email = typia.random<string & tags.Format<"email">>();
  if (api.functional.discussionBoard.member.authenticate?.join) {
    await api.functional.discussionBoard.member.authenticate.join(connection, {
      body: {
        email: memberB_email,
        password: "1234",
        nickname: RandomGenerator.name(),
      },
    });
  }
  // upvote from B
  const voteB =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: true },
      },
    );
  typia.assert(voteB);

  const memberC_email = typia.random<string & tags.Format<"email">>();
  if (api.functional.discussionBoard.member.authenticate?.join) {
    await api.functional.discussionBoard.member.authenticate.join(connection, {
      body: {
        email: memberC_email,
        password: "1234",
        nickname: RandomGenerator.name(),
      },
    });
  }
  // downvote from C
  const voteC =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: false },
      },
    );
  typia.assert(voteC);

  // 3. Retrieve all votes for the post as moderator (should show sensitive fields)
  // (If no moderator authentication API, assume connection is privileged)
  const result =
    await api.functional.discussionBoard.moderator.posts.postVotes.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(result);

  // 4. Check that both votes are present (with audit fields: voter id, upvote boolean, created_at)
  const voter_ids = [
    voteB.discussion_board_member_id,
    voteC.discussion_board_member_id,
  ];
  for (const voterId of voter_ids) {
    const found = result.data.find(
      (v) => v.discussion_board_member_id === voterId,
    );
    TestValidator.predicate(`vote from member ${voterId} exists`)(!!found);
    if (found) {
      TestValidator.equals("post id matches")(found.discussion_board_post_id)(
        post.id,
      );
      TestValidator.equals("created_at field present")(
        typeof found.created_at === "string",
      )(true);
      TestValidator.equals("upvote field present")(
        typeof found.upvote === "boolean",
      )(true);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardCategoryTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategoryTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategoryTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryTag";

/**
 * Test retrieving the complete list of all category-tag assignments as a
 * moderator.
 *
 * This test verifies that as a moderator, you can correctly retrieve a
 * paginated list of all category-tag assignments in the discussion board
 * system, including, but not limited to, the assignments just created for this
 * test. The function checks that all audit, access, and control policies are
 * correctly enforced:
 *
 * 1. Create a new category via the admin API to ensure a category exists.
 * 2. Create a new tag via the admin API to ensure a tag exists.
 * 3. Assign the created tag to the category as a moderator to guarantee at least
 *    one assignment exists.
 * 4. Retrieve the list of all category-tag assignments via the moderator endpoint
 *    and check that at least the record just created appears in the returned
 *    list.
 * 5. Validate that returned records have all necessary audit fields (IDs,
 *    timestamps) and IDs match the association created above.
 * 6. Test expected negative scenario: attempt to call without authentication and
 *    verify access is denied.
 *
 * Note: Because deletion and role-switching APIs are not available, soft-delete
 * and non-moderator access cannot be directly tested. DB/network error
 * simulation is not possible with current test surface.
 */
export async function test_api_discussionBoard_test_list_all_category_tag_assignments_as_moderator(
  connection: api.IConnection,
) {
  // 1. Create a new category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 2. Create a new tag
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: "#" + RandomGenerator.alphaNumeric(6),
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag);

  // 3. Assign the created tag to the category as a moderator
  const assignment =
    await api.functional.discussionBoard.moderator.categoryTags.create(
      connection,
      {
        body: {
          discussion_board_category_id: category.id,
          discussion_board_tag_id: tag.id,
        } satisfies IDiscussionBoardCategoryTag.ICreate,
      },
    );
  typia.assert(assignment);

  // 4. Retrieve the list of all category-tag assignments as a moderator
  const page =
    await api.functional.discussionBoard.moderator.categoryTags.index(
      connection,
    );
  typia.assert(page);
  TestValidator.predicate("There is at least one assignment")(
    page.data.length >= 1,
  );

  // 5. Validate that the assignment just created is present and fields are correct
  const found = page.data.find(
    (x) =>
      x.id === assignment.id &&
      x.discussion_board_category_id === category.id &&
      x.discussion_board_tag_id === tag.id,
  );
  TestValidator.predicate("Created assignment is in the result")(!!found);
  TestValidator.equals("Assignment id matches")(found?.id)(assignment.id);
  TestValidator.equals("Category id matches")(
    found?.discussion_board_category_id,
  )(category.id);
  TestValidator.equals("Tag id matches")(found?.discussion_board_tag_id)(
    tag.id,
  );
  TestValidator.predicate("created_at is ISO8601 string")(
    !!found &&
      typeof found.created_at === "string" &&
      found.created_at.includes("T"),
  );

  // 6. Attempt as unauthenticated user and confirm permission denied
  const unauthConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };
  await TestValidator.error(
    "Unauthenticated user cannot list category-tag assignments",
  )(async () => {
    await api.functional.discussionBoard.moderator.categoryTags.index(
      unauthConnection as api.IConnection,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IDiscussionBoardCategoryTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryTag";
import type { IPageIDiscussionBoardCategoryTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategoryTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering of discussion board category-tag assignments by category ID.
 *
 * This test sets up several categories and tags, assigns tags to categories,
 * and verifies that the category-tag assignment search endpoint's filter for a
 * specific category ID works correctly. Additionally, it validates that
 * pagination metadata and response integrity are correct, and that error cases
 * (invalid category IDs, lack of privilege) are handled as expected.
 *
 * Steps:
 *
 * 1. Create multiple categories to ensure variety in assignment.
 * 2. Create multiple tags for assignments.
 * 3. Assign tags to categories with at least one assignment per category (ensuring
 *    some categories have multiple tags).
 * 4. Select one of the categories and search for assignments using the PATCH
 *    /discussionBoard/admin/categoryTags endpoint with a filter for the chosen
 *    category.
 * 5. Confirm that only assignments for that category are returned, with all fields
 *    matching expectations.
 * 6. Verify pagination fields (current, limit, records, pages) are present and
 *    logical.
 * 7. Attempt search with an invalid (non-existent) category ID and confirm no
 *    assignments are returned.
 * 8. (If possible given API) Attempt search with insufficient permissions and
 *    verify access is denied (skipped if not feasible).
 */
export async function test_api_discussionBoard_admin_categoryTags_test_filter_category_tag_assignments_by_category_id(
  connection: api.IConnection,
) {
  // 1. Create multiple categories
  const categories = await Promise.all(
    ArrayUtil.repeat(3)(() =>
      api.functional.discussionBoard.admin.categories.create(connection, {
        body: {
          name: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardCategory.ICreate,
      }),
    ),
  );
  categories.forEach(typia.assert);

  // 2. Create multiple tags
  const tags = await Promise.all(
    ArrayUtil.repeat(4)(() =>
      api.functional.discussionBoard.admin.tags.create(connection, {
        body: {
          label: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
          color: "#" + typia.random<string>().slice(2, 8),
        } satisfies IDiscussionBoardTag.ICreate,
      }),
    ),
  );
  tags.forEach(typia.assert);

  // 3. Assign tags to categories (at least one tag per category, some multiple)
  const assignments: IDiscussionBoardCategoryTag[] = [];
  for (const category of categories) {
    // assign 1-2 tags randomly to each category
    const numTags = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<2>
    >();
    const chosenTags = RandomGenerator.sample(tags)(numTags);
    for (const tag of chosenTags) {
      const assignment =
        await api.functional.discussionBoard.admin.categoryTags.create(
          connection,
          {
            body: {
              discussion_board_category_id: category.id,
              discussion_board_tag_id: tag.id,
            } satisfies IDiscussionBoardCategoryTag.ICreate,
          },
        );
      typia.assert(assignment);
      assignments.push(assignment);
    }
  }

  // 4. Select a category for filtering
  const filterCategory = RandomGenerator.pick(categories);

  // 5. Search assignments filtered by category ID
  const searchResult =
    await api.functional.discussionBoard.admin.categoryTags.search(connection, {
      body: {
        discussion_board_category_id: filterCategory.id,
      } satisfies IDiscussionBoardCategoryTag.IRequest,
    });
  typia.assert(searchResult);

  // 6. Verify only assignments for the selected category are returned
  TestValidator.equals("filtered all assignments are for selected category")(
    searchResult.data.every(
      (x) => x.discussion_board_category_id === filterCategory.id,
    ),
  )(true);
  // Also validate returned assignments are a subset of our created assignments
  const expectedIds = assignments
    .filter((a) => a.discussion_board_category_id === filterCategory.id)
    .map((a) => a.id);
  const actualIds = searchResult.data.map((a) => a.id);
  TestValidator.equals("all returned assignments are those assigned in test")(
    actualIds.sort(),
  )(expectedIds.sort());

  // 7. Validate pagination fields
  typia.assert(searchResult.pagination);
  TestValidator.predicate("pagination limit >= data length")(
    searchResult.pagination.limit >= searchResult.data.length,
  );
  TestValidator.predicate("pagination current page positive")(
    searchResult.pagination.current > 0,
  );
  TestValidator.predicate("pagination records >= data length")(
    searchResult.pagination.records >= searchResult.data.length,
  );
  TestValidator.predicate("pagination pages >= 1")(
    searchResult.pagination.pages >= 1,
  );

  // 8. Search with invalid (random) category ID -- must yield no results
  const invalidCategoryId = typia.random<string & tags.Format<"uuid">>();
  const invalidResult =
    await api.functional.discussionBoard.admin.categoryTags.search(connection, {
      body: {
        discussion_board_category_id: invalidCategoryId,
      } satisfies IDiscussionBoardCategoryTag.IRequest,
    });
  typia.assert(invalidResult);
  TestValidator.equals("search with invalid category returns empty data")(
    invalidResult.data.length,
  )(0);
}

