import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Test that a moderator can update any member's post vote (approval/rejection).
 *
 * ## Business context
 *
 * Moderators may correct, reverse, or address abuse of votes. Member starts by
 * voting, and moderator flips this vote as an audit action.
 *
 * ## Steps
 *
 * 1. Register a member (simulates a new user sign up)
 * 2. Register a moderator (simulates privileged admin onboarding a new moderator)
 * 3. Member creates a post
 * 4. Member casts a vote (upvote)
 * 5. Moderator updates the member's vote to the opposite (downvote)
 * 6. Validates that vote is changed, and vote-audit fields reflect the new state
 */
export async function test_api_discussionBoard_test_moderator_updates_member_post_vote_success(
  connection: api.IConnection,
) {
  // 1. Register a member (simulate a regular user signup)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // 2. Register a moderator (simulate admin creating a privileged user)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.name(),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: moderatorEmail,
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 3. Member creates a discussion board post
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 4. Member casts an upvote for the new post
  const memberVote: IDiscussionBoardPostVote =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: {
          upvote: true,
        } satisfies IDiscussionBoardPostVote.ICreate,
      },
    );
  typia.assert(memberVote);
  TestValidator.equals("vote was upvote")(memberVote.upvote)(true);
  TestValidator.equals("vote for correct post")(
    memberVote.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("vote for correct member")(
    memberVote.discussion_board_member_id,
  )(member.id);

  // 5. Moderator updates the member's vote to downvote (to simulate abuse correction)
  const updatedVote: IDiscussionBoardPostVote =
    await api.functional.discussionBoard.moderator.posts.postVotes.update(
      connection,
      {
        postId: post.id,
        postVoteId: memberVote.id,
        body: {
          upvote: false,
        } satisfies IDiscussionBoardPostVote.IUpdate,
      },
    );
  typia.assert(updatedVote);

  // 6. Validate vote change and updated audit field
  TestValidator.equals("vote now downvote")(updatedVote.upvote)(false);
  TestValidator.equals("updated: same post ID")(
    updatedVote.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("updated: same member ID")(
    updatedVote.discussion_board_member_id,
  )(member.id);
  TestValidator.notEquals("updated_at should differ from created_at")(
    updatedVote.updated_at,
  )(memberVote.created_at);
}

