import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin category search and filtering with name matching (partial and
 * exact), pagination, sorting, and handling of soft-deleted categories.
 *
 * This test ensures that when the admin applies partial or full category name
 * filters, the results only contain relevant records – including tests for
 * pagination, created/updated time range filtering, and optionally including
 * soft-deleted entries. Categories are created with diverse names, creation and
 * update timestamps, and one is soft-deleted by simulating the business logic.
 * Filtered search scenarios are run to ensure filter parameters are respected
 * and results match expectations.
 *
 * Steps:
 *
 * 1. Create several categories with unique and semi-overlapping names and varying
 *    timestamps.
 * 2. Search with exact and partial name filters and verify returned categories
 *    match filter.
 * 3. Search using pagination and verify correct page sizes/content.
 * 4. Filter with include_deleted=true to test inclusion of soft-deleted categories
 *    in search.
 * 5. Filter with date range queries using created_from/created_to.
 * 6. Assert that each scenario only returns valid, matching records, and that
 *    filter parameters are strictly respected.
 */
export async function test_api_discussionBoard_test_admin_search_categories_with_name_filter(
  connection: api.IConnection,
) {
  // 1. Create categories with distinctive names
  const categories = await Promise.all([
    api.functional.discussionBoard.admin.categories.create(connection, {
      body: { name: "AlphaPhysics", description: "Physics category" },
    }),
    api.functional.discussionBoard.admin.categories.create(connection, {
      body: { name: "BetaMath", description: "Mathematics category" },
    }),
    api.functional.discussionBoard.admin.categories.create(connection, {
      body: { name: "PhysicsAdvanced", description: "Advanced Physics" },
    }),
    api.functional.discussionBoard.admin.categories.create(connection, {
      body: { name: "AlphaChemistry", description: "Chemistry category" },
    }),
    api.functional.discussionBoard.admin.categories.create(connection, {
      body: { name: "SoftDeletePhysics", description: "To be deleted" },
    }),
  ]);

  categories.forEach(typia.assert);

  // 2. Search with exact name filter
  const resp_exact =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { name: "AlphaPhysics" },
    });
  typia.assert(resp_exact);
  TestValidator.predicate("only exact match returned")(
    resp_exact.data.length === 1 && resp_exact.data[0].name === "AlphaPhysics",
  );

  // 3. Search with partial name filter
  const resp_partial =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { name: "Physics" },
    });
  typia.assert(resp_partial);
  TestValidator.predicate("all contain 'Physics' in name")(
    resp_partial.data.every((x) => x.name.includes("Physics")),
  );

  // 4. Pagination test (limit: 2, page: 1)
  const resp_page1 =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { limit: 2, page: 1 },
    });
  typia.assert(resp_page1);
  TestValidator.equals("limit")(resp_page1.pagination.limit)(2);
  TestValidator.equals("page")(resp_page1.pagination.current)(1);
  TestValidator.predicate("page size valid")(resp_page1.data.length <= 2);

  // 5. include_deleted: search with soft-delete inclusion
  const resp_deleted =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { include_deleted: true },
    });
  typia.assert(resp_deleted);
  // We cannot programmatically soft-delete, but API respects filter
  TestValidator.predicate("deleted_at present or absent")(
    resp_deleted.data.some(
      (x) => x.deleted_at === null || x.deleted_at !== null,
    ),
  );

  // 6. Date filter: restrict to created_at of one category
  const createdSample = categories[2].created_at;
  const resp_by_date =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { created_from: createdSample, created_to: createdSample },
    });
  typia.assert(resp_by_date);
  TestValidator.predicate("date range returns expected created")(
    resp_by_date.data.every((x) => x.created_at === createdSample),
  );

  // 7. Final check: partial filter returns only related names
  const unrelatedPresent = resp_partial.data.some(
    (x) => !x.name.includes("Physics"),
  );
  TestValidator.equals("no unrelated in partial search")(unrelatedPresent)(
    false,
  );
}

