/**
 * Validates that a guest session cannot update another guest's notification
 * settings.
 *
 * This test ensures that notification setting modification is allowed only by
 * the session that owns it. When a guest attempts to modify a notification
 * setting belonging to a different guest session, the update is rejected,
 * enforcing strict notification preference isolation among guests.
 *
 * Steps:
 *
 * 1. Register guest session A, and create notification settings for it.
 * 2. Register guest session B (distinct session).
 * 3. Attempt to update notification settings created by session A using B's
 *    identity/context.
 * 4. Confirm that the operation is denied (error is thrown), ensuring system
 *    integrity against cross-session manipulation.
 */
export async function test_api_discussionBoard_test_guest_update_fails_on_unowned_setting(
  connection: api.IConnection,
) {
  // 1. Register guest session A
  const guestA = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: RandomGenerator.ip(),
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestA);

  // 2. Create notification settings for guestA
  const notificationSetting =
    await api.functional.discussionBoard.guest.notificationSettings.create(
      connection,
      {
        body: {
          guest_id: guestA.id,
          admin_id: null,
          moderator_id: null,
          member_id: null,
          in_app_enabled: true,
          email_enabled: false,
          moderation_notification_enabled: true,
          reply_notification_enabled: true,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    );
  typia.assert(notificationSetting);

  // 3. Register guest session B (ensure different identity)
  const guestB = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: RandomGenerator.ip(),
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestB);

  // 4. As guest B, attempt to update notification setting that belongs to guestA
  TestValidator.error(
    "unowned notification settings cannot be updated by different guest",
  )(async () => {
    await api.functional.discussionBoard.guest.notificationSettings.update(
      connection,
      {
        notificationSettingId: notificationSetting.id,
        body: {
          guest_id: guestB.id,
          in_app_enabled: false,
        } satisfies IDiscussionBoardNotificationSetting.IUpdate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
