import type { IPageIDiscussionBoardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardBoardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin search, filter and pagination for board settings.
 *
 * This test checks whether an admin can search and paginate board settings
 * records using various search criteria—filtering by title substring, enabled
 * status, and date ranges. Partial matches and pagination (page/limit) are
 * included. The test ensures that the API supports the configuration management
 * needs for admin roles and that only correct records are returned for each
 * filter.
 *
 * Steps:
 *
 * 1. Create multiple board setting records with diverse attributes (title, enabled
 *    flag, dates)
 * 2. Search with title substring filter (case-insensitive)
 * 3. Search filtering for enabled/disabled status
 * 4. Search filtering using created_at date range
 * 5. Search with multiple criteria combined
 * 6. Use pagination (page/limit) to test results splitting
 * 7. For each search, assert response contains only records matching the filter
 *    and pagination info is correct
 */
export async function test_api_discussionBoard_admin_boardSettings_test_search_board_settings_with_valid_criteria(
  connection: api.IConnection,
) {
  // Step 1. Create diverse board settings
  const records = await Promise.all([
    api.functional.discussionBoard.admin.boardSettings.create(connection, {
      body: {
        title: "Support Board",
        enabled: true,
        description: "Get help and support",
        logo_uri: null,
      },
    }),
    api.functional.discussionBoard.admin.boardSettings.create(connection, {
      body: {
        title: "General Discussion",
        enabled: false,
        description: "Random conversations",
        logo_uri: null,
      },
    }),
    api.functional.discussionBoard.admin.boardSettings.create(connection, {
      body: {
        title: "Announcements",
        enabled: true,
        description: "Official news and announcements",
        logo_uri: null,
      },
    }),
  ]);
  records.forEach(typia.assert);

  // Step 2. Title substring search (case-insensitive)
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            title: "support",
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Title filter matches only records with substring")(
      output.data.every((row) => row.title.toLowerCase().includes("support")),
    );
  }

  // Step 3. Enabled status filtering
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            enabled: false,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Enabled filter matches only disabled records")(
      output.data.every((row) => row.enabled === false),
    );
  }

  // Step 4. Created_at date range filtering (using a known created_at)
  {
    // For real implementation: use specific dates; here, pick from created record
    const from = records[0].created_at;
    const output =
