import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Validate moderator or admin updating a member suspension to 'expired'.
 *
 * Simulates a real moderation workflow:
 *
 * 1. Admin creates a suspension/ban for a member.
 * 2. Moderator updates the suspension's status to 'expired' (for an appeal or time
 *    lapse).
 * 3. Verifies the update succeeded and audit/compliance fields remain correct.
 * 4. Checks correct error handling for:
 *
 *    - Invalid status value
 *    - Update attempt of non-existent suspension ID
 *
 * Only API endpoints and DTO fields explicitly provided are used. Only runtime
 * business errors for invalid payloads/IDs are tested (no TS type errors).
 *
 * Steps:
 *
 * 1. Create a valid suspension as admin.
 * 2. Update its status to 'expired' as moderator.
 * 3. Assert status is updated, audit/actor references persist, and mutable fields
 *    behave.
 * 4. Negative: Updating with business-invalid status returns error.
 * 5. Negative: Updating with non-existent UUID returns error.
 */
export async function test_api_discussionBoard_moderator_suspensions_test_update_suspension_status_to_expired_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create a suspension record as admin (prerequisite)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const suspensionCreate: IDiscussionBoardSuspension.ICreate = {
    suspended_admin_id: null,
    suspended_moderator_id: null,
    suspended_member_id: memberId,
    suspended_guest_id: null,
    admin_id: adminId,
    moderator_id: null,
    related_report_id: null,
    related_action_id: null,
    suspended_at: new Date().toISOString(),
    ends_at: new Date(Date.now() + 3600_000).toISOString(),
    reason: "Serious violation of rules.",
    status: "active",
  };
  const created = await api.functional.discussionBoard.admin.suspensions.create(
    connection,
    { body: suspensionCreate },
  );
  typia.assert(created);

  // 2. Update suspension status to 'expired'
  const updateBody: IDiscussionBoardSuspension.IUpdate = {
    status: "expired",
    reason: "Ban ended after appeal.",
    ends_at: new Date().toISOString(),
  };
  const updated =
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: updateBody,
      },
    );
  typia.assert(updated);

  // 3. Audit & compliance field assertions
  TestValidator.equals("suspension id")(updated.id)(created.id);
  TestValidator.equals("member target")(updated.suspended_member_id)(memberId);
  TestValidator.equals("admin reference")(updated.admin_id)(adminId);
  TestValidator.equals("status is expired")(updated.status)("expired");
  TestValidator.equals("reason updated")(updated.reason)(
    "Ban ended after appeal.",
  );
  TestValidator.equals("ends_at updated")(typeof updated.ends_at === "string")(
    true,
  );

  // 4. Error: invalid status value (business rule, not TS error)
  await TestValidator.error("invalid status should fail")(async () => {
    // @ts-expect-error - intentional for runtime negative test (not for TS type validation)
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: {
          status: "not_a_valid_status" as any,
        },
      },
    );
  });

  // 5. Error: update non-existent suspension
  await TestValidator.error("non-existent suspension id fails")(async () => {
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: typia.random<string & tags.Format<"uuid">>(),
        body: { status: "expired" },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostCategory";

/**
 * Test that a member can retrieve all category assignments for a post they have
 * authored (GET /discussionBoard/member/posts/{postId}/postCategories)
 *
 * Business context: Ensures that once a member creates a post and associates
 * one or more categories to that post, they are able to correctly fetch all
 * their category assignments via the corresponding endpoint. This validates the
 * integrity of the post-category relationship, correct assignment, and API
 * output for member workflows (e.g., detail/edit view, moderation visibility,
 * filtering options, and UI chips/tags).
 *
 * Step-by-step process:
 *
 * 1. Create a member account (for authoring the post).
 * 2. Create a new discussion board post using this member account.
 * 3. As an admin, create multiple categories (at least 2) that can be assigned to
 *    posts.
 * 4. As the member, assign each category created in step 3 to the new post
 *    (creating post-category junctions for each).
 * 5. Fetch all category assignments for the post using the GET endpoint.
 * 6. Verify that all assigned categories are returned (the set matches all those
 *    assigned) with proper metadata (id, post id, category id).
 */
export async function test_api_discussionBoard_test_list_post_categories_for_member(
  connection: api.IConnection,
) {
  // 1. Create a member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32); // Simulate secure hash
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // 2. Create a post by this member
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 3. As admin, create multiple categories (simulate with 2 categories)
  const categories: IDiscussionBoardCategory[] = [];
  for (let i = 0; i < 2; ++i) {
    const category =
      await api.functional.discussionBoard.admin.categories.create(connection, {
        body: {
          name: RandomGenerator.alphabets(8),
          description: RandomGenerator.paragraph()(false),
        } satisfies IDiscussionBoardCategory.ICreate,
      });
    typia.assert(category);
    categories.push(category);
  }

  // 4. Assign each category to the post
  const assignments: IDiscussionBoardPostCategory[] = [];
  for (const category of categories) {
    const assignment =
      await api.functional.discussionBoard.member.posts.postCategories.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            discussion_board_category_id: category.id,
          } satisfies IDiscussionBoardPostCategory.ICreate,
        },
      );
    typia.assert(assignment);
    assignments.push(assignment);
  }

  // 5. Fetch all category assignments for the post
  const result: IDiscussionBoardPostCategory.ISummary[] =
    await api.functional.discussionBoard.member.posts.postCategories.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(result);

  // 6. Verify output matches the assigned categories
  // Check that all category assignments are present (by category id)
  const resultCategoryIds = result
    .map((a) => a.discussion_board_category_id)
    .sort();
  const assignedCategoryIds = assignments
    .map((a) => a.discussion_board_category_id)
    .sort();
  TestValidator.equals("category assignment count")(result.length)(
    assignments.length,
  );
  TestValidator.equals("category assignment ids")(resultCategoryIds)(
    assignedCategoryIds,
  );

  // Check that post ids and record ids are correct
  for (const assignment of result) {
    TestValidator.equals("post id match")(assignment.discussion_board_post_id)(
      post.id,
    );
    TestValidator.predicate("assignment id format")(
      !!assignment.id && typeof assignment.id === "string",
    );
  }
}

