import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccessLog";

/**
 * Test creation failure for access log entry with missing required fields.
 *
 * This test verifies that the system enforces required field validation when
 * attempting to create a new audit log. It attempts to create access log
 * entries with missing or incomplete "required" fields and expects validation
 * errors to be thrown by the API, thereby ensuring data integrity. It also
 * ensures that no partial records are created for invalid inputs.
 *
 * Steps:
 *
 * 1. Attempt to create an access log with no body (all fields missing).
 * 2. Attempt creation with each required field (accessed_at, http_method,
 *    endpoint, result) missing in turn, ensuring validation errors.
 * 3. Assert that the API throws a validation error for each failure; no log record
 *    should be created if required data is missing.
 */
export async function test_api_discussionBoard_admin_accessLogs_test_create_access_log_entry_with_missing_fields(
  connection: api.IConnection,
) {
  // 1. Attempt creation with an entirely empty body
  await TestValidator.error("missing all required fields should fail")(
    async () => {
      // Intentionally sending empty object to provoke validation
      // @ts-expect-error: Missing required fields for e2e validation test
      await api.functional.discussionBoard.admin.accessLogs.create(connection, {
        body: {},
      });
    },
  );

  // 2. Enumerate required fields (accessed_at, http_method, endpoint, result)
  //    Attempt creation with each one missing
  const minimalValid: IDiscussionBoardAccessLog.ICreate = {
    accessed_at: typia.random<string & tags.Format<"date-time">>(),
    http_method: "POST",
    endpoint: "/discussionBoard/admin/accessLogs",
    result: "success",
  };

  for (const key of ["accessed_at", "http_method", "endpoint", "result"]) {
    const testPayload = { ...minimalValid };
    delete testPayload[key as keyof typeof testPayload];
    await TestValidator.error(`missing required field '${key}' should fail`)(
      async () => {
        // Intentionally missing a field to test validation enforcement
        // @ts-expect-error: Missing required fields for e2e validation test
        await api.functional.discussionBoard.admin.accessLogs.create(
          connection,
          {
            body: testPayload,
          },
        );
      },
    );
  }
}

