import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAppeal";

/**
 * Validate the enforcement of required fields when submitting an appeal as a
 * member.
 *
 * Tests that submitting an appeal without the required 'reason' field results
 * in a validation error and no appeal is created.
 *
 * 1. Create a valid moderation action (as dependency)
 * 2. Attempt to submit an appeal as a member omitting the 'reason' field
 * 3. Assert the API responds with a validation error indicating the missing
 *    'reason'
 */
export async function test_api_discussionBoard_test_member_appeal_with_missing_reason_is_rejected(
  connection: api.IConnection,
) {
  // 1. Create a valid moderation action as dependency
  const moderationAction =
    await api.functional.discussionBoard.moderator.moderationActions.create(
      connection,
      {
        body: {
          report_id: typia.random<string & tags.Format<"uuid">>(),
          admin_id: null,
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
          action_type: "edit",
          description:
            "Automated moderation action for appeal validation test.",
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationAction);

  // 2. Attempt to submit an appeal with 'reason' omitted (should trigger validation error)
  await TestValidator.error(
    "Appeal submission without required 'reason' must fail validation",
  )(() =>
    api.functional.discussionBoard.member.appeals.create(connection, {
      body: {
        action_id: moderationAction.id,
        // reason is purposefully omitted to trigger server-side validation
        status: "pending",
        appellant_admin_id: null,
        appellant_moderator_id: null,
        appellant_member_id: typia.random<string & tags.Format<"uuid">>(),
        appellant_guest_id: null,
      },
    }),
  );

  // 3. There is no available API to query appeals directly and confirm none were created,
  // so validation is based on error response only.
}

