import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validates that a discussion board member can successfully update their own
 * profile fields with valid data.
 *
 * This test simulates the typical workflow in which a user creates an account
 * and then updates their profile fields. It ensures that after registration, a
 * member can modify editable profile attributes (display_name, password_hash).
 * The test updates both values and verifies that updates are successful and
 * compliant with API response expectations (i.e., sensitive info like
 * password_hash is not returned in the profile).
 *
 * Steps:
 *
 * 1. Register a new member account with a unique display name, email, and password
 *    hash.
 * 2. Perform a profile update (change display_name and password_hash).
 * 3. Validate that the returned profile reflects the new display_name and omits
 *    sensitive fields.
 */
export async function test_api_discussionBoard_member_members_test_update_own_member_profile_with_valid_data(
  connection: api.IConnection,
) {
  // Step 1: Register a new member.
  const memberCreationInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: memberCreationInput,
    },
  );
  typia.assert(member);

  // Step 2: Update the member's display_name and password_hash using their own ID.
  const newDisplayName = RandomGenerator.name();
  const newPasswordHash = RandomGenerator.alphaNumeric(64);
  const updateInput: IDiscussionBoardMember.IUpdate = {
    display_name: newDisplayName,
    password_hash: newPasswordHash,
  };
  const updated = await api.functional.discussionBoard.member.members.update(
    connection,
    {
      memberId: member.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // Step 3: Assertions. The display_name must match, id must be unchanged, sensitive fields like password_hash are omitted.
  TestValidator.equals("display_name updated")(updated.display_name)(
    newDisplayName,
  );
  TestValidator.equals("member id unchanged")(updated.id)(member.id);
  TestValidator.equals("password_hash not present")(undefined)(
    updated.password_hash,
  );
}

