import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate that a guest cannot update another guest's notification
 * (cross-session authorization boundary).
 *
 * This test ensures strict privacy and session isolation controls for
 * notification updates in the discussion board:
 *
 * - Only the guest session assigned as notification recipient may update (e.g.,
 *   mark as read) their notifications
 * - Any attempt to update another guest's notification must be denied
 *   (forbidden/unauthorized)
 *
 * Why: This is crucial for privacy, anti-abuse, and regulatory
 * compliance—preventing users from interfering with others' notifications.
 *
 * **Workflow:**
 *
 * 1. Register Guest A (captures guestAId for notification recipient)
 * 2. Register Guest B (captures guestBId to simulate actor)
 * 3. Admin issues notification for Guest A
 * 4. Admin issues notification for Guest B (control)
 * 5. Simulate Guest B's context and attempt to update Guest A's notification
 *    (should be forbidden)
 *
 * The negative result (forbidden/unauthorized) confirms correct access policy
 * is enforced.
 */
export async function test_api_discussionBoard_guest_notifications_test_update_guest_notification_without_permission(
  connection: api.IConnection,
) {
  // 1. Register Guest A with separate session
  const guestA = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: RandomGenerator.ip(),
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestA);
  const guestAId = guestA.id;

  // 2. Register Guest B (different session)
  const guestB = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: RandomGenerator.ip(),
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestB);
  const guestBId = guestB.id;

  // 3. Admin delivers a notification to Guest A
  const notificationA =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          guest_id: guestAId,
          type: "in-app",
          category: "test-cat",
          message: "You have a new notification as Guest A.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(notificationA);

  // 4. Admin delivers a notification to Guest B (for parity/control)
  const notificationB =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          guest_id: guestBId,
          type: "in-app",
          category: "test-cat",
          message: "You have a notification as Guest B.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(notificationB);

  // 5. Attempt to update Guest A's notification using Guest B (should fail with forbidden/unauthorized)
  // Assumption: The backend uses session context or token in the connection to identify guest
  await TestValidator.error("cross-session update forbidden")(() =>
    api.functional.discussionBoard.guest.notifications.update(connection, {
      notificationId: notificationA.id,
      body: {
        is_read: true,
      } satisfies IDiscussionBoardNotification.IUpdate,
    }),
  );
}

