import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Attempt to access a specific suspension's detail with insufficient privileges
 * (e.g., as a regular member or guest).
 *
 * This test ensures that the API endpoint for retrieving a suspension's full
 * detail enforces RBAC: sensitive information about suspensions cannot be
 * accessed by unauthorized roles. Both unauthenticated (guest) users and
 * authenticated non-admin members must be forbidden from accessing this
 * resource.
 *
 * Process Outline:
 *
 * 1. Attempt access to a known suspension id as an unauthenticated guest.
 *
 *    - The API must reject the request and throw an error (forbidden or unauthorized
 *         response).
 * 2. Attempt access as a regular member: simulate by inserting a fake member token
 *    (no member authentication API provided).
 *
 *    - Again, the API must reject the request and throw an error (forbidden
 *         response).
 *
 * This covers core negative path RBAC enforcement on this admin endpoint.
 */
export async function test_api_discussionBoard_test_get_suspension_detail_forbidden_for_non_admin(
  connection: api.IConnection,
) {
  // Generate a random suspension id (as required by all test cases)
  const suspensionId: string = typia.random<string & tags.Format<"uuid">>();

  // 1. Attempt to access as a guest (unauthenticated: remove Authorization header)
  await TestValidator.error("should forbid guest access")(async () => {
    await api.functional.discussionBoard.admin.suspensions.at(
      {
        ...connection,
        headers: { ...connection.headers, Authorization: undefined },
      },
      { suspensionId },
    );
  });

  // 2. Attempt to access as a regular member (simulate with fake token; no member auth API available)
  const fakeMemberToken = "Bearer " + typia.random<string>();
  await TestValidator.error("should forbid normal member access")(async () => {
    await api.functional.discussionBoard.admin.suspensions.at(
      {
        ...connection,
        headers: { ...connection.headers, Authorization: fakeMemberToken },
      },
      { suspensionId },
    );
  });
}

