import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Test searching for moderators by admin promoter using PATCH filter endpoint
 *
 * This test validates that the moderator search PATCH endpoint correctly
 * filters moderators according to their promoted_by_admin_id — that is, the
 * admin who promoted the moderator. This is essential for audit tracking and
 * admin visibility workflows. The test covers three cases: moderators promoted
 * by adminA, adminB, and legacy/manual entries with no promoter recorded.
 *
 * Steps:
 *
 * 1. Generate UUIDs for two fake admin accounts (adminA & adminB) acting as
 *    promoters
 * 2. Create several moderators:
 *
 *    - Two with promoted_by_admin_id = adminA
 *    - One with promoted_by_admin_id = adminB
 *    - One with no promoted_by_admin_id (legacy/manual)
 * 3. Use the PATCH search endpoint to query for moderators with promoter adminA
 *
 *    - Verify all returned entries have promoted_by_admin_id === adminA
 *    - Verify no results for adminB or legacy moderator
 * 4. Repeat PATCH query for adminB, expect only their moderator appears
 * 5. PATCH query for null promoted_by_admin_id, only legacy/manual appears
 */
export async function test_api_discussionBoard_test_search_moderators_by_promoter(
  connection: api.IConnection,
) {
  // 1. Prepare two unique admin IDs
  const adminAId: string = typia.random<string & tags.Format<"uuid">>();
  const adminBId: string = typia.random<string & tags.Format<"uuid">>();

  // 2a. Moderators promoted by adminA
  const modA1 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modA1);
  const modA2 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modA2);

  // 2b. Moderator promoted by adminB
  const modB = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminBId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modB);

  // 2c. Legacy/manual moderator with no promoted_by_admin_id
  const modLegacy =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        // promoted_by_admin_id omitted on purpose
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(modLegacy);

  // 3. Search moderators promoted by adminA
  const resA = await api.functional.discussionBoard.moderator.moderators.patch(
    connection,
    {
      body: {
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.IRequest,
    },
  );
  typia.assert(resA);
  TestValidator.predicate("every returned moderator was promoted by adminA")(
    resA.data.every((m) => m.promoted_by_admin_id === adminAId),
  );
  TestValidator.predicate(
    "no moderator promoted by adminB or legacy appears in adminA's results",
  )(resA.data.every((m) => m.promoted_by_admin_id === adminAId));

  // 4. Search moderators promoted by adminB
  const resB = await api.functional.discussionBoard.moderator.moderators.patch(
    connection,
    {
      body: {
        promoted_by_admin_id: adminBId,
      } satisfies IDiscussionBoardModerator.IRequest,
    },
  );
  typia.assert(resB);
  TestValidator.predicate("every returned moderator was promoted by adminB")(
    resB.data.every((m) => m.promoted_by_admin_id === adminBId),
  );

  // 5. Search for legacy/manual moderators (with no promoted_by_admin_id)
  const resLegacy =
    await api.functional.discussionBoard.moderator.moderators.patch(
      connection,
      {
        body: {
          promoted_by_admin_id: undefined,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resLegacy);
  TestValidator.predicate("all legacy moderators have no promoted_by_admin_id")(
    resLegacy.data.every((m) => !m.promoted_by_admin_id),
  );
}

