import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate error handling when attempting to create a moderator notification
 * with missing required fields.
 *
 * This test ensures that creating a notification as a moderator without
 * providing required fields, such as recipient (e.g., no admin_id,
 * moderator_id, member_id, or guest_id specified), type, category, or message,
 * is properly rejected by the API. The endpoint should respond with a 400 Bad
 * Request and provide validation error feedback.
 *
 * Steps:
 *
 * 1. Construct a valid IDiscussionBoardNotification.ICreate object, then
 *    intentionally omit one or more required properties (e.g., recipient or
 *    message).
 * 2. Attempt to call api.functional.discussionBoard.moderator.notifications.create
 *    with the incomplete body as a moderator.
 * 3. Verify that the API responds with a 400 Bad Request error.
 * 4. Confirm that an error is thrown and that type assertion/validation for error
 *    handling occurs.
 */
export async function test_api_discussionBoard_test_create_moderator_notification_missing_required_field(
  connection: api.IConnection,
) {
  // 1. Prepare: Build a notification body missing the "recipient" (all recipient IDs undefined) and the message
  const bodyMissingRecipientAndMessage: IDiscussionBoardNotification.ICreate = {
    // Omitting all recipient fields
    // admin_id: undefined, moderator_id: undefined, member_id: undefined, guest_id: undefined,
    type: "in-app",
    category: "moderation_event",
    // message is omitted
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };

  // 2. Attempt to create, expecting an error
  await TestValidator.error("missing recipient and message should fail")(
    async () => {
      await api.functional.discussionBoard.moderator.notifications.create(
        connection,
        {
          body: bodyMissingRecipientAndMessage,
        },
      );
    },
  );

  // 3. Also test missing only "message" field (recipient given)
  const bodyMissingMessage: IDiscussionBoardNotification.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    type: "in-app",
    category: "moderation_event",
    // message is omitted
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };

  await TestValidator.error("missing message should fail")(async () => {
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: bodyMissingMessage,
      },
    );
  });

  // 4. Also test missing only recipient fields (message given)
  const bodyMissingRecipient: IDiscussionBoardNotification.ICreate = {
    // All recipient IDs omitted
    type: "in-app",
    category: "moderation_event",
    message: "Test notification message.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };

  await TestValidator.error("missing recipient should fail")(async () => {
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: bodyMissingRecipient,
      },
    );
  });
}

