import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate error handling when attempting to create a moderator notification
 * with missing required fields.
 *
 * This test ensures that creating a notification as a moderator without
 * providing required fields, such as recipient (e.g., no admin_id,
 * moderator_id, member_id, or guest_id specified), type, category, or message,
 * is properly rejected by the API. The endpoint should respond with a 400 Bad
 * Request and provide validation error feedback.
 *
 * Steps:
 *
 * 1. Construct a valid IDiscussionBoardNotification.ICreate object, then
 *    intentionally set all recipient fields to null (simulating missing recipient).
 * 2. Attempt to call api.functional.discussionBoard.moderator.notifications.create
 *    with the invalid body as a moderator.
 * 3. Verify that the API responds with a 400 Bad Request error.
 * 4. Also, test message as an empty string, if business rules require non-empty message.
 * 5. Confirm that error(s) are thrown and type assertion/validation for error
 *    handling occurs.
 */
export async function test_api_discussionBoard_test_create_moderator_notification_missing_required_field(
  connection: api.IConnection,
) {
  // 1. All recipients missing (null), which violates backend expectation for at least one recipient
  const bodyMissingAllRecipients: IDiscussionBoardNotification.ICreate = {
    admin_id: null,
    moderator_id: null,
    member_id: null,
    guest_id: null,
    type: "in-app",
    category: "moderation_event",
    message: "Some notification message.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };

  await TestValidator.error("missing all recipient IDs should fail")(async () => {
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: bodyMissingAllRecipients,
      },
    );
  });

  // 2. message is empty string; backend might reject as invalid if business logic enforced
  const bodyEmptyMessage: IDiscussionBoardNotification.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    type: "in-app",
    category: "moderation_event",
    message: "", // Intentionally empty
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };

  await TestValidator.error("empty message should fail if backend requires non-empty message")(async () => {
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: bodyEmptyMessage,
      },
    );
  });
}

