import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Test that requesting the comment edit history for a comment with no edits
 * returns an empty collection.
 *
 * Business context: Edit histories for discussion board comments must only
 * exist if a member (or moderator) has actually edited content. This test
 * ensures that when a new comment is created and not subsequently modified, the
 * comment edit audit trail is empty. This protects against phantom or automatic
 * edit records and ensures compliance with auditability requirements.
 *
 * Test workflow:
 *
 * 1. Register a new discussion board member (the comment author)
 * 2. As that member, create a new post
 * 3. As that member, add a new comment to that post (no edits performed)
 * 4. Fetch the edit history for this comment
 * 5. Assert that the response is an empty list (no edit events present)
 */
export async function test_api_discussionBoard_test_list_comment_edit_history_for_comment_with_no_edits_returns_empty(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member (for authoring the post/comment)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPasswordHash = RandomGenerator.alphabets(20);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // (Assume the next actions are performed as this member; authentication context managed by SDK or test harness)

  // 2. Create a new post as the member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add a new comment to the post (no edits performed yet)
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          parent_id: null,
          body: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Fetch the edit history for this comment
  const editHistory: IDiscussionBoardCommentEdit.ISummary[] =
    await api.functional.discussionBoard.member.comments.commentEdits.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(editHistory);

  // 5. Assert that the edit history is an empty list
  TestValidator.equals(
    "Edit history should be empty for a never-edited comment",
  )(editHistory)([]);
}

