import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Ensure that only the author/editor, admin, or moderator can access the
 * detailed edit information for a post's edit event.
 *
 * This test verifies that another unrelated member (not the post author nor an
 * admin/moderator) cannot retrieve details of a post edit and receives a
 * forbidden/error response. The workflow prepares a post authored and edited by
 * one member and attempts retrieval with a different member's account.
 *
 * Steps:
 *
 * 1. Register the post creator member.
 * 2. As the creator, make a post.
 * 3. As the creator, make an edit to the post (produces postEditId).
 * 4. Register a second, unrelated member (non-admin/non-editor).
 * 5. Attempt to use the unrelated member to fetch details for the post edit via
 *    admin endpoint.
 * 6. Validate that access is forbidden, and an error (HTTP 403 or similar) is
 *    thrown.
 */
export async function test_api_discussionBoard_test_retrieve_post_edit_details_forbidden_for_non_admin_or_unrelated_user(
  connection: api.IConnection,
) {
  // 1. Register the post creator member
  const creator: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(creator);

  // 2. As the creator, make a post
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(2, 8),
        body: RandomGenerator.content()(2, 16)(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 3. As the creator, make an edit on the post to establish a postEditId
  const edit: IDiscussionBoardPostEdit =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: creator.id,
          new_title: RandomGenerator.paragraph()(1, 2),
          new_body: RandomGenerator.content()(2, 8)(),
          edited_at: new Date().toISOString(),
          rationale: RandomGenerator.sentence()(2, 8),
        } satisfies IDiscussionBoardPostEdit.ICreate,
      },
    );
  typia.assert(edit);

  // 4. Register a second, unrelated member who will attempt to access the edit details
  const unrelated: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(unrelated);

  // Note: In an actual authentication system, you would switch 'connection' context here
  // to that of the unrelated user. If such an operation/endpoint exists, use it; otherwise
  // this step simulates the unrelated user's session for the access attempt.

  // 5. Attempt to use the unrelated member to fetch post edit details (expect forbidden/error)
  TestValidator.error("unrelated member cannot view post edit details")(
    async () => {
      await api.functional.discussionBoard.admin.posts.postEdits.at(
        connection,
        {
          postId: post.id,
          postEditId: edit.id,
        },
      );
    },
  );
}

