import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * Validate prevention of duplicate audit log entries for the same moderation
 * action and timestamp.
 *
 * This test ensures the compliance policy is enforced such that duplicate audit
 * log records (having identical action_id and created_at) are not permitted in
 * the system. This is vital for audit integrity, as redundant entries would
 * compromise traceability and regulatory review.
 *
 * The procedure is as follows:
 *
 * 1. Create a valid audit log entry with a unique action reference and timestamp.
 * 2. Attempt to create a second audit log entry with the exact same action_id and
 *    created_at as the first one.
 * 3. Confirm that the system rejects the duplicate per compliance policy (error is
 *    thrown, or record is not persisted).
 * 4. Optionally, verify that other fields being different (such as actor) does not
 *    allow bypassing the uniqueness constraint if action_id and created_at are
 *    unchanged.
 *
 * This protects the reliability of audit trail data for reporting and
 * forensics.
 */
export async function test_api_discussionBoard_test_prevent_duplicate_audit_log_for_same_action_and_timestamp(
  connection: api.IConnection,
) {
  // 1. Create a valid audit log entry
  const uniqueActionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const fixedTimestamp: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;
  const firstAuditLog =
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        action_id: uniqueActionId,
        actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
        action_type: "edit",
        created_at: fixedTimestamp,
        context: "Initial entry for unique action",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    });
  typia.assert(firstAuditLog);
  TestValidator.equals("original persisted values match input")(
    firstAuditLog.action_id,
  )(uniqueActionId);
  TestValidator.equals("original persisted timestamp matches")(
    firstAuditLog.created_at,
  )(fixedTimestamp);

  // 2. Attempt duplicate entry with same action_id and created_at
  await TestValidator.error("duplicate audit log should be rejected")(
    async () => {
      await api.functional.discussionBoard.admin.auditLogs.create(connection, {
        body: {
          action_id: uniqueActionId,
          actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
          actor_member_id: typia.random<string & tags.Format<"uuid">>(),
          action_type: "edit",
          created_at: fixedTimestamp,
          context: "Duplicate attempt for test",
        } satisfies IDiscussionBoardAuditLog.ICreate,
      });
    },
  );
}

