import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Test that notification setting privacy is enforced for
 * /discussionBoard/admin/notificationSettings (index/list).
 *
 * 1. Create two admin accounts (adminA and adminB). Each triggers authentication
 *    as that admin.
 * 2. As adminA: call notification settings index endpoint, verify any returned
 *    settings belong ONLY to adminA (admin_id matches adminA.id, no others
 *    set).
 * 3. As adminB: same test, must only see adminB's settings (admin_id = adminB.id).
 * 4. Create a moderator account, which authenticates as that moderator, and test
 *    listing; must only see settings for the moderator's id (moderator_id
 *    matches, others null/undefined).
 * 5. Create a member account, which authenticates as that member, and test
 *    listing; must only see settings for the member's id.
 * 6. As a guest (unauthenticated), call the listing and check that result is empty
 *    or forbidden.
 */
export async function test_api_discussionBoard_test_list_notification_settings_admin_privacy_enforced(
  connection: api.IConnection,
) {
  // ---- STEP 1: Create AdminA and authenticate as AdminA ----
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAUsername = RandomGenerator.alphaNumeric(10);
  const adminAPasswordHash = RandomGenerator.alphaNumeric(16);
  const adminA = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminAUsername,
        email: adminAEmail,
        password_hash: adminAPasswordHash,
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminA);

  // STEP 2: As AdminA: fetch notification settings (should return only AdminA's or empty)
  {
    const page =
      await api.functional.discussionBoard.admin.notificationSettings.index(
        connection,
      );
    typia.assert(page);
    TestValidator.predicate(
      "all returned notification settings belong to AdminA",
    )(
      page.data.every(
        (setting) =>
          setting.admin_id === adminA.id &&
          !setting.moderator_id &&
          !setting.member_id &&
          !setting.guest_id,
      ),
    );
  }

  // ---- STEP 3: Create AdminB, authenticate as AdminB ----
  const adminBEmail = typia.random<string & tags.Format<"email">>();
  const adminBUsername = RandomGenerator.alphaNumeric(10);
  const adminBPasswordHash = RandomGenerator.alphaNumeric(16);
  const adminB = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminBUsername,
        email: adminBEmail,
        password_hash: adminBPasswordHash,
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminB);

  // As adminB: fetch notification settings, only see own
  {
    const page =
      await api.functional.discussionBoard.admin.notificationSettings.index(
        connection,
      );
    typia.assert(page);
    TestValidator.predicate("all notification settings are scoped to AdminB")(
      page.data.every(
        (setting) =>
          setting.admin_id === adminB.id &&
          !setting.moderator_id &&
          !setting.member_id &&
          !setting.guest_id,
      ),
    );
  }

  // ---- STEP 4: Create moderator, authenticate as moderator ----
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(10);
  const moderatorPasswordHash = RandomGenerator.alphaNumeric(16);
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: moderatorUsername,
        email: moderatorEmail,
        password_hash: moderatorPasswordHash,
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // As moderator: fetch notification settings, only see own
  {
    const page =
      await api.functional.discussionBoard.admin.notificationSettings.index(
        connection,
      );
    typia.assert(page);
    TestValidator.predicate("all notification settings belong to moderator")(
      page.data.every(
        (setting) =>
          setting.moderator_id === moderator.id &&
          !setting.admin_id &&
          !setting.member_id &&
          !setting.guest_id,
      ),
    );
  }

  // ---- STEP 5: Create member, authenticate as member ----
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.alphaNumeric(8);
  const memberPasswordHash = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // As member: fetch notification settings, only see own
  {
    const page =
      await api.functional.discussionBoard.admin.notificationSettings.index(
        connection,
      );
    typia.assert(page);
    TestValidator.predicate("all notification settings belong to member")(
      page.data.every(
        (setting) =>
          setting.member_id === member.id &&
          !setting.admin_id &&
          !setting.moderator_id &&
          !setting.guest_id,
      ),
    );
  }

  // ---- STEP 6: As guest (unauthenticated user) ----
  // Remove authentication header if present
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {
      ...(connection.headers ?? {}),
      Authorization: undefined,
    },
  };
  const guestPage =
    await api.functional.discussionBoard.admin.notificationSettings.index(
      guestConnection,
    );
  typia.assert(guestPage);
  TestValidator.predicate(
    "guest cannot see admin/moderator/member notification settings",
  )(
    guestPage.data.every(
      (setting) =>
        !setting.admin_id && !setting.moderator_id && !setting.member_id,
    ),
  );
}

