import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAppeal";
import type { IPageIDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching moderation action appeals as an admin, covering advanced
 * filter logic and pagination.
 *
 * This test covers admin workflow for high-volume or regulatory review
 * scenarios. Steps:
 *
 * 1. Create multiple appeals with different actors (admin, moderator, member,
 *    guest), statuses (pending, approved, denied), and rationales.
 * 2. Filter by status: search only for 'pending' appeals, confirm only pending
 *    rendered.
 * 3. Filter by specific moderation action id: only appeals related to a specific
 *    action.
 * 4. Filter by actor: fetch only member appeals, moderator appeals, admin appeals,
 *    or guest appeals.
 * 5. Combine date-range (submitted_from/to) filter to ensure accurate filtering by
 *    timestamps.
 * 6. Paginate: request first page with a small limit, verify count and pagination
 *    meta returned is accurate.
 * 7. Error: submit a search with a clearly-invalid filter value (e.g. status =
 *    'foo'), ensure error is thrown.
 *
 * Each step verifies:
 *
 * - Results only include expected appeals.
 * - Pagination metadata is correct (counts/pages/records).
 * - Error handling occurs for invalid filters.
 */
export async function test_api_discussionBoard_admin_appeals_test_search_appeals_with_varied_filters_as_admin(
  connection: api.IConnection,
) {
  // 1. Prepare several appeals with different values for actor fields, status and rationale.
  const actionId1 = typia.random<string & tags.Format<"uuid">>();
  const actionId2 = typia.random<string & tags.Format<"uuid">>();
  // actors
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const guestId = typia.random<string & tags.Format<"uuid">>();

  const appeals: IDiscussionBoardAppeal[] = [];

  // Create various appeals
  for (const params of [
    // action 1, status pending, by admin
    {
      action_id: actionId1,
      status: "pending",
      appellant_admin_id: adminId,
      appellant_moderator_id: null,
      appellant_member_id: null,
      appellant_guest_id: null,
    },
    // action 1, status approved, by member
    {
      action_id: actionId1,
      status: "approved",
      appellant_admin_id: null,
      appellant_moderator_id: null,
      appellant_member_id: memberId,
      appellant_guest_id: null,
    },
    // action 2, status denied, by moderator
    {
      action_id: actionId2,
      status: "denied",
      appellant_admin_id: null,
      appellant_moderator_id: moderatorId,
      appellant_member_id: null,
      appellant_guest_id: null,
    },
    // action 2, status pending, by guest
    {
      action_id: actionId2,
      status: "pending",
      appellant_admin_id: null,
      appellant_moderator_id: null,
      appellant_member_id: null,
      appellant_guest_id: guestId,
    },
  ]) {
    const appeal = await api.functional.discussionBoard.admin.appeals.create(
      connection,
      {
        body: {
          action_id: params.action_id,
          reason: RandomGenerator.paragraph()(),
          status: params.status,
          appellant_admin_id: params.appellant_admin_id,
          appellant_moderator_id: params.appellant_moderator_id,
          appellant_member_id: params.appellant_member_id,
          appellant_guest_id: params.appellant_guest_id,
        } satisfies IDiscussionBoardAppeal.ICreate,
      },
    );
    typia.assert(appeal);
    appeals.push(appeal);
  }

  // 2. Filter by status = pending
  const result_pending =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { status: "pending" },
    });
  typia.assert(result_pending);
  for (const a of result_pending.data)
    TestValidator.equals("status is pending")(a.status)("pending");

  // 3. Filter by specific action
  const result_action1 =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { action_id: actionId1 },
    });
  typia.assert(result_action1);
  for (const a of result_action1.data)
    TestValidator.equals("action matches")(a.action_id)(actionId1);

  // 4. Filter by actor type (member)
  const result_member =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_member_id: memberId },
    });
  typia.assert(result_member);
  for (const a of result_member.data)
    TestValidator.equals("appellant_member_id matches")(a.appellant_member_id)(
      memberId,
    );

  // 4b. Filter by actor type (admin)
  const result_admin =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_admin_id: adminId },
    });
  typia.assert(result_admin);
  for (const a of result_admin.data)
    TestValidator.equals("appellant_admin_id matches")(a.appellant_admin_id)(
      adminId,
    );

  // 4c. Filter by actor type (moderator)
  const result_mod = await api.functional.discussionBoard.admin.appeals.search(
    connection,
    { body: { appellant_moderator_id: moderatorId } },
  );
  typia.assert(result_mod);
  for (const a of result_mod.data)
    TestValidator.equals("appellant_moderator_id matches")(
      a.appellant_moderator_id,
    )(moderatorId);

  // 4d. Filter by actor type (guest)
  const result_guest =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_guest_id: guestId },
    });
  typia.assert(result_guest);
  for (const a of result_guest.data)
    TestValidator.equals("appellant_guest_id matches")(a.appellant_guest_id)(
      guestId,
    );

  // 5. Combine date range filter
  // (use min and max submitted_at in created appeals)
  const minDate = appeals.reduce(
    (min, cur) => (cur.submitted_at < min ? cur.submitted_at : min),
    appeals[0].submitted_at,
  );
  const maxDate = appeals.reduce(
    (max, cur) => (cur.submitted_at > max ? cur.submitted_at : max),
    appeals[0].submitted_at,
  );
  const result_daterange =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { submitted_from: minDate, submitted_to: maxDate },
    });
  typia.assert(result_daterange);
  // all returned appeals must be within minDate/maxDate inclusively
  for (const a of result_daterange.data) {
    TestValidator.predicate("submitted_at >= minDate")(
      a.submitted_at >= minDate,
    );
    TestValidator.predicate("submitted_at <= maxDate")(
      a.submitted_at <= maxDate,
    );
  }

  // 6. Paginate: set limit=2, page=1
  const result_page = await api.functional.discussionBoard.admin.appeals.search(
    connection,
    { body: { limit: 2, page: 1 } },
  );
  typia.assert(result_page);
  TestValidator.equals("limit")(result_page.pagination.limit)(2);
  TestValidator.equals("page")(result_page.pagination.current)(1);

  // 7. Error: invalid status value
  await TestValidator.error("invalid status enum")(() =>
    api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { status: "foo" as any },
    }),
  );
}

