import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Validate the response when there are no moderation actions in the system.
 *
 * This test ensures that when the moderation actions table is empty—such as in
 * a freshly initialized or wiped database—calling the admin moderation actions
 * list API (`GET /discussionBoard/admin/moderationActions`) returns an empty
 * array. This is crucial so that UI consumers and downstream integrators can
 * reliably process the absence of moderation actions without encountering null,
 * undefined, or explodes.
 *
 * Process:
 *
 * 1. Assume a clean database (no moderation actions exist).
 * 2. Call the API as an admin to list all moderation actions.
 * 3. Assert that the response is an empty array and schema is correct.
 *
 * This verifies the empty-state contract and the API's resilience for absence
 * of data.
 */
export async function test_api_discussionBoard_admin_moderationActions_index_empty(
  connection: api.IConnection,
) {
  // 1. No dependency setup is required; clean DB is assumed.

  // 2. Fetch all moderation actions as an admin
  const moderationActions: IDiscussionBoardModerationAction[] =
    await api.functional.discussionBoard.admin.moderationActions.index(
      connection,
    );
  typia.assert(moderationActions);

  // 3. Validate that the list is empty and array-typed
  TestValidator.equals("moderationActions is empty when none exist")(
    moderationActions.length,
  )(0);
}

