import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a guest cannot access notification settings of other users
 * (guest, member, moderator, or admin).
 *
 * Business context:
 *
 * - The endpoint /discussionBoard/guest/notificationSettings allows guests to
 *   query their own notification settings with filtering.
 * - The privacy requirements dictate that a guest user should NOT be able to
 *   retrieve notification settings for any user except their own guest
 *   session.
 * - The API must enforce Role-Based Access Control (RBAC) and prevent information
 *   disclosure.
 *
 * Test steps:
 *
 * 1. As a guest, attempt to search notification settings by specifying filter
 *    fields targeting other roles (e.g. by setting member_id, admin_id,
 *    moderator_id, or a different guest_id).
 * 2. Expect the API to return either an access denied error, or an empty result
 *    set (data array length 0) with no information disclosure.
 * 3. Validate that no records belonging to other users/roles are returned. Confirm
 *    the guest is not able to enumerate or retrieve other users' settings.
 *
 * Edge Cases:
 *
 * - Use randomly generated UUIDs for member_id, admin_id, moderator_id, and
 *   guest_id so that the guest is targeting non-matching and non-owned
 *   records.
 * - Try searching without specifying any filter (should only return own guest's
 *   settings, if any).
 *
 * Negative/Failure Test:
 *
 * - If the API allows searching other's data and returns at least one setting not
 *   belonging to guest session, fail the test.
 */
export async function test_api_discussionBoard_test_guest_cannot_search_other_users_notification_settings(
  connection: api.IConnection,
) {
  // 1. Try searching with member_id filter (should NOT return member's settings)
  const memberSearch =
    await api.functional.discussionBoard.guest.notificationSettings.search(
      connection,
      {
        body: {
          member_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(memberSearch);
  TestValidator.equals("member_id results empty")(memberSearch.data.length)(0);

  // 2. Try searching with admin_id filter
  const adminSearch =
    await api.functional.discussionBoard.guest.notificationSettings.search(
      connection,
      {
        body: {
          admin_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(adminSearch);
  TestValidator.equals("admin_id results empty")(adminSearch.data.length)(0);

  // 3. Try searching with moderator_id filter
  const moderatorSearch =
    await api.functional.discussionBoard.guest.notificationSettings.search(
      connection,
      {
        body: {
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(moderatorSearch);
  TestValidator.equals("moderator_id results empty")(
    moderatorSearch.data.length,
  )(0);

  // 4. Try searching with an arbitrary (different) guest_id
  const otherGuestSearch =
    await api.functional.discussionBoard.guest.notificationSettings.search(
      connection,
      {
        body: {
          guest_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(otherGuestSearch);
  TestValidator.equals("other guest_id results empty")(
    otherGuestSearch.data.length,
  )(0);

  // 5. Try searching with no filter - should only return current guest's records (if any), but must not return others'
  const ownSearch =
