import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Validate that a logged-in member can view the complete edit history for their
 * comment, including multiple revisions.
 *
 * This test verifies that the comment edit audit trail mechanism works for
 * members:
 *
 * - Register a member and authenticate.
 * - Create a post as this member.
 * - Comment on the post.
 * - Edit the comment multiple times (different bodies, as if revising over time).
 * - Fetch the edit history list using the member's commentEdits API.
 * - Validate that the edit events:
 *
 *   1. Exist (by count, matching edits made),
 *   2. Contain correct editor display names,
 *   3. Appear in chronological order.
 *
 * This assures that version tracking and audit trail requirements are met and
 * auditable for moderation.
 */
export async function test_api_discussionBoard_test_list_comment_edit_history_for_existing_comment(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const display_name = RandomGenerator.name();
  const email = typia.random<string & tags.Format<"email">>();
  const password_hash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name,
        email,
        password_hash,
      },
    },
  );
  typia.assert(member);

  // 2. Create a new post as this member
  const post_title = RandomGenerator.paragraph()();
  const post_body = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: post_title,
        body: post_body,
      },
    },
  );
  typia.assert(post);

  // 3. Add an initial comment to the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: "Initial comment body",
        },
      },
    );
  typia.assert(comment);

  // 4. Edit the comment multiple times
  const edit_bodies = [
    "Edit version 1",
    "Edit version 2",
    "Edit version 3 - final revision!",
  ];
  for (const body of edit_bodies) {
    const updated = await api.functional.discussionBoard.member.comments.update(
      connection,
      {
        commentId: comment.id,
        body: {
          body,
        },
      },
    );
    typia.assert(updated);
    TestValidator.equals("comment updated")(updated.body)(body);
  }

  // 5. Fetch edit history events for the comment
  const edits =
    await api.functional.discussionBoard.member.comments.commentEdits.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(edits);

  // 6. Validate total edit events, editor name, and chronological order
  TestValidator.equals("number of edits")(edits.length)(edit_bodies.length);
  let previous_time: string | undefined = undefined;
  edits.forEach((event, index) => {
    TestValidator.equals(`editor display name for edit #${index + 1}`)(
      event.editor_display_name,
    )(display_name);
    if (previous_time) {
      TestValidator.predicate(`chronological order for edit #${index + 1}`)(
        new Date(event.edited_at) > new Date(previous_time),
      );
    }
    previous_time = event.edited_at;
  });
}

