import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Test for creating an authentication token with a duplicate token value.
 *
 * This test validates that the API enforces uniqueness on authentication token
 * strings:
 *
 * 1. Creates an initial admin authentication token with a designated token value.
 * 2. Attempts to create a second token using the exact same token string and
 *    admin_id.
 * 3. Expects the API to reject the duplicate and return an error indicating a
 *    duplicate violation (such as HTTP 409 or validation error).
 *
 * Steps:
 *
 * 1. Generate test data: admin_id (UUID), token string, issued_at/expires_at
 *    timestamps.
 * 2. Create the initial token (POST /discussionBoard/admin/authTokens) as admin.
 * 3. Assert the token was created successfully and matches input.
 * 4. Attempt to create another token with the same token value and admin_id.
 * 5. Use TestValidator.error to ensure the duplicate is rejected.
 */
export async function test_api_discussionBoard_test_create_auth_token_with_duplicate_token(
  connection: api.IConnection,
) {
  // Step 1: Generate required values for token creation
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const token = typia.random<string>();
  const issued_at = new Date().toISOString();
  const expires_at = new Date(Date.now() + 60 * 60 * 1000).toISOString(); // 1 hour ahead

  // Step 2: Create the initial admin authentication token
  const first = await api.functional.discussionBoard.admin.authTokens.create(
    connection,
    {
      body: {
        admin_id,
        actor_type: "admin",
        token,
        issued_at,
        expires_at,
      } satisfies IDiscussionBoardAuthToken.ICreate,
    },
  );
  typia.assert(first);
  TestValidator.equals("token matches")(first.token)(token);
  TestValidator.equals("actor_type matches")(first.actor_type)("admin");

  // Step 3: Attempt to create duplicate token with same values
  await TestValidator.error("duplicate token should fail")(async () => {
    await api.functional.discussionBoard.admin.authTokens.create(connection, {
      body: {
        admin_id,
        actor_type: "admin",
        token,
        issued_at,
        expires_at,
      } satisfies IDiscussionBoardAuthToken.ICreate,
    });
  });
}

