import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Validate that the advanced moderator search endpoint fails gracefully with
 * invalid filter criteria.
 *
 * This test ensures proper error handling for invalid request payloads,
 * focusing on backend validation:
 *
 * 1. Send a search request with a malformed email filter (not a valid email
 *    format)
 * 2. Expect the API to throw a validation error
 * 3. Send a search request with an invalid value for a boolean field (is_active as
 *    string)
 * 4. Expect the API to throw a validation error
 * 5. Ensure that no partial or fallback data is returned in response
 *
 * This confirms that the endpoint enforces input validation, returns a
 * validation error, and does not return any result data on error.
 */
export async function test_api_discussionBoard_admin_moderators_test_search_moderators_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Send a request with a malformed email (missing "@")
  await TestValidator.error("Invalid email filter should fail")(async () => {
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: {
        email: "invalid-email-format",
      } satisfies IDiscussionBoardModerator.IRequest,
    });
  });

  // 2. Send a request with an invalid is_active value (should be boolean, provide string)
  await TestValidator.error(
    "Invalid is_active filter (string instead of boolean) should fail",
  )(async () => {
    // @ts-expect-error: Intentional type misusage for runtime validation
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: {
        is_active: "yes",
      } as any, // Only for runtime input validation check (skip type safety)
    });
  });
}

