import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";
import type { IPageIDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that a post author (member) can search their post's edit history by date
 * range and rationale keyword.
 *
 * Steps:
 *
 * 1. Register a new verified discussion board member (author).
 * 2. Submit a post as this member.
 * 3. Perform two edits on the post, each with unique rationale text AND set the
 *    edit timestamps sufficiently apart.
 * 4. Search edit history for the post using PATCH, specifying:
 *
 *    - The postId
 *    - The memberId (should match only this user)
 *    - A date range filter that covers only one of the edits
 *    - A rationale keyword that matches only that edit's rationale
 *    - Explicit page/limit for pagination (e.g., page:1, limit:10)
 * 5. Assert the search returns the correct, single edit (the one matching both
 *    filters), and that no edits for other users could be present.
 * 6. Verify proper authorization (this member can only see their own edits, but in
 *    this test, only this one exists).
 *
 * Edge Cases:
 *
 * - The date window excludes the second edit: ensure only one edit is returned.
 * - Rationale keyword partial matching is case-insensitive.
 *
 * Business/contract validation:
 *
 * - Confirm the returned data's editor id, post id, rationale, edited_at are as
 *   expected.
 */
export async function test_api_discussionBoard_test_search_post_edits_as_post_author_with_specific_date_range(
  connection: api.IConnection,
) {
  // Step 1: Register a new verified discussion board member
  const passwordHash = RandomGenerator.alphaNumeric(24);
  const author = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: passwordHash,
      },
    },
  );
  typia.assert(author);

  // Step 2: Submit a post as this member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(1),
        parent_id: null,
      },
    },
  );
  typia.assert(post);

  // Step 3: Perform two edits with unique rationales and edited_at timestamps
  const baseDate = new Date();
  // First edit (earlier date)
  const edit1Date = new Date(baseDate.getTime() - 1000 * 60 * 60 * 24); // 1 day ago
  const rationale1 = "typo-fix-AlphaCase";
  const edit1 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          new_title: post.title + " [fixed]",
          new_body: post.body,
          edited_at: edit1Date.toISOString(),
          rationale: rationale1,
        },
      },
    );
  typia.assert(edit1);
  // Second edit (later date)
  const edit2Date = new Date(baseDate.getTime() + 1000 * 60 * 30); // 30 min in future
  const rationale2 = "expanded-example-beta";
  const edit2 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          new_title: post.title + " [expanded]",
          new_body: post.body + "\nExtra details for example.",
          edited_at: edit2Date.toISOString(),
          rationale: rationale2,
        },
      },
    );
  typia.assert(edit2);

  // Step 4: Search only for edits within the window that matches edit1, with matching rationale keyword (case-insensitive partial)
  const keyword = "alphaCASE"; // intentionally mixed case to check case insensitivity
  const result =
    await api.functional.discussionBoard.member.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          start: new Date(
            baseDate.getTime() - 1000 * 60 * 60 * 25,
          ).toISOString(), // 25h ago
          end: new Date(baseDate.getTime() - 1000 * 60 * 60 * 23).toISOString(), // 23h ago (tight window containing edit1 only)
          rationale: keyword,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(result);

  // Step 5: Validate search result
  TestValidator.equals("should return exactly one matching edit")(
    result.data.length,
  )(1);
  const foundEdit = result.data[0];
  TestValidator.equals("editor id matches")(
    foundEdit.discussion_board_member_id,
  )(author.id);
  TestValidator.equals("post id matches")(foundEdit.discussion_board_post_id)(
    post.id,
  );
  TestValidator.predicate("case-insensitive rationale match")(
    foundEdit.rationale &&
      foundEdit.rationale.toLowerCase().includes(keyword.toLowerCase()),
  );
  TestValidator.equals("edited_at matches")(foundEdit.edited_at)(
    edit1.edited_at,
  );
}

