/**
 * Test that updating a moderation report by specifying disallowed/immutable
 * fields fails as expected.
 *
 * This test covers that only defined fields (status, category, reason, resolved_at)
 * are allowed for update on a report. Attempting to mutate other fields (such as
 * reporter_admin_id, discussion_board_post_id, etc.) is prevented by the SDK/types,
 * and cannot be compiled as a test; thus, immutability here is enforced at compile-time.
 *
 * Steps:
 * 1. Create a valid moderation report
 * 2. Update allowed field(s) - ensure update is accepted and changed
 * 3. (Compile-time) Show that immutable fields cannot be updated at all with the SDK
 */
export async function test_api_discussionBoard_admin_contentReports_test_admin_update_report_with_invalid_field_rejected(
  connection: api.IConnection,
) {
  // 1. Create a valid report
  const created = await api.functional.discussionBoard.admin.contentReports.create(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussion_board_comment_id: null,
        content_type: "post",
        category: "spam",
        reason: "Unapproved advertising content.",
      },
    },
  );
  typia.assert(created);

  // 2. Update an allowed field to demonstrate success
  const updated = await api.functional.discussionBoard.admin.contentReports.update(
    connection,
    {
      contentReportId: created.id,
      body: {
        status: "resolved",
        reason: "Reviewed and resolved.",
      },
    },
  );
  typia.assert(updated);
  TestValidator.equals("ID unchanged")(updated.id)(created.id);
  TestValidator.equals("Status updated")(updated.status)("resolved");
  TestValidator.equals("Reason updated")(updated.reason)("Reviewed and resolved.");
  // 3. Attempting to update immutable fields is not possible at the TypeScript level,
  // so cannot be tested at runtime (compile-time safety enforced).
}

