import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate the paginated and filtered retrieval of discussion board moderators.
 *
 * This test ensures the moderator listing endpoint properly supports listing,
 * pagination, and filtering on properties like username and is_active.
 *
 * Steps:
 *
 * 1. Create several moderators with distinct usernames and active/inactive states
 *    (e.g., 2 "active", 1 "inactive").
 * 2. Fetch all moderators through the listing endpoint.
 * 3. Confirm all created moderators are present and at the expected total count.
 * 4. Pagination/filtering cannot be directly tested as the endpoint currently
 *    accepts no such parameters—this is documented for future support. Instead,
 *    just assert total count includes the created users.
 */
export async function test_api_discussionBoard_admin_moderators_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create moderators with distinct usernames and activity states
  const moderators = await Promise.all([
    api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `alpha_${RandomGenerator.alphaNumeric(5)}`,
        password_hash: RandomGenerator.alphaNumeric(24),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    }),
    api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `bravo_${RandomGenerator.alphaNumeric(5)}`,
        password_hash: RandomGenerator.alphaNumeric(24),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    }),
    api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `charlie_${RandomGenerator.alphaNumeric(5)}`,
        password_hash: RandomGenerator.alphaNumeric(24),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      } satisfies IDiscussionBoardModerator.ICreate,
    }),
  ]);
  moderators.forEach(typia.assert);

  // 2. List all moderators
  const listing =
    await api.functional.discussionBoard.admin.moderators.index(connection);
  typia.assert(listing);

  // 3. Confirm all created moderators are present in the returned dataset
  for (const created of moderators) {
    const found = listing.data.find((mod) => mod.username === created.username);
    TestValidator.predicate(`moderator ${created.username} present in listing`)(
      !!found,
    );
    // Confirm all fields match (except timestamps)
    if (found) {
      TestValidator.equals(`email matches for ${created.username}`)(
        found.email,
      )(created.email);
      TestValidator.equals(`is_active matches for ${created.username}`)(
        found.is_active,
      )(created.is_active);
    }
  }

  // 4. Pagination and filter tests:
  // At this time, the listing endpoint does NOT accept pagination or filter params (GET only, no query/body accepted).
  // Only check that the overall total is >= number created. Add pagination and filter tests if endpoint is updated in the future.
  TestValidator.predicate("listing includes all created moderators")(
    listing.data.length >= moderators.length,
  );
}

