import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostCategory";

/**
 * Verify that retrieving category assignments for a post with no categories
 * returns an empty result.
 *
 * Business context: This test ensures the endpoint for listing category
 * assignments on a post returns an empty array if the post has no categories
 * assigned.
 *
 * Test process:
 *
 * 1. Register a discussion board member (to act as post author)
 * 2. Create a new post as this member, with no categories assigned
 * 3. Retrieve assigned categories for the new post via the endpoint
 * 4. Assert that the response is an empty array, proving correct empty-state
 *    handling
 */
export async function test_api_discussionBoard_test_list_categories_on_post_with_no_assignments_returns_empty(
  connection: api.IConnection,
) {
  // 1. Register a new member for test
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post (authorship via this member, business logic assumes context)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Retrieve the category assignments for this post (should be none assigned)
  const categories =
    await api.functional.discussionBoard.member.posts.postCategories.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(categories);

  // 4. Validate that result is [] (empty assignment list)
  TestValidator.equals("no category assignments returned")(categories)([]);
}

