import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Validates that an admin user can successfully retrieve a paginated list of
 * all guest session records for the discussion board system.
 *
 * This test ensures that when an admin (with proper
 * authentication/authorization) requests the guest sessions list endpoint, the
 * system returns a paginated response containing correct guest session
 * metadata, including session token, IP address, and entry timestamp, for both
 * recent and historical guest sessions.
 *
 * RBAC is enforced such that only admins can access this endpoint; non-admin or
 * guest attempts would be covered elsewhere or are omitted due to unavailable
 * endpoints for those roles. The response must match the
 * IPageIDiscussionBoardGuest.ISummary DTO structure. The test also probes
 * infrastructure error handling by simulating a database outage and verifying
 * correct error surfaces, if feasible.
 *
 * Test Steps:
 *
 * 1. Use an admin-authenticated connection to call
 *    api.functional.discussionBoard.admin.guests.index().
 * 2. Assert the response using typia.assert().
 * 3. Validate pagination metadata and existence of expected guest record fields
 *    (id, guest_ip, session_token, entered_at).
 * 4. Optionally, switch to a non-admin or guest context and verify rejection
 *    (skipped due to dependency limitations).
 * 5. Optionally, simulate database downtime and assert proper error handling (if
 *    feasible, may mention in comment).
 */
export async function test_api_discussionBoard_test_list_all_guest_sessions_as_admin(
  connection: api.IConnection,
) {
  // 1. Fetch paginated guest session records as admin
  const page: IPageIDiscussionBoardGuest.ISummary =
    await api.functional.discussionBoard.admin.guests.index(connection);
  // 2. Structure assertion
  typia.assert(page);
  // 3. Validate pagination fields
  TestValidator.predicate("pagination.current is integer and >= 1")(
    Number.isInteger(page.pagination.current) && page.pagination.current >= 1,
  );
  TestValidator.predicate("pagination.limit is integer and >= 1")(
    Number.isInteger(page.pagination.limit) && page.pagination.limit >= 1,
  );
  TestValidator.predicate("pagination.records is integer and >= 0")(
    Number.isInteger(page.pagination.records) && page.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages is integer and >= 1")(
    Number.isInteger(page.pagination.pages) && page.pagination.pages >= 1,
  );
  // 4. Validate that guest record fields are present and properly structured
  for (const guest of page.data) {
    TestValidator.predicate("id is UUID string")(
      typeof guest.id === "string" && guest.id.length > 0,
    );
    TestValidator.predicate("guest_ip is string")(
      typeof guest.guest_ip === "string" && guest.guest_ip.length > 0,
    );
    TestValidator.predicate("session_token is string")(
      typeof guest.session_token === "string" && guest.session_token.length > 0,
    );
    TestValidator.predicate("entered_at is string")(
      typeof guest.entered_at === "string" && guest.entered_at.length > 0,
    );
  }
  // 5. Optionally, negative roles and infra error scenarios are omitted or commented as not feasible here
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced filtering and searching of discussion board guest session
 * records.
 *
 * Business Context: Only admin users can access the advanced guest search
 * endpoint. This test ensures that analytics, forensics, and compliance
 * filtering for guest session access via a variety of query criteria (IP,
 * session token, date range) works correctly and robustly. It confirms that the
 * endpoint reliably returns matching session records for each filter and
 * gracefully handles invalid queries.
 *
 * Step-by-step process:
 *
 * 1. Create multiple guest sessions with distinct combinations of guest_ip,
 *    session_token, and entered_at values.
 * 2. As an admin, filter for guest sessions by an exact guest_ip and verify that
 *    only matching records are returned.
 * 3. Filter by a session_token substring and verify that only matching sessions
 *    are present.
 * 4. Filter by entered_at date range and confirm all results fall within
 *    boundaries.
 * 5. Combine multiple filters (e.g., IP + token fragment) and check results.
 * 6. Use pagination fields (page/limit) and ensure the result page matches
 *    expectations.
 * 7. Submit invalid queries, such as reversed dates or non-existent session_token
 *    values, and verify errors are correctly handled and system remains
 *    stable.
 */
export async function test_api_discussionBoard_test_filter_guest_sessions_by_criteria(
  connection: api.IConnection,
) {
  // 1. Create multiple guest sessions with unique combinations
  const baseIp = "203.0.113.";
  const guests: IDiscussionBoardGuest[] = [];
  for (let i = 0; i < 5; i++) {
    const guest = await api.functional.discussionBoard.guests.create(
      connection,
      {
        body: {
          guest_ip: `${baseIp}${100 + i}`,
          session_token: `token_${i}_${RandomGenerator.alphaNumeric(6)}`,
          entered_at: new Date(
            Date.now() - i * 3600 * 1000,
          ).toISOString() as string & tags.Format<"date-time">,
        } satisfies IDiscussionBoardGuest.ICreate,
      },
    );
    typia.assert(guest);
    guests.push(guest);
  }

  // 2. Filter by guest_ip (should return only matching record)
  const filterIp = guests[2].guest_ip;
  const searchByIp = await api.functional.discussionBoard.admin.guests.search(
    connection,
    {
      body: {
        guest_ip: filterIp,
        session_token: null,
        entered_at_from: null,
        entered_at_to: null,
        page: null,
        limit: null,
      },
    },
  );
  typia.assert(searchByIp);
  TestValidator.predicate("should only have records with target IP")(
    searchByIp.data.every((g) => g.guest_ip === filterIp),
  );

  // 3. Filter by session_token fragment
  const tokenFragment = guests[1].session_token.slice(0, 8);
  const searchByToken =
    await api.functional.discussionBoard.admin.guests.search(connection, {
      body: {
        guest_ip: null,
        session_token: tokenFragment,
        entered_at_from: null,
        entered_at_to: null,
        page: null,
        limit: null,
      },
    });
  typia.assert(searchByToken);
  TestValidator.predicate(
    "should only have records with session token fragment",
  )(searchByToken.data.every((g) => g.session_token.includes(tokenFragment)));

  // 4. Filter by entered_at date range
  const [from, to] = [guests[3].entered_at, guests[1].entered_at];
  const searchByDateRange =
    await api.functional.discussionBoard.admin.guests.search(connection, {
      body: {
