        entered_at_to: to,
        page: null,
        limit: null,
      },
    });
  typia.assert(searchByDateRange);
  TestValidator.predicate("should have records within date range")(
    searchByDateRange.data.every(
      (g) => g.entered_at >= from && g.entered_at <= to,
    ),
  );

  // 5. Combine guest_ip and session_token filters
  const comboGuest = guests[4];
  const combined = await api.functional.discussionBoard.admin.guests.search(
    connection,
    {
      body: {
        guest_ip: comboGuest.guest_ip,
        session_token: comboGuest.session_token.slice(0, 8),
        entered_at_from: null,
        entered_at_to: null,
        page: null,
        limit: null,
