  typia.assert(combined);
  TestValidator.predicate("should match both IP and token")(
    combined.data.every(
      (g) =>
        g.guest_ip === comboGuest.guest_ip &&
        g.session_token.includes(comboGuest.session_token.slice(0, 8)),
    ),
  );

  // 6. Pagination
  const paged = await api.functional.discussionBoard.admin.guests.search(
    connection,
    {
      body: {
        guest_ip: null,
        session_token: null,
        entered_at_from: null,
        entered_at_to: null,
        page: 0,
        limit: 2,
      },
