    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      {
        body: { content_type: createdReport.content_type },
      },
    );
  typia.assert(byType);
  TestValidator.predicate("by content_type contains")(
    byType.data.some((r) => r.id === createdReport.id),
  );

  // 5. Filter by status
  const byStatus =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { status: createdReport.status } },
    );
  typia.assert(byStatus);
  TestValidator.predicate("by status contains")(
    byStatus.data.some((r) => r.id === createdReport.id),
  );

  // 6. Filter by category
  const byCategory =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { category: createdReport.category } },
    );
  typia.assert(byCategory);
  TestValidator.predicate("by category contains")(
    byCategory.data.some((r) => r.id === createdReport.id),
  );

  // 7. Filter by discussion_board_post_id
  if (createdReport.discussion_board_post_id) {
    const byPostId =
      await api.functional.discussionBoard.moderator.contentReports.search(
        connection,
        {
          body: {
            discussion_board_post_id: createdReport.discussion_board_post_id,
          },
        },
      );
    typia.assert(byPostId);
    TestValidator.predicate("by post id contains")(
      byPostId.data.some((r) => r.id === createdReport.id),
    );
  }

  // 8. Filter by discussion_board_comment_id (should be null, so skip if not set)
  if (createdReport.discussion_board_comment_id) {
    const byCommentId =
      await api.functional.discussionBoard.moderator.contentReports.search(
        connection,
        {
          body: {
            discussion_board_comment_id:
              createdReport.discussion_board_comment_id,
          },
        },
      );
    typia.assert(byCommentId);
    TestValidator.predicate("by comment id contains")(
      byCommentId.data.some((r) => r.id === createdReport.id),
    );
  }

  // 9. Filter by date_from and date_to (should include report in a wide window)
  const wideFrom = new Date(
    new Date(createdReport.reported_at).getTime() - 1000 * 60 * 60 * 24,
  ).toISOString();
  const wideTo = new Date(
    new Date(createdReport.reported_at).getTime() + 1000 * 60 * 60 * 24,
  ).toISOString();
  const byDateRange =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { date_from: wideFrom, date_to: wideTo } },
    );
  typia.assert(byDateRange);
  TestValidator.predicate("by date range contains")(
    byDateRange.data.some((r) => r.id === createdReport.id),
  );

  // 10. Pagination: use limit=1 and page=1, data length should be <= 1, pagination matches
  const paged =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { pagination: { page: 1, limit: 1 } } },
    );
  typia.assert(paged);
  TestValidator.predicate("pagination respect")(
    paged.data.length <= 1 && paged.pagination.limit === 1,
  );

  // 11. Impossible filter: random UUID for reporter_member_id
  const impossible =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      {
        body: {
          reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(impossible);
  TestValidator.equals("no data for unknown member id")(impossible.data.length)(
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Validates that an admin can perform advanced search for content moderation
 * reports with various filter/pagination combinations.
 *
 * This test ensures admins can:
 *
 * - Filter moderation/abuse reports by reporter identity, status, category,
 *   referenced post/comment, date range
 * - Apply pagination and receive correct metadata
 * - Only receive reports matching filter criteria (no unauthorized leaks)
 * - Handle invalid queries gracefully (empty or valid error result)
 *
 * Steps:
 *
 * 1. Seed the system with multiple, diverse content reports
 * 2. Run searches for each type of filter (reporter, status/category, post-id,
 *    comment-id, date range, pagination)
 * 3. Validate results for accuracy and security (fields match, pagination correct,
 *    no leaks)
 * 4. Query with invalid input and validate correct behavior.
 */
export async function test_api_discussionBoard_test_admin_advanced_search_of_content_reports_with_pagination(
  connection: api.IConnection,
) {
  // 1. Seed database with diverse reports (alternating post/comment, membership, category, etc)
  const createdReports: IDiscussionBoardContentReport[] = [];
  for (let i = 0; i < 5; i++) {
    const isPost = i % 2 === 0;
    const report =
      await api.functional.discussionBoard.member.contentReports.create(
        connection,
        {
          body: {
            discussion_board_post_id: isPost
              ? typia.random<string & tags.Format<"uuid">>()
              : undefined,
            discussion_board_comment_id: isPost
              ? undefined
              : typia.random<string & tags.Format<"uuid">>(),
            content_type: isPost ? "post" : "comment",
            category: ["spam", "policy", "offensive"][i % 3],
            reason: `Test reason ${i}`,
          } satisfies IDiscussionBoardContentReport.ICreate,
        },
      );
    typia.assert(report);
    createdReports.push(report);
  }

  // Pick one with a member for filtering (for simplicity, just pick index 2)
  const sampleReport = createdReports[2];

  // 2a. Filter by reporter_member_id
  let res = await api.functional.discussionBoard.admin.contentReports.search(
    connection,
    {
      body: { reporter_member_id: sampleReport.reporter_member_id },
    },
  );
  typia.assert(res);
  for (const v of res.data)
    TestValidator.equals("reporter_member_id")(v.reporter_member_id)(
      sampleReport.reporter_member_id,
    );

  // 2b. Filter by status and category
  res = await api.functional.discussionBoard.admin.contentReports.search(
    connection,
    {
      body: { status: sampleReport.status, category: sampleReport.category },
    },
  );
  typia.assert(res);
  for (const v of res.data) {
    TestValidator.equals("status")(v.status)(sampleReport.status);
    TestValidator.equals("category")(v.category)(sampleReport.category);
  }

  // 2c. Filter by discussion_board_post_id and content_type
  if (sampleReport.discussion_board_post_id) {
    res = await api.functional.discussionBoard.admin.contentReports.search(
      connection,
      {
        body: {
          discussion_board_post_id: sampleReport.discussion_board_post_id,
          content_type: "post",
        },
      },
    );
    typia.assert(res);
    for (const v of res.data) {
      TestValidator.equals("discussion_board_post_id")(
        v.discussion_board_post_id,
      )(sampleReport.discussion_board_post_id);
      TestValidator.equals("content_type")(v.content_type)("post");
    }
  }

  // 2d. Filter by comment id
  const commentReport = createdReports.find(
    (r) => r.discussion_board_comment_id,
  );
  if (commentReport) {
    res = await api.functional.discussionBoard.admin.contentReports.search(
      connection,
      {
        body: {
          discussion_board_comment_id:
            commentReport.discussion_board_comment_id,
          content_type: "comment",
        },
      },
    );
    typia.assert(res);
    for (const v of res.data) {
      TestValidator.equals("discussion_board_comment_id")(
        v.discussion_board_comment_id,
      )(commentReport.discussion_board_comment_id);
      TestValidator.equals("content_type")(v.content_type)("comment");
    }
  }

  // 2e. Filter by date_from/date_to range
  const from = createdReports[0].reported_at;
  const to = createdReports[createdReports.length - 1].reported_at;
  res = await api.functional.discussionBoard.admin.contentReports.search(
    connection,
    {
      body: { date_from: from, date_to: to },
    },
  );
  typia.assert(res);
  for (const v of res.data)
    TestValidator.predicate("reported_at in range")(
      v.reported_at >= from && v.reported_at <= to,
    );

  // 2f. Pagination control
  res = await api.functional.discussionBoard.admin.contentReports.search(
    connection,
    {
      body: { pagination: { page: 1, limit: 2 } },
    },
  );
  typia.assert(res);
  TestValidator.equals("current page")(res.pagination.current)(1);
  TestValidator.equals("limit")(res.pagination.limit)(2);
  TestValidator.equals("data length")(res.data.length)(2);

  // 3. Invalid query: random UUID for post_id (should yield empty set)
  res = await api.functional.discussionBoard.admin.contentReports.search(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(res);
  TestValidator.equals("data empty for non-existent post")(res.data.length)(0);
}

