/**
 * E2E test for the creation of a new moderation action by an admin, triggered
 * in response to a content report.
 *
 * Validates that an admin can:
 *
 * 1. Successfully create a content report as a prerequisite.
 * 2. Use valid data (including proper linkage to the report and all required
 *    rationale/fields) to create a moderation action.
 * 3. Receive a response containing all persisted and metadata fields.
 * 4. Attempt duplicate creation for the same report/action and observe expected
 *    behavior (e.g., either uniqueness enforcement or acceptance depending on
 *    business rules).
 * 5. Receive and handle errors for missing required fields, referencing a
 *    non-existing report, invalid role/actor specification, and malformed
 *    rationale/description.
 *
 * Steps:
 *
 * 1. Create a content report with valid required information.
 * 2. Create a moderation action as admin against that report, supplying all valid
 *    fields.
 * 3. Assert the action is persisted, references intended report, and metadata is
 *    present.
 * 4. Re-attempt to create a moderation action with same report/action type and
 *    check handling.
 * 5. Attempt creating a moderation action with missing required fields and check
 *    for error.
 * 6. Attempt with a bogus/non-existing report_id and check that it fails.
 * 7. Attempt with invalid role fields (missing both admin_id and moderator_id; or
 *    both present), and malformed description, and check for errors.
 */
export async function test_api_discussionBoard_test_create_moderation_action_as_admin_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a content report as precondition for moderation action
  const report =
    await api.functional.discussionBoard.admin.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_comment_id: null,
          content_type: "post",
          category: "spam",
          reason: "Automated content spam detected by admin.",
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(report);

  // 2. Create moderation action as admin against this report
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction =
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: report.id,
          admin_id: adminId,
          moderator_id: null,
          action_type: "suspend",
          description:
            "Suspended content after admin review for spam policy violation.",
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationAction);
  TestValidator.equals("report reference")(moderationAction.report_id)(
    report.id,
  );
  TestValidator.equals("admin reference")(moderationAction.admin_id)(adminId);
  TestValidator.equals("action type")(moderationAction.action_type)("suspend");

  // 3. Try to create another moderation action of the same type for same report (business rules may accept or reject)
  const moderationActionRepeat =
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: report.id,
          admin_id: adminId,
          moderator_id: null,
          action_type: "suspend",
          description:
            "Second admin action (should be handled according to business rules).",
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationActionRepeat);
  TestValidator.equals("report reference repeat")(
    moderationActionRepeat.report_id,
  )(report.id);

  // 4. Error: missing required fields (e.g. action_type & description)
  await TestValidator.error("missing required fields")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        report_id: report.id,
        admin_id: adminId,
        // Missing action_type and description
      } as any, // Forced for runtime error simulation
    }),
  );

  // 5. Error: reference to a non-existing report
  await TestValidator.error("non-existing report reference")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        report_id: typia.random<string & tags.Format<"uuid">>(), // random uuid not linked
        admin_id: adminId,
        moderator_id: null,
        action_type: "delete",
        description: "Attempt to moderate non-existent report.",
      } satisfies IDiscussionBoardModerationAction.ICreate,
    }),
  );

  // 6. Error: invalid role/actor (both admin_id and moderator_id specified)
  await TestValidator.error(
    "invalid role specification: both admin and moderator ids set",
  )(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        report_id: report.id,
        admin_id: adminId,
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        action_type: "edit",
        description: "Should fail: both admin_id and moderator_id set.",
      } satisfies IDiscussionBoardModerationAction.ICreate,
    }),
  );

  // 7. Error: malformed description (e.g. blank/empty)
  await TestValidator.error("malformed rationale/description")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        report_id: report.id,
        admin_id: adminId,
        moderator_id: null,
        action_type: "edit",
        description: "",
      } satisfies IDiscussionBoardModerationAction.ICreate,
    }),
  );
}

