import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate retrieval of a moderator notification by ID with strict access
 * control.
 *
 * Business purpose: Ensures that moderators can correctly access notifications
 * specifically addressed to them, while access to notifications for other roles
 * (admin, member, guest) or entirely non-existent notifications is strictly
 * forbidden or yields not found.
 *
 * Steps:
 *
 * 1. Create a moderator account (as admin).
 * 2. Create a notification addressed to the moderator (as admin).
 * 3. As the moderator, retrieve the notification by its ID and confirm all fields.
 * 4. As the moderator, attempt to retrieve a notification for an admin, member, or
 *    guest and verify access is denied (forbidden/not found).
 * 5. As the moderator, attempt to retrieve a non-existent notification and verify
 *    not found or forbidden error is raised.
 */
export async function test_api_discussionBoard_test_retrieve_moderator_notification_by_id_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create a moderator (admin provides all required fields)
  const moderatorICreate: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphabets(8),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
  };
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderatorICreate,
    });
  typia.assert(moderator);

  // 2. Create a notification for the moderator
  const moderatorNotificationCreate: IDiscussionBoardNotification.ICreate = {
    moderator_id: moderator.id,
    type: "in-app",
    category: "moderation_event",
    message: RandomGenerator.paragraph()(1),
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };
  const moderatorNotification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: moderatorNotificationCreate },
    );
  typia.assert(moderatorNotification);

  // 3. As the moderator, retrieve the notification by its ID and confirm all fields match
  const fetchedModeratorNotification =
    await api.functional.discussionBoard.moderator.notifications.at(
      connection,
      { notificationId: moderatorNotification.id },
    );
  typia.assert(fetchedModeratorNotification);
  TestValidator.equals("Moderator's notification fields")(
    fetchedModeratorNotification,
  )(moderatorNotification);

  // 4. Create a notification for a different recipient (admin)
  const adminNotificationCreate: IDiscussionBoardNotification.ICreate = {
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    type: "in-app",
    category: "admin_event",
    message: RandomGenerator.paragraph()(1),
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
  };
  const adminNotification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: adminNotificationCreate },
    );
  typia.assert(adminNotification);

  // As moderator, attempt to fetch admin's notification (should be forbidden or not found)
  await TestValidator.error(
    "Moderator cannot access admin/other notifications",
  )(() =>
    api.functional.discussionBoard.moderator.notifications.at(connection, {
      notificationId: adminNotification.id,
    }),
  );

  // 5. Attempt access for non-existent notification ID
  await TestValidator.error("Not found for non-existent notification")(() =>
    api.functional.discussionBoard.moderator.notifications.at(connection, {
      notificationId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
