export async function test_api_discussionBoard_test_no_notifications_returned_for_admin_with_empty_inbox(
  connection: api.IConnection,
) {
  // 1. Precondition: Cannot create or purge notifications via available APIs, so accept current state.

  // 2. Request notifications for the admin user
  const output =
    await api.functional.discussionBoard.admin.notifications.index(connection);
  typia.assert(output);

  // 3. Assert the notifications list is empty
  TestValidator.equals("admin receives no notifications if inbox is empty")(
    output.data.length,
  )(0);

  // 4. Assert pagination metadata is valid (should be present regardless of emptiness)
  TestValidator.predicate("pagination metadata present")(
    typeof output.pagination === "object" && output.pagination !== null,
