    typeof output.pagination.current === "number",
  );
  TestValidator.predicate("pagination.limit is a number")(
    typeof output.pagination.limit === "number",
  );
  TestValidator.predicate("pagination.records is a number")(
    typeof output.pagination.records === "number",
  );
  TestValidator.predicate("pagination.pages is a number")(
    typeof output.pagination.pages === "number",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
