 *
 * This test ensures that a moderator, when authenticated, can retrieve a list
 * of notifications addressed to them, and that the result does not contain
 * notifications meant for any other role (admin, member, guest) or for other
 * moderators. The test flow is as follows:
 *
 * 1. Create a notification specifically for the moderator (POST dependency).
 * 2. Create control notifications for admin, member, guest, and another moderator
 *    to verify scoping (ensures only correct notifications are returned).
 * 3. Call the GET endpoint as the moderator to retrieve notifications.
 * 4. Validate:
 *
 *    - The response includes the original moderator notification.
 *    - The response does NOT include control notifications for other
 *         roles/moderators.
 *    - All returned notifications have the same moderator_id, and no admin_id,
 *         member_id, or guest_id set.
 */
export async function test_api_discussionBoard_test_retrieve_moderator_notifications_inbox(
  connection: api.IConnection,
) {
  // 1. Generate a distinct UUID for this test moderator (recipient)
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a notification delivered to this moderator
  const moderatorNotification =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: {
          moderator_id: moderatorId,
          type: "in-app",
          category: "moderation_event",
          message: "Moderator alert for your test inbox.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(moderatorNotification);

  // 3. Create control notifications for admin, member, guest, and a different moderator
  const controlAdminNotification =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: {
          admin_id: typia.random<string & tags.Format<"uuid">>(),
          type: "in-app",
          category: "admin_notice",
          message: "Admin control notification.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(controlAdminNotification);

  const controlMemberNotification =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: {
          member_id: typia.random<string & tags.Format<"uuid">>(),
          type: "in-app",
          category: "member_update",
          message: "Member control notification.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(controlMemberNotification);

  const controlGuestNotification =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: {
          guest_id: typia.random<string & tags.Format<"uuid">>(),
          type: "in-app",
          category: "guest_notice",
          message: "Guest control notification.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(controlGuestNotification);

  const anotherModeratorId: string = typia.random<
    string & tags.Format<"uuid">
  >();
  const anotherModeratorNotification =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      {
        body: {
          moderator_id: anotherModeratorId,
          type: "in-app",
          category: "moderation_event",
          message: "Notification for another moderator.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(anotherModeratorNotification);

  // 4. Retrieve notifications as the moderator
  // (Assume connection represents moderatorId's authenticated session)
  const page =
    await api.functional.discussionBoard.moderator.notifications.index(
      connection,
    );
  typia.assert(page);

  // 5. Validate all returned notifications have moderator_id and correct scoping
  page.data.forEach((notif) => {
    TestValidator.equals("notification recipient is correct moderator")(
      notif.moderator_id,
    )(moderatorId);
    TestValidator.equals("notification not for admin")(notif.admin_id)(null);
    TestValidator.equals("notification not for member")(notif.member_id)(null);
    TestValidator.equals("notification not for guest")(notif.guest_id)(null);
  });

  // 6. Ensure the created moderator notification is present in the result
  TestValidator.predicate("created moderator notification exists")(
    page.data.some((n) => n.id === moderatorNotification.id),
  );

  // 7. Ensure control notifications are not included
  TestValidator.predicate("admin notification not in result")(
    !page.data.some((n) => n.id === controlAdminNotification.id),
  );
  TestValidator.predicate("member notification not in result")(
    !page.data.some((n) => n.id === controlMemberNotification.id),
  );
  TestValidator.predicate("guest notification not in result")(
    !page.data.some((n) => n.id === controlGuestNotification.id),
  );
  TestValidator.predicate("another moderator notification not in result")(
    !page.data.some((n) => n.id === anotherModeratorNotification.id),
  );
}

