/**
 * Test updating a category-tag assignment link by an admin.
 *
 * This scenario validates the following:
 *
 * 1. Admin can create a new category.
 * 2. Admin can create two tags (for initial assignment and for update).
 * 3. Admin can assign the first tag to the new category (creating a category-tag
 *    link).
 * 4. Admin can update the existing assignment to change the tag to the second tag.
 * 5. The returned record reflects the updated tag assignment.
 *
 * Steps:
 *
 * 1. Create a category via api.functional.discussionBoard.admin.categories.create
 * 2. Create the first tag via api.functional.discussionBoard.admin.tags.create
 * 3. Create the second tag via api.functional.discussionBoard.admin.tags.create
 * 4. Assign the first tag to the category via
 *    api.functional.discussionBoard.admin.categoryTags.create
 * 5. Update the assignment with the second tag via
 *    api.functional.discussionBoard.admin.categoryTags.update
 * 6. Assert that the updated assignment contains the new tag id and the category
 *    id is unchanged
 */
export async function test_api_discussionBoard_admin_categoryTags_test_update_category_tag_assignment_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(category);

  // 2. Create the first tag
  const tag1 = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: "#2387e7",
      },
    },
  );
  typia.assert(tag1);

  // 3. Create the second tag
  const tag2 = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: "#32e77d",
      },
    },
  );
  typia.assert(tag2);

  // 4. Assign the first tag to the category
  const assignment =
    await api.functional.discussionBoard.admin.categoryTags.create(connection, {
      body: {
        discussion_board_category_id: category.id,
        discussion_board_tag_id: tag1.id,
      },
