  // 5. Update assignment to use the second tag
  const updatedAssignment =
    await api.functional.discussionBoard.admin.categoryTags.update(connection, {
      categoryTagId: assignment.id,
      body: {
        discussion_board_tag_id: tag2.id,
        // category id is not changed
      },
    });
  typia.assert(updatedAssignment);
  TestValidator.equals("category unchanged")(
    updatedAssignment.discussion_board_category_id,
  )(category.id);
  TestValidator.equals("tag updated")(
    updatedAssignment.discussion_board_tag_id,
  )(tag2.id);
}

