 * category-tag assignment.
 *
 * Steps:
 *
 * 1. Create a new discussion board category (admin privilege).
 * 2. Create a new tag (admin privilege).
 * 3. Assign the tag to the category, receiving a new assignment record.
 * 4. Delete the assignment using its unique ID via the admin API.
 * 5. Validate that the assignment is gone after deletion by attempting to delete
 *    again (should throw error).
 *
 * This ensures that the category-tag assignment is completely hard deleted and
 * cannot be found or operated upon after deletion.
 */
export async function test_api_discussionBoard_test_admin_delete_category_tag_assignment_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board category.
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
