/**
 * Verify that fetching board settings reflects the most recent admin update.
 *
 * Scenario:
 *
 * 1. Fetch the current board settings to obtain the boardSettingId and the initial
 *    values.
 * 2. Update the board settings as an admin to known, controlled values (title,
 *    description, enabled, logo_uri).
 * 3. Fetch the board settings again via the main GET endpoint.
 * 4. Assert that all returned fields reflect the update input, validating API-data
 *    consistency.
 * 5. Ensure audit timestamps show updated_at >= created_at, confirming update
 *    propagation.
 *
 * This test ensures that the latest admin-initiated configuration changes are
 * correctly visible to frontend/API queries, and that board branding/system
 * controls truly update in real time for end users.
 */
export async function test_api_discussionBoard_test_fetch_board_settings_reflects_latest_updates(
  connection: api.IConnection,
) {
  // 1. Fetch current board settings to get the boardSettingId and base values
  const original: IDiscussionBoardBoardSetting =
    await api.functional.discussionBoard.boardSettings.index(connection);
  typia.assert(original);

  // 2. Prepare known update values
  const updateInput: IDiscussionBoardBoardSetting.IUpdate = {
    title: `${original.title} - updated by E2E`,
    description: original.description
      ? `${original.description} (amended)`
      : "Automated description for test",
    enabled: !original.enabled,
    logo_uri:
      original.logo_uri ?? "https://cdn.example.com/autobe-logo-e2e.png",
  };

  // 3. Update settings as admin
  const updated: IDiscussionBoardBoardSetting =
    await api.functional.discussionBoard.admin.boardSettings.update(
      connection,
      {
        boardSettingId: original.id,
        body: updateInput,
      },
    );
  typia.assert(updated);

  // 4. Fetch settings again to check propagation
  const fetched: IDiscussionBoardBoardSetting =
    await api.functional.discussionBoard.boardSettings.index(connection);
  typia.assert(fetched);

  // 5. Assert that field values reflect the update and have not regressed
  TestValidator.equals("title reflects update")(fetched.title)(
    updateInput.title ?? original.title,
  );
  TestValidator.equals("enabled reflects update")(fetched.enabled)(
    updateInput.enabled ?? original.enabled,
  );
  TestValidator.equals("description reflects update")(fetched.description)(
    updateInput.description ?? original.description ?? null,
  );
  TestValidator.equals("logo_uri reflects update")(fetched.logo_uri)(
    updateInput.logo_uri ?? original.logo_uri ?? null,
  );
  TestValidator.predicate("updated_at is newer or equal to created_at")(
    new Date(fetched.updated_at).getTime() >=
      new Date(fetched.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
