import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";
import type { IPageIDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuthToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and paginating authentication tokens with a variety of
 * valid filter combinations such as actor_type, issued_at date range, and
 * revoked status.
 *
 * This test verifies that the search API for admin auth tokens can handle
 * multi-criteria search/filtering in a realistic administrative scenario. We
 * ensure that the system has tokens for various actor types (admin, member,
 * moderator, guest) and different revoked states. For robust pagination, we
 * create more than one token for some types/statuses.
 *
 * Steps:
 *
 * 1. Create tokens for each actor_type (admin, member, moderator, guest) and for
 *    different revoked statuses (revoked and not revoked).
 * 2. Perform a search filtered by a single actor_type (e.g., 'admin') and verify
 *    only tokens for that type are returned.
 * 3. Perform a search filtered for revoked tokens only and check results.
 * 4. Search for tokens issued within a specific date range. Validate all returned
 *    tokens fall within that range.
 * 5. Apply pagination with limit and page values, verify both returned data and
 *    the pagination meta are correct.
 * 6. Combine multiple filters (e.g., actor_type + revoked + issued_at range) and
 *    check only exact matches are returned.
 */
export async function test_api_discussionBoard_admin_authTokens_test_search_auth_tokens_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Create tokens for different actor_type/revoked combinations
  const now = new Date();
  const tokenData = [
    { actor_type: "admin", revoked: false },
    { actor_type: "admin", revoked: true },
    { actor_type: "member", revoked: false },
    { actor_type: "moderator", revoked: true },
    { actor_type: "guest", revoked: false },
    { actor_type: "member", revoked: true },
  ];
  const allTokens: IDiscussionBoardAuthToken[] = [];
  for (const [i, info] of tokenData.entries()) {
    // Stagger issued_at times for date-range tests
    const issued_at = new Date(
      now.getTime() - i * 60 * 60 * 1000,
    ).toISOString(); // each token 1hr apart
    const expires_at = new Date(
      now.getTime() + 24 * 60 * 60 * 1000,
    ).toISOString(); // all expire in 24hr
    const createInput: IDiscussionBoardAuthToken.ICreate = {
      actor_type: info.actor_type,
      token: typia.random<string>(),
      issued_at,
      expires_at,
      admin_id:
        info.actor_type === "admin"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      moderator_id:
        info.actor_type === "moderator"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      member_id:
        info.actor_type === "member"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      guest_id:
        info.actor_type === "guest"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
    };
    const t = await api.functional.discussionBoard.admin.authTokens.create(
      connection,
      { body: createInput },
    );
    typia.assert(t);
    // Simulate revocation by setting test record status
    allTokens.push({ ...t, revoked: info.revoked });
  }

  // 2. Search by actor_type 'admin'
  {
    const res = await api.functional.discussionBoard.admin.authTokens.search(
      connection,
      { body: { actor_type: "admin" } },
    );
    typia.assert(res);
    TestValidator.predicate("all tokens actor_type is admin")(
      res.data.every((x) => x.actor_type === "admin"),
    );
  }

  // 3. Search for revoked tokens
  {
    const res = await api.functional.discussionBoard.admin.authTokens.search(
      connection,
      { body: { revoked: true } },
    );
    typia.assert(res);
    TestValidator.predicate("all tokens are revoked")(
      res.data.every((x) => x.revoked === true),
    );
  }

  // 4. Search for tokens issued within a date range
  {
    // Use time window that should include a subset
    const from = new Date(now.getTime() - 2 * 60 * 60 * 1000).toISOString();
    const to = now.toISOString();
    const res = await api.functional.discussionBoard.admin.authTokens.search(
      connection,
      { body: { issued_at_from: from, issued_at_to: to } },
    );
    typia.assert(res);
    TestValidator.predicate("all tokens issued in window")(
      res.data.every((x) => x.issued_at >= from && x.issued_at <= to),
    );
  }

  // 5. Apply pagination (limit/page)
  {
    const res = await api.functional.discussionBoard.admin.authTokens.search(
      connection,
      { body: { limit: 2, page: 1 } },
    );
    typia.assert(res);
    TestValidator.equals("limit")(res.pagination.limit)(2);
    TestValidator.equals("page")(res.pagination.current)(1);
    TestValidator.predicate("no more than limit tokens")(res.data.length <= 2);
  }

  // 6. Combine filters: actor_type=member, revoked=true, and matching issued_at
  {
    const target = allTokens.find(
      (x) => x.actor_type === "member" && x.revoked === true,
    );
    if (!target) throw new Error("Test setup failed: missing expected token");
    const res = await api.functional.discussionBoard.admin.authTokens.search(
      connection,
      {
        body: {
          actor_type: "member",
          revoked: true,
          issued_at_from: target.issued_at,
          issued_at_to: target.issued_at,
        },
      },
    );
    typia.assert(res);
    TestValidator.predicate("all tokens match filters")(
      res.data.every(
        (x) =>
          x.actor_type === "member" &&
          x.revoked === true &&
          x.issued_at === target.issued_at,
      ),
    );
  }
}

