import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Validate that an admin can successfully revoke an authentication token in the
 * discussion board system.
 *
 * This test ensures that a valid (non-revoked) authentication token can be
 * updated to a revoked state.
 *
 * Business rules:
 *
 * - A token must exist and not be revoked prior to the update attempt.
 * - Revoking the token sets 'revoked' to true; expiry remains unchanged unless
 *   the token was already expired.
 * - The returned result after update should show 'revoked: true' and (unless
 *   intentionally expired) not change the existing expires_at.
 *
 * Test workflow:
 *
 * 1. Create a valid authentication token assigned to an admin (not revoked).
 * 2. Update this token to set 'revoked: true'.
 * 3. Validate that the returned record now has revoked: true and that the id
 *    matches the original token.
 * 4. Confirm that expires_at is unmodified (unless the created token was already
 *    expired).
 *
 * Edge case: If expires_at is in the past (token already expired), check that
 * revoked is still set to true, but test does not manipulate expiry in this
 * scenario.
 */
export async function test_api_discussionBoard_admin_authTokens_test_update_auth_token_revoke_status(
  connection: api.IConnection,
) {
  // 1. Create a new authentication token assigned to an admin (not revoked)
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const token: IDiscussionBoardAuthToken =
    await api.functional.discussionBoard.admin.authTokens.create(connection, {
      body: {
        admin_id: adminId,
        actor_type: "admin",
        token: typia.random<string>(),
        issued_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1 hour in the future
      } satisfies IDiscussionBoardAuthToken.ICreate,
    });
  typia.assert(token);
  TestValidator.equals("token not revoked precondition")(token.revoked)(false);

  // 2. Update this token to set 'revoked: true'
  const updated: IDiscussionBoardAuthToken =
    await api.functional.discussionBoard.admin.authTokens.update(connection, {
      authTokenId: token.id,
      body: {
        revoked: true,
      } satisfies IDiscussionBoardAuthToken.IUpdate,
    });
  typia.assert(updated);

  // 3. Validate the returned record now has 'revoked: true' and id matches
  TestValidator.equals("token id matches after update")(updated.id)(token.id);
  TestValidator.equals("revoked is now true")(updated.revoked)(true);

  // 4. Confirm that expires_at is unchanged (or still defined and matches original)
  TestValidator.equals("expires_at unchanged")(updated.expires_at)(
    token.expires_at,
  );
}

