  const page =
    await api.functional.discussionBoard.member.notificationSettings.index(
      connection,
    );
  typia.assert(page);

  // 3. Assert each returned setting belongs to the created member and all required fields are valid
  for (const setting of page.data) {
    TestValidator.equals("Returned member_id matches the new member")(
      setting.member_id,
    )(member.id);

    // Validate presence and types of all required fields
    TestValidator.predicate("Valid setting ID")(
      typeof setting.id === "string" && setting.id.length > 0,
    );
    TestValidator.predicate("Valid created_at")(
      typeof setting.created_at === "string",
    );
    TestValidator.predicate("Valid updated_at")(
      typeof setting.updated_at === "string",
    );
    TestValidator.predicate("in_app_enabled is boolean")(
      typeof setting.in_app_enabled === "boolean",
    );
    TestValidator.predicate("email_enabled is boolean")(
      typeof setting.email_enabled === "boolean",
    );
    TestValidator.predicate("moderation_notification_enabled is boolean")(
      typeof setting.moderation_notification_enabled === "boolean",
    );
    TestValidator.predicate("reply_notification_enabled is boolean")(
      typeof setting.reply_notification_enabled === "boolean",
    );
    TestValidator.predicate("vote_notification_enabled is boolean")(
      typeof setting.vote_notification_enabled === "boolean",
    );
  }

  // 4. Pagination metadata is present and correct
  TestValidator.predicate("Pagination block is present")(
    typeof page.pagination === "object",
  );
  TestValidator.predicate("pagination.current is valid int")(
    typeof page.pagination.current === "number" &&
      Number.isInteger(page.pagination.current) &&
      page.pagination.current > 0,
  );
  TestValidator.predicate("pagination.limit is valid")(
    typeof page.pagination.limit === "number" && page.pagination.limit > 0,
  );
  TestValidator.predicate("pagination.records is valid")(
    typeof page.pagination.records === "number" && page.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages is valid")(
    typeof page.pagination.pages === "number" && page.pagination.pages >= 1,
  );
  TestValidator.predicate("pagination.records matches data length")(
    page.pagination.records === page.data.length,
  );

  // 5. Redundant: repeat call to check stability/idempotency
  const page2 =
    await api.functional.discussionBoard.member.notificationSettings.index(
      connection,
    );
  typia.assert(page2);
  TestValidator.equals("Pagination should match for subsequent identical call")(
    page2.pagination,
  )(page.pagination);
  TestValidator.equals("Data array should match for subsequent identical call")(
    page2.data,
  )(page.data);
}

