import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that an admin can filter their notification settings by notification
 * category (moderation/reply/vote) and that pagination returns correct data.
 *
 * Business context: This test checks the admin-facing API for
 * searching/filtering notification settings. An admin should be able to
 * retrieve only those notification settings entries that match chosen
 * enablement flags (moderation, reply, vote), and response pagination metadata
 * should be accurate. Both positive and negative filter cases are checked.
 *
 * Test process:
 *
 * 1. Create an admin account for testing.
 * 2. Create several notification settings entries for the admin, each enabling
 *    only a unique notification category (moderation, reply, vote).
 * 3. For each notification type (moderation, reply, vote): a. Search by that
 *    category (enabled=true), check that returned settings have the queried
 *    category enabled and admin_id correct. b. Confirm the response is paged
 *    and paging fields are sensible.
 * 4. Negative: Search for records with all categories disabled—no results should
 *    be returned.
 */
export async function test_api_discussionBoard_test_search_notification_settings_admin_by_category(
  connection: api.IConnection,
) {
  // 1. Create an admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUsername: string = RandomGenerator.alphaNumeric(10);
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: adminUsername,
        email: adminEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Create several notification settings, each enabling only one category
  const settings = [
    // Moderation enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: true,
          email_enabled: false,
          moderation_notification_enabled: true,
          reply_notification_enabled: false,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
    // Reply enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: false,
          email_enabled: true,
          moderation_notification_enabled: false,
          reply_notification_enabled: true,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
    // Vote enabled only
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: admin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: true,
          email_enabled: true,
          moderation_notification_enabled: false,
          reply_notification_enabled: false,
          vote_notification_enabled: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    ),
  ];
  for (const setting of settings) typia.assert(setting);

  // Helper to search and validate a category
  async function filterAndValidate(
    category: keyof Pick<
      IDiscussionBoardNotificationSetting,
      | "moderation_notification_enabled"
      | "reply_notification_enabled"
      | "vote_notification_enabled"
    >,
  ) {
    const searchBody: IDiscussionBoardNotificationSetting.IRequest = {
      [category]: true,
      page: 1,
      limit: 10,
    };
    const pageResult =
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: searchBody,
        },
      );
    typia.assert(pageResult);
    for (const rec of pageResult.data) {
      TestValidator.equals(category + " enabled")(rec[category])(true);
      TestValidator.equals("admin match")(rec.admin_id)(admin.id);
    }
    TestValidator.predicate("at least one result for " + category)(
      pageResult.data.length > 0,
    );
    TestValidator.equals("pagination: page 1")(pageResult.pagination.current)(
      1,
    );
    TestValidator.equals("pagination: limit 10")(pageResult.pagination.limit)(
      10,
    );
  }

  await filterAndValidate("moderation_notification_enabled");
  await filterAndValidate("reply_notification_enabled");
  await filterAndValidate("vote_notification_enabled");

  // 4. Negative: search where all categories are disabled
  const resultNone =
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: {
          moderation_notification_enabled: false,
          reply_notification_enabled: false,
          vote_notification_enabled: false,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resultNone);
  TestValidator.equals("no results for all categories false")(
    resultNone.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error handling in the notification settings admin search endpoint
 * when supplied with invalid filters/query parameters.
 *
 * This test ensures the API surfaces proper validation errors—not
 * internal/unexpected errors—if the admin submits search queries with:
 *
 * - Malformed request properties (wrong data types for schema fields)
 * - Incorrectly-formatted date parameters (not valid ISO 8601 strings)
 * - Negative or unreasonably large pagination values
 *
 * The API must provide clear validation errors, not generic 500-level
 * responses.
 *
 * Steps:
 *
 * 1. Create an admin account for authentication/role
 * 2. Attempt to search notification settings as admin with malformed requests: a.
 *    Supply string instead of boolean for a boolean filter b. Provide non-date
 *    strings for 'created_at_from'/'created_at_to' c. Provide negative/absurdly
 *    large page or limit values
 * 3. For each, verify the API throws a validation error but not an infrastructural
 *    error.
 */
export async function test_api_discussionBoard_test_search_notification_settings_admin_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Create an admin account.
  const adminInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(12),
    is_active: true,
  } satisfies IDiscussionBoardAdmin.ICreate;
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    { body: adminInput },
  );
  typia.assert(admin);

  // a. Use string for a boolean field (should trigger validation error)
  await TestValidator.error("search fails when boolean filters are strings")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { in_app_enabled: "yes" as unknown as boolean },
        },
      );
    },
  );

  // b. Malformed date values for from/to
  await TestValidator.error(
    "search fails on invalid created_at_from date string",
  )(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { created_at_from: "not-a-date" as any },
      },
    );
  });
  await TestValidator.error(
    "search fails on malformed created_at_to date string",
  )(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { created_at_to: "1234567890" as any },
      },
    );
  });

  // c. Use negative paging
  await TestValidator.error("search fails when page is negative")(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { page: -1 },
      },
    );
  });
  await TestValidator.error("search fails when limit is negative")(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.search(
      connection,
      {
        body: { limit: -5 },
      },
    );
  });

  // d. Out-of-range large page/limit
  await TestValidator.error("search fails on unreasonably large page")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { page: 999999999 },
        },
      );
    },
  );
  await TestValidator.error("search fails on unreasonably large limit")(
    async () => {
      await api.functional.discussionBoard.admin.notificationSettings.search(
        connection,
        {
          body: { limit: 9999999 },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator notification settings search and filtering with advanced
 * parameters.
 *
 * This test ensures a moderator can search their notification settings by
 * delivery channel (in-app/email), individual notification categories, and
 * creation time ranges. It guarantees that:
 *
 * - Only records for the current moderator are returned, never other users'
 *   settings.
 * - All filters (channel toggles, category toggles, date range) are respected
 *   individually and in combination.
 * - Pagination and page/limit query parameters control result data and metadata
 *   correctly.
 *
 * Steps:
 *
 * 1. Create four notification settings records (as the current moderator), each
 *    with unique channel/category flag permutations and distinct creation
 *    dates.
 * 2. Perform a series of searches, each filtering on different fields or
 *    combinations (channel toggle, category toggle, created_at date range,
 *    combined filters).
 * 3. For each search, validate that every result matches only the requested
 *    criteria and belongs to the moderator.
 * 4. Use pages/limits to confirm that pagination actually segments the result set
 *    as expected, and that metadata matches the response payload.
 *
 * All output is type-asserted. No DTO or API calls are made outside the
 * documented/allowed interfaces.
 */
export async function test_api_discussionBoard_moderator_notificationSettings_test_search_notification_settings_with_various_filters_as_moderator(
  connection: api.IConnection,
) {
  // 1. Create four notification settings with broad permutations and spaced timestamps
  const now = new Date();
  const isoDate = (days: number) =>
    new Date(now.getTime() + days * 86400 * 1000).toISOString();
  const settingsDatas = [
    {
      in_app_enabled: true,
      email_enabled: true,
      moderation_notification_enabled: true,
      reply_notification_enabled: false,
      vote_notification_enabled: false,
      created_at: isoDate(-3),
      updated_at: isoDate(-3),
    },
    {
      in_app_enabled: false,
      email_enabled: true,
      moderation_notification_enabled: false,
      reply_notification_enabled: true,
      vote_notification_enabled: false,
      created_at: isoDate(-2),
      updated_at: isoDate(-2),
    },
    {
      in_app_enabled: false,
      email_enabled: false,
      moderation_notification_enabled: true,
      reply_notification_enabled: false,
      vote_notification_enabled: true,
      created_at: isoDate(-1),
      updated_at: isoDate(-1),
    },
    {
      in_app_enabled: true,
      email_enabled: false,
      moderation_notification_enabled: false,
      reply_notification_enabled: true,
      vote_notification_enabled: true,
      created_at: isoDate(0),
      updated_at: isoDate(0),
    },
  ];
  const createdSettings = [];
  for (const data of settingsDatas) {
    const output =
      await api.functional.discussionBoard.moderator.notificationSettings.create(
        connection,
        {
          body: {
            moderator_id: null, // For current actor
            admin_id: null,
            member_id: null,
            guest_id: null,
            ...data,
          },
        },
      );
    typia.assert(output);
    createdSettings.push(output);
  }

  // 2. Search: in_app_enabled true
  const resInAppEnabled =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      { body: { in_app_enabled: true } },
    );
  typia.assert(resInAppEnabled);
  for (const row of resInAppEnabled.data) {
    TestValidator.equals("in_app_enabled results")(row.in_app_enabled)(true);
  }

  // 3. Search: email_enabled false
  const resEmailDisabled =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      { body: { email_enabled: false } },
    );
  typia.assert(resEmailDisabled);
  for (const row of resEmailDisabled.data) {
    TestValidator.equals("email_enabled results")(row.email_enabled)(false);
  }

  // 4. Search: moderation_notification_enabled true
  const resModeration =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      { body: { moderation_notification_enabled: true } },
    );
  typia.assert(resModeration);
  for (const row of resModeration.data) {
    TestValidator.equals("moderation_notification_enabled results")(
      row.moderation_notification_enabled,
    )(true);
  }

  // 5. Search: reply_notification_enabled false
  const resReplyDisabled =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      { body: { reply_notification_enabled: false } },
    );
  typia.assert(resReplyDisabled);
  for (const row of resReplyDisabled.data) {
    TestValidator.equals("reply_notification_enabled results")(
      row.reply_notification_enabled,
    )(false);
  }

  // 6. Search: created_at range
  const from = isoDate(-2.5);
  const to = isoDate(-0.5);
  const resTimeRange =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      {
        body: {
          created_at_from: from,
          created_at_to: to,
        },
      },
    );
  typia.assert(resTimeRange);
  for (const row of resTimeRange.data) {
    TestValidator.predicate("created_at in range")(
      row.created_at >= from && row.created_at <= to,
    );
  }

  // 7. Pagination: limit 2, page 1
  const resPage1 =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      {
        body: {
          page: 1,
          limit: 2,
        },
      },
    );
  typia.assert(resPage1);
  TestValidator.equals("pagination limit")(resPage1.pagination.limit)(2);
  TestValidator.equals("pagination current")(resPage1.pagination.current)(1);
  TestValidator.predicate("page 1 <= 2 results")(resPage1.data.length <= 2);

  // 8. Pagination: limit 2, page 2
  const resPage2 =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      {
        body: {
          page: 2,
          limit: 2,
        },
      },
    );
  typia.assert(resPage2);
  TestValidator.equals("pagination limit")(resPage2.pagination.limit)(2);
  TestValidator.equals("pagination current")(resPage2.pagination.current)(2);
  TestValidator.predicate("page 2 <= 2 results")(resPage2.data.length <= 2);

  // 9. Combined filter: in_app_enabled true AND vote_notification_enabled true
  const resCombo =
    await api.functional.discussionBoard.moderator.notificationSettings.search(
      connection,
      {
        body: {
          in_app_enabled: true,
          vote_notification_enabled: true,
        },
      },
    );
  typia.assert(resCombo);
  for (const row of resCombo.data) {
    TestValidator.equals("in_app_enabled combo")(row.in_app_enabled)(true);
    TestValidator.equals("vote_notification_enabled combo")(
      row.vote_notification_enabled,
    )(true);
  }

  // 10. Validate all search results: Only current moderator's records returned
  for (const group of [
    resInAppEnabled,
    resEmailDisabled,
    resModeration,
    resReplyDisabled,
    resTimeRange,
    resCombo,
    resPage1,
    resPage2,
  ]) {
    for (const row of group.data) {
      TestValidator.predicate("must belong to moderator or be self-settings")(
        row.moderator_id === null || typeof row.moderator_id === "string",
      );
    }
  }
}

