import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate guest notification settings search returns only authenticated
 * guest's own data (never another's).
 *
 * Business context:
 *
 * - Guests can create notification settings for their session.
 * - Each guest session must be fully isolated: a guest should never see
 *   notification settings belonging to another session or any
 *   member/moderator/admin.
 *
 * Steps:
 *
 * 1. Register notification setting for this guest session ("main guest").
 * 2. Register notification setting in another guest session (for isolation
 *    negative check).
 * 3. Search with no filters in main session; verify only own record(s) appear.
 * 4. Search with filters that could match both sessions, but verify still only
 *    main session data is returned.
 * 5. Repeat in other session to confirm same isolation.
 *
 * Notes:
 *
 * - Guest session separation here is simulated by constructing an independent
 *   connection object (with headers/cookies cleared/unique). In a full E2E
 *   framework, a dedicated guest session login/register utility would ensure
 *   unique isolation if required.
 */
export async function test_api_discussionBoard_guest_notificationSettings_test_guest_search_notification_settings_returns_own_settings_only(
  connection: api.IConnection,
) {
  // 1. Register notification setting for main guest session
  const now = new Date().toISOString();
  const mainSetting =
    await api.functional.discussionBoard.guest.notificationSettings.create(
      connection,
      {
        body: {
          in_app_enabled: true,
          email_enabled: false,
          moderation_notification_enabled: true,
          reply_notification_enabled: false,
          vote_notification_enabled: true,
          created_at: now,
          updated_at: now,
          // Don't specify *_id fields: API identifies active guest automatically
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    );
  typia.assert(mainSetting);

  // 2. Register notification setting for "other" guest session
  // - Simulate new guest session by removing any potential identifiers from connection
  const connection2 = {
    ...connection,
    headers: { ...connection.headers },
  };
  // Remove session tokens/cookies to simulate guest isolation
  delete connection2.headers["cookie"];
  delete connection2.headers["authorization"];
  const now2 = new Date(Date.now() + 1000).toISOString();
  const otherSetting =
    await api.functional.discussionBoard.guest.notificationSettings.create(
      connection2,
      {
        body: {
          in_app_enabled: false,
          email_enabled: true,
          moderation_notification_enabled: false,
          reply_notification_enabled: true,
          vote_notification_enabled: false,
          created_at: now2,
          updated_at: now2,
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    );
  typia.assert(otherSetting);

  // 3. Main session: Search with no filter
  {
    const page =
      await api.functional.discussionBoard.guest.notificationSettings.search(
        connection,
        {
          body: {}, // No filters
        },
      );
    typia.assert(page);
    for (const s of page.data) {
      // Every record must belong to the main guest only
      TestValidator.equals("results are only from own session")(s.guest_id)(
        mainSetting.guest_id,
      );
      // No record may be from other guest
      TestValidator.notEquals("no other guest's settings visible")(s.guest_id)(
        otherSetting.guest_id,
      );
      // There should NOT be any admin, member, or moderator settings
      TestValidator.equals("is not member setting")(s.member_id)(null);
      TestValidator.equals("is not admin setting")(s.admin_id)(null);
      TestValidator.equals("is not moderator setting")(s.moderator_id)(null);
    }
  }
  // 4. Main session: Search with filter (vote_notification_enabled: true, which only mainSetting has)
  {
    const page =
      await api.functional.discussionBoard.guest.notificationSettings.search(
        connection,
        {
          body: {
            vote_notification_enabled: true,
          },
        },
      );
    typia.assert(page);
    for (const s of page.data) {
      TestValidator.equals("is still own session")(s.guest_id)(
        mainSetting.guest_id,
      );
      TestValidator.notEquals("no other guest via filter")(s.guest_id)(
        otherSetting.guest_id,
      );
      TestValidator.equals("is not member setting")(s.member_id)(null);
      TestValidator.equals("is not admin setting")(s.admin_id)(null);
      TestValidator.equals("is not moderator setting")(s.moderator_id)(null);
    }
  }
  // 5. Other session: Search with no filters, must also see only own
  {
    const page =
      await api.functional.discussionBoard.guest.notificationSettings.search(
        connection2,
        {
          body: {},
        },
      );
    typia.assert(page);
    for (const s of page.data) {
      TestValidator.equals("results belong to other guest")(s.guest_id)(
        otherSetting.guest_id,
      );
      TestValidator.notEquals("not main guest")(s.guest_id)(
        mainSetting.guest_id,
      );
      TestValidator.equals("not member")(s.member_id)(null);
      TestValidator.equals("not admin")(s.admin_id)(null);
      TestValidator.equals("not moderator")(s.moderator_id)(null);
    }
  }
}

