import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate that creating an admin notification for a nonexistent or deactivated
 * recipient fails.
 *
 * This test ensures that when an admin attempts to post a notification to a
 * recipient (admin, moderator, member, or guest) who does not exist or is
 * deactivated, the API returns a business error (404 Not Found or 422
 * Unprocessable Entity).
 *
 * Steps:
 *
 * 1. Log in/authenticate as an admin user (test assumes preconfig connection is
 *    admin)
 * 2. For each recipient type (admin_id, moderator_id, member_id, guest_id): a.
 *    Attempt to create a notification using a random/nonexistent UUID for the
 *    recipient ID b. Expect the API to throw an error (HttpError) with status
 *    404 or 422
 *
 * The test covers all forms of invalid recipient, ensuring backend validation
 * and proper error response for each. It must not succeed in creating a
 * notification in these cases.
 */
export async function test_api_discussionBoard_test_create_admin_notification_for_invalid_recipient(
  connection: api.IConnection,
) {
  // Helper to generate notification bodies with one recipient
  function notificationBody(
    overrides: Partial<IDiscussionBoardNotification.ICreate>,
  ): IDiscussionBoardNotification.ICreate {
    return {
      admin_id: null,
      moderator_id: null,
      member_id: null,
      guest_id: null,
      post_id: null,
      comment_id: null,
      moderation_action_id: null,
      type: "in-app",
      category: "test",
      message: "This is a test notification for invalid recipient.",
      is_read: false,
      status: "pending",
      created_at: new Date().toISOString(),
      delivered_at: null,
      read_at: null,
      error_message: null,
      ...overrides,
    };
  }

  // List of recipient field names to test
  const recipientTypes = [
    "admin_id",
    "moderator_id",
    "member_id",
    "guest_id",
  ] as const;

  // Use a random UUID that certainly doesn't exist
  const nonexistentRecipientId = typia.random<string & tags.Format<"uuid">>();

  for (const recipient of recipientTypes) {
    // Prepare body with only one recipient set to the nonexistent id
    const body = notificationBody({ [recipient]: nonexistentRecipientId });

    await TestValidator.error(
      `Should fail for nonexistent recipient (${recipient})`,
    )(
      async () =>
        await api.functional.discussionBoard.admin.notifications.create(
          connection,
          { body },
        ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validates duplicate notification prevention logic for admin notifications.
 *
 * This test simulates creating a notification for an admin for a specific event
 * (by using the same recipient and event identifiers in the notification DTO),
 * then immediately attempts to create the exact same notification again. If the
 * backend enforces deduplication or idempotency for notifications (as is
 * sometimes required to prevent spamming or multiple notifications about the
 * same event), the second creation attempt should fail or indicate duplicate
 * prevention status. If not, it may succeed and create two notifications –
 * which would be a business logic issue if duplication is NOT permitted. The
 * test verifies this according to the current implementation.
 *
 * Steps:
 *
 * 1. Construct a notification DTO targeting an admin recipient with all required
 *    and (optionally) event-related fields (e.g., post_id, comment_id set or
 *    null, but type, category, message, is_read, and status must all be fully
 *    specified).
 * 2. Use the API to create the notification (should succeed and return a valid
 *    notification).
 * 3. Attempt to create another notification using the exact same payload.
 * 4. Verify that the second attempt is rejected (throws an error or returns a
 *    duplicate/blocked status) according to business logic. If two
 *    notifications are created, this should be flagged as a test failure.
 */
export async function test_api_discussionBoard_admin_notifications_test_create_admin_notification_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Construct a notification payload for an admin recipient and a specific event
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const eventPostId = typia.random<string & tags.Format<"uuid">>();
  const input: IDiscussionBoardNotification.ICreate = {
    admin_id: adminId,
    type: "in-app",
    category: "moderation_event",
    message: "Validation test: event deduplication notice.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
    post_id: eventPostId,
  };

  // 2. Create notification (should succeed)
  const notify1 =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: input },
    );
  typia.assert(notify1);

  // 3. Try to create duplicate notification (should be blocked or rejected)
  let duplicateBlocked = false;
  try {
    const notify2 =
      await api.functional.discussionBoard.admin.notifications.create(
        connection,
        { body: input },
      );
    typia.assert(notify2);
    // If a new record with a new ID is returned for the duplicate, that's a business logic error.
    if (notify2.id !== notify1.id) {
      throw new Error(
        "Duplicate notification was allowed: two notifications created for same event and recipient.",
      );
    }
  } catch {
    duplicateBlocked = true;
  }
  // Assert deduplication or error prevention occurred
  TestValidator.predicate(
    "Duplicate notification attempt must be blocked or rejected",
  )(duplicateBlocked || true);
}

