/**
 * Test successful notification creation by a moderator for a valid recipient
 * (admin, moderator, member, or guest).
 *
 * This test verifies that a moderator can create a notification by sending a
 * POST request to the /discussionBoard/moderator/notifications endpoint, that
 * all mandatory fields are included, and that the notification becomes visible
 * for the intended recipient.
 *
 * Steps:
 *
 * 1. Generate valid notification creation data, specifying exactly one recipient
 *    of type admin_id, moderator_id, member_id, or guest_id.
 * 2. Call the moderator notifications create API endpoint as a moderator role.
 * 3. Assert that the API responds with a valid notification and the response
 *    object represents a notification matching the input (type, category,
 *    message, etc.).
 * 4. Assert that the notification fields (id, status, is_read, created_at, etc.)
 *    are present and correctly reflect initial sent state.
 * 5. Optionally (if available), retrieve the notification list for the recipient
 *    and assert the new notification appears.
 */
export async function test_api_discussionBoard_test_create_moderator_notification_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Generate notification creation data targeting a moderator recipient
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const input: IDiscussionBoardNotification.ICreate = {
    moderator_id: moderatorId,
    type: "in-app",
    category: "moderation_event",
    message: "You have received a test moderator notification.",
    is_read: false,
    status: "sent",
    created_at: now,
    delivered_at: now,
    read_at: null,
    error_message: null,
  };

  // 2. Call the API to create a new notification
  const output =
    await api.functional.discussionBoard.moderator.notifications.create(
      connection,
      { body: input },
    );
  typia.assert(output);

  // 3. Validate the main properties of the notification in the result
  TestValidator.equals("moderator_id echoed correctly")(output.moderator_id)(
    moderatorId,
  );
  TestValidator.equals("type echoed correctly")(output.type)(input.type);
  TestValidator.equals("category echoed correctly")(output.category)(
    input.category,
  );
  TestValidator.equals("message echoed correctly")(output.message)(
    input.message,
  );
  TestValidator.equals("is_read is false initially")(output.is_read)(false);
  TestValidator.equals("status is sent")(output.status)("sent");

  // 4. Confirm required fields are present and valid
  TestValidator.predicate("id should be uuid")(
    typeof output.id === "string" && output.id.length > 0,
  );
  TestValidator.predicate("created_at matches")(output.created_at === now);
  TestValidator.predicate("delivered_at matches")(output.delivered_at === now);
  TestValidator.equals("read_at should be null")(output.read_at)(null);
  TestValidator.equals("error_message should be null")(output.error_message)(
    null,
  );

  // 5. Note: Retrieval of recipient's notification list and assertion is omitted, as no such endpoint is provided.
}

