import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate marking an admin notification as read by the admin.
 *
 * This test checks that an admin can successfully update a notification's
 * 'is_read' status to true, and that only the intended fields are updated
 * (admin ownership, message integrity, etc). It focuses on the direct update of
 * the flag and the persistency of other notification data, following the
 * standard admin notification handling process.
 *
 * Steps:
 *
 * 1. Create a notification for the admin using the notification creation endpoint
 * 2. Update that notification by setting 'is_read' to true as the admin
 * 3. Confirm the updated notification has 'is_read' set to true, and other
 *    relevant fields ( like admin_id, message) remain correct and unchanged
 */
export async function test_api_discussionBoard_test_admin_update_notification_mark_as_read(
  connection: api.IConnection,
) {
  // 1. Create a notification for an admin
  // Use a random admin UUID to simulate a unique admin recipient
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const notificationInput: IDiscussionBoardNotification.ICreate = {
    admin_id: adminId,
    moderator_id: null,
    member_id: null,
    guest_id: null,
    post_id: null,
    comment_id: null,
    moderation_action_id: null,
    type: "in-app",
    category: "system",
    message: "Test notification - please mark as read.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
    delivered_at: null,
    read_at: null,
    error_message: null,
  };
  const created =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: notificationInput },
    );
  typia.assert(created);

  // 2. Mark the notification as read by updating its 'is_read' field
  const updated =
    await api.functional.discussionBoard.admin.notifications.update(
      connection,
      {
        notificationId: created.id,
        body: {
          is_read: true,
          read_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(updated);

  // 3. Confirm the notification has been marked as read
  TestValidator.equals("notification was marked read")(updated.is_read)(true);
  // Confirm admin ownership and message are unchanged
  TestValidator.equals("admin_id persists")(updated.admin_id)(adminId);
  TestValidator.equals("original message persists")(updated.message)(
    notificationInput.message,
  );
}

