 *
 * This test verifies that an authenticated moderator can successfully update
 * one of their own notifications, specifically toggling the 'is_read' flag to
 * true using its notificationId. The scenario ensures that only the owning
 * moderator sees this change, and that it does not affect any other user's
 * notifications.
 *
 * Steps:
 *
 * 1. Create a notification addressed to the moderator (to acquire a valid
 *    notificationId).
 * 2. As the same moderator, update this notification to set 'is_read' = true.
 * 3. Confirm that the update returns 200 OK and that the notification's 'is_read'
 *    property is now true.
 */
export async function test_api_discussionBoard_test_moderator_update_notification_mark_as_read(
  connection: api.IConnection,
) {
  // 1. Create a notification for the moderator
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const notificationCreateInput: IDiscussionBoardNotification.ICreate = {
    moderator_id: moderatorId,
    type: "in-app",
    category: "moderation_event",
    message: "Moderator test notification for marking as read.",
    is_read: false,
    status: "pending",
    created_at: new Date().toISOString(),
