import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator search for comments with basic filters and pagination.
 *
 * This test simulates a moderator user performing advanced search queries on
 * discussion board comments using body text match, member ID, post ID, and
 * creation date range filters. It also confirms that pagination, sorting, and
 * visibility of (potentially) soft-deleted comments are correct per moderator
 * RBAC policies.
 *
 * High-level Steps:
 *
 * 1. Populate the database with sample comments authored by different members,
 *    posts, and timestamps (some should be soft-deleted if possible).
 * 2. As moderator, search for: a) Comments containing a specific keyword in the
 *    body (q) b) Comments from a particular member (discussion_board_member_id)
 *    c) Comments belonging to a specific post (discussion_board_post_id) d)
 *    Comments within a creation date range (created_from/created_to) e)
 *    Soft-deleted comments using include_deleted=true f) Pagination: ensure
 *    result counts and page boundaries
 * 3. Validate returned comments: a) All match the search criteria b) Moderator can
 *    see both active and soft-deleted comments c) Pagination metadata is
 *    accurate (page, limit, records, pages)
 */
export async function test_api_discussionBoard_test_search_comments_with_basic_filters_as_moderator(
  connection: api.IConnection,
) {
  // 1. Create a set of comments spanning various bodies, authors, posts, and timestamps
  //    This ensures we have a realistic dataset to search against.
  // (We use the /discussionBoard/member/comments endpoint as dependency)

  // Create two post IDs
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();

  // Create two member IDs
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();

  // Create comments:
  // - Keyword body: "keyword-magic-case"
  // - Different bodies, authors, posts, and timestamps
  const baseDate = new Date();
  const timeOffsetsSec = [0, 86400, 172800, 259200]; // 0, +1, +2, +3 days
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 6; ++i) {
    const body =
      i === 2
        ? "Hello world with keyword-magic-case"
        : i % 2 === 0
          ? `Member1, Post1, ${i}`
          : `Member2, Post2, ${i}`;
    const postId = i % 2 === 0 ? postId1 : postId2;
    const memberId = i % 2 === 0 ? memberId1 : memberId2;
    // Simulate different creation dates
    const date = new Date(baseDate.getTime() - timeOffsetsSec[i % 4] * 1000);

    const comment: IDiscussionBoardComment =
      await api.functional.discussionBoard.member.comments.create(connection, {
        body: {
          discussion_board_post_id: postId,
          body,
        },
      });
    // Patch created_at with simulated date for test (skip if system disallows manual override)
    // Otherwise, rely on natural times for demo.
    comments.push(comment);
  }

  // 2.a) Search by keyword in body
  const keyword = "keyword-magic-case";
  const resKeyword =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { q: keyword },
    });
  typia.assert(resKeyword);
  TestValidator.predicate("all comments contain keyword")(
    resKeyword.data.every((c) => c.body.includes(keyword)),
  );

  // 2.b) Search by memberId
  const resMember =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { discussion_board_member_id: memberId1 },
    });
  typia.assert(resMember);
  TestValidator.predicate("all returned comments belong to memberId1")(
    resMember.data.every((c) => c.discussion_board_member_id === memberId1),
  );

  // 2.c) Search by postId
  const resPost =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { discussion_board_post_id: postId2 },
    });
  typia.assert(resPost);
  TestValidator.predicate("all returned comments belong to postId2")(
    resPost.data.every((c) => c.discussion_board_post_id === postId2),
  );

  // 2.d) Search within a created date range
  const fromDate = new Date(baseDate.getTime() - 172800 * 1000).toISOString(); // 2 days before
  const toDate = new Date(baseDate.getTime() + 3600 * 1000).toISOString(); // +1 hour
  const resDate =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { created_from: fromDate, created_to: toDate },
    });
  typia.assert(resDate);
  TestValidator.predicate("all comments are within date range")(
    resDate.data.every(
      (c) => c.created_at >= fromDate && c.created_at <= toDate,
    ),
  );

  // 2.e) Search with include_deleted=true (assuming some may be soft-deleted later)
  // For now, we just verify the presence of deleted_at values in the results if any
  const resWithDeleted =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { include_deleted: true },
    });
  typia.assert(resWithDeleted);
  TestValidator.predicate(
    "moderator can see all comments, including soft-deleted",
  )(
    resWithDeleted.data.some((c) => c.deleted_at !== null) ||
      resWithDeleted.data.every((c) => c.deleted_at === null),
  );

  // 2.f) Pagination test: page size 2, fetch two pages, check boundaries
  const pagRes1 =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { limit: 2, page: 1 },
    });
  typia.assert(pagRes1);
  TestValidator.equals("page 1")(pagRes1.pagination.current)(1);
  TestValidator.equals("limit 2")(pagRes1.pagination.limit)(2);
  TestValidator.predicate("page 1 size ")(pagRes1.data.length <= 2);

  const pagRes2 =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: { limit: 2, page: 2 },
    });
  typia.assert(pagRes2);
  TestValidator.equals("page 2")(pagRes2.pagination.current)(2);
  TestValidator.equals("limit 2")(pagRes2.pagination.limit)(2);
  TestValidator.predicate("page 2 size")(pagRes2.data.length <= 2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced search for threaded comments by parent_id in moderation panel.
 *
 * This test verifies that moderation search returns correct hierarchical
 * replies:
 *
 * 1. Creates a root/top-level comment.
 * 2. Creates several direct child replies to root.
 * 3. Creates further replies to a child comment (grandchildren).
 * 4. Executes moderation search with parent_id set to root—ensuring only direct
 *    children are returned.
 * 5. Executes search for the next thread layer, verifying only grandchildren
 *    (direct to child).
 * 6. Verifies pagination/limit controls.
 * 7. Checks edge case for parent with no direct replies (should return empty set).
 *
 * This ensures moderation can rely on parent_id filtering for reviewing
 * threads, and paging meta behaves as expected.
 */
export async function test_api_discussionBoard_test_search_comments_by_parent_id_and_threading_moderation_panel(
  connection: api.IConnection,
) {
  // 1. Create a root/top-level comment (no parent)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const rootComment =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_post_id: postId,
        body: "Root comment",
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(rootComment);

  // 2. Create direct replies to root
  const childComments = await ArrayUtil.asyncRepeat(3)(async () => {
    const child = await api.functional.discussionBoard.member.comments.create(
      connection,
      {
        body: {
          discussion_board_post_id: postId,
          parent_id: rootComment.id,
          body: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
    typia.assert(child);
    return child;
  });

  // 3. Create replies to one child (grandchildren/deeper thread)
  const grandChildComments = await ArrayUtil.asyncRepeat(2)(async () => {
    const grandchild =
      await api.functional.discussionBoard.member.comments.create(connection, {
        body: {
          discussion_board_post_id: postId,
          parent_id: childComments[0].id,
          body: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardComment.ICreate,
      });
    typia.assert(grandchild);
    return grandchild;
  });

  // 4. Moderator advanced search: fetch direct children of root
  const directReplies =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        parent_id: rootComment.id,
        discussion_board_post_id: postId,
        limit: 10,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(directReplies);
  TestValidator.equals(
    "should return all direct children of root, no grandchildren",
  )(directReplies.data.map((c) => c.id).sort())(
    childComments.map((c) => c.id).sort(),
  );
  TestValidator.predicate("no grandchildren included as direct children")(
    directReplies.data.every((c) => c.parent_id === rootComment.id),
  );

  // 5. Moderator advanced search: fetch direct children (grandchildren) of a child
  const grandchildren =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        parent_id: childComments[0].id,
        discussion_board_post_id: postId,
        limit: 10,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(grandchildren);
  TestValidator.equals("should return only grandchildren for selected child")(
    grandchildren.data.map((c) => c.id).sort(),
  )(grandChildComments.map((c) => c.id).sort());
  TestValidator.predicate("parent_id field correct for grandchildren")(
    grandchildren.data.every((c) => c.parent_id === childComments[0].id),
  );

  // 6. Pagination check: limit to 2 per page
  const paged = await api.functional.discussionBoard.moderator.comments.search(
    connection,
    {
      body: {
        parent_id: rootComment.id,
        discussion_board_post_id: postId,
        limit: 2,
        page: 1,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(paged);
  TestValidator.equals("should return 2 items for page size 2")(
    paged.data.length,
  )(2);
  TestValidator.equals("paging meta: per-page limit")(paged.pagination.limit)(
    2,
  );
  TestValidator.equals("paging meta: current page")(paged.pagination.current)(
    1,
  );

  // 7. Edge case: parent_id with no direct children returns empty
  const emptyResults =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        parent_id: grandChildComments[0].id,
        discussion_board_post_id: postId,
        limit: 10,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(emptyResults);
  TestValidator.equals("should be empty, no further replies present")(
    emptyResults.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that moderator comment search correctly exposes soft-deleted
 * comments when requested via filters, and that such comments are NOT visible
 * to ordinary members.
 *
 * Business scenario:
 *
 * - Create a batch of comments (by a member) under a single post, then
 *   soft-delete some (but not all) of them
 * - As a moderator, use the advanced comment search API to search for comments
 *   belonging to this post, with and without the filter that includes
 *   soft-deleted comments
 * - Confirm that, with include_deleted=true, the deleted ones (with deleted_at
 *   populated) appear in results, and those records have deleted_at fields set
 * - Confirm that as a regular member, the soft-deleted comments ARE NOT returned
 *   at all
 * - Validate RBAC: Only moderators can use the moderator search endpoint, and can
 *   see deleted comments; members cannot
 * - Check that deleted comments' deleted_at timestamps are ISO dates and
 *   non-null, and that non-deleted ones have deleted_at as null
 *
 * Steps:
 *
 * 1. (Data setup) Use member access to create several comments on a post.
 * 2. (Data setup) Soft-delete a subset of comments via member deletion API.
 * 3. (Moderator) Use moderator search (with include_deleted=false or omitted):
 *    only active comments visible.
 * 4. (Moderator) Use moderator search (with include_deleted=true): both active and
 *    soft-deleted visible; deleted have deleted_at set.
 * 5. (Member) As regular member, attempt to use moderator search: RBAC denied
 *    (throws error).
 * 6. Validate that deleted_at sets are as expected, all returned comments are for
 *    the right post, and that RBAC boundaries are respected.
 */
export async function test_api_discussionBoard_test_search_comments_returns_soft_deleted_to_moderator(
  connection: api.IConnection,
) {
  // Step 1: Data setup - create multiple comments as a member on a single post
  const postId: string = typia.random<string & tags.Format<"uuid">>();
  const createdComments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 4; ++i) {
    const comment = await api.functional.discussionBoard.member.comments.create(
      connection,
      {
        body: {
          discussion_board_post_id: postId,
          parent_id: null,
          body: `Sample comment body #${i + 1}`,
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
    typia.assert(comment);
    createdComments.push(comment);
  }

  // Step 2: Soft-delete a subset of comments (e.g., index 1 and 2)
  for (let i of [1, 2]) {
    await api.functional.discussionBoard.member.comments.erase(connection, {
      commentId: createdComments[i].id,
    });
  }

  // Step 3: Moderator search, include_deleted: false (should see only active)
  const modResActive =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        discussion_board_post_id: postId,
        include_deleted: false,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(modResActive);
  TestValidator.equals("active comments count")(modResActive.data.length)(2);
  for (const rec of modResActive.data) {
    TestValidator.equals("deleted_at for active is null")(rec.deleted_at)(null);
    TestValidator.equals("comments on right post")(
      rec.discussion_board_post_id,
    )(postId);
  }

  // Step 4: Moderator search, include_deleted: true (should see all, deleted have deleted_at set)
  const modResAll =
    await api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        discussion_board_post_id: postId,
        include_deleted: true,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(modResAll);
  TestValidator.equals("all comments count")(modResAll.data.length)(4);
  let deletedCount = 0,
    activeCount = 0;
  for (const rec of modResAll.data) {
    TestValidator.equals("comments on right post")(
      rec.discussion_board_post_id,
    )(postId);
    if (rec.deleted_at === null) ++activeCount;
    else {
      ++deletedCount;
      TestValidator.predicate("deleted_at is valid ISO date-time")(
        !!rec.deleted_at && !isNaN(Date.parse(rec.deleted_at || "")),
      );
    }
  }
  TestValidator.equals("deleted comments seen")(deletedCount)(2);
  TestValidator.equals("active comments seen")(activeCount)(2);

  // Step 5: RBAC - Using moderator endpoint as unprivileged member should throw
  TestValidator.error("member forbidden from using moderator search")(() =>
    api.functional.discussionBoard.moderator.comments.search(connection, {
      body: {
        discussion_board_post_id: postId,
        include_deleted: true,
      } satisfies IDiscussionBoardComment.IRequest,
    }),
  );
}

