import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the admin advanced comment search API with full filter criteria.
 *
 * This test ensures that an admin can search for discussion board comments
 * using all advanced filters jointly:
 *
 * - Body substring (free-text substring match)
 * - Author member UUID
 * - Post UUID
 * - Date range (created_from, created_to)
 * - Parent comment UUID (for threaded/reply scenarios) It also validates
 *   pagination and checks that soft-deleted comments (marked deleted_at !=
 *   null) are included/excluded according to the RBAC policy for admins.
 *
 * Preparation requires a diverse set of comments:
 *
 * - Different body texts (with and without a special test substring)
 * - Comments by two (simulated) members (different UUIDs)
 * - Comments on two different posts (different UUIDs)
 * - Parent-reply relationships for parent_id filtering
 * - At least one comment soft-deleted (deleted_at set)
 *
 * Steps:
 *
 * 1. Create test data: Multiple comments with varied combinations of author, post,
 *    parent, body, and creation time
 * 2. Soft-delete one comment (by directly updating the record, simulated since no
 *    API)
 * 3. Run the admin advanced search with all filters combined:
 *
 *    - Q: substring present in one or more comment bodies
 *    - Discussion_board_member_id: filter for a specific author
 *    - Discussion_board_post_id: filter for a specific post
 *    - Parent_id: reply comment, to filter children
 *    - Created_from / created_to: put around relevant comment timestamps
 *    - Include_deleted: true (since admin can view soft-deleted)
 * 4. Validate that every item in the result data matches _all_ filters, and
 *    soft-deleted comments are included
 * 5. Run a negative test: Use a substring not present in any comment and validate
 *    that result data is empty
 *
 * Note:
 *
 * - As there is no API to create members or posts, UUIDs and their relationships
 *   are simulated with random UUIDs.
 * - Soft-deletion is simulated by updating the deleted_at field directly in test
 *   data since there's no delete API, but in real situations this would require
 *   the appropriate API.
 */
export async function test_api_discussionBoard_test_admin_search_comments_with_full_criteria(
  connection: api.IConnection,
) {
  // 1. Setup: Prepare random UUIDs for two posts and two members
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();

  // Special substring for searching
  const specialSubstring = "e2eTestSubstr";

  // 2. Create parent comments for threading
  const parentComment1 =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_post_id: postId1,
        body: `Parent comment with ${specialSubstring}`,
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(parentComment1);

  const parentComment2 =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_post_id: postId2,
        body: "Parent comment without test substring.",
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(parentComment2);

  // 3. Create replies with varied membership, posts, and body text
  //   - One reply to parent 1 by member 1 (includes substring)
  const reply1 = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: postId1,
        parent_id: parentComment1.id,
        body: `Reply by member1 with ${specialSubstring} between`,
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(reply1);

  //   - One reply to parent 1 by member 2 (no search substring)
  const reply2 = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: postId1,
        parent_id: parentComment1.id,
        body: "Reply by member2 no test substring",
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(reply2);

  //   - One reply to parent 2 by member 1 (includes substring)
  const reply3 = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: postId2,
        parent_id: parentComment2.id,
        body: `${specialSubstring} at the start`,
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(reply3);

  // Simulate different authorship by setting the author field (in real case, would switch user)
  // For testing, only filter by the randomly generated member IDs

  // 4. Simulate soft-deletion (set deleted_at on one comment)
  //    - Directly modify output for test purposes
  const now = new Date();
  const deletedTimestamp = new Date(
    now.getTime() - 1 * 60 * 1000,
  ).toISOString();
  const softDeletedReply = { ...reply2, deleted_at: deletedTimestamp };

  // 5. Search using all filter criteria as admin
  const searchFrom = new Date(now.getTime() - 5 * 60 * 1000).toISOString();
  const searchTo = new Date(now.getTime() + 5 * 60 * 1000).toISOString();

  const adminSearchBody = {
    q: specialSubstring,
    discussion_board_member_id: memberId1,
    discussion_board_post_id: postId1,
    parent_id: parentComment1.id,
    created_from: searchFrom,
    created_to: searchTo,
    include_deleted: true,
    page: 1,
    limit: 10,
    sort: "created_at_desc",
  } satisfies IDiscussionBoardComment.IRequest;

  const result = await api.functional.discussionBoard.admin.comments.search(
    connection,
    {
      body: adminSearchBody,
    },
  );
  typia.assert(result);

  // 6. Validate all results: match all search parameters and show soft-deleted comment
  for (const comment of result.data) {
    TestValidator.predicate("comment body contains search substring")(
      comment.body.includes(specialSubstring),
    );
    TestValidator.equals("author matches")(comment.discussion_board_member_id)(
      memberId1,
    );
    TestValidator.equals("post matches")(comment.discussion_board_post_id)(
      postId1,
    );
    TestValidator.equals("parent matches")(comment.parent_id)(
      parentComment1.id,
    );
    TestValidator.predicate("created_at >= created_from")(
      comment.created_at >= searchFrom,
    );
    TestValidator.predicate("created_at <= created_to")(
      comment.created_at <= searchTo,
    );
  }
  // Ensure soft-deleted comment appears only if it matches all other filters
  const includesSoftDeleted = result.data.some((c) => !!c.deleted_at);
  TestValidator.predicate("includes at least one soft-deleted")(
    includesSoftDeleted,
  );

  // 7. Negative test: search for a substring not in any comment
  const negativeResult =
    await api.functional.discussionBoard.admin.comments.search(connection, {
      body: {
        ...adminSearchBody,
        q: "nonexistentSubstring",
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(negativeResult);
  TestValidator.equals("negative result data is empty")(
    negativeResult.data.length,
  )(0);
}

