 * Business rationale:
 *
 * - Admins require robust feedback when searching for comments with criteria
 *   guaranteed to produce no results (e.g., gibberish body text, or a member ID
 *   that does not exist).
 * - This ensures the search endpoint properly handles zero-match scenarios,
 *   returning an empty data array and correct pagination (zero records/pages)
 *   without errors.
 *
 * Test workflow:
 *
 * 1. Perform a search with a "nonsense" body query string that no comment should
 *    match.
 *
 *    - Expect: data array is empty; pagination.records and pages are zero;
 *         current/limit match input.
 * 2. Perform a search with a random/fake member UUID as discussion_board_member_id
 *    filter (unlikely to exist).
 *
 *    - Expect: data array is empty; pagination.records and pages are zero;
 *         current/limit match input.
 * 3. Assert response always matches schema; no errors are thrown by the endpoint.
 */
export async function test_api_discussionBoard_test_search_comments_returns_no_results_when_no_match(
  connection: api.IConnection,
) {
  // 1. Search using a nonsense body query string to guarantee no match
  const nonsenseQuery = "asdfqwerzxcv123!@#$";
  const requestPage1 = 1;
  const requestLimit1 = 10;
