  TestValidator.equals("pagination pages should be zero")(
    output1.pagination.pages,
  )(0);
  TestValidator.equals("pagination current page as requested")(
    output1.pagination.current,
  )(requestPage1);
  TestValidator.equals("pagination limit as requested")(
    output1.pagination.limit,
  )(requestLimit1);

  // 2. Search with a fake/nonexistent member UUID (should yield zero results)
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();
  const requestPage2 = 1;
  const requestLimit2 = 5;
