      body: {
        discussion_board_member_id: fakeMemberId,
        page: requestPage2,
        limit: requestLimit2,
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(output2);
  TestValidator.equals("should return empty data array for fake member")(
    output2.data,
  )([]);
  TestValidator.equals("pagination for zero records with member filter")(
    output2.pagination.records,
  )(0);
  TestValidator.equals("pagination pages should be zero with member filter")(
    output2.pagination.pages,
  )(0);
  TestValidator.equals("pagination current page for member filter")(
    output2.pagination.current,
  )(requestPage2);
  TestValidator.equals("pagination limit for member filter")(
    output2.pagination.limit,
  )(requestLimit2);
}

