/**
 * Validate forbidden/not found when accessing restricted or soft-deleted
 * comments by member
 *
 * This test validates that the API does not leak information about comments
 * under posts the member cannot access (e.g., private posts) or comments that
 * have been soft-deleted. Attempting to access such a comment must result in a
 * forbidden/not found error, and no comment data must be returned.
 *
 * Step-by-step process:
 *
 * 1. Create a discussion post as a member (simulating a post private to the
 *    author)
 * 2. Add a comment to the post as the same member
 * 3. Attempt to fetch the comment (with the same member – in real world, would use
 *    another member, but user switching is not available in current context)
 * 4. Validate that the API returns a forbidden or not found error (no data leak)
 * 5. Create a second post and comment as the current member
 * 6. Soft-delete the comment
 * 7. Attempt to fetch the soft-deleted comment (should also return forbidden or
 *    not found error)
 */
export async function test_api_discussionBoard_test_member_get_comment_forbidden_if_private_or_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a post as a member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Add a comment to the post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 3. Attempt to fetch the comment where access should be forbidden (private post)
  await TestValidator.error(
    "forbidden/not found for comment under inaccessible post",
  )(() =>
    api.functional.discussionBoard.member.comments.at(connection, {
      commentId: comment.id,
    }),
  );

  // 4. Create another post and comment
  const post2 = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
