 * and subsequently mark it as read, following realistic board system workflows.
 * The test verifies both the ability of the guest to update their notification
 * and the correctness of read-status transition.
 *
 * Steps:
 *
 * 1. Register a new guest session. (Needed to populate guest_id for notification)
 * 2. Create a notification, delivered via admin API directly to this guest.
 * 3. Guest marks the notification as read using the guest notification update
 *    endpoint.
 * 4. Validate the notification's is_read field and audit correct assignment.
 */
export async function test_api_discussionBoard_guest_notifications_test_update_guest_notification_mark_as_read(
  connection: api.IConnection,
) {
  // 1. Register a new guest session
  const guestCreateInput = {
    guest_ip: "203.0.113.84",
    session_token: RandomGenerator.alphaNumeric(20),
    entered_at: new Date().toISOString(),
  } satisfies IDiscussionBoardGuest.ICreate;
  const guest = await api.functional.discussionBoard.guests.create(connection, {
    body: guestCreateInput,
  });
  typia.assert(guest);

  // 2. Admin creates and delivers a notification for this guest
  const notificationInput = {
    guest_id: guest.id,
    type: "in-app",
    category: "info",
    message: "Test notification: please mark as read.",
    is_read: false,
    status: "sent",
    created_at: new Date().toISOString(),
  } satisfies IDiscussionBoardNotification.ICreate;
  const notification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      { body: notificationInput },
    );
  typia.assert(notification);
  TestValidator.equals("notification is unread after delivery")(
    notification.is_read,
  )(false);
  TestValidator.equals("recipient guest ID is correct")(notification.guest_id)(
    guest.id,
  );

  // 3. Guest marks the notification as read
  const updateResult =
    await api.functional.discussionBoard.guest.notifications.update(
      connection,
      {
        notificationId: notification.id,
        body: { is_read: true } satisfies IDiscussionBoardNotification.IUpdate,
      },
    );
  typia.assert(updateResult);

  // 4. Validate read status and ownership
  TestValidator.equals("notification marked as read")(updateResult.is_read)(
    true,
  );
  TestValidator.equals("notification ID matches")(updateResult.id)(
    notification.id,
  );
  TestValidator.equals("guest recipient matches")(updateResult.guest_id)(
    guest.id,
  );
}

