    await api.functional.discussionBoard.member.comments.commentVotes.search(
      connection,
      {
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          page: 0,
        },
      },
    );
  });
  await TestValidator.error("negative page should fail")(async () => {
    await api.functional.discussionBoard.member.comments.commentVotes.search(
      connection,
      {
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          page: -3,
        },
      },
    );
  });

  // 5. Logically inconsistent date range (created_from > created_to)
