    async () => {
      await api.functional.discussionBoard.member.comments.commentVotes.search(
        connection,
        {
          commentId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            created_from: "not-a-timestamp",
          },
        },
      );
    },
  );
