  TestValidator.predicate("member list is valid page")(
    memberPosts.pagination && Array.isArray(memberPosts.data),
  );

  // 4. Verify RBAC: every post visible to guest must also be included for the member
  const guestIds = new Set(guestPosts.data.map((p) => p.id));
  const memberIds = new Set(memberPosts.data.map((p) => p.id));
  for (const id of guestIds) {
    TestValidator.predicate(`RBAC: post ${id} is visible to member as well`)(
      memberIds.has(id),
    );
