  // 5. Validate each post has all summary fields (id, title, discussion_board_member_id)
  for (const post of [...guestPosts.data, ...memberPosts.data]) {
    TestValidator.predicate("post has summary fields")(
      typeof post.id === "string" &&
        typeof post.title === "string" &&
        typeof post.discussion_board_member_id === "string",
    );
  }
}

