import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validates that the posts listing API excludes soft-deleted discussion board
 * posts for both guests and members.
 *
 * This function simulates a realistic member workflow: creating two posts as a
 * member, soft-deleting one of them, and confirming that subsequent listings do
 * not include the deleted post, while the remaining post remains visible. The
 * visibility is checked for both an authenticated member and as a guest
 * (unauthenticated user) by clearing any authentication headers. The test also
 * covers the edge case of idempotent soft deletion.
 *
 * Test steps:
 *
 * 1. Create two posts as a member.
 * 2. Soft-delete the first post.
 * 3. Simulate logout (guest) and fetch all posts, verifying only non-deleted posts
 *    are present.
 * 4. As the original member, fetch all posts and verify only non-deleted posts are
 *    present.
 * 5. Attempt to soft-delete the already-deleted post again (edge case: repeated
 *    delete).
 * 6. Confirm listings remain correct following repeated delete attempt.
 */
export async function test_api_discussionBoard_test_list_posts_excludes_soft_deleted_posts(
  connection: api.IConnection,
) {
  // 1. Create the first post as a member
  const post1 = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: `Post 1 - ${RandomGenerator.alphaNumeric(8)}`,
        body: "First test body",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post1);

  // 2. Create the second post as a member
  const post2 = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: `Post 2 - ${RandomGenerator.alphaNumeric(8)}`,
        body: "Second test body",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post2);

  // 3. Soft-delete the first post as a member
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post1.id,
  });

  // 4. As guest (simulate logout by clearing Authorization header), fetch all posts
  const guestConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConnection.headers.Authorization;
  const guestPosts =
    await api.functional.discussionBoard.posts.index(guestConnection);
  typia.assert(guestPosts);
  TestValidator.predicate("Soft-deleted post should NOT appear for guests")(
    !guestPosts.data.some((p) => p.id === post1.id),
  );
  TestValidator.predicate("Active post should appear for guests")(
    guestPosts.data.some((p) => p.id === post2.id),
  );

  // 5. As a member (original connection), fetch all posts
  const memberPosts =
    await api.functional.discussionBoard.posts.index(connection);
  typia.assert(memberPosts);
  TestValidator.predicate("Soft-deleted post should NOT appear for members")(
    !memberPosts.data.some((p) => p.id === post1.id),
  );
  TestValidator.predicate("Active post should appear for members")(
    memberPosts.data.some((p) => p.id === post2.id),
  );

  // 6. Edge case: repeat soft-delete of already deleted post (should not error, listing unaffected)
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post1.id,
  });
  const postsAfterRepeatDelete =
    await api.functional.discussionBoard.posts.index(connection);
  typia.assert(postsAfterRepeatDelete);
  TestValidator.predicate(
    "Soft-deleted post still NOT in list after repeated delete",
  )(!postsAfterRepeatDelete.data.some((p) => p.id === post1.id));
  TestValidator.predicate("Active post still appears after repeated delete")(
    postsAfterRepeatDelete.data.some((p) => p.id === post2.id),
  );
}

