/**
 * Validate advanced filtering, pagination, and sorting for discussion board
 * post search.
 *
 * This test ensures advanced post search correctly filters posts by author,
 * category, and tag, and that pagination and sorting options work as intended.
 * It covers realistic business logic by simulating author/category/tag UUIDs
 * for test filtering; category/tag assignments are only testable via search
 * parameters (not post creation DTO).
 *
 * Workflow:
 *
 * 1. Create a set of posts by varying possible authors (simulated via random UUIDs
 *    for authorship, as assignments are inferred for test filtering).
 * 2. Simulate category and tag values for filtering by generating UUIDs to use in
 *    search request, since these are not assignable during post creation.
 * 3. Search for posts by a specific author and validate all returned posts have
 *    matching author_id.
 * 4. Search with random non-existent category filter; assert that no posts are
 *    returned.
 * 5. Test pagination by setting page and limit; assert correct number of records
 *    and proper page number.
 * 6. Validate sort order of returned posts (by created_at descending).
 * 7. Confirm that unfiltered search returns the list of posts.
 */
export async function test_api_discussionBoard_test_advanced_search_posts_by_category_tag_author(
  connection: api.IConnection,
) {
  // 1. Create sample posts (simulate different authors by creating multiple posts)
  const postA = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: "A - Cat1,Tag1",
        body: "First body",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(postA);
  const postB = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: "B - Cat2,Tag2",
        body: "Second body",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(postB);
  const postC = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: "C - Cat1,Tag2",
        body: "Third body",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(postC);

  // 2. Simulated filtering field values
  const authorId = postA.discussion_board_member_id; // Use an actual author UUID for test
  const nonExistentCategoryId = typia.random<string & tags.Format<"uuid">>();
  const nonExistentTagId = typia.random<string & tags.Format<"uuid">>();

  // 3. Search by author, verify all have the correct author
  const resAuthor = await api.functional.discussionBoard.posts.search(
    connection,
    {
      body: {
        discussion_board_member_id: authorId,
      } satisfies IDiscussionBoardPost.IRequest,
    },
  );
  typia.assert(resAuthor);
  TestValidator.predicate("Returned posts by correct author")(
    resAuthor.data.every((p) => p.discussion_board_member_id === authorId),
  );

  // 4. Search by non-existent category; expect no posts
  const resNonCategory = await api.functional.discussionBoard.posts.search(
    connection,
    {
      body: {
        category_id: nonExistentCategoryId,
      } satisfies IDiscussionBoardPost.IRequest,
    },
  );
  typia.assert(resNonCategory);
  TestValidator.equals("No posts found for unknown category")(
    resNonCategory.data.length,
  )(0);

  // 5. Pagination (limit and page)
  const resPaginated = await api.functional.discussionBoard.posts.search(
    connection,
    {
      body: { page: 0, limit: 2 } satisfies IDiscussionBoardPost.IRequest,
    },
  );
  typia.assert(resPaginated);
  TestValidator.equals("Paginated limit=2")(resPaginated.data.length)(2);
  TestValidator.equals("Pagination page=0")(resPaginated.pagination.current)(0);

  // 6. Sort test - created_at descending (at least two posts expected)
  if (resPaginated.data.length > 1) {
    const times = resPaginated.data.map((p) =>
      new Date(p.created_at).getTime(),
    );
    TestValidator.predicate("Sorted by created_at descending")(
      times[0] >= times[1],
    );
  }

  // 7. Unfiltered search returns post array
  const resAll = await api.functional.discussionBoard.posts.search(connection, {
    body: {} satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(resAll);
  TestValidator.predicate("Returns array of posts")(Array.isArray(resAll.data));
}

