import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Validate that a guest cannot retrieve details of a soft-deleted tag in the
 * discussion board.
 *
 * Business context: Tags in the discussion board feature are essential for
 * organizing post navigation, category filtering, and analytics. Admins can
 * create these tags and soft-delete them when necessary to preserve compliance
 * or audit trails while keeping them hidden from regular (guest) users.
 * Soft-deleted tags are not supposed to be accessible to guests via API.
 *
 * Test procedure:
 *
 * 1. (Admin) Create a tag with unique label and random description/color.
 * 2. (Admin) Soft-delete the tag by id.
 * 3. (Guest) Attempt to fetch the tag by id using the guest (unauthenticated)
 *    connection.
 * 4. Assert that the guest is NOT able to retrieve the tag details:
 *
 *    - Either the API throws a forbidden or not found error (expected business
 *         logic)
 *    - OR, if the API returns the tag, it must have deleted_at NOT null (should not
 *         happen, but if so, assert it is soft-deleted).
 * 5. (Edge) For maximum robustness, check that error-throwing is the
 *    preferred/expected case.
 */
export async function test_api_discussionBoard_test_guest_cannot_see_soft_deleted_tag(
  connection: api.IConnection,
) {
  // 1. Admin creates a tag
  const tag: IDiscussionBoardTag =
    await api.functional.discussionBoard.admin.tags.create(connection, {
      body: {
        label: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
        color:
          "#" +
          Math.floor(Math.random() * 0xffffff)
            .toString(16)
            .padStart(6, "0"),
      } satisfies IDiscussionBoardTag.ICreate,
    });
  typia.assert(tag);

  // 2. Admin soft-deletes the tag
  await api.functional.discussionBoard.admin.tags.erase(connection, {
    tagId: tag.id,
  });

  // 3. Guest attempts to fetch deleted tag
  await TestValidator.error("guest cannot see soft-deleted tag")(async () => {
    // Simulate guest (no auth header) by passing connection as-is
    await api.functional.discussionBoard.tags.at(connection, {
      tagId: tag.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test updating a discussion board tag as an admin user with valid data.
 *
 * This test validates that an admin can successfully update the label,
 * description, and/or color of a discussion board tag. The process covers:
 *
 * 1. Creation of a tag with initial data as a prerequisite.
 * 2. Performing an update to the created tag's properties (label, description,
 *    color).
 * 3. Verifying the response reflects updated values, and audit fields (updated_at)
 *    have changed as expected.
 *
 * Workflow Steps:
 *
 * 1. Use the admin API to create a new tag with random but valid properties for
 *    label, description, and color.
 * 2. Use the admin API to update the tag using its id, changing some/all updatable
 *    fields (label, description, color).
 * 3. Verify in the response that:
 *
 * - The id is unchanged.
 * - The changed fields match the update request.
 * - Audit fields (updated_at, created_at) exist and are in the correct format,
 *   and updated_at has changed compared to before the update.
 * - No unexpected deletion (deleted_at is null or unchanged).
 */
export async function test_api_discussionBoard_test_update_tag_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new tag as an admin
  const initialTag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
        color:
          "#" +
          Math.floor(Math.random() * 0xffffff)
            .toString(16)
            .padStart(6, "0"),
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(initialTag);

  // 2. Update the tag as an admin using its id, changing label, description, color
  const updateInput = {
    label: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
    color:
      "#" +
      Math.floor(Math.random() * 0xffffff)
        .toString(16)
        .padStart(6, "0"),
  } satisfies IDiscussionBoardTag.IUpdate;

  const updatedTag = await api.functional.discussionBoard.admin.tags.update(
    connection,
    {
      tagId: initialTag.id,
      body: updateInput,
    },
  );
  typia.assert(updatedTag);

  // 3. Validate the response reflects the updates and audit fields
  TestValidator.equals("tag id")(updatedTag.id)(initialTag.id);
  TestValidator.equals("label updated")(updatedTag.label)(updateInput.label);
  TestValidator.equals("description updated")(updatedTag.description)(
    updateInput.description,
  );
  TestValidator.equals("color updated")(updatedTag.color)(updateInput.color);
  TestValidator.notEquals("updated_at changed")(updatedTag.updated_at)(
    initialTag.updated_at,
  );
  TestValidator.equals("created_at unchanged")(updatedTag.created_at)(
    initialTag.created_at,
  );
  // deleted_at should remain null or unchanged
  TestValidator.equals("deleted_at unchanged")(updatedTag.deleted_at)(
    initialTag.deleted_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Validate uniqueness constraint enforcement when updating a tag's label.
 *
 * This test ensures that updating a discussion board tag's label to a value
 * that already exists (on another tag) is forbidden and triggers an error,
 * enforcing the uniqueness constraint. The full workflow is as follows:
 *
 * 1. Create the first discussion board tag with a unique label (tagA).
 * 2. Create a second discussion board tag with a different unique label (tagB).
 * 3. Attempt to update tagB's label to tagA's label. This should fail with a
 *    uniqueness constraint error (no business/contract-defined error detail is
 *    required for this test).
 *
 * Business rationale: Tag labels function as unique identifiers in the
 * discussion board for filtering/navigation, and admin operations must not
 * permit duplicates. This test simulates a common error scenario to guarantee
 * contract enforcement by the API.
 */
export async function test_api_discussionBoard_test_update_tag_label_to_duplicate_should_fail(
  connection: api.IConnection,
) {
  // 1. Create the first tag with label 'UniqueTagLabelA'<random>
  const labelA: string = `UniqueTagLabelA_${typia.random<string>()}`;
  const tagA = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelA,
        description: "First test tag",
        color: "#FF0000",
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tagA);
  TestValidator.equals("tag label matches")(tagA.label)(labelA);

  // 2. Create the second tag with label 'UniqueTagLabelB'<random>
  const labelB: string = `UniqueTagLabelB_${typia.random<string>()}`;
  const tagB = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelB,
        description: "Second test tag",
        color: "#00FF00",
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tagB);
  TestValidator.equals("tag label matches")(tagB.label)(labelB);

  // 3. Attempt to update tagB's label to labelA (expecting uniqueness constraint violation)
  await TestValidator.error("should fail to update label to duplicate")(
    async () => {
      await api.functional.discussionBoard.admin.tags.update(connection, {
        tagId: tagB.id,
        body: {
          label: labelA,
        } satisfies IDiscussionBoardTag.IUpdate,
      });
    },
  );
}

