  // 3. Validate update reflected in output
  TestValidator.equals("Appeal ID unchanged")(updatedAppeal.id)(
    initialAppeal.id,
  );
  TestValidator.equals("Appeal status updated to approved")(
    updatedAppeal.status,
  )("approved");
  TestValidator.equals("Rationale updated")(updatedAppeal.reason)(
    adminDecisionRationale,
  );
  TestValidator.predicate(
    "resolved_at should now be present and valid ISO timestamp",
  )(
    !!updatedAppeal.resolved_at &&
      !isNaN(Date.parse(updatedAppeal.resolved_at)),
  );
  TestValidator.notEquals("resolved_at changed from pre-update")(
    updatedAppeal.resolved_at,
  )(beforeUpdateResolvedAt);

  // 4. (Optionally) Audit/compliance hooks would be checked here if accessible via separate audit log APIs or system hooks
}

