import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate retrieving a paginated list of comments for a discussion board post
 * (as a guest or member).
 *
 * This test covers comment listing as a non-admin user. It verifies that
 * pagination and ordering are correct, and only active (non-deleted) comments
 * are returned.
 *
 * Step-by-step workflow:
 *
 * 1. Register a member for posting and commenting
 * 2. Create a new post as this member
 * 3. Add several comments (at least 3) to that post
 * 4. Retrieve the comments list via GET /discussionBoard/posts/{postId}/comments
 * 5. Validate:
 *
 *    - All created comments appear in the response
 *    - Comment content and linkage (post id) is correct
 *    - Pagination metadata reflects reality
 *    - Only non-deleted comments appear (soft-deleted case not tested)
 */
export async function test_api_discussionBoard_test_get_comments_for_post_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post as that member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add several comments (at least 3) to the post
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 4; ++i) {
    const comment =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body: `[${i + 1}] ${RandomGenerator.paragraph()()}`,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(comment);
    comments.push(comment);
  }

  // 4. Retrieve paginated list of comments via index endpoint
  const commentPage = await api.functional.discussionBoard.posts.comments.index(
    connection,
    {
      postId: post.id,
    },
  );
  typia.assert(commentPage);

  // 5. Validate: all created, only non-deleted, content and linkage
  const returnedCommentIds = commentPage.data.map((c) => c.id);
  for (const comment of comments) {
    TestValidator.predicate(`comment ${comment.id} is listed`)(
      returnedCommentIds.includes(comment.id),
    );
    const found = commentPage.data.find((c) => c.id === comment.id);
    if (found) {
      TestValidator.equals(`comment post mapping`)(
        found.discussion_board_post_id,
      )(comment.discussion_board_post_id);
      TestValidator.equals(`comment body content`)(found.body)(comment.body);
    }
  }

  // Pagination correctness
  TestValidator.equals("pagination.records")(commentPage.pagination.records)(
    comments.length,
  );
  TestValidator.predicate("pagination current page is 1")(
    commentPage.pagination.current === 1,
  );
  TestValidator.predicate("pagination limit >= comment count")(
    commentPage.pagination.limit >= comments.length,
  );
}

