/**
 * Test that a post author (member) can search their post's edit history by date
 * range and rationale keyword.
 *
 * Steps:
 *
 * 1. Register a new verified discussion board member (author).
 * 2. Submit a post as this member.
 * 3. Perform two edits on the post, each with unique rationale text AND set the
 *    edit timestamps sufficiently apart.
 * 4. Search edit history for the post using PATCH, specifying:
 *
 *    - The postId
 *    - The memberId (should match only this user)
 *    - A date range filter that covers only one of the edits
 *    - A rationale keyword that matches only that edit's rationale
 *    - Explicit page/limit for pagination (e.g., page:1, limit:10)
 * 5. Assert the search returns the correct, single edit (the one matching both
 *    filters), and that no edits for other users could be present.
 * 6. Verify proper authorization (this member can only see their own edits, but in
 *    this test, only this one exists).
 *
 * Edge Cases:
 *
 * - The date window excludes the second edit: ensure only one edit is returned.
 * - Rationale keyword partial matching is case-insensitive.
 *
 * Business/contract validation:
 *
 * - Confirm the returned data's editor id, post id, rationale, edited_at are as
 *   expected.
 */
export async function test_api_discussionBoard_test_search_post_edits_as_post_author_with_specific_date_range(
  connection: api.IConnection,
) {
  // Step 1: Register a new verified discussion board member
  const passwordHash = RandomGenerator.alphaNumeric(24);
  const author = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
