  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(1),
        parent_id: null,
      },
    },
  );
  typia.assert(post);

  // Step 3: Perform two edits with unique rationales and edited_at timestamps
  const baseDate = new Date();
  // First edit (earlier date)
  const edit1Date = new Date(baseDate.getTime() - 1000 * 60 * 60 * 24); // 1 day ago
  const rationale1 = "typo-fix-AlphaCase";
  const edit1 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          new_title: post.title + " [fixed]",
          new_body: post.body,
          edited_at: edit1Date.toISOString(),
          rationale: rationale1,
        },
      },
    );
  typia.assert(edit1);
  // Second edit (later date)
  const edit2Date = new Date(baseDate.getTime() + 1000 * 60 * 30); // 30 min in future
  const rationale2 = "expanded-example-beta";
  const edit2 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          new_title: post.title + " [expanded]",
          new_body: post.body + "\nExtra details for example.",
          edited_at: edit2Date.toISOString(),
          rationale: rationale2,
        },
      },
    );
  typia.assert(edit2);

  // Step 4: Search only for edits within the window that matches edit1, with matching rationale keyword (case-insensitive partial)
  const keyword = "alphaCASE"; // intentionally mixed case to check case insensitivity
  const result =
    await api.functional.discussionBoard.member.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: author.id,
          start: new Date(
            baseDate.getTime() - 1000 * 60 * 60 * 25,
          ).toISOString(), // 25h ago
          end: new Date(baseDate.getTime() - 1000 * 60 * 60 * 23).toISOString(), // 23h ago (tight window containing edit1 only)
          rationale: keyword,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(result);

  // Step 5: Validate search result
  TestValidator.equals("should return exactly one matching edit")(
    result.data.length,
  )(1);
