/**
 * Test the ability of a moderator to search and paginate the audit edit trail
 * of any discussion board post, using advanced filtering options.
 *
 * Business context: Moderators require the ability to audit the entire edit
 * history of posts for compliance, abuse handling, or dispute resolution.
 * Unlike regular members, moderators can access the full edit history of any
 * post, not just ones they have authored. This audit operation should support
 * exact and partial match filters (e.g., rationale keyword, editor/member, date
 * range), and support pagination for large history sets.
 *
 * Steps:
 *
 * 1. Create a normal member account via the discussionBoard.members API. This
 *    member will author a post.
 * 2. The member creates a new post, then performs several edits to ensure there is
 *    a history.
 * 3. Create a moderator account via discussionBoard.admin.moderators.create.
 *    (Moderator does not have to be author or editor.)
 * 4. (If system supports authentication context switching, switch connection to
 *    moderator context.)
 * 5. The moderator uses the PATCH
 *    /discussionBoard/moderator/posts/{postId}/postEdits endpoint to search for
 *    all edit events for the member's post, by: a. No filter: Fetch all
 *    histories to verify all entered edits are retrievable. b. Filter by
 *    rationale keyword: Ensure only histories with a specific rationale substr
 *    is returned. c. Filter by member/editor: Only histories by the member are
 *    found. d. Filter by date range: Only edits within a specific range are
 *    found. e. Use pagination (limit=1, page=2) and check returned data is
 *    correct.
 * 6. At each step, validate:
 *
 *    - Response is type-correct.
 *    - Results match expectations/filters.
 *    - Pagination metadata is accurate (records, pages).
 *    - Moderator can see posts/edits from other users, not just own.
 */
export async function test_api_discussionBoard_test_search_post_edits_as_moderator_for_any_post(
  connection: api.IConnection,
) {
  // 1. Create member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: passwordHash,
      },
    },
  );
  typia.assert(member);

  // 2. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: "Initial post title",
        body: "Initial post body",
      },
    },
  );
