  // 3. Create moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modUsername = RandomGenerator.name();
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: modUsername,
        password_hash: RandomGenerator.alphaNumeric(32),
        email: modEmail,
        is_active: true,
      },
    });
  typia.assert(moderator);

  // 4. Moderator fetches edit history using advanced filters
  // a. No filter: fetch all edit histories
  const editHistoryAll =
    await api.functional.discussionBoard.moderator.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {},
      },
    );
  typia.assert(editHistoryAll);

  // b. Filter: rationale substring
  const editHistoryRationale =
    await api.functional.discussionBoard.moderator.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          rationale: "update",
        },
      },
    );
  typia.assert(editHistoryRationale);

  // c. Filter: only edits by this member/editor
  const editHistoryEditor =
    await api.functional.discussionBoard.moderator.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_member_id: member.id,
        },
      },
    );
  typia.assert(editHistoryEditor);

  // d. Filter: date range
  const editHistoryDateRange =
    await api.functional.discussionBoard.moderator.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          start: post.created_at,
          end: post.updated_at,
        },
      },
    );
  typia.assert(editHistoryDateRange);

  // e. Pagination - page 2 (with limit 1)
  const editHistoryPaginated =
    await api.functional.discussionBoard.moderator.posts.postEdits.search(
      connection,
      {
        postId: post.id,
        body: {
          page: 2,
          limit: 1,
        },
      },
    );
  typia.assert(editHistoryPaginated);

  // Response validations for each query
  // Validate pagination metadata present & correct type
  TestValidator.equals("pagination object exists")(
    typeof editHistoryAll.pagination,
  )("object");
  TestValidator.predicate("pagination current >= 1")(
    editHistoryAll.pagination.current >= 1,
  );

  // Validate edit events fetched are all for the post (if any events)
  if (editHistoryAll.data.length > 0) {
    for (const event of editHistoryAll.data) {
      TestValidator.equals("edit event corresponds to post")(
        event.discussion_board_post_id,
      )(post.id);
    }
  }
  // (Further filter result validations can be performed if/when additional edit events exist or can be created)
}

