) {
  // 1. Register a verified member to serve as post author
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);
  TestValidator.predicate("must be verified field present")(
    typeof member.is_verified === "boolean",
  );

  // 2. The member creates a post
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        // parent_id omitted for top-level post
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 3. The member makes two edits to the same post, each with unique content/rationale
  const editPayloads = [
    {
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date(Date.now() + 1000).toISOString(),
      rationale: "Initial typo fix",
    },
    {
      new_title: RandomGenerator.paragraph()(),
      new_body: RandomGenerator.content()()(),
      edited_at: new Date(Date.now() + 2000).toISOString(),
      rationale: "Added clarification",
    },
  ];

  const edits: IDiscussionBoardPostEdit[] = [];
  for (const payload of editPayloads) {
    const edit =
      await api.functional.discussionBoard.member.posts.postEdits.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            discussion_board_member_id: member.id,
            ...payload,
          } satisfies IDiscussionBoardPostEdit.ICreate,
        },
      );
    typia.assert(edit);
    edits.push(edit);
  }

  // 4. Fetch one of the edit events by its edit ID (e.g., the first edit)
  const targetEdit: IDiscussionBoardPostEdit =
    await api.functional.discussionBoard.member.posts.postEdits.at(connection, {
      postId: post.id,
      postEditId: edits[0].id,
    });
  typia.assert(targetEdit);

  // 5. Assert returned event matches the expected edit and context
  TestValidator.equals("returned edit ID matches")(targetEdit.id)(edits[0].id);
  TestValidator.equals("is for the correct post")(
    targetEdit.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("is edited by the author")(
    targetEdit.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("audit: rationale")(targetEdit.rationale)(
    editPayloads[0].rationale,
  );
  TestValidator.equals("audit: new_title")(targetEdit.new_title)(
    editPayloads[0].new_title,
  );
  TestValidator.equals("audit: new_body")(targetEdit.new_body)(
    editPayloads[0].new_body,
  );
  TestValidator.predicate("edited_at matches payload")(
    targetEdit.edited_at === editPayloads[0].edited_at,
  );
}

