import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Validates updating a moderation action as admin with allowed fields.
 *
 * This test ensures:
 *
 * - An admin can update the details (action_type, description) of a moderation
 *   action.
 * - Immutable fields (id, report_id, admin_id, moderator_id) remain unchanged.
 * - Audit fields (acted_at) are updated post-modification.
 *
 * Steps:
 *
 * 1. Create a content report (admin endpoint) that serves as the moderation
 *    subject.
 * 2. File a moderation action (by admin) linked to the report.
 * 3. Update some details of the moderation action: both action_type and
 *    description.
 * 4. Validate the allowed fields updated, immutable ones did not, and that audit
 *    trace is correct.
 */
export async function test_api_discussionBoard_admin_moderationActions_test_update_moderation_action_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a content report as the moderation context
  const contentReport =
    await api.functional.discussionBoard.admin.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_comment_id: null,
          content_type: "post",
          category: "policy",
          reason: "Automated QA: potential policy infraction.",
        },
      },
    );
  typia.assert(contentReport);

  // 2. File a moderation action by admin for this report
  const moderationAction =
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: contentReport.id,
          admin_id: typia.random<string & tags.Format<"uuid">>(),
          moderator_id: null,
          action_type: "warning",
          description: "QA issued warning as compliance check.",
        },
      },
    );
  typia.assert(moderationAction);

  // 3. Update moderation action details (fields allowed by business rules)
  const updateBody = {
    action_type: "suspend",
    description: "QA elevated to suspension based on repeat offense.",
  };
  const updatedAction =
    await api.functional.discussionBoard.admin.moderationActions.update(
      connection,
      {
        moderationActionId: moderationAction.id,
        body: updateBody,
      },
    );
  typia.assert(updatedAction);

  // 4. Assert updated/immutable fields and audit accuracy
  TestValidator.equals("moderation action id unchanged")(updatedAction.id)(
    moderationAction.id,
  );
  TestValidator.equals("report_id unchanged")(updatedAction.report_id)(
    moderationAction.report_id,
  );
  TestValidator.equals("admin_id unchanged")(updatedAction.admin_id)(
    moderationAction.admin_id,
  );
  TestValidator.equals("moderator_id unchanged")(updatedAction.moderator_id)(
    moderationAction.moderator_id,
  );
  TestValidator.equals("action_type updated")(updatedAction.action_type)(
    updateBody.action_type,
  );
  TestValidator.equals("description updated")(updatedAction.description)(
    updateBody.description,
  );
  TestValidator.notEquals("acted_at audit updated")(updatedAction.acted_at)(
    moderationAction.acted_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
