import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Validate RBAC enforcement: forbid update of moderation actions without
 * admin/moderator role.
 *
 * This test confirms that only users with privileged roles (admin or moderator)
 * can update moderation actions. It simulates creating a content report, then
 * (under privileged context) a moderation action for it, and finally attempts
 * (as a non-privileged user, e.g., regular member or guest) to update the
 * moderation action. The update should be forbidden, ensuring that RBAC
 * boundaries are secure around sensitive moderation endpoints.
 *
 * Steps:
 *
 * 1. Create a content report using contentReports.create (reporter context =
 *    member/guest)
 * 2. Create a moderation action for this report as if by admin/mod (for test
 *    setup; actor fields set null/simulated)
 * 3. Attempt to update the moderation action with non-privileged user
 * 4. Assert the request is forbidden and fails with access error (using
 *    TestValidator.error)
 *
 * This test verifies the system prohibits escalation or manipulation of
 * moderation workflows by unprivileged users.
 */
export async function test_api_discussionBoard_test_update_moderation_action_forbidden_without_admin_or_moderator_role(
  connection: api.IConnection,
) {
  // 1. Create a content report as a regular member/guest
  const contentReport =
    await api.functional.discussionBoard.admin.contentReports.create(
      connection,
      {
        body: {
          content_type: "post",
          category: "spam",
          reason: "Reported for spam.",
          discussion_board_post_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_comment_id: null,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(contentReport);

  // 2. Create a moderation action for that report as if by admin/mod (simulated)
  const moderationAction =
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: contentReport.id,
          action_type: "edit",
          description: "Initial moderation action for RBAC test.",
          admin_id: null,
          moderator_id: null,
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationAction);

  // 3. Attempt to update as a regular member/guest (RBAC: should be forbidden)
  await TestValidator.error(
    "Non-privileged users cannot update moderation actions",
  )(async () => {
    await api.functional.discussionBoard.admin.moderationActions.update(
      connection,
      {
        moderationActionId: moderationAction.id,
        body: {
          action_type: "suspend",
          description:
            "Attempt to elevate moderation action by unauthorized actor.",
        } satisfies IDiscussionBoardModerationAction.IUpdate,
      },
    );
  });
}

