import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";

/**
 * Validates that creating a duplicate vote on the same comment by the same
 * member fails due to unique vote constraint enforcement.
 *
 * Business workflow covered:
 *
 * 1. Register a new member (which serves as implicit authentication)
 * 2. Member creates a discussion post
 * 3. Member adds a comment to the post
 * 4. Member submits an upvote for that comment
 * 5. Member attempts to submit another vote (upvote or downvote) on the same
 *    comment
 * 6. The API should reject the duplicate vote attempt and return a
 *    validation/business error, enforcing the business rule that a member can
 *    only vote once per comment.
 *
 * Steps:
 *
 * 1. Register a new discussion board member
 * 2. Create a post as that member
 * 3. Create a comment on the post
 * 4. Submit an upvote for the comment
 * 5. Confirm the first vote is saved
 * 6. Attempt a duplicate vote (can be upvote or downvote), expect an error
 */
export async function test_api_discussionBoard_test_create_comment_vote_duplicate_vote_fails(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPasswordHash = RandomGenerator.alphaNumeric(24); // Simulate password hash
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post as this member (authentication context assumed via connection)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Member creates a comment on the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Submit an upvote for the comment
  const firstVote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  typia.assert(firstVote);
  // 5. Confirm that the saved vote matches input details
  TestValidator.equals("vote upvote flag")(firstVote.upvote)(true);
  TestValidator.equals("vote member ID")(firstVote.discussion_board_member_id)(
    member.id,
  );
  TestValidator.equals("vote comment ID")(
    firstVote.discussion_board_comment_id,
  )(comment.id);

  // 6. Attempt to add a duplicate vote on the same comment, expect business validation error
  await TestValidator.error("duplicate comment vote by same member fails")(
    async () => {
      await api.functional.discussionBoard.member.comments.commentVotes.create(
        connection,
        {
          commentId: comment.id,
          body: {
            discussion_board_comment_id: comment.id,
            upvote: false, // Downvote also violates unique constraint
          } satisfies IDiscussionBoardCommentVote.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";

/**
 * Test that unauthenticated (guest) users cannot vote on comments.
 *
 * Business context: Only registered and authenticated members are permitted to
 * cast upvotes or downvotes on comments within the discussion board. Guest
 * (unauthenticated) users must be denied such operations to maintain community
 * integrity and prevent abuse.
 *
 * Steps:
 *
 * 1. Register a new member account (used as the post/comment author)
 * 2. Authenticate as that member (to obtain permission for creating
 *    posts/comments)
 * 3. Create a new post as the member
 * 4. Add a comment to the post as the member
 * 5. Sign out or clear authentication to simulate a guest user
 * 6. Attempt to create a vote (upvote/downvote) on the comment without
 *    authentication
 * 7. Validate that the vote operation is denied with a permission or authorization
 *    error, as per system rules
 *
 * This ensures security and proper RBAC enforcement on comment voting APIs.
 */
export async function test_api_discussionBoard_test_create_comment_vote_unauthenticated_denied(
  connection: api.IConnection,
) {
  // 1. Register a new member (the post and comment author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const passwordHash: string = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. (Connection context is authenticated as member after registration)
  // Create a post as the member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.content()()(20),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add a comment to the post as the member
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.content()()(10),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Simulate guest by removing authorization header
  const guestConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConnection.headers["Authorization"];

  // 5. Attempt to create a vote as a guest (unauthenticated user)
  await TestValidator.error("guest cannot create comment vote")(async () => {
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      guestConnection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";

/**
 * Test successful update of a comment vote (from upvote to downvote) by the
 * original voting member.
 *
 * Business context: Discussion board members can vote (upvote/downvote) on
 * comments, but only once per comment. If the member changes their mind, they
 * can update their vote polarity via PUT.
 *
 * This test ensures that the vote owner can change a vote from upvote to
 * downvote, and the update endpoint enforces correct ownership/auditing
 * behavior.
 *
 * Steps:
 *
 * 1. Register a member (owner for all actions)
 * 2. Create a post as this member
 * 3. Create a comment (by same member) on the post
 * 4. Submit an upvote for the comment as the member
 * 5. Update the same comment vote to be a downvote using the update endpoint
 * 6. Validate that the vote was updated correctly and the returned vote object
 *    reflects the new polarity, keeping audit fields consistent with update
 */
export async function test_api_discussionBoard_test_update_comment_vote_success_by_owner(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a member to act as voter
  const uniqueEmail: string = typia.random<string & tags.Format<"email">>();
  const passwordHash: string = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: uniqueEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post as this member (auth context is "connection")
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(5),
        body: RandomGenerator.content()(1)(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Create a comment on the post (by same member)
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Submit an upvote for the comment
  const upvote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  typia.assert(upvote);
  TestValidator.equals("vote must be upvote")(upvote.upvote)(true);
  TestValidator.equals("vote must reference comment")(
    upvote.discussion_board_comment_id,
  )(comment.id);
  TestValidator.equals("vote must reference voter")(
    upvote.discussion_board_member_id,
  )(member.id);

  // 5. Update the same comment vote to a downvote via PUT endpoint
  const updatedVote =
    await api.functional.discussionBoard.member.comments.commentVotes.update(
      connection,
      {
        commentId: comment.id,
        commentVoteId: upvote.id,
        body: {
          upvote: false,
        } satisfies IDiscussionBoardCommentVote.IUpdate,
      },
    );
  typia.assert(updatedVote);

  // 6. Validate that the vote is now a downvote and audit fields remain consistent
  TestValidator.equals("vote must now be downvote")(updatedVote.upvote)(false);
  TestValidator.equals("vote ID must remain the same")(updatedVote.id)(
    upvote.id,
  );
  TestValidator.equals("vote references same comment")(
    updatedVote.discussion_board_comment_id,
  )(upvote.discussion_board_comment_id);
  TestValidator.equals("vote references same voter")(
    updatedVote.discussion_board_member_id,
  )(upvote.discussion_board_member_id);
  // Optionally check audit trail if desired (created_at should remain, could check updated_at if exposed)
}

