/**
 * Validate administrative ability to delete any comment vote, regardless of
 * owner.
 *
 * This test ensures that when two members (A and B) and one admin exist:
 *
 * 1. Member A creates a post.
 * 2. Member A then creates a comment on this post.
 * 3. Member A casts a vote on their own comment.
 * 4. The admin uses privileged API to delete Member A's vote.
 *
 * This simulates a real-world moderation/audit scenario and validates that:
 *
 * - The vote is successfully deleted (e.g., would no longer be returned in
 *   listing APIs).
 * - Admin privilege is correctly enforced for force-deletion, regardless of who
 *   owns the vote.
 * - (If possible) an audit or time field changes, or a soft-delete is not
 *   applicable and hard deletion occurs.
 */
export async function test_api_discussionBoard_test_admin_can_delete_any_comment_vote(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberA: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberAEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(memberA);

  // 2. Register Member B (not used directly in steps, but validates privilege for cross-user actions)
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberB: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberBEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(memberB);

  // 3. Register Admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(12),
        email: adminEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(admin);

  // 4. Member A creates a post
  // (assumes connection is properly authorized as Member A)
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 5. Member A creates a comment on the post
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(8),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 6. Member A votes on their own comment
  const vote: IDiscussionBoardCommentVote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
