  // 7. Admin deletes the vote using admin API
  // (assumes connection is properly authorized as Admin)
  await api.functional.discussionBoard.admin.comments.commentVotes.erase(
    connection,
    {
      commentId: comment.id,
      commentVoteId: vote.id,
    },
