import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";

/**
 * Test successful retrieval of all tag assignments for a specific post as a
 * member.
 *
 * This test covers the following workflow:
 *
 * 1. Register a new member for the discussion board.
 * 2. Have the member create a new post.
 * 3. Create several tags as admin.
 * 4. Assign several tags to the created post as the member.
 * 5. Fetch all tag assignments for that post as the member and verify:
 *
 *    - All assigned tags are retrieved.
 *    - Tag assignments point to correct tag IDs and post IDs.
 *    - All returned tag assignments match the created assignments.
 *    - (Edge case) For a post with no tags, the fetch returns an empty array.
 *
 * Ensures authentication is respected, system relations are honored, and both
 * normal and edge-case responses are handled.
 */
export async function test_api_discussionBoard_test_list_post_tags_success_member(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 2. Create a post as this member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);
  TestValidator.equals("author is member")(post.discussion_board_member_id)(
    member.id,
  );

  // 3. Create several tags as admin
  const tagInputs: IDiscussionBoardTag.ICreate[] = [
    {
      label: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      color: "#FF0000",
    },
    {
      label: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      color: "#00FF00",
    },
    {
      label: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      color: null,
    },
  ];
  const tags = [] as IDiscussionBoardTag[];
  for (const tagInput of tagInputs) {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      { body: tagInput },
    );
    typia.assert(tag);
    tags.push(tag);
  }

  // 4. Assign several tags to the post as the member
  const postTagAssignments = [] as IDiscussionBoardPostTag[];
  for (const tag of tags) {
    const assignInput: IDiscussionBoardPostTag.ICreate = {
      discussion_board_post_id: post.id,
      discussion_board_tag_id: tag.id,
    };
    const assigned =
      await api.functional.discussionBoard.member.posts.postTags.create(
        connection,
        {
          postId: post.id,
          body: assignInput,
        },
      );
    typia.assert(assigned);
    postTagAssignments.push(assigned);
  }

  // 5. Fetch tags for the post, verify that all assignments are present
  const result =
    await api.functional.discussionBoard.member.posts.postTags.index(
      connection,
      { postId: post.id },
    );
  typia.assert(result);
  TestValidator.equals("postTags list length")(result.data.length)(
    postTagAssignments.length,
  );
  const assignmentIdsSorted = [...postTagAssignments].map((x) => x.id).sort();
  const resultIdsSorted = [...result.data].map((x) => x.id).sort();
  TestValidator.equals("postTag IDs match")(assignmentIdsSorted)(
    resultIdsSorted,
  );
  for (const tagAssignment of postTagAssignments) {
    const found = result.data.find((x) => x.id === tagAssignment.id);
    TestValidator.predicate(
      `assignment for tag ${tagAssignment.discussion_board_tag_id} found`,
    )(!!found);
    if (found) {
      TestValidator.equals("post id")(found.discussion_board_post_id)(
        tagAssignment.discussion_board_post_id,
      );
      TestValidator.equals("tag id")(found.discussion_board_tag_id)(
        tagAssignment.discussion_board_tag_id,
      );
    }
  }

  // 6. Edge case: Create another post, do not assign any tags
  const postNoTagInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const postNoTags = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postNoTagInput },
  );
  typia.assert(postNoTags);
  const emptyTagResult =
    await api.functional.discussionBoard.member.posts.postTags.index(
      connection,
      { postId: postNoTags.id },
    );
  typia.assert(emptyTagResult);
  TestValidator.equals("postTags should be empty")(emptyTagResult.data.length)(
    0,
  );
}

