import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced moderator search and pagination on post votes.
 *
 * This test simulates a realistic scenario where a moderator needs to audit all
 * votes on a discussion board post, using advanced search filters. The test
 * covers a complete business flow and permissions:
 *
 * 1. Register three member accounts (simulate different voters).
 * 2. Register a moderator account (simulating elevated access).
 * 3. As member 1, create a post.
 * 4. As all three members, vote on the post—using a mix of upvotes and downvotes,
 *    with timing gap simulation for date range filtering.
 * 5. As the moderator, call PATCH
 *    /discussionBoard/moderator/posts/{postId}/postVotes with advanced
 *    filters:
 *
 * - Upvote true (filter for upvotes only)
 * - Upvote false (downvotes only)
 * - Voting member ID (filter for votes cast by a specific member)
 * - Created_from and created_to range covering the simulated time window
 * - Pagination (page/limit)
 *
 * 6. Verify that returned records match expected votes—including those that would
 *    be hidden from regular members. Check vote data, counts, and paging
 *    metadata.
 *
 * This flow ensures that moderator search is comprehensive, filter options work
 * correctly, and pagination is accurate.
 */
export async function test_api_discussionBoard_test_moderator_search_post_votes_with_advanced_filters(
  connection: api.IConnection,
) {
  // Step 1: Register 3 member accounts
  const memberInputs: IDiscussionBoardMember.ICreate[] = [
    {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(16),
    },
    {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(16),
    },
    {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(16),
    },
  ];
  const members: IDiscussionBoardMember[] = [];
  for (const input of memberInputs) {
    const member = await api.functional.discussionBoard.members.create(
      connection,
      { body: input },
    );
    typia.assert(member);
    members.push(member);
  }

  // Step 2: Register a moderator account
  const moderatorInput: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(24),
    is_active: true,
  };
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderatorInput,
    });
  typia.assert(moderator);

  // Step 3: As member 1, create a post
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // Step 4: Have 3 members vote on the post (simulate upvote/downvote, with delay)
  // Track which votes are up/down and by whom
  const now = new Date();
  // We alternate upvote/downvote and collect timing by timestamps
  const voteRecords: Array<{
    member: IDiscussionBoardMember;
    upvote: boolean;
    vote: IDiscussionBoardPostVote;
  }> = [];
  for (let i = 0; i < 3; ++i) {
    const upvote = i !== 1; // 1st & 3rd are upvotes, 2nd is downvote
    // Simulate vote time difference (increase seconds for each)
    const vote =
      await api.functional.discussionBoard.member.posts.postVotes.create(
        connection,
        {
          postId: post.id,
          body: { upvote } satisfies IDiscussionBoardPostVote.ICreate,
        },
      );
    typia.assert(vote);
    voteRecords.push({ member: members[i], upvote, vote });
    // Wait 1 second for distinct created_at (simulate time range filtering)
    await new Promise((r) => setTimeout(r, 1100));
  }

  // Collect the created_at timestamps
  const timestamps = voteRecords.map((r) => r.vote.created_at);
  timestamps.sort(); // ascending
  const firstTimestamp = timestamps[0];
  const lastTimestamp = timestamps[timestamps.length - 1];

  // Step 5: As moderator, search and test advanced filters

  // 5.1 Filter for upvotes only
  const upvotesOutput =
    await api.functional.discussionBoard.moderator.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          upvote: true,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(upvotesOutput);
  TestValidator.equals("upvote filter - count")(upvotesOutput.data.length)(
    voteRecords.filter((r) => r.upvote).length,
  );
  for (const vote of upvotesOutput.data) {
    TestValidator.equals("upvote filter - upvote only")(vote.upvote)(true);
    TestValidator.equals("upvote filter - correct post")(
      vote.discussion_board_post_id,
    )(post.id);
  }

  // 5.2 Filter for downvotes only
  const downvotesOutput =
    await api.functional.discussionBoard.moderator.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          upvote: false,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(downvotesOutput);
  TestValidator.equals("downvote filter - count")(downvotesOutput.data.length)(
    voteRecords.filter((r) => !r.upvote).length,
  );
  for (const vote of downvotesOutput.data) {
    TestValidator.equals("downvote filter - downvote only")(vote.upvote)(false);
    TestValidator.equals("downvote filter - correct post")(
      vote.discussion_board_post_id,
    )(post.id);
  }

  // 5.3 Filter by member id (for each member)
  for (const { member, vote } of voteRecords) {
    const output =
      await api.functional.discussionBoard.moderator.posts.postVotes.search(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_member_id: member.id,
            page: 1,
            limit: 10,
          } satisfies IDiscussionBoardPostVote.IRequest,
        },
      );
    typia.assert(output);
    // Should contain one record for that member if only voted once
    TestValidator.equals("member id filter - count")(output.data.length)(1);
    TestValidator.equals("member id filter - member")(
      output.data[0].discussion_board_member_id,
    )(member.id);
    TestValidator.equals("member id filter - correct post")(
      output.data[0].discussion_board_post_id,
    )(post.id);
  }

  // 5.4 Filter by created_from and created_to
  // Pick out the second (middle) vote timestamp
  const midTimestamp = timestamps[1];
  const output =
    await api.functional.discussionBoard.moderator.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          created_from: midTimestamp,
          created_to: lastTimestamp,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(output);
  // The records returned should have created_at in [midTimestamp, lastTimestamp]
  for (const vote of output.data) {
    TestValidator.predicate(
      `date range filter (${midTimestamp} <= x <= ${lastTimestamp})`,
    )(vote.created_at >= midTimestamp && vote.created_at <= lastTimestamp);
    TestValidator.equals("date range filter - correct post")(
      vote.discussion_board_post_id,
    )(post.id);
  }

  // 5.5 Pagination: limit = 2, expect two pages when 3 votes exist
  const paged =
    await api.functional.discussionBoard.moderator.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          page: 1,
          limit: 2,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(paged);
  // Check pagination data
  TestValidator.equals("pagination limit")(paged.pagination.limit)(2);
  TestValidator.equals("pagination total records")(paged.pagination.records)(3);
  TestValidator.equals("pagination total pages")(paged.pagination.pages)(2);
  TestValidator.equals("pagination current page")(paged.pagination.current)(1);
  // The second page should have the remaining record
  const paged2 =
    await api.functional.discussionBoard.moderator.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          page: 2,
          limit: 2,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(paged2);
  TestValidator.equals("pagination page 2")(paged2.pagination.current)(2);
  TestValidator.equals("pagination - page 2 count")(paged2.data.length)(1);
}

