import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccessLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccessLog";

/**
 * Validates the successful retrieval of all access logs as an admin user.
 *
 * Ensures that access logs for all actors (admin, moderator, member, guest) are
 * returned in a paginated, schema-compliant structure. This is critical for
 * audit compliance, forensic investigation, and data integrity checks.
 *
 * Steps:
 *
 * 1. Call the admin access logs endpoint (as an admin)
 * 2. Validate the API returns a paginated structure
 *    (IPageIDiscussionBoardAccessLog)
 * 3. Check pagination metadata: current/limit/records/pages fields and logical
 *    values
 * 4. For each access log, verify all mandatory audit fields (id, accessed_at,
 *    http_method, endpoint, result)
 * 5. Confirm at least one actor field (admin_id, moderator_id, member_id,
 *    guest_id) is present (not all null/undefined)
 * 6. Enforce only allowed properties exist on log records (no extra fields)
 * 7. (If no records) page.data is empty array; else, evaluates at least one record
 */
export async function test_api_discussionBoard_test_get_all_access_logs_with_admin_access(
  connection: api.IConnection,
) {
  // 1. Call the access logs endpoint as an admin
  const page =
    await api.functional.discussionBoard.admin.accessLogs.index(connection);
  typia.assert(page);

  // 2. Validate pagination metadata - required fields and logical values
  TestValidator.predicate("pagination.current is positive int")(
    typeof page.pagination.current === "number" &&
      Number.isInteger(page.pagination.current) &&
      page.pagination.current > 0,
  );
  TestValidator.predicate("pagination.limit is positive int")(
    typeof page.pagination.limit === "number" &&
      Number.isInteger(page.pagination.limit) &&
      page.pagination.limit > 0,
  );
  TestValidator.predicate("pagination.records non-negative int")(
    typeof page.pagination.records === "number" &&
      Number.isInteger(page.pagination.records) &&
      page.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages non-negative int")(
    typeof page.pagination.pages === "number" &&
      Number.isInteger(page.pagination.pages) &&
      page.pagination.pages >= 0,
  );

  // 3. If records == 0 there should be no data, else: spot check entries
  if (page.pagination.records === 0)
    TestValidator.equals("empty page data if no logs exist")(page.data)([]);
  else {
    TestValidator.predicate("data array non-empty when records exist")(
      Array.isArray(page.data) && page.data.length > 0,
    );
    // Only check a sample (first) log - or all logs if desired
