  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        parent_id: null,
      },
    },
  );
  typia.assert(post);
  TestValidator.equals("post author matches member")(
    post.discussion_board_member_id,
  )(member.id);

  // 3. Perform two edits to the post via the edit event endpoint
  const edit1Title = RandomGenerator.paragraph()();
  const edit1Body = RandomGenerator.content()()();
  const edit1 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: edit1Title,
          new_body: edit1Body,
          edited_at: new Date().toISOString(),
          rationale: "Initial revision",
        },
      },
    );
  typia.assert(edit1);

  // Ensure at least a millisecond difference between edits for order
  await new Promise((res) => setTimeout(res, 5));

  const edit2Title = RandomGenerator.paragraph()();
  const edit2Body = RandomGenerator.content()()();
  const edit2 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: edit2Title,
          new_body: edit2Body,
          edited_at: new Date().toISOString(),
          rationale: "Second revision",
        },
      },
    );
  typia.assert(edit2);

  // 4. Fetch the edit history for the post
  const history =
    await api.functional.discussionBoard.member.posts.postEdits.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(history);

  // 5. Confirm the response lists both edits in chronological order
  TestValidator.predicate("edit history contains both edits")(
    history.data.length >= 2,
  );

  // As returned order may be either ascending or descending (API-dependent), sort for predictable check
  const editsByEditedAt = [...history.data].sort((a, b) =>
    a.edited_at.localeCompare(b.edited_at),
  );
  const [firstEdit, secondEdit] = [editsByEditedAt[0], editsByEditedAt[1]];
  TestValidator.equals("first edit title matches")(firstEdit.new_title)(
    edit1Title,
  );
  TestValidator.equals("second edit title matches")(secondEdit.new_title)(
    edit2Title,
  );
  TestValidator.equals("first edit rationale matches")(firstEdit.rationale)(
    "Initial revision",
  );
  TestValidator.equals("second edit rationale matches")(secondEdit.rationale)(
    "Second revision",
  );
  TestValidator.equals("edit member id matches")(
    firstEdit.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("edit member id matches")(
    secondEdit.discussion_board_member_id,
  )(member.id);

  // 6. Confirm timeline and attribution fields are present and correctly populated
  TestValidator.predicate("edit at exists")(
    typeof firstEdit.edited_at === "string",
  );
  TestValidator.predicate("edit at exists")(
    typeof secondEdit.edited_at === "string",
  );
}

