import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Validate that a moderator can retrieve the edit history for any post – even
 * if not authored by them.
 *
 * Business Context: Moderators must be able to audit/edit logs for any post,
 * regardless of authorship, in order to properly handle disputes, policy
 * compliance, and member appeals. Edit histories should include all
 * member-performed edits for transparency and accountability.
 *
 * Step-by-step Process:
 *
 * 1. Register a member user who will author the post.
 * 2. As that member, create a discussion board post.
 * 3. As the member, make two edits to the post to generate an edit history.
 * 4. Register a moderator account.
 * 5. As the moderator, fetch the edit audit trail for the member's post.
 * 6. Assert that both edits are present in the audit trail, reference the correct
 *    post and editor, and that no edit is hidden from moderation.
 */
export async function test_api_discussionBoard_test_moderator_can_see_edits_for_any_post(
  connection: api.IConnection,
) {
  // 1. Register a member user (post author)
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. As member, create a discussion post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. As member, create two post edit events (simulating user edits)
  const edit1 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: post.title + " [edit 1]",
          new_body: post.body + "\nEdit 1: grammar fix.",
          edited_at: new Date().toISOString(),
          rationale: "Grammar fix",
        } satisfies IDiscussionBoardPostEdit.ICreate,
      },
    );
  typia.assert(edit1);
  // Simulate a second edit a minute later
  const edit2 =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: post.title + " [edit 2]",
          new_body: post.body + "\nEdit 2: added details.",
          edited_at: new Date(Date.now() + 60000).toISOString(),
          rationale: "Adding detail",
        } satisfies IDiscussionBoardPostEdit.ICreate,
      },
    );
  typia.assert(edit2);

  // 4. Register a moderator account
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphabets(12),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 5. As moderator, fetch and verify the post's edit audit trail
  const pageEdits =
    await api.functional.discussionBoard.moderator.posts.postEdits.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(pageEdits);

  // 6. Assert both edits are present and reference correct post/editor
  TestValidator.predicate("at least 2 edits present")(
    pageEdits.data.length >= 2,
  );
  const found1 = pageEdits.data.some((edit) => edit.id === edit1.id);
  const found2 = pageEdits.data.some((edit) => edit.id === edit2.id);
  TestValidator.predicate("edit 1 visible to moderator")(found1);
  TestValidator.predicate("edit 2 visible to moderator")(found2);
  for (const edit of [edit1, edit2]) {
    const audit = pageEdits.data.find((e) => e.id === edit.id);
    TestValidator.predicate("each edit present in audit trail")(!!audit);
    TestValidator.equals("correct post id")(audit?.discussion_board_post_id)(
      post.id,
    );
    TestValidator.equals("correct member id")(
      audit?.discussion_board_member_id,
    )(member.id);
  }
}

