/**
 * Validate that a member can retrieve the list of votes for a specific post.
 *
 * Business context: Voting is a primary engagement mechanism on discussion
 * boards. Members can upvote or downvote posts, but only authenticated users
 * may see the full vote details. Accurate aggregation is needed for both
 * moderation and analytics.
 *
 * Steps:
 *
 * 1. Create a post (could represent an author).
 * 2. Cast votes with several members (simulated; assumes connection context change
 *    per unique member if available).
 * 3. Fetch all votes for post and validate number/count, vote-voter linkage,
 *    upvote flag, and timestamp format.
 * 4. Edge: Create a new post but do not vote; assert returned list is empty.
 */
export async function test_api_discussionBoard_test_list_post_votes_as_member_for_post_with_votes(
  connection: api.IConnection,
) {
  // 1. Create a post (as current member)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(2),
        body: RandomGenerator.content()()(2),
        parent_id: null,
      },
    },
  );
  typia.assert(post);

  // 2. Simulate votes from three different members (context switch depends on auth setup)
  // If the system supports multiple member identities, switch context per member here
  // For simplicity, these votes will be cast in series using the same connection
  // (For thorough E2E: in real system, use different account/connection objects per voter)
  const votesToCast = [true, false, true];
  const recordedVotes: string[] = [];
  for (const vote of votesToCast) {
    const voteObj =
      await api.functional.discussionBoard.member.posts.postVotes.create(
        connection,
        {
          postId: post.id,
          body: { upvote: vote },
        },
      );
    typia.assert(voteObj);
    recordedVotes.push(voteObj.id);
  }

  // 3. Retrieve votes and validate
  const page =
    await api.functional.discussionBoard.member.posts.postVotes.index(
      connection,
      { postId: post.id },
    );
  typia.assert(page);
  TestValidator.equals("total votes")(page.data.length)(votesToCast.length);
  for (const expectedVote of votesToCast) {
    const found = page.data.find((v) => v.upvote === expectedVote);
    TestValidator.predicate(`found vote with upvote=${expectedVote}`)(!!found);
    if (found) {
      TestValidator.equals("post id")(found.discussion_board_post_id)(post.id);
      TestValidator.equals("upvote field")(typeof found.upvote === "boolean")(
        true,
      );
      TestValidator.predicate("created_at present")(
        typeof found.created_at === "string" && found.created_at.length > 0,
      );
    }
  }

  // 4. Edge: no votes scenario
  const post2 = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(2),
        body: RandomGenerator.content()()(2),
        parent_id: null,
      },
    },
  );
  typia.assert(post2);
  const emptyVotes =
    await api.functional.discussionBoard.member.posts.postVotes.index(
      connection,
      { postId: post2.id },
    );
  typia.assert(emptyVotes);
  TestValidator.equals("zero votes")(emptyVotes.data.length)(0);
}

