import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Validate admin capability to retrieve the full list of authentication tokens
 * issued on the discussion board system.
 *
 * Business rationale: Administrators require comprehensive access—via
 * /discussionBoard/admin/authTokens—to audit all session tokens issued to any
 * user role, for compliance, monitoring, or investigation. This test ensures
 * the endpoint returns paginated results with well-formed token records, after
 * at least one member has generated a token via registration/login.
 *
 * Steps:
 *
 * 1. Register a new member to guarantee at least one authentication token exists
 *    in the system.
 * 2. As an admin, use the /discussionBoard/admin/authTokens endpoint to retrieve
 *    tokens.
 * 3. Assert the returned page has valid pagination metadata and at least one token
 *    record.
 * 4. Validate each token: all business-critical fields (id/type/audit) exist, and
 *    exactly one actor_id (admin, moderator, member, guest) is non-null per
 *    record.
 */
export async function test_api_discussionBoard_test_list_auth_tokens_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Register a member (ensures at least one token exists for test coverage)
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. As admin, retrieve auth tokens from admin endpoint
  const tokensPage =
    await api.functional.discussionBoard.admin.authTokens.index(connection);
  typia.assert(tokensPage);

  // 3. Assert at least one token exists (from previous step or otherwise)
  TestValidator.predicate("At least one token is returned for admin")(
    tokensPage.data.length > 0,
  );

  // 4. Validate pagination structure (current page, page size, total, etc)
  const { pagination } = tokensPage;
  TestValidator.predicate("Page current >= 0")(pagination.current >= 0);
  TestValidator.predicate("Page limit > 0")(pagination.limit > 0);
  TestValidator.predicate("Page records non-negative")(pagination.records >= 0);
  TestValidator.predicate("Page count non-negative")(pagination.pages >= 0);

  // 5. Validate each auth token's integrity and actor association
  for (const tok of tokensPage.data) {
    TestValidator.predicate("Token id is plausibly uuid")(
      typeof tok.id === "string" && tok.id.length >= 32,
    );
    TestValidator.predicate("actor_type allowed")(
      typeof tok.actor_type === "string" &&
        ["admin", "moderator", "member", "guest"].includes(tok.actor_type),
    );
    TestValidator.predicate("issued_at format plausible")(
      typeof tok.issued_at === "string" && tok.issued_at.length > 10,
    );
    TestValidator.predicate("revoked flag boolean")(
      typeof tok.revoked === "boolean",
    );
    // Exactly one actor_id must be set (enforces business rule for token-user association)
    TestValidator.predicate("One and only one actor id reference is set")(
      [tok.admin_id, tok.moderator_id, tok.member_id, tok.guest_id].filter(
        (v) => v != null,
      ).length === 1,
    );
  }
}

