/**
 * Test retrieving the complete list of all category-tag assignments as a
 * moderator.
 *
 * This test verifies that as a moderator, you can correctly retrieve a
 * paginated list of all category-tag assignments in the discussion board
 * system, including, but not limited to, the assignments just created for this
 * test. The function checks that all audit, access, and control policies are
 * correctly enforced:
 *
 * 1. Create a new category via the admin API to ensure a category exists.
 * 2. Create a new tag via the admin API to ensure a tag exists.
 * 3. Assign the created tag to the category as a moderator to guarantee at least
 *    one assignment exists.
 * 4. Retrieve the list of all category-tag assignments via the moderator endpoint
 *    and check that at least the record just created appears in the returned
 *    list.
 * 5. Validate that returned records have all necessary audit fields (IDs,
 *    timestamps) and IDs match the association created above.
 * 6. Test expected negative scenario: attempt to call without authentication and
 *    verify access is denied.
 *
 * Note: Because deletion and role-switching APIs are not available, soft-delete
 * and non-moderator access cannot be directly tested. DB/network error
 * simulation is not possible with current test surface.
 */
export async function test_api_discussionBoard_test_list_all_category_tag_assignments_as_moderator(
  connection: api.IConnection,
) {
  // 1. Create a new category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 2. Create a new tag
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: "#" + RandomGenerator.alphaNumeric(6),
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag);

  // 3. Assign the created tag to the category as a moderator
  const assignment =
    await api.functional.discussionBoard.moderator.categoryTags.create(
      connection,
      {
        body: {
          discussion_board_category_id: category.id,
          discussion_board_tag_id: tag.id,
        } satisfies IDiscussionBoardCategoryTag.ICreate,
      },
    );
  typia.assert(assignment);

  // 4. Retrieve the list of all category-tag assignments as a moderator
  const page =
    await api.functional.discussionBoard.moderator.categoryTags.index(
      connection,
    );
  typia.assert(page);
  TestValidator.predicate("There is at least one assignment")(
    page.data.length >= 1,
  );

  // 5. Validate that the assignment just created is present and fields are correct
  const found = page.data.find(
    (x) =>
      x.id === assignment.id &&
      x.discussion_board_category_id === category.id &&
      x.discussion_board_tag_id === tag.id,
  );
  TestValidator.predicate("Created assignment is in the result")(!!found);
  TestValidator.equals("Assignment id matches")(found?.id)(assignment.id);
  TestValidator.equals("Category id matches")(
    found?.discussion_board_category_id,
  )(category.id);
  TestValidator.equals("Tag id matches")(found?.discussion_board_tag_id)(
    tag.id,
  );
  TestValidator.predicate("created_at is ISO8601 string")(
    !!found &&
      typeof found.created_at === "string" &&
      found.created_at.includes("T"),
  );

  // 6. Attempt as unauthenticated user and confirm permission denied
  const unauthConnection: api.IConnection = { ...connection };
  // Remove Authorization header only if it existed
  if (unauthConnection.headers && "Authorization" in unauthConnection.headers)
    delete unauthConnection.headers["Authorization"];
  await TestValidator.error(
    "Unauthenticated user cannot list category-tag assignments",
  )(async () => {
    await api.functional.discussionBoard.moderator.categoryTags.index(
      unauthConnection,
    );
  });
}

