/**
 * Test advanced filtering and pagination of category-tag assignments using
 * moderator search.
 *
 * This test verifies the filtering of assignments by tag_id and confirms
 * correct pagination:
 *
 * 1. Create multiple distinct categories via the admin endpoint.
 * 2. Create multiple distinct tags via the admin endpoint.
 * 3. For each (category, tag) pair, assign the tag to the category as a moderator.
 * 4. Pick one tag and perform an advanced search filter with that tag_id. Assert:
 *
 *    - Only assignments for that tag are included in results.
 *    - No assignments from other tag_ids are present.
 *    - Pagination fields are present and logical for the requested page size.
 * 5. Also, search by a non-existent tag_id. Assert:
 *
 *    - Result is empty (no assignments returned, pages/records are zero).
 */
export async function test_api_discussionBoard_test_search_category_tag_assignments_by_tag_id_as_moderator(
  connection: api.IConnection,
) {
  // 1. Create multiple categories
  const categories = await ArrayUtil.asyncRepeat(3)(async () => {
    const category =
      await api.functional.discussionBoard.admin.categories.create(connection, {
        body: {
          name: RandomGenerator.alphaNumeric(8),
          description: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardCategory.ICreate,
      });
    typia.assert(category);
    return category;
  });

  // 2. Create multiple tags
  const tags = await ArrayUtil.asyncRepeat(3)(async () => {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      {
        body: {
          label: RandomGenerator.alphaNumeric(8),
          description: RandomGenerator.paragraph()(),
          color: "#" + RandomGenerator.alphaNumeric(6),
        } satisfies IDiscussionBoardTag.ICreate,
      },
    );
    typia.assert(tag);
    return tag;
  });

  // 3. Assign tags to categories (every combination)
  const assignments = [] as IDiscussionBoardCategoryTag[];
  for (const category of categories) {
    for (const tag of tags) {
      const assignment =
        await api.functional.discussionBoard.moderator.categoryTags.create(
          connection,
          {
            body: {
              discussion_board_category_id: category.id,
              discussion_board_tag_id: tag.id,
            } satisfies IDiscussionBoardCategoryTag.ICreate,
          },
        );
      typia.assert(assignment);
      assignments.push(assignment);
    }
  }

  // 4. Pick one tag, filter assignments using its tag id
  const filterTag = RandomGenerator.pick(tags).id;
  const pageLimit = 2;
  const result =
    await api.functional.discussionBoard.moderator.categoryTags.search(
      connection,
      {
        body: {
          discussion_board_tag_id: filterTag,
          page: 1,
          limit: pageLimit,
        } satisfies IDiscussionBoardCategoryTag.IRequest,
      },
    );
  typia.assert(result);
  // Assert that all assignments in results are for the filter tag
  for (const assignment of result.data) {
    TestValidator.equals("assignment tag_id matches query")(
      assignment.discussion_board_tag_id,
    )(filterTag);
  }
  TestValidator.predicate("results contain only assignments for filtered tag")(
    result.data.every((a) => a.discussion_board_tag_id === filterTag),
  );
  // Check pagination values
  TestValidator.equals("pagination.limit as requested")(
    result.pagination.limit,
  )(pageLimit);
  TestValidator.equals("pagination.current page is 1")(
    result.pagination.current,
  )(1);

  // 5. Query with a non-existent tag_id (should yield empty result)
  const nonExistentTagId = typia.random<string & tags.Format<"uuid">>();
  const emptyResult =
    await api.functional.discussionBoard.moderator.categoryTags.search(
      connection,
      {
        body: {
          discussion_board_tag_id: nonExistentTagId,
          page: 1,
          limit: pageLimit,
        } satisfies IDiscussionBoardCategoryTag.IRequest,
      },
    );
  typia.assert(emptyResult);
  TestValidator.equals("no assignments for non-existent tag")(
    emptyResult.data.length,
  )(0);
  TestValidator.equals("records is 0 for empty result")(
    emptyResult.pagination.records,
  )(0);
}

