import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Validate that an admin can retrieve full details for a specific suspension by
 * ID.
 *
 * Business context: Admins need to review, audit, or manage suspension/ban
 * events for community moderation. This test ensures not only that the admin
 * can access details for a known suspension, but also validates the
 * completeness and accuracy of the data returned by the API.
 *
 * Step-by-Step Workflow:
 *
 * 1. Create a valid suspension using POST /discussionBoard/admin/suspensions to
 *    establish a known suspensionId for test.
 * 2. As a (pre-authenticated) admin, call GET
 *    /discussionBoard/admin/suspensions/{suspensionId} with this ID.
 * 3. Validate that the returned suspension details match creation input for all
 *    key business fields, and that required fields conform to type and format
 *    expectations.
 */
export async function test_api_discussionBoard_admin_suspensions_test_get_suspension_detail_valid_admin_access(
  connection: api.IConnection,
) {
  // 1. Create a valid suspension to use for detail retrieval validation
  const createInput: IDiscussionBoardSuspension.ICreate = {
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Violation of community guidelines.",
    status: "active",
    suspended_at: new Date().toISOString(),
    ends_at: null,
  };
  const created: IDiscussionBoardSuspension =
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Fetch the suspension details as admin
  const detail: IDiscussionBoardSuspension =
    await api.functional.discussionBoard.admin.suspensions.at(connection, {
      suspensionId: created.id,
    });
  typia.assert(detail);

  // 3. Validate that key data matches original input and required fields exist
  TestValidator.equals("suspension id matches")(detail.id)(created.id);
  TestValidator.equals("suspended_member_id matches")(
    detail.suspended_member_id,
  )(createInput.suspended_member_id);
  TestValidator.equals("reason matches")(detail.reason)(createInput.reason);
  TestValidator.equals("status matches")(detail.status)(createInput.status);
  TestValidator.equals("suspended_at matches")(detail.suspended_at)(
    createInput.suspended_at,
  );
  TestValidator.equals("ends_at matches")(detail.ends_at)(createInput.ends_at);

  // 4. Confirm system-populated/admin fields exist and are plausibly formatted
  TestValidator.predicate("id is UUID")(
    typeof detail.id === "string" && detail.id.length > 0,
  );
  TestValidator.predicate("suspended_at is ISO8601 string")(
    typeof detail.suspended_at === "string" &&
      detail.suspended_at.includes("T"),
  );
  TestValidator.predicate("reason is non-empty")(detail.reason.length > 0);
  TestValidator.equals("status is 'active'")(detail.status)("active");
}

