/**
 * Test the creation of a suspension record for a discussion board member by an
 * admin.
 *
 * This test ensures that an admin can successfully impose a suspension on a
 * member account, providing all required information, and that the returned
 * suspension record matches the input and audit requirements.
 *
 * Steps:
 *
 * 1. Retrieve the list of existing discussion board members to get a valid member
 *    UUID.
 * 2. As an authenticated admin, create a new suspension for one of the members,
 *    specifying the appropriate fields (target UUID as 'suspended_member_id',
 *    admin's UUID as 'admin_id' if it can be known in the test context, proper
 *    timestamps, rationale/reason, and 'active' status).
 * 3. Verify that: a. The returned suspension record references the correct member
 *    (by UUID) b. Actor/admin ID is set appropriately or null if not available
 *    in test context c. Timestamps (suspended_at, ends_at) are audit-valid
 *    ISO8601 strings d. The reason/rationale and status match your input e. All
 *    critical fields (IDs and audit fields) are present and correctly
 *    formatted. f. No extraneous properties are present, and no critical field
 *    is missing or null
 */
export async function test_api_discussionBoard_test_create_suspension_for_member_by_admin(
  connection: api.IConnection,
) {
  // 1. Retrieve a list of members to acquire a valid member UUID
  const members =
    await api.functional.discussionBoard.admin.members.index(connection);
  typia.assert(members);
  if (!members.data.length)
    throw new Error("No members found for suspension test");
  const member = RandomGenerator.pick(members.data);

  // 2. Create a new suspension for the selected member.
  //    Note: Actor/admin UUID (admin_id) cannot be set unless the API or testbed provides it. We set it to null, which is valid for this scenario.
  const now = new Date();
  const endsAt = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour suspension
  const reason = `Violation of guidelines at ${now.toISOString()}`;

  const createInput = {
    suspended_admin_id: null, // Only member is suspended
    suspended_moderator_id: null,
    suspended_member_id: member.id,
    suspended_guest_id: null,
    admin_id: null, // Set to null unless known test identity is available
    moderator_id: null,
    related_report_id: null,
    related_action_id: null,
    suspended_at: now.toISOString(),
    ends_at: endsAt.toISOString(),
    reason,
    status: "active",
  } satisfies IDiscussionBoardSuspension.ICreate;

  const suspension =
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(suspension);

  // 3. Validate returned record matches input
  TestValidator.equals("suspended_member_id matches")(
    suspension.suspended_member_id,
  )(member.id);
  TestValidator.equals("actor admin_id matches")(suspension.admin_id)(null);
  TestValidator.equals("status matches")(suspension.status)("active");
  TestValidator.equals("reason matches")(suspension.reason)(reason);
  TestValidator.equals("suspended_at matches")(suspension.suspended_at)(
    now.toISOString(),
  );
  TestValidator.equals("ends_at matches")(suspension.ends_at)(
    endsAt.toISOString(),
  );
  TestValidator.predicate("output id is uuid")(
    typeof suspension.id === "string" && suspension.id.length > 0,
  );
  // Ensure no banned-admin/mod/guest IDs are set, only member
  TestValidator.equals("suspended_admin_id null")(
    suspension.suspended_admin_id,
  )(null);
  TestValidator.equals("suspended_moderator_id null")(
    suspension.suspended_moderator_id,
  )(null);
  TestValidator.equals("suspended_guest_id null")(
    suspension.suspended_guest_id,
  )(null);
  TestValidator.equals("moderator_id null")(suspension.moderator_id)(null);
  TestValidator.equals("related_report_id null")(suspension.related_report_id)(
    null,
  );
  TestValidator.equals("related_action_id null")(suspension.related_action_id)(
    null,
  );
}

