import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Validate prevention of duplicate active suspensions for the same member.
 *
 * This test checks that the system enforces business rules disallowing
 * overlapping suspensions. A member who already has an active suspension should
 * not be able to receive another, unless policy specifically allows (e.g., for
 * record updates). Generally, a duplicate active suspension creation should be
 * rejected to maintain moderation integrity and auditability.
 *
 * Steps:
 *
 * 1. List members and pick an available member.
 * 2. Create an initial active suspension for the member.
 * 3. Attempt to create a second active suspension for the same member and
 *    overlapping period.
 * 4. Assert that the second suspension request is rejected (the API throws error).
 *
 * Edge case: If member list is empty, the test will fail. Ensure there is at
 * least one member before running this test.
 */
export async function test_api_discussionBoard_admin_suspensions_test_create_duplicate_active_suspension_for_same_subject(
  connection: api.IConnection,
) {
  // 1. Obtain list of members (for picking a member to suspend)
  const memberList =
    await api.functional.discussionBoard.admin.members.index(connection);
  typia.assert(memberList);
  const pickedMember = memberList.data[0];
  TestValidator.predicate("At least one member exists for suspension testing")(
    !!pickedMember,
  );

  // 2. Create an initial active suspension for this member
  const now = new Date();
  const endsAt = new Date(now.getTime() + 1000 * 60 * 60 * 24); // +1 day duration
  const firstSuspension =
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: {
        suspended_admin_id: null,
        suspended_moderator_id: null,
        suspended_member_id: pickedMember.id,
        suspended_guest_id: null,
        admin_id: null,
        moderator_id: null,
        related_report_id: null,
        related_action_id: null,
        suspended_at: now.toISOString(),
        ends_at: endsAt.toISOString(),
        reason: "Initial active suspension for duplicate prevention",
        status: "active",
      } satisfies IDiscussionBoardSuspension.ICreate,
    });
  typia.assert(firstSuspension);

  // 3. Attempt to create a duplicate active suspension for the same member, same period
  await TestValidator.error(
    "API should prevent duplicate active suspensions for the same subject",
  )(async () => {
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: {
