    });
  typia.assert(secondPost);
  const unrelatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: secondPost.id,
        body: {
          discussion_board_post_id: secondPost.id,
          parent_id: null,
