import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

/**
 * E2E test for searching moderation actions as an admin with complex filter and
 * pagination.
 *
 * This test case verifies the advanced search/filter/pagination logic on the
 * moderation actions audit/event table for the admin backend. It ensures all
 * filter criteria (by action_type, admin_id, moderator_id, report_id,
 * combinations) work correctly and only matching actions are returned. It
 * checks pagination for correct slicing and metadata, and verifies edge cases
 * like filters yielding empty results. Audit fields and all search logic are
 * exercised for coverage, using seeded records with controlled
 * actor/report/type.
 *
 * Steps:
 *
 * 1. Seed the system with a diverse set of moderation actions (varied actors,
 *    types, reports)
 * 2. Test each single-filter mode (by action_type, admin_id, moderator_id,
 *    report_id)
 * 3. Test multi-filter mode (intersection logic)
 * 4. Test pagination metadata/correctness
 * 5. Edge: Ensure empty filter yields empty data, valid though
 * 6. For every result set, verify audit fields' presence and that all hit records
 *    satisfy the filter(s)
 */
export async function test_api_discussionBoard_admin_moderationActions_test_search_moderation_actions_with_specific_criteria(
  connection: api.IConnection,
) {
  // 1. Seed moderation actions with controlled variety
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const reportIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Create a known set: some by admin, some by moderator, covering type/report variations
  const createdActions = [
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[0],
          admin_id: adminId,
          action_type: "suspend",
          description: "Admin suspended on report 1",
        },
      },
    ),
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[0],
          admin_id: adminId,
          action_type: "edit",
          description: "Admin edited content on report 1",
        },
      },
    ),
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[1],
          moderator_id: moderatorId,
          action_type: "suspend",
          description: "Moderator suspended on report 2",
        },
      },
    ),
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[1],
          moderator_id: moderatorId,
          action_type: "delete",
          description: "Moderator deleted on report 2",
        },
      },
    ),
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[1],
          admin_id: adminId,
          action_type: "delete",
          description: "Admin deleted on report 2",
        },
      },
    ),
  ];

  // Add extra actions to ensure pagination logic can be tested
  for (let i = 0; i < 3; ++i)
    await api.functional.discussionBoard.admin.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportIds[i % 2],
          admin_id: adminId,
          action_type: "edit",
          description: `Paged edit action ${i}`,
        },
      },
    );

  // 2. Single-filter: action_type
  const res_byActionType =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          action_type: "suspend",
        },
      },
    );
  typia.assert(res_byActionType);
  for (const rec of res_byActionType.data)
    TestValidator.equals("action_type = suspend")(rec.action_type)("suspend");

  // 3. Single-filter: admin_id
  const res_byAdminId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          admin_id: adminId,
        },
      },
    );
  typia.assert(res_byAdminId);
  for (const rec of res_byAdminId.data)
    TestValidator.equals("admin_id match")(rec.admin_id)(adminId);

  // 4. Single-filter: moderator_id
  const res_byModeratorId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          moderator_id: moderatorId,
        },
      },
    );
  typia.assert(res_byModeratorId);
  for (const rec of res_byModeratorId.data)
    TestValidator.equals("moderator_id match")(rec.moderator_id)(moderatorId);

  // 5. Single-filter: report_id
  const res_byReportId =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          report_id: reportIds[0],
        },
      },
    );
  typia.assert(res_byReportId);
  for (const rec of res_byReportId.data)
    TestValidator.equals("report_id match")(rec.report_id)(reportIds[0]);

  // 6. Combined filter: action_type + admin_id + report_id
  const res_combined =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          action_type: "edit",
          admin_id: adminId,
          report_id: reportIds[0],
        },
      },
    );
  typia.assert(res_combined);
  for (const rec of res_combined.data) {
    TestValidator.equals("action_type = edit")(rec.action_type)("edit");
    TestValidator.equals("admin_id match")(rec.admin_id)(adminId);
    TestValidator.equals("report_id match")(rec.report_id)(reportIds[0]);
  }

  // 7. Pagination: page 2, limit 2
  const res_paged =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          pagination: {
            limit: 2,
            page: 2,
          },
        },
      },
    );
  typia.assert(res_paged);
  TestValidator.equals("pagination.current=2")(res_paged.pagination.current)(2);
  TestValidator.equals("pagination.limit=2")(res_paged.pagination.limit)(2);
  TestValidator.predicate("data length <= 2")(res_paged.data.length <= 2);

  // 8. Edge: Filters matching nothing
  const res_none =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      {
        body: {
          action_type: "not-a-type",
          admin_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(res_none);
  TestValidator.equals("empty result")(res_none.data.length)(0);
  TestValidator.equals("page 1 for empty")(res_none.pagination.current)(1);

  // 9. For every result set, audit field check
  for (const res of [
    res_byActionType,
    res_byAdminId,
    res_byModeratorId,
    res_byReportId,
    res_combined,
    res_paged,
  ])
    for (const rec of res.data) {
      TestValidator.predicate("id is present")(
        typeof rec.id === "string" && rec.id.length > 0,
      );
      TestValidator.predicate("has report_id")(
        typeof rec.report_id === "string" && rec.report_id.length > 0,
      );
      TestValidator.predicate("has action_type")(
        typeof rec.action_type === "string" && rec.action_type.length > 0,
      );
      TestValidator.predicate("has description")(
        typeof rec.description === "string" && rec.description.length > 0,
      );
      TestValidator.predicate("has acted_at")(
        typeof rec.acted_at === "string" && rec.acted_at.length > 0,
      );
    }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

/**
 * Validate that searching for moderation actions with criteria that yield no
 * matching records returns an empty dataset and correct pagination
 * information.
 *
 * This ensures the admin moderation actions search endpoint gracefully handles
 * no-result (empty result) scenarios, with no data returned but with full
 * pagination metadata indicating zero records and one page.
 *
 * Steps:
 *
 * 1. Construct a search filter with highly unlikely/non-existent criteria (e.g., a
 *    random UUID for report_id, admin_id, or moderator_id) to avoid matching
 *    any moderation actions.
 * 2. Call the moderation actions search API with those criteria.
 * 3. Validate that the returned data array is empty.
 * 4. Validate that pagination information indicates zero records, one page, and
 *    correct limit and page values.
 */
export async function test_api_discussionBoard_admin_moderationActions_test_search_moderation_actions_returns_empty_on_no_match(
  connection: api.IConnection,
) {
  // 1. Construct a filter guaranteed not to match any records (use a random UUID as report_id)
  //    This minimizes the likelihood of matching any existing moderation actions.
  const noResultFilter: IDiscussionBoardModerationAction.IRequest = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    admin_id: null,
    moderator_id: null,
    action_type: null,
    date_from: null,
    date_to: null,
    pagination: {
      page: 1,
      limit: 5,
    },
  };

  // 2. Execute search with no-result criteria
  const output =
    await api.functional.discussionBoard.admin.moderationActions.search(
      connection,
      { body: noResultFilter },
    );
  typia.assert(output);

  // 3. Assert returned data is empty
  TestValidator.equals("no moderation actions in data")(output.data)([]);

  // 4. Validate pagination reflects zero records and a single page
  TestValidator.equals("zero records")(output.pagination.records)(0);
  TestValidator.equals("single page")(output.pagination.pages)(1);
  TestValidator.equals("correct current page")(output.pagination.current)(1);
  TestValidator.equals("correct limit")(output.pagination.limit)(5);
}

