/**
 * Validate admin search and filtering for discussion board members by email.
 *
 * This test ensures an admin can accurately search, filter, and paginate member
 * accounts using both exact and partial email filters. The scenario includes
 * creating multiple member accounts with diverse emails, then executing admin
 * member search with both full and partial email matches. Edge cases such as
 * partial string matches, full matches, and unrelated accounts are validated,
 * along with pagination metadata.
 *
 * Steps:
 *
 * 1. Register several members programmatically with distinct and
 *    partially-overlapping email addresses (some sharing partial strings, some
 *    unique)
 * 2. Execute search as admin with the PATCH /discussionBoard/admin/members
 *    endpoint, passing a full email (exact match) of one user as filter
 * 3. Confirm only the exact-matching member is returned; pagination reflects a
 *    single record
 * 4. Execute search as admin with a partial email substring (e.g., domain or
 *    common prefix) as filter
 * 5. Confirm all members with emails matching the substring are returned
 * 6. Validate pagination/meta data correctness for both cases (record count
 *    matches, current page, limit, pages)
 * 7. Negative case: Search with a non-existent email pattern, expect zero results
 *    and correct pagination meta data
 */
export async function test_api_discussionBoard_admin_members_test_search_members_with_email_filter_as_admin(
  connection: api.IConnection,
) {
  // 1. Register several members with varying emails
  const emails = [
    `alice${typia.random<number>()}@testmail.com`,
    `bob${typia.random<number>()}@example.com`,
    `charlie${typia.random<number>()}@testmail.com`,
    `dana${typia.random<number>()}@mailservice.com`,
    `eve${typia.random<number>()}@testmail.com`,
  ];
  const members = [];
  for (const email of emails) {
    const member = await api.functional.discussionBoard.members.create(
      connection,
      {
        body: {
          display_name: email.split("@")[0],
          email,
          password_hash: RandomGenerator.alphaNumeric(20),
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(member);
    members.push(member);
  }

  // 2. Search by exact email (should return a single user)
  const exactEmail = emails[0];
  const exactResult = await api.functional.discussionBoard.admin.members.search(
    connection,
    { body: { email: exactEmail } satisfies IDiscussionBoardMember.IRequest },
  );
  typia.assert(exactResult);
  TestValidator.equals("exact match record length")(exactResult.data.length)(1);
  TestValidator.equals("exact match email")(exactResult.data[0].email)(
    exactEmail,
  );
  TestValidator.equals("pagination records")(exactResult.pagination.records)(1);

  // 3. Search by partial email (should return all *@testmail.com users)
  const partialEmail = "testmail.com";
  const partialResult =
    await api.functional.discussionBoard.admin.members.search(connection, {
      body: { email: partialEmail } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(partialResult);
  const expectedPartial = members.filter((m) => m.email.includes(partialEmail));
  TestValidator.equals("partial match count")(partialResult.data.length)(
    expectedPartial.length,
  );
  for (const member of expectedPartial) {
    TestValidator.predicate(`member present in partial result`)(
      partialResult.data.some((r) => r.email === member.email),
    );
  }
  TestValidator.equals("pagination records")(partialResult.pagination.records)(
    expectedPartial.length,
  );

  // 4. Pagination meta check: default limit is 100, current page 1
  TestValidator.equals("pagination current")(partialResult.pagination.current)(
    1,
  );
  TestValidator.equals("pagination limit")(partialResult.pagination.limit)(100);

  // 5. Negative case: no matches
  const noneResult = await api.functional.discussionBoard.admin.members.search(
    connection,
    { body: { email: "nomatch" } satisfies IDiscussionBoardMember.IRequest },
  );
  typia.assert(noneResult);
  TestValidator.equals("no result count")(noneResult.data.length)(0);
  TestValidator.equals("pagination records")(noneResult.pagination.records)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Validates pagination and ordering of admin member search results for
 * discussion board.
 *
 * Business context: Admins and moderators need to view member lists with
 * pagination in order to audit, analyze, or manage large user bases. Correct
 * pagination and ordering are essential for accuracy, fairness, and usability
 * in admin dashboards.
 *
 * Test Workflow:
 *
 * 1. Register 17 unique members so that the dataset exceeds 1 page (using page
 *    size 10).
 * 2. As admin, perform paginated member searches with explicit pagination input
 *    (no sort available in API, so checks default/natural order, assumed by
 *    display_name ascending).
 * 3. For each retrieved page:
 *
 *    - Validate pagination meta (current/limit/total records/pages)
 *    - Validate data length matches page, especially last page edge-case
 *    - After all pages collected, confirm aggregate ordering matches expected
 * 4. Edge: last page should contain only the remainder (not a full page)
 */
export async function test_api_discussionBoard_test_search_members_with_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register enough members for multiple pages (total: 17, page size: 10)
  const totalMembers = 17;
  const members: IDiscussionBoardMember[] = [];
  for (let i = 0; i < totalMembers; ++i) {
    const display_name = `User${String(i).padStart(2, "0")}`;
    const email = `user${i}_${typia.random<string & tags.Format<"uuid">>()}@test.com`;
    const password_hash = typia.random<string>();
    const created = await api.functional.discussionBoard.members.create(
      connection,
      {
        body: {
          display_name,
          email,
          password_hash,
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(created);
    members.push(created);
  }

  // Reference: display_name ascending
  const sortedByDisplayName = [...members].sort((a, b) =>
    a.display_name.localeCompare(b.display_name),
  );

  // 2. Iterate through paginated admin search (no sort parameter)
  const limit = 10;
  let collected: IDiscussionBoardMember[] = [];
  let currentPage = 1;
  const totalPages = Math.ceil(totalMembers / limit);

  while (collected.length < totalMembers) {
    const res = await api.functional.discussionBoard.admin.members.search(
      connection,
      {
        body: {
          pagination: { page: currentPage, limit },
        } satisfies IDiscussionBoardMember.IRequest,
      },
    );
    typia.assert(res);
    // Validate pagination meta
    TestValidator.equals(`page ${currentPage} current`)(res.pagination.current)(
      currentPage,
    );
    TestValidator.equals(`page ${currentPage} limit`)(res.pagination.limit)(
      limit,
    );
    if (currentPage === 1)
      TestValidator.equals("total records")(res.pagination.records)(
        totalMembers,
      );
    // Validate length for page or edge
    if (currentPage < totalPages) {
      TestValidator.equals(`members on page ${currentPage}`)(res.data.length)(
        limit,
      );
    } else {
      TestValidator.equals("last page count")(res.data.length)(
        totalMembers % limit,
      );
    }
    collected.push(...res.data);
    currentPage++;
  }

  // 3. Validate ordering is correct: display_name ascending
  for (let i = 0; i < totalMembers; ++i) {
    TestValidator.equals(`member display_name order ${i}`)(
      collected[i].display_name,
    )(sortedByDisplayName[i].display_name);
  }

  // 4. Edge: last page only contains the remainder
  const lastPageRes = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        pagination: { page: totalPages, limit },
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(lastPageRes);
  TestValidator.equals("last page count")(lastPageRes.data.length)(
    totalMembers % limit,
  );
}

