/**
 * Validate that a guest (unauthenticated user) can retrieve only active
 * (non-soft-deleted) discussion board categories.
 *
 * This test ensures that when a guest requests the category list:
 *
 * - All returned items have deleted_at === null or undefined
 * - No soft-deleted (deleted_at set) categories are present in the response
 * - Guest access does not trigger any permissions error (should only error for DB
 *   issues)
 *
 * Business rationale: Guests require category access for browsing, post
 * creation, or navigation. The endpoint must exclude soft-deleted categories
 * from guest visibility, supporting compliance and usability.
 *
 * Process:
 *
 * 1. Issue GET request to /discussionBoard/categories as a guest (unauthenticated
 *    connection)
 * 2. Assert response is a valid IPageIDiscussionBoardCategory structure
 * 3. Assert that no returned category has deleted_at set (all are active)
 * 4. Verify paging contract is respected and data array is present
 */
export async function test_api_discussionBoard_categories_index(
  connection: api.IConnection,
) {
  // 1. Send GET request for discussion board categories as guest
  const result =
    await api.functional.discussionBoard.categories.index(connection);
  typia.assert(result);

  // 2. Assert pagination/data structure exist
  if (
    !("pagination" in result) ||
    !("data" in result) ||
    !Array.isArray(result.data)
  ) {
    throw new Error("Result missing expected pagination/data contract");
  }

  // 3. Assert every category is not soft-deleted (deleted_at must be null or undefined)
  for (const category of result.data) {
    if (
      category.deleted_at !== null &&
      typeof category.deleted_at !== "undefined"
    ) {
      throw new Error(
        `Soft-deleted category returned to guest: ${category.id}`,
      );
    }
  }

