/**
 * Validate that an admin or moderator can retrieve all discussion board
 * categories—including soft-deleted ones—using the standard category listing
 * endpoint.
 *
 * This scenario tests privileged access for category management and audit:
 *
 * 1. Simulates admin by using the admin search endpoint with include_deleted: true
 *    to get the full reference list, including soft-deleted categories
 *    (deleted_at set).
 * 2. Then uses the public categories endpoint (with admin context) to fetch the
 *    list as visible to a privileged user.
 * 3. Asserts that all categories returned via the admin endpoint are also present
 *    in the public endpoint's result, verifying mandatory and optional fields
 *    are correct (id, name, created_at, updated_at, description, deleted_at).
 * 4. Asserts no permission error or access restriction occurs for the privileged
 *    context.
 */
export async function test_api_discussionBoard_test_list_categories_as_admin_returns_all_categories_including_deleted(
  connection: api.IConnection,
) {
  // 1. As admin, fetch all categories including soft-deleted
  const adminCategories =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: { include_deleted: true },
    });
  typia.assert(adminCategories);
  const adminAll = adminCategories.data;

  // 2. In admin context, request categories via public endpoint
  const publicCategories =
    await api.functional.discussionBoard.categories.index(connection);
  typia.assert(publicCategories);
  const publicAll = publicCategories.data;

  // 3. Check that every admin-seen category appears in the public result, with all fields matching
  for (const adminCat of adminAll) {
    const found = publicAll.find((c) => c.id === adminCat.id);
    TestValidator.predicate(
      `category ${adminCat.id} present in public results`,
    )(!!found);
    if (found) {
      TestValidator.equals(`id matches for ${adminCat.id}`)(found.id)(
        adminCat.id,
      );
      TestValidator.equals(`name matches for ${adminCat.id}`)(found.name)(
        adminCat.name,
      );
      TestValidator.equals(`created_at matches for ${adminCat.id}`)(
        found.created_at,
      )(adminCat.created_at);
      TestValidator.equals(`updated_at matches for ${adminCat.id}`)(
        found.updated_at,
      )(adminCat.updated_at);
      TestValidator.equals(`deleted_at matches for ${adminCat.id}`)(
        found.deleted_at ?? null,
      )(adminCat.deleted_at ?? null);
      TestValidator.equals(`description matches for ${adminCat.id}`)(
        found.description ?? null,
      )(adminCat.description ?? null);
    }
  }
  // 4. Check that every category in public result has required fields
  for (const cat of publicAll) {
    TestValidator.predicate("id exists")(!!cat.id);
    TestValidator.predicate("name exists")(!!cat.name);
    TestValidator.predicate("created_at exists")(!!cat.created_at);
    TestValidator.predicate("updated_at exists")(!!cat.updated_at);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
