import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin search filter for soft-deleted categories exclusion in
 * discussion board categories.
 *
 * This test ensures that when searching discussion board categories as an
 * admin, soft-deleted categories (those with a non-null deleted_at) are
 * excluded by default (or when explicitly excluded) from results. Test data
 * consists of a mix of active and soft-deleted categories.
 *
 * Steps:
 *
 * 1. Create multiple categories using the admin create endpoint.
 * 2. Soft-delete a subset of these categories using the admin delete endpoint.
 * 3. Use the admin search/filter endpoint, omitting the include_deleted parameter
 *    (or setting it to false/null).
 * 4. Confirm that the response contains only active categories (none with
 *    deleted_at set).
 */
export async function test_api_discussionBoard_test_admin_search_categories_excluding_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create multiple categories
  const categoryNames: string[] = [
    RandomGenerator.alphabets(8),
    RandomGenerator.alphabets(8),
    RandomGenerator.alphabets(8),
    RandomGenerator.alphabets(8),
  ];
  const createdCategories: IDiscussionBoardCategory[] = [];
  for (const name of categoryNames) {
    const category: IDiscussionBoardCategory =
      await api.functional.discussionBoard.admin.categories.create(connection, {
        body: {
          name,
          description: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardCategory.ICreate,
      });
    typia.assert(category);
    createdCategories.push(category);
  }

  // 2. Soft-delete two categories
  const toDelete = RandomGenerator.sample(createdCategories)(2);
  for (const category of toDelete) {
    await api.functional.discussionBoard.admin.categories.erase(connection, {
      categoryId: category.id,
    });
  }

  // 3. Search categories without include_deleted (should exclude soft-deleted)
  const searchResponse =
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        page: 1,
        limit: 10,
        name: null,
        created_from: null,
        created_to: null,
        include_deleted: false, // explicitly set to false
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(searchResponse);

  // 4. Validate that no soft-deleted categories are present in the results
  const deletedIds = toDelete.map((x) => x.id);
  for (const category of searchResponse.data) {
    if (deletedIds.includes(category.id)) {
      throw new Error(
        "A soft-deleted category was returned in search results.",
      );
    }
    if (category.deleted_at != null) {
      throw new Error(
        "A category with non-null deleted_at appeared in results.",
      );
    }
  }
  TestValidator.predicate("No soft-deleted categories should appear")(
    searchResponse.data.every(
      (cat) => cat.deleted_at === null || cat.deleted_at === undefined,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
