import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin search validation and error handling for category filter
 * requests.
 *
 * Ensures that invalid or malformed admin search requests:
 *
 * - Are rejected with validation errors
 * - Never leak category or internal data
 * - Robustly handle bad pagination, date, and type errors
 *
 * 1. Try negative page/limit
 * 2. Use a backwards date range (created_from > created_to)
 * 3. Try excessive limit
 * 4. Submit incorrect type (string for page)
 * 5. Inject an unsupported field
 */
export async function test_api_discussionBoard_test_admin_search_categories_with_invalid_filter_fails(
  connection: api.IConnection,
) {
  // 1. Negative page/limit (API should reject negative paging)
  await TestValidator.error("negative page/limit rejected")(async () => {
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        page: -5 as number,
        limit: -30 as number,
      },
    });
  });

  // 2. created_from after created_to (malformed date interval)
  const later = new Date();
  const earlier = new Date(later.getTime() - 1000000);
  await TestValidator.error("created_from > created_to rejected")(async () => {
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        created_from: later.toISOString(),
        created_to: earlier.toISOString(),
      },
    });
  });

  // 3. Excessive limit (pagination cap)
  await TestValidator.error("excessive limit rejected")(async () => {
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        limit: 999999,
      },
    });
  });

  // 4. Incorrect type: string for page
  await TestValidator.error("string for page rejected")(async () => {
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        page: "not-a-number" as any,
      },
    });
  });

  // 5. Unsupported/injected field
  await TestValidator.error("unsupported field rejected")(async () => {
    await api.functional.discussionBoard.admin.categories.search(connection, {
      body: {
        extra_field: "nope" as any,
      } as any,
    });
  });
}

