 * 1. Admin creates two discussion board categories: one that will remain active,
 *    and one that will be soft-deleted.
 * 2. Admin soft-deletes the second category.
 * 3. Moderator searches for categories with filter `include_deleted: true` and a
 *    large enough limit.
 * 4. Assert that the result includes both categories, with correct deleted_at
 *    status.
 */
export async function test_api_discussionBoard_test_moderator_search_categories_includes_soft_deleted_with_permission(
  connection: api.IConnection,
) {
  // 1. Admin creates two categories (one active, one intended to be deleted)
  const categoryActive =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(8),
