import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate default moderator search excludes soft-deleted categories.
 *
 * This test ensures that when a moderator searches for discussion board
 * categories without specifying `include_deleted`, the default search results
 * only contain active (non-soft-deleted) categories. It verifies that
 * soft-deleted categories (those with non-null `deleted_at`) are excluded from
 * the moderator view unless explicitly included by filter.
 *
 * Steps:
 *
 * 1. Create several categories as an admin (at least 2 to soft-delete, and at
 *    least 2 to remain active)
 * 2. Soft-delete two of the categories created in step 1
 * 3. Perform a moderator search for categories using default parameters (do not
 *    set `include_deleted`)
 * 4. Assert that only the active categories (those with `deleted_at` null) are
 *    returned, and that soft-deleted ones are excluded
 */
export async function test_api_discussionBoard_test_moderator_search_categories_excludes_soft_deleted_by_default(
  connection: api.IConnection,
) {
  // 1. Create categories (4 total: 2 active, 2 to soft-delete later)
  const categoryActive1 =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryActive1);

  const categoryActive2 =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryActive2);

  const categoryDeleted1 =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryDeleted1);

  const categoryDeleted2 =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryDeleted2);

  // 2. Soft-delete two categories
  await api.functional.discussionBoard.admin.categories.erase(connection, {
    categoryId: categoryDeleted1.id,
  });
  await api.functional.discussionBoard.admin.categories.erase(connection, {
    categoryId: categoryDeleted2.id,
  });

  // 3. Moderator searches with default filters (do not set include_deleted)
  const result =
    await api.functional.discussionBoard.moderator.categories.search(
      connection,
      {
        body: {}, // default parameters, should exclude soft-deleted by default
      },
    );
  typia.assert(result);

  // 4. Validate the result contains only the two active categories
  const activeIds = [categoryActive1.id, categoryActive2.id];
  for (const cat of result.data) {
    TestValidator.equals("category is not deleted")(cat.deleted_at)(null);
    TestValidator.predicate("category is an active member")(
      activeIds.includes(cat.id),
    );
  }
  // Assert none of the soft-deleted categories are included
  const deletedIds = [categoryDeleted1.id, categoryDeleted2.id];
  for (const id of deletedIds) {
    TestValidator.predicate("soft-deleted category absent")(
      result.data.find((cat) => cat.id === id) === undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
