/**
 * Validate that searching discussion board categories with invalid parameters
 * triggers robust input validation errors without leaking system or category
 * details.
 *
 * This test ensures that the API strictly enforces type and value validation on
 * category search request fields (pagination, date filters, soft-deletion
 * flag), and safely handles invalid input by:
 *
 * - Testing invalid data types for numeric, date, and boolean fields
 * - Providing negative, zero, and excessive values for page/limit
 * - Submitting malformed date strings and incorrect types for date/bool fields
 * - Asserting errors are thrown for each case using TestValidator.error
 * - Ensuring no category or system details are leaked in error responses
 *
 * Steps:
 *
 * 1. Attempt to search with a string for 'page' (must be integer)
 * 2. Supply negative and zero values for 'page' and 'limit'
 * 3. Use unreasonably large numbers for pagination
 * 4. Input invalid date formats or types for 'created_from'/'created_to'
 * 5. Provide invalid types for 'include_deleted'
 * 6. Combine several invalid types to verify robust multi-field validation
 * 7. Verify that every case fails with a validation error and no sensitive
 *    response is returned
 */
export async function test_api_discussionBoard_test_moderator_search_categories_with_invalid_parameters_returns_error(
  connection: api.IConnection,
) {
  // 1. Invalid: page as string
  await TestValidator.error("string for page causes error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: "one" as any,
      } as any,
    }),
  );

  // 2. Invalid: negative & zero for page and limit
  await TestValidator.error("negative page causes error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: -3 as any,
        limit: 10,
      } as any,
    }),
  );
  await TestValidator.error("negative limit causes error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: 1,
        limit: -7 as any,
      } as any,
    }),
  );
  await TestValidator.error("zero for page triggers error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: 0 as any,
        limit: 10,
      } as any,
    }),
  );
  await TestValidator.error("zero for limit triggers error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: 1,
        limit: 0 as any,
      } as any,
    }),
  );

  // 3. Invalid: huge values for page/limit
  await TestValidator.error("large page value causes error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: 10_000_000 as any,
      } as any,
    }),
  );
  await TestValidator.error("large limit value causes error")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: 1,
        limit: 10_000_000 as any,
      } as any,
    }),
  );

  // 4. Invalid date types and formats
  await TestValidator.error("malformed created_from date")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        created_from: "not-a-date" as any,
      } as any,
    }),
  );
  await TestValidator.error("malformed created_to date")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        created_to: "2022-25-77T99:99:99Z" as any,
      } as any,
    }),
  );
  await TestValidator.error("boolean instead of date")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        created_from: false as any,
        created_to: true as any,
      } as any,
    }),
  );

  // 5. Invalid type for include_deleted
  await TestValidator.error("number for include_deleted")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        include_deleted: 45 as any,
      } as any,
    }),
  );
  await TestValidator.error("string for include_deleted")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        include_deleted: "yes" as any,
      } as any,
    }),
  );

  // 6. Multiple invalids together
  await TestValidator.error("multiple types invalid together")(() =>
    api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        page: "bad" as any,
        limit: -1 as any,
        created_from: null,
        created_to: 1337 as any,
        include_deleted: "why not" as any,
      } as any,
    }),
  );

  // 7. All errors should only result in validation error (not data leak)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
