/**
 * Validate retrieval of discussion board category details by ID for an active
 * (non-deleted) category.
 *
 * This test ensures that, after creating a category via admin API, retrieving
 * its details using the public GET endpoint immediately returns accurate and
 * complete information as per the schema.
 *
 * Workflow:
 *
 * 1. Create a new category using the admin creation API (persist a unique name and
 *    optional description).
 * 2. Immediately request category details by ID using the public endpoint for that
 *    exact category.
 * 3. Assert that all schema-required fields are present and match the values
 *    persisted during creation (name, description, id, timestamps).
 * 4. Assert that 'deleted_at' is null or undefined for an active category.
 * 5. Validate field formats (id is UUID, timestamps are ISO8601, etc.).
 */
export async function test_api_discussionBoard_test_get_category_details_success_active_category(
  connection: api.IConnection,
) {
  // 1. Create a new category using the admin creation API
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
  };
  const created: IDiscussionBoardCategory =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Retrieve category details by ID (immediately after creation)
  const details: IDiscussionBoardCategory =
    await api.functional.discussionBoard.categories.at(connection, {
      categoryId: created.id,
    });
  typia.assert(details);

  // 3. Assert returned details match the persisted category data
  TestValidator.equals("category id")(details.id)(created.id);
  TestValidator.equals("category name")(details.name)(created.name);
  TestValidator.equals("category description")(details.description)(
    created.description,
  );
  TestValidator.predicate("created_at is ISO8601")(
    !!Date.parse(details.created_at),
  );
  TestValidator.predicate("updated_at is ISO8601")(
    !!Date.parse(details.updated_at),
  );
  TestValidator.equals("deleted_at is null or undefined")(
    details.deleted_at ?? null,
  )(null);
}

