 *
 * - Username
 * - Password_hash
 * - Email
 * - Is_active The endpoint should enforce integrity by returning a validation
 *   error rather than creating a partial or invalid account. This protects the
 *   system against incomplete staff entries and preserves audit and access
 *   integrity.
 *
 * Test Workflow:
 *
 * 1. Attempt to create a moderator with the 'username' field missing.
 * 2. Verify that a validation error is thrown and no account is created.
 * 3. Attempt to create a moderator with the 'password_hash' field missing.
 * 4. Verify that a validation error is thrown and no account is created.
 * 5. Attempt to create a moderator with the 'email' field missing.
 * 6. Verify that a validation error is thrown and no account is created.
 * 7. Attempt to create a moderator with the 'is_active' field missing.
 * 8. Verify that a validation error is thrown and no account is created.
 * 9. (Bonus) Attempt to create with all fields present as a control and expect
 *    success.
 */
export async function test_api_discussionBoard_test_create_moderator_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Attempt to create a moderator with username missing
  await TestValidator.error("missing username should cause validation failure")(
    async () => {
      await api.functional.discussionBoard.admin.moderators.create(connection, {
        body: {
          // username intentionally missing
          password_hash: "hashed-password-sample",
          email: typia.random<string & tags.Format<"email">>(),
          is_active: true,
          // promoted_by_admin_id is optional
        } as any, // intentionally malformed (TypeScript cannot allow omitted required properties)
      });
    },
  );

  // 2. Attempt to create a moderator with password_hash missing
  await TestValidator.error(
    "missing password_hash should cause validation failure",
  )(async () => {
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: "mod_no_password",
        // password_hash intentionally missing
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } as any,
    });
  });

  // 3. Attempt to create a moderator with email missing
  await TestValidator.error("missing email should cause validation failure")(
    async () => {
      await api.functional.discussionBoard.admin.moderators.create(connection, {
        body: {
          username: "mod_no_email",
          password_hash: "hashed-password-sample",
          // email intentionally missing
          is_active: true,
        } as any,
      });
    },
  );

  // 4. Attempt to create a moderator with is_active missing
  await TestValidator.error(
    "missing is_active should cause validation failure",
  )(async () => {
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: "mod_no_active",
        password_hash: "hashed-password-sample",
        email: typia.random<string & tags.Format<"email">>(),
        // is_active intentionally missing
      } as any,
    });
  });

  // 5. Attempt to create a moderator with all required fields present (should succeed)
  const validOut = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: "valid_moderator",
        password_hash: "hashed-password-sample",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        // promoted_by_admin_id is optional
      },
    },
  );
  typia.assert(validOut);
}

