 * - Validates full workflow—setup, deletion, and post-deletion effects.
 * - Ensures the delete operation cannot be performed by the self-targeting admin.
 * - Confirms visibility and status changes after deletion.
 *
 * Steps:
 *
 * 1. Create two admin accounts (A and B) with unique credentials, both active.
 * 2. List admins before deletion and ensure both are present.
 * 3. Delete admin A by ID as admin B (context simulated: always-authorized
 *    super-admin).
 * 4. List admins again and confirm A is absent or inactive (is_active === false).
 * 5. Attempt self-delete as admin B and confirm business policy forbids this.
 * 6. (Audit and login-blocked behaviors are not implementable—skip.)
 */
export async function test_api_discussionBoard_test_delete_admin_success_with_proper_authorization(
  connection: api.IConnection,
) {
  // 1. Create two admin accounts (A and B)
  const adminA = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminA);

  const adminB = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminB);

  // 2. List admins before deletion, ensure both A and B are found
  const adminListBefore =
    await api.functional.discussionBoard.admin.admins.index(connection);
  typia.assert(adminListBefore);
  TestValidator.predicate("admin A found before deletion")(
    adminListBefore.data.some((a) => a.id === adminA.id),
