/**
 * Test searching for moderators by admin promoter using PATCH filter endpoint
 *
 * This test validates that the moderator search PATCH endpoint correctly
 * filters moderators according to their promoted_by_admin_id — that is, the
 * admin who promoted the moderator. This is essential for audit tracking and
 * admin visibility workflows. The test covers three cases: moderators promoted
 * by adminA, adminB, and legacy/manual entries with no promoter recorded.
 *
 * Steps:
 *
 * 1. Generate UUIDs for two fake admin accounts (adminA & adminB) acting as
 *    promoters
 * 2. Create several moderators:
 *
 *    - Two with promoted_by_admin_id = adminA
 *    - One with promoted_by_admin_id = adminB
 *    - One with no promoted_by_admin_id (legacy/manual)
 * 3. Use the PATCH search endpoint to query for moderators with promoter adminA
 *
 *    - Verify all returned entries have promoted_by_admin_id === adminA
 *    - Verify no results for adminB or legacy moderator
 * 4. Repeat PATCH query for adminB, expect only their moderator appears
 * 5. PATCH query for null promoted_by_admin_id, only legacy/manual appears
 */
export async function test_api_discussionBoard_test_search_moderators_by_promoter(
  connection: api.IConnection,
) {
  // 1. Prepare two unique admin IDs
  const adminAId: string = typia.random<string & tags.Format<"uuid">>();
  const adminBId: string = typia.random<string & tags.Format<"uuid">>();

  // 2a. Moderators promoted by adminA
  const modA1 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modA1);
  const modA2 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modA2);

  // 2b. Moderator promoted by adminB
  const modB = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: adminBId,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(modB);

  // 2c. Legacy/manual moderator with no promoted_by_admin_id
  const modLegacy =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(6),
        password_hash: RandomGenerator.alphaNumeric(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        // promoted_by_admin_id omitted on purpose
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(modLegacy);

  // 3. Search moderators promoted by adminA
  const resA = await api.functional.discussionBoard.moderator.moderators.search(
    connection,
    {
      body: {
        promoted_by_admin_id: adminAId,
      } satisfies IDiscussionBoardModerator.IRequest,
    },
  );
  typia.assert(resA);
  TestValidator.predicate("every returned moderator was promoted by adminA")(
    resA.data.every(
      (m: IDiscussionBoardModerator) => m.promoted_by_admin_id === adminAId,
    ),
  );
  TestValidator.predicate(
    "no moderator promoted by adminB or legacy appears in adminA's results",
  )(
    resA.data.every(
      (m: IDiscussionBoardModerator) => m.promoted_by_admin_id === adminAId,
    ),
  );

  // 4. Search moderators promoted by adminB
  const resB = await api.functional.discussionBoard.moderator.moderators.search(
    connection,
    {
      body: {
        promoted_by_admin_id: adminBId,
      } satisfies IDiscussionBoardModerator.IRequest,
    },
  );
  typia.assert(resB);
  TestValidator.predicate("every returned moderator was promoted by adminB")(
    resB.data.every(
      (m: IDiscussionBoardModerator) => m.promoted_by_admin_id === adminBId,
    ),
  );

  // 5. Search for legacy/manual moderators (with no promoted_by_admin_id)
  const resLegacy =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          promoted_by_admin_id: undefined,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resLegacy);
  TestValidator.predicate("all legacy moderators have no promoted_by_admin_id")(
    resLegacy.data.every(
      (m: IDiscussionBoardModerator) => !m.promoted_by_admin_id,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Validate searching discussion board moderators by creation and update time
 * range.
 *
 * This test ensures that the moderator search (PATCH
 * /discussionBoard/moderator/moderators) supports filtering by creation time
 * windows. It:
 *
 * 1. Creates two moderators with distinct timestamps (simulate gap via setTimeout)
 * 2. Searches with 'created_after' (should return only the second moderator)
 * 3. Searches with 'created_before' (should return only the first moderator)
 * 4. Searches with a between-window (should return no moderators)
 * 5. Searches with no filters (should return both moderators)
 * 6. Searches with a future window (no results expected)
 */
export async function test_api_discussionBoard_test_search_moderators_by_time_range(
  connection: api.IConnection,
) {
  // 1. Create first moderator (with controlled timestamp)
  const mod1 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        password_hash: RandomGenerator.alphaNumeric(32), // mock hash
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(mod1);
  const mod1Created = new Date(mod1.created_at);

  // Simulate time difference
  await new Promise((resolve) => setTimeout(resolve, 1200));

  // 2. Create second moderator
  const mod2 = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        password_hash: RandomGenerator.alphaNumeric(32), // mock hash
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(mod2);
  const mod2Created = new Date(mod2.created_at);

  // Defensive - ensure timestamps are strictly increasing
  TestValidator.predicate("mod2 created after mod1")(
    mod2Created.getTime() > mod1Created.getTime(),
  );

  // 3. Search for moderators created AFTER mod1 (should include only mod2 among test-created ones)
  const resultAfter1 =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_after: mod1.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resultAfter1);
  // Data may contain other preexisting moderators, but we check for mod2
  TestValidator.predicate("mod2 found, mod1 not found")(
    resultAfter1.data.some((m) => m.id === mod2.id) &&
      !resultAfter1.data.some((m) => m.id === mod1.id),
  );
  // All results must have created_at > mod1's
  TestValidator.predicate("all are after mod1.created_at")(
    resultAfter1.data.every((m) => new Date(m.created_at) > mod1Created),
  );

  // 4. Search for moderators created BEFORE mod2
  const resultBefore2 =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_before: mod2.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(resultBefore2);
  TestValidator.predicate("mod1 found, mod2 not found")(
    resultBefore2.data.some((m) => m.id === mod1.id) &&
      !resultBefore2.data.some((m) => m.id === mod2.id),
  );
  TestValidator.predicate("all are before mod2.created_at")(
    resultBefore2.data.every((m) => new Date(m.created_at) < mod2Created),
  );

  // 5. Search between windows (should yield no new test mods)
  const between =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_after: mod1.created_at,
          created_before: mod2.created_at,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(between);
  // None of the test moderators should appear
  TestValidator.predicate("between search empty for test mods")(
    !between.data.some((m) => m.id === mod1.id || m.id === mod2.id),
  );
  // Just in case, if pre-existing data matches, ensure the count is very low
  TestValidator.predicate("likely empty or very small result")(
    between.data.length <= 1,
  );

  // 6. Search with no filter (should see both test-created moderators among results)
  const allResult =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {} satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(allResult);
  TestValidator.predicate("both test moderators present")(
    allResult.data.some((m) => m.id === mod1.id) &&
      allResult.data.some((m) => m.id === mod2.id),
  );

  // 7. Search with a future window (should yield no results for new mods)
  const futureDate = new Date(Date.now() + 1000 * 60 * 60).toISOString(); // 1h into the future
  const future =
    await api.functional.discussionBoard.moderator.moderators.search(
      connection,
      {
        body: {
          created_after: futureDate,
        } satisfies IDiscussionBoardModerator.IRequest,
      },
    );
  typia.assert(future);
  TestValidator.predicate("no test mods found in future search")(
    !future.data.some((m) => m.id === mod1.id || m.id === mod2.id),
  );
}

