/**
 * Validates admin's ability to retrieve details of a specific post edit event
 * in the discussion board.
 *
 * This test case simulates the workflow of a new member creating a post, then
 * editing that post, and finally having an admin retrieve the exact details of
 * the created edit event.
 *
 * Steps:
 *
 * 1. Register a new discussion board member (as post author and editor).
 * 2. Using this member, create a new post.
 * 3. Make an edit to the created post.
 * 4. As admin (assuming connection context has admin rights), retrieve the edit
 *    event using postId and postEditId.
 * 5. Verify the result fields (new title/body, rationale, editor, timestamp) match
 *    the original edit event data.
 */
export async function test_api_discussionBoard_test_retrieve_post_edit_details_successfully_as_admin(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member (author/editor)
  const memberDisplayName = RandomGenerator.name();
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new discussion board post as the member
  const postTitle = RandomGenerator.paragraph()();
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: postTitle,
        body: postBody,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Make an edit to the created post
  const newTitle = RandomGenerator.paragraph()();
  const newBody = RandomGenerator.content()()();
  const rationale = "Typo correction and content update";
  const edited_at = new Date().toISOString();
  const edit =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: newTitle,
          new_body: newBody,
          edited_at,
          rationale,
        } satisfies IDiscussionBoardPostEdit.ICreate,
      },
    );
  typia.assert(edit);

  // 4. As admin, retrieve the edit event details
  const output = await api.functional.discussionBoard.admin.posts.postEdits.at(
    connection,
    {
      postId: post.id,
      postEditId: edit.id,
    },
  );
  typia.assert(output);

  // 5. Verify the response matches the edit event
  TestValidator.equals("edit id matches")(output.id)(edit.id);
  TestValidator.equals("post id matches")(output.discussion_board_post_id)(
    post.id,
  );
  TestValidator.equals("editor id matches")(output.discussion_board_member_id)(
    member.id,
  );
  TestValidator.equals("new title matches")(output.new_title)(newTitle);
  TestValidator.equals("new body matches")(output.new_body)(newBody);
  TestValidator.equals("rationale matches")(output.rationale)(rationale);
  TestValidator.equals("edited_at matches")(output.edited_at)(edited_at);
}

