  // 2. Create a new post as this member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(1),
    parent_id: null, // top-level post (no parent)
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: postInput,
    },
  );
  typia.assert(post);

  // 3. Submit an edit event for this post, updating both title and body
  const newTitle = RandomGenerator.paragraph()(1) + " [edited]";
  const newBody = RandomGenerator.content()(1)(1) + "\nEdit rationale test.";
  const rationale = "Fixed typos and clarified section.";
  const now = new Date().toISOString();
  const editInput: IDiscussionBoardPostEdit.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: member.id,
    new_title: newTitle,
    new_body: newBody,
    edited_at: now,
    rationale,
  };
  const editEvent =
    await api.functional.discussionBoard.member.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: editInput,
      },
