  TestValidator.equals("discussion_board_post_id = post.id")(
    editEvent.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("discussion_board_member_id = member.id")(
    editEvent.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("edit title")(editEvent.new_title)(newTitle);
  TestValidator.equals("edit body")(editEvent.new_body)(newBody);
  TestValidator.equals("edit rationale")(editEvent.rationale)(rationale);
  // edited_at should be within 1 minute (60,000 ms) of 'now' for this test
  TestValidator.predicate("edited_at close to now")(
    Math.abs(
      new Date(editEvent.edited_at).getTime() - new Date(now).getTime(),
    ) < 60000,
  );
}

