/**
 * Test that a moderator can successfully update an existing post edit event for
 * a discussion board post.
 *
 * This E2E test simulates the following realistic workflow:
 *
 * 1. Register a member (as required for post authorship).
 * 2. Member creates a post on the board.
 * 3. Register a moderator.
 * 4. Moderator creates an initial post edit event for the member's post.
 * 5. Moderator then updates the post edit event using the moderator endpoint,
 *    changing fields such as title, body, or rationale.
 * 6. Verify:
 *
 *    - All changed fields in the edit event are reflected as expected from the
 *         response.
 *    - The editor reference in the post edit event remains immutable (does not
 *         change after update).
 *    - Timestamps and audit logs are updated accordingly.
 *    - No irrelevant fields are modified.
 */
export async function test_api_discussionBoard_test_moderator_updates_existing_post_edit_event_successfully(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberCreate: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: memberCreate,
    },
  );
  typia.assert(member);

  // 2. Member creates a post
  const postCreate: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(2),
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: postCreate,
    },
  );
  typia.assert(post);

  // 3. Register a moderator
  const moderatorCreate: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
  };
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderatorCreate,
    });
  typia.assert(moderator);

  // 4. Moderator creates an initial post edit event for the member's post
  const initialEditCreate: IDiscussionBoardPostEdit.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: moderator.id,
    new_title: RandomGenerator.paragraph()(1),
    new_body: RandomGenerator.content()()(2),
    edited_at: new Date().toISOString() as string & tags.Format<"date-time">,
    rationale: "Initial moderation edit",
  };
  const edit =
    await api.functional.discussionBoard.moderator.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: initialEditCreate,
      },
    );
  typia.assert(edit);

  // 5. Moderator updates the post edit event via moderator endpoint
  const updatePayload: IDiscussionBoardPostEdit.IUpdate = {
    new_title: RandomGenerator.paragraph()(1),
    new_body: RandomGenerator.content()()(2),
    rationale: "Updated rationale for improved clarity",
  };
  const updatedEdit =
    await api.functional.discussionBoard.moderator.posts.postEdits.update(
      connection,
      {
        postId: post.id,
        postEditId: edit.id,
        body: updatePayload,
      },
    );
  typia.assert(updatedEdit);

  // 6. Assertions for business rules and correct mutation
  // Changed fields updated
  TestValidator.equals("updated title")(updatedEdit.new_title)(
    updatePayload.new_title,
  );
  TestValidator.equals("updated body")(updatedEdit.new_body)(
    updatePayload.new_body,
  );
  TestValidator.equals("updated rationale")(updatedEdit.rationale)(
    updatePayload.rationale,
  );
  // Editor reference remains immutable
  TestValidator.equals("editor reference is immutable")(
    updatedEdit.discussion_board_member_id,
  )(edit.discussion_board_member_id);
  TestValidator.equals("edit event id remains unchanged")(updatedEdit.id)(
    edit.id,
  );
  TestValidator.equals("linked post id remains unchanged")(
    updatedEdit.discussion_board_post_id,
  )(edit.discussion_board_post_id);
  // Timestamps: edited_at must be present and ISO string
  TestValidator.predicate("edited_at is ISO date-time string")(
    typeof updatedEdit.edited_at === "string" &&
      !isNaN(Date.parse(updatedEdit.edited_at)),
  );
}

