import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced admin search and filtering functionality for admin accounts.
 *
 * This test validates that as a super-admin:
 *
 * - Admin accounts can be located by filtering on partial username and is_active
 *   status
 * - Only matching records are included in results
 * - Pagination/limit parameters are respected (i.e., no data leakage from
 *   adjacent pages)
 * - Off-by-one and edge boundary checks for paging
 * - Only authorized users (admins) have access to search; unauthorized calls are
 *   rejected
 *
 * Step-by-step process:
 *
 * 1. Create 5 admin accounts with distinct usernames and is_active statuses (e.g.,
 *    3 active, 2 inactive, both with variety in username substrings)
 * 2. As an admin user, search for all admins with username containing a unique
 *    substring present in one account only and is_active=true; check that only
 *    the correct admin is returned
 * 3. Search for all inactive admins (is_active=false); check only the 2 inactive
 *    ones are returned
 * 4. Search with no filters, but limit=2 and page=2; verify the correct offset
 *    (pagination) is respected with no records from previous or following pages
 *    leaking in
 * 5. Attempt to search for admins as a non-admin/non-privileged connection; verify
 *    access is denied (e.g., error is thrown)
 */
export async function test_api_discussionBoard_admin_admins_test_search_admins_by_username_and_status(
  connection: api.IConnection,
) {
  // 1. Create 5 admin accounts with varying usernames and statuses
  const admins: IDiscussionBoardAdmin[] = [];
  for (let i = 0; i < 5; ++i) {
    const is_active = i % 2 === 0;
    const username = `e2e_admin_user_${i}_${RandomGenerator.alphabets(4)}`;
    const admin = await api.functional.discussionBoard.admin.admins.create(
      connection,
      {
        body: {
          username,
          email: `e2e_admin${i}_${typia.random<string & tags.Format<"email">>()}`,
          password_hash: RandomGenerator.alphaNumeric(8),
          is_active,
        } satisfies IDiscussionBoardAdmin.ICreate,
      },
    );
    typia.assert(admin);
    admins.push(admin);
  }

  // 2. Search for an account with a unique username substring, is_active=true
  const target = admins.find((a) => a.is_active)!;
  const unique_user_sub = target.username.slice(0, 12); // unique prefix
  const search1 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        username: unique_user_sub,
        is_active: true,
        page: 1,
        limit: 10,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search1);
  TestValidator.equals("matched data only")(search1.data.length)(1);
  TestValidator.equals("matched admin id")(search1.data[0].id)(target.id);

  // 3. Search for all inactive admins
  const search2 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        is_active: false,
        page: 1,
        limit: 10,
        username: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search2);
  const expectedInactive = admins
    .filter((a) => !a.is_active)
    .map((a) => a.id)
    .sort();
  const actualInactive = search2.data.map((a) => a.id).sort();
  TestValidator.equals("inactive admins correct")(actualInactive)(
    expectedInactive,
  );

  // 4. Pagination/offset test: no filter, page=2, limit=2
  const search3 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
        username: null,
        is_active: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search3);
  TestValidator.equals("pagination respects limit")(search3.data.length)(2);
  // IDs for second page match source
  const expectedPage2 = admins.slice(2, 4).map((a) => a.id);
  const actualPage2 = search3.data.map((a) => a.id);
  TestValidator.equals("pagination 2nd page IDs")(actualPage2)(expectedPage2);

  // 5. Negative case: try calling search as guest/invalid (simulate unauthorized user)
  const guestConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized search fails")(async () => {
    await api.functional.discussionBoard.admin.admins.search(guestConnection, {
      body: {
        page: 1,
        limit: 10,
        username: null,
        is_active: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    });
  });
}

