 * or malformed arguments triggers proper validation errors, that no sensitive
 * fields (passwords, tokens, etc.) are ever included in error responses, and
 * that error structures are descriptive but never expose implementation
 * internals.
 *
 * Steps:
 *
 * 1. Attempt to search admins with a malformed email address, expecting a
 *    validation error with no private data.
 * 2. Attempt to search admins using an out-of-range page number (e.g., zero or
 *    negative), expecting a validation error.
 * 3. Attempt to search admins with a negative limit value, expecting a validation
 *    error.
 * 4. Attempt to search admins using non-boolean (number) for is_active (runtime
 *    validation, not compile-time).
 * 5. Optionally, large numbers for page/limit (e.g., greater than max safe int)
 *    for robustness.
 * 6. For each error returned, validate that the error does NOT expose sensitive
 *    information and only provides clear, bounded details.
 */
export async function test_api_discussionBoard_test_search_admins_with_invalid_criteria(
  connection: api.IConnection,
) {
  // 1. Invalid email format
  await TestValidator.error("invalid email validation error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        email: "not-an-email",
        page: 1,
        limit: 5,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 2. Out-of-range pagination: page = 0
  await TestValidator.error("page number min boundary error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        page: 0,
        limit: 10,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 3. Negative limit
  await TestValidator.error("negative limit error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        limit: -1,
        page: 1,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 4. Non-boolean is_active (number instead of boolean/null)
  await TestValidator.error("non-boolean is_active error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      // Intentionally send a wrong type to catch backend validation
      body: {
        is_active: 1,
        page: 1,
        limit: 3,
        email: null,
      } as any,
    }),
  );

  // 5. Excessive/large pagination values
  await TestValidator.error("excessively large page/limit")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        page: Number.MAX_SAFE_INTEGER,
        limit: Number.MAX_SAFE_INTEGER,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 6. Defensive check: all errors must be bounded; real error structure check requires API-level agreement
  // DO NOT attempt to extract details from error surface unless SDK surfaces error data
  // Defensive comment: API never exposes password/token information in any response (enforced contract)
}

