 * or nonexistent IDs, ensuring access control and workflow consistency.
 *
 * Steps:
 *
 * 1. Create an appeal via POST /discussionBoard/admin/appeals (fill only admin
 *    appellant; others as null).
 * 2. Retrieve the same appeal with GET /discussionBoard/admin/appeals/{appealId}.
 * 3. Assert all fields (including id) match between creation input and fetched
 *    record.
 * 4. Confirm submitted_at is a valid ISO8601 datetime string.
 * 5. Perform lookup using random, non-existent ID and assert a 404 error occurs.
 */
export async function test_api_discussionBoard_admin_appeals_test_get_single_appeal_by_id_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a new moderation action appeal as admin
  const input: IDiscussionBoardAppeal.ICreate = {
    action_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Test appeal reason for E2E validation",
    status: "pending",
    appellant_admin_id: typia.random<string & tags.Format<"uuid">>(),
    appellant_moderator_id: null,
    appellant_member_id: null,
    appellant_guest_id: null,
