  TestValidator.equals("appellant_moderator_id")(
    fetched.appellant_moderator_id,
  )(input.appellant_moderator_id);
  TestValidator.equals("appellant_member_id")(fetched.appellant_member_id)(
    input.appellant_member_id,
  );
  TestValidator.equals("appellant_guest_id")(fetched.appellant_guest_id)(
    input.appellant_guest_id,
  );
  TestValidator.predicate("submitted_at is ISO8601 string")(
    !!Date.parse(fetched.submitted_at),
  );
  // 4. Error scenario: attempt to fetch appeal by a missing/invalid id
  TestValidator.error("not found appeal returns 404")(async () => {
    await api.functional.discussionBoard.admin.appeals.at(connection, {
      appealId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

