 *    /discussionBoard/moderator/appeals/{appealId}.
 * 3. Assert all fields match original creation data, including NULLs for mutually
 *    exclusive actor fields.
 * 4. Confirm type safety on every response.
 * 5. Attempt to fetch a random non-existent appeal ID, asserting error is thrown.
 */
export async function test_api_discussionBoard_test_get_single_appeal_by_id_as_moderator(
  connection: api.IConnection,
) {
  // 1. Setup: create a new appeal using the admin endpoint
  const appealInput: IDiscussionBoardAppeal.ICreate = {
    action_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Moderator action appeal for E2E test",
    status: "pending",
    appellant_admin_id: typia.random<string & tags.Format<"uuid">>(),
    appellant_moderator_id: null,
    appellant_member_id: null,
    appellant_guest_id: null,
  };
  const createdAppeal =
    await api.functional.discussionBoard.admin.appeals.create(connection, {
      body: appealInput,
    });
