  // 2. As a moderator, fetch the appeal by its unique ID
  const fetchedAppeal =
    await api.functional.discussionBoard.moderator.appeals.at(connection, {
      appealId: createdAppeal.id,
    });
  typia.assert(fetchedAppeal);

  // 3. Assert all fields are as expected and match what was created
  TestValidator.equals("appeal id matches")(fetchedAppeal.id)(createdAppeal.id);
  TestValidator.equals("action id matches")(fetchedAppeal.action_id)(
    appealInput.action_id,
  );
  TestValidator.equals("reason matches")(fetchedAppeal.reason)(
    appealInput.reason,
  );
  TestValidator.equals("status matches")(fetchedAppeal.status)(
    appealInput.status,
  );
  TestValidator.equals("appellant admin id matches")(
    fetchedAppeal.appellant_admin_id,
  )(appealInput.appellant_admin_id);
  TestValidator.equals("appellant moderator id null")(
    fetchedAppeal.appellant_moderator_id,
  )(null);
  TestValidator.equals("appellant member id null")(
    fetchedAppeal.appellant_member_id,
  )(null);
  TestValidator.equals("appellant guest id null")(
    fetchedAppeal.appellant_guest_id,
  )(null);

  // 4. Negative scenario: fetching an unknown appealId yields error
  await TestValidator.error("non-existent appealId triggers error")(
    async () => {
      await api.functional.discussionBoard.moderator.appeals.at(connection, {
        appealId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
