import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";
import type { IPageIDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced, filtered, and paginated retrieval of comment edit history
 * records.
 *
 * This test simulates a real-world moderation or analytic use case: after
 * generating a comment with a rich sequence of edits (including at least two
 * different editors and varied rationale texts, with time separation between
 * edits), it performs PATCH requests to search the edit history with diverse
 * filters—such as filtering solely by editor, by a substring in the rationale,
 * and by an explicit date range.
 *
 * Step-by-step:
 *
 * 1. Register two members (editorA, editorB).
 * 2. Member A creates a discussion post.
 * 3. Member A creates a comment on their post.
 * 4. Member A performs a first edit (specifying a rationale).
 * 5. Member B performs a second edit later (different rationale, different
 *    editor).
 * 6. Query the edit histories using the comment edit search endpoint, filtering
 *    by: a. Editor A's ID (should only include their edit), b. Rationale
 *    substring matching editor B's edit only, c. A date range that includes
 *    only one of the edits.
 * 7. For each query, validate the API returns correct pagination and the expected
 *    single edit (and no unrelated edits).
 * 8. Additionally, check ordering of multiple results: ensure records appear
 *    sorted by edit timestamp in the correct order (descending by created time,
 *    or as documented).
 *
 * Limitations: Actual API does not provide a field for rationale in edit/update
 * requests, nor does it allow explicit user impersonation/switching between
 * comment edits. Thus, all edits will occur under the same session context, and
 * rationale content cannot be set. Test is written as far as API and DTOs
 * permit.
 */
export async function test_api_discussionBoard_test_advanced_search_edit_history_for_comment_with_filters(
  connection: api.IConnection,
) {
  // 1. Register two members (editorA, editorB)
  const memberA = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      },
    },
  );
  typia.assert(memberA);
  const memberB = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      },
    },
  );
  typia.assert(memberB);

  // 2. Member A creates a discussion post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. Member A creates a comment on their post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.content()()(),
        },
      },
    );
  typia.assert(comment);
  const commentId = comment.id;

  // 4. Member A performs a first edit
  const updatedBodyA = RandomGenerator.content()()();
  await api.functional.discussionBoard.member.comments.update(connection, {
    commentId,
    body: { body: updatedBodyA },
  });

  // 5. Member B performs a second edit
  // (API does not allow session change; both edits will appear as same actor if context not switchable)
  const updatedBodyB = RandomGenerator.content()()();
  await api.functional.discussionBoard.member.comments.update(connection, {
    commentId,
    body: { body: updatedBodyB },
  });

  // 6. Perform PATCH searches using edit history search
  // a. By Editor A's memberId
  const byEditorA =
    await api.functional.discussionBoard.member.comments.commentEdits.search(
      connection,
      {
        commentId,
        body: { editor_member_id: memberA.id, page: 1, limit: 10 },
      },
    );
  typia.assert(byEditorA);
  TestValidator.predicate("All edit summaries are by editor A")(
    byEditorA.data.every((e) => e.editor_display_name === memberA.display_name),
  );

  // b. By rationale substring (no rationale can be set in API, but test the endpoint regardless)
  const byRationale =
    await api.functional.discussionBoard.member.comments.commentEdits.search(
      connection,
      {
        commentId,
        body: { rationale: "clarified", page: 1, limit: 10 },
      },
    );
  typia.assert(byRationale);
  TestValidator.predicate("If any edits, rationale contains 'clarified'")(
    byRationale.data.every(
      (e) => e.rationale && e.rationale.includes("clarified"),
    ),
  );

  // c. (Best effort) Filter by a date range narrowly containing an edit (if any edit returned)
  if (byEditorA.data.length > 0) {
    const firstEdit = byEditorA.data[0];
    const targetDate = firstEdit.edited_at;
    const byDateRange =
      await api.functional.discussionBoard.member.comments.commentEdits.search(
        connection,
        {
          commentId,
          body: {
            start: targetDate,
            end: targetDate,
            page: 1,
            limit: 5,
          },
        },
      );
    typia.assert(byDateRange);
    TestValidator.predicate("All edits fall within requested date range")(
      byDateRange.data.every(
        (e) => e.edited_at >= targetDate && e.edited_at <= targetDate,
      ),
    );
  }

  // 7. Validate order of returned results (descending by timestamp assumed)
  const allEdits =
    await api.functional.discussionBoard.member.comments.commentEdits.search(
      connection,
      {
        commentId,
        body: { page: 1, limit: 10 },
      },
    );
  typia.assert(allEdits);
  for (let i = 1; i < allEdits.data.length; ++i) {
    TestValidator.predicate("Edit events ordered by descending edited_at")(
      allEdits.data[i - 1].edited_at >= allEdits.data[i].edited_at,
    );
  }
}

