 * 5. Validate the returned audit record (edit event) for correct actor, targets,
 *    timestamp, and rationale
 *
 * **Purpose:** Prove that the system allows a member to edit their own comment
 * and logs the edit event correctly, preserving audit/version history with all
 * key fields (editor, rationale, time, and new content).
 *
 * Steps:
 *
 * - Register member and capture their UUID
 * - Create a post as that member
 * - Comment on the post
 * - Edit the comment (using the member's own ID as editor), providing a new body
 *   and rationale
 * - Assert the audit edit record contains correct actor, body, rationale, and
 *   event time
 */
export async function test_api_discussionBoard_test_create_comment_edit_event_by_original_author(
  connection: api.IConnection,
) {
