    editEvent.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("edit timestamp matches")(editEvent.edited_at)(editedAt);
  TestValidator.equals("new body correctly updated")(editEvent.new_body)(
    newBody,
  );
