import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator-issued suspension search filtering.
 *
 * This test validates that a moderator can filter suspension/ban records to
 * return ONLY those issued by the moderator (not those imposed by an admin)
 * using the PATCH /discussionBoard/moderator/suspensions API endpoint. This
 * supports audit and compliance checks where role-based granularity is
 * required.
 *
 * Steps:
 *
 * 1. Setup test actor UUIDs: one moderator, one admin, and a member to be
 *    suspended.
 * 2. Create a suspension imposed by the moderator (moderator_id set, admin_id
 *    null).
 * 3. Create a suspension imposed by the admin (admin_id set, moderator_id null)
 *    for the same subject.
 * 4. Search/filter for only moderator-issued suspensions using the moderator_id
 *    filter.
 * 5. Assert that only moderator-issued suspensions are returned in the result data
 *    array (all moderator_id match and all admin_id are null).
 * 6. Assert that the admin-imposed suspension does NOT appear in the filtered
 *    result.
 */
export async function test_api_discussionBoard_test_moderator_can_filter_suspensions_by_moderator_actions(
  connection: api.IConnection,
) {
  // 1. Setup test actor UUIDs
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const suspendedMemberId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a suspension by moderator
  const moderatorSuspension =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      {
        body: {
          suspended_admin_id: null,
          suspended_moderator_id: null,
          suspended_member_id: suspendedMemberId,
          suspended_guest_id: null,
          admin_id: null,
          moderator_id: moderatorId,
          related_report_id: null,
          related_action_id: null,
          suspended_at: new Date().toISOString(),
          ends_at: null,
          reason: "Moderator-imposed suspension for test.",
          status: "active",
        } satisfies IDiscussionBoardSuspension.ICreate,
      },
    );
  typia.assert(moderatorSuspension);

  // 3. Create a suspension by admin (for the same member)
  const adminSuspension =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      {
        body: {
          suspended_admin_id: null,
          suspended_moderator_id: null,
          suspended_member_id: suspendedMemberId,
          suspended_guest_id: null,
          admin_id: adminId,
          moderator_id: null,
          related_report_id: null,
          related_action_id: null,
          suspended_at: new Date(Date.now() + 1000).toISOString(),
          ends_at: null,
          reason: "Admin-imposed suspension for test.",
          status: "active",
        } satisfies IDiscussionBoardSuspension.ICreate,
      },
    );
  typia.assert(adminSuspension);

  // 4. Search: filter for only moderator-issued suspensions
  const result =
    await api.functional.discussionBoard.moderator.suspensions.search(
      connection,
      {
        body: {
          moderator_id: moderatorId,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardSuspension.IRequest,
      },
    );
  typia.assert(result);
  // 5. Check all results are only moderator-imposed suspensions
  for (const r of result.data) {
    TestValidator.equals("all results moderator_id match")(r.moderator_id)(
      moderatorId,
    );
    TestValidator.equals("no admin_id present")(r.admin_id)(null);
  }
  // 6. Ensure the admin-imposed suspension does not appear in the result
  const adminSuspFound = result.data.find((r) => r.id === adminSuspension.id);
  TestValidator.equals("admin-imposed suspension not in result")(
    adminSuspFound,
  )(undefined);
}

