/**
 * Validates the admin category update operation for a discussion board.
 *
 * Ensures that an admin can successfully update both the name and description
 * of a category. This includes creating a new category, updating its
 * information, and then retrieving it to confirm the changes have persisted and
 * audit fields are updated.
 *
 * Steps:
 *
 * 1. Create a new category via admin API and store its categoryId.
 * 2. Update this category's name to a new unique name and change the description.
 * 3. Confirm the update response reflects these values and updated_at timestamp
 *    has changed.
 * 4. Retrieve the category using GET and ensure the values have persisted exactly
 *    as updated.
 */
export async function test_api_discussionBoard_test_update_category_with_valid_information(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board category as admin
  const originalName = `${RandomGenerator.alphabets(8)}-cat`;
  const originalDescription = RandomGenerator.paragraph()();
  const created: IDiscussionBoardCategory =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: originalName,
        description: originalDescription,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(created);

  // 2. Prepare new unique name and updated description, then update the category
  const updatedName = `${RandomGenerator.alphabets(8)}-cat-upd`;
  const updatedDescription = RandomGenerator.content()()();
  const updated: IDiscussionBoardCategory =
    await api.functional.discussionBoard.admin.categories.update(connection, {
      categoryId: created.id,
      body: {
        name: updatedName,
        description: updatedDescription,
      } satisfies IDiscussionBoardCategory.IUpdate,
    });
  typia.assert(updated);
  // Ensure ID is unchanged
  TestValidator.equals("category id")(updated.id)(created.id);
  // Ensure name and description are updated
  TestValidator.equals("updated name")(updated.name)(updatedName);
  TestValidator.equals("updated description")(updated.description)(
    updatedDescription,
  );
  // Ensure updated_at has changed and is later than created_at
  TestValidator.predicate("updated_at has changed after creation")(
    new Date(updated.updated_at).getTime() >
      new Date(created.updated_at).getTime(),
  );

  // 3. Retrieve the category and confirm persistence of changes
  const reloaded: IDiscussionBoardCategory =
    await api.functional.discussionBoard.categories.at(connection, {
      categoryId: created.id,
    });
  typia.assert(reloaded);
  TestValidator.equals("reloaded name")(reloaded.name)(updatedName);
  TestValidator.equals("reloaded description")(reloaded.description)(
    updatedDescription,
  );
  TestValidator.equals("reloaded updated_at matches")(reloaded.updated_at)(
    updated.updated_at,
  );
}

