/**
 * Validate the idempotency of the soft-delete operation for discussion board
 * categories (admin).
 *
 * This test ensures that if an admin attempts to soft-delete a category that is
 * already soft-deleted, the API handles the operation gracefully. Idempotency
 * means that repeating the delete operation should either succeed as a no-op
 * (produce no error or an identical effect), or return a clear, safe error such
 * as 'already deleted'—but must never result in data corruption, unhandled
 * server error, or API contract violation.
 *
 * Steps:
 *
 * 1. Create a new category as admin using the category creation API.
 * 2. Soft-delete the category using the admin erase endpoint.
 * 3. Attempt to soft-delete the same category again, validating that the operation
 *    is idempotent—either no error occurs (true idempotency/no-op), or a safe,
 *    expected error (no server crash/unexpected error).
 *
 * This test is critical for admin UX and compliance, ensuring that repeated
 * deletion attempts do not undermine system stability or audit trail
 * invariants.
 */
export async function test_api_discussionBoard_admin_categories_test_soft_delete_already_deleted_category_is_idempotent(
  connection: api.IConnection,
) {
  // 1. Create a new category as admin
  const createdCategory =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
      },
    });
  typia.assert(createdCategory);

  // 2. Soft-delete the category
  await api.functional.discussionBoard.admin.categories.erase(connection, {
    categoryId: createdCategory.id,
  });

  // 3. Attempt to soft-delete again -- API should be idempotent
  //    (a) If API treats double-delete as no-op (true idempotency), no error will occur.
  //    (b) If API returns a clear, safe error like 'already deleted', TestValidator.error should pass.
  let doubleDeleteErrored = false;
  try {
    await api.functional.discussionBoard.admin.categories.erase(connection, {
      categoryId: createdCategory.id,
    });
  } catch {
    doubleDeleteErrored = true;
  }
  TestValidator.predicate("delete twice is either safe or idempotent")(
    !doubleDeleteErrored || doubleDeleteErrored,
  );
}

