import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the admin search functionality for including soft-deleted tags.
 *
 * This test verifies that an admin can retrieve both active and soft-deleted
 * tag records by using the `include_deleted` search filter. It covers the
 * following workflow:
 *
 * 1. Create multiple discussion board tags (at least two), each with a distinct
 *    label.
 * 2. Soft-delete one of the created tags (verify that the deleted_at timestamp is
 *    set).
 * 3. Search for tags with `include_deleted = true` and assert that both deleted
 *    and non-deleted tags are included in the results.
 * 4. Search with `include_deleted = false` (or omitted) and assert that only
 *    non-deleted tags appear in the results.
 * 5. Explicitly search for deleted tags using label match and `include_deleted =
 *    true`, and check that the soft-deleted tag is surfaced (and its deleted_at
 *    is non-null).
 *
 * This ensures proper functioning of tag admin inventory, and that the system
 * state of soft deletions is correctly reflected in search with appropriate
 * filters.
 */
export async function test_api_discussionBoard_admin_tags_test_admin_can_include_soft_deleted_tags_in_results(
  connection: api.IConnection,
) {
  // 1. Create two unique tags
  const labelA = RandomGenerator.alphabets(12);
  const tagA = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelA,
        description: RandomGenerator.paragraph()(),
        color: "#3399ff",
      },
    },
  );
  typia.assert(tagA);
  TestValidator.equals("tagA label round-trip")(tagA.label)(labelA);

  const labelB = RandomGenerator.alphabets(12);
  const tagB = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelB,
        description: RandomGenerator.paragraph()(),
        color: "#dd5522",
      },
    },
  );
  typia.assert(tagB);
  TestValidator.equals("tagB label round-trip")(tagB.label)(labelB);

  // 2. Soft-delete tagB
  await api.functional.discussionBoard.admin.tags.erase(connection, {
    tagId: tagB.id,
  });

  // 3. Search for tags with include_deleted = true (should include both tags)
  const searchWithDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: true,
        label: null,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchWithDeleted);

  const tagIds = searchWithDeleted.data.map((t) => t.id);
  TestValidator.predicate("contains both created and deleted tags")(
    tagIds.includes(tagA.id) && tagIds.includes(tagB.id),
  );

  // Verify deleted state in result for tagB
  const softDeletedTag = searchWithDeleted.data.find((t) => t.id === tagB.id);
  TestValidator.predicate("deleted_at is set for soft-deleted tag")(
    !!softDeletedTag?.deleted_at,
  );

  const activeTag = searchWithDeleted.data.find((t) => t.id === tagA.id);
  TestValidator.equals("active tag is not soft-deleted")(activeTag?.deleted_at)(
    null,
  );

  // 4. Search for tags with include_deleted = false (should only include non-deleted tag)
  const searchWithoutDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: false,
        label: null,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchWithoutDeleted);
  const nonDeletedIds = searchWithoutDeleted.data.map((t) => t.id);
  TestValidator.predicate("non-deleted tags only in result")(
    nonDeletedIds.includes(tagA.id) && !nonDeletedIds.includes(tagB.id),
  );

  // 5. Search by label for the soft-deleted tag and include_deleted: true
  const searchOnlyDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: true,
        label: tagB.label,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchOnlyDeleted);
  const foundTag = searchOnlyDeleted.data.find((t) => t.id === tagB.id);
  TestValidator.predicate("found deleted tag by label")(!!foundTag);
  TestValidator.predicate("deleted tag has deleted_at set")(
    !!foundTag?.deleted_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test pagination boundary conditions in the admin tag search API.
 *
 * This test ensures the /discussionBoard/admin/tags PATCH endpoint for tag
 * search correctly handles edge cases of pagination such as: single-item pages
 * (limit=1), requests for out-of-range pages, zero and negative page inputs,
 * and limits exceeding set size or set to zero. The test guarantees correct
 * structure, boundary, and empty result responses as per API contract.
 *
 * 1. Sets up the test by creating 3 discernible tags with unique labels (for easy
 *    validation)
 * 2. Tests limit=1 paging: fetches pages 1-3 (expect 1 tag each), then page 4
 *    (expect empty)
 * 3. Tests out-of-range and negative page numbers (page=0, page=-1), expects
 *    current defaults or empty data, and valid structure
 * 4. Tests over-large limit (limit=4 for 3 records), expects all data and correct
 *    page math
 * 5. Tests limit=0, expects error or empty data depending on contract
 * 6. Validates all response structure, pagination metadata, and tag label
 *    correctness
 */
export async function test_api_discussionBoard_admin_tags_test_search_tags_pagination_boundary_conditions(
  connection: api.IConnection,
) {
  // 1. Create 3 unique tags
  const baseLabel = `test-pagination-tag-${typia.random<number & tags.Type<"uint32">>()}`;
  const createdTags: IDiscussionBoardTag[] = [];
  for (let i = 0; i < 3; ++i) {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      {
        body: {
          label: `${baseLabel}-${i}`,
          description: `Test tag #${i} for pagination boundary case`,
          color: null,
        } satisfies IDiscussionBoardTag.ICreate,
      },
    );
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 2. Test limit=1, fetch pages 1-3 (single result), then page 4 (empty)
  for (let page = 1; page <= 4; ++page) {
    const res = await api.functional.discussionBoard.admin.tags.search(
      connection,
      {
        body: { page, limit: 1 } satisfies IDiscussionBoardTag.IRequest,
      },
    );
    typia.assert(res);
    TestValidator.equals(`limit=1 at page ${page}`)(res.pagination.limit)(1);
    TestValidator.equals(`records at page ${page}`)(res.pagination.records)(3);
    TestValidator.equals(`pages for limit=1 at page ${page}`)(
      res.pagination.pages,
    )(3);
    TestValidator.equals(`current page for limit=1`)(res.pagination.current)(
      Math.min(page, 3),
    );
    if (page <= 3) {
      TestValidator.equals(`result count page ${page}`)(res.data.length)(1);
      TestValidator.equals(`tag label ordering page ${page}`)(
        res.data[0].label,
      )(createdTags[page - 1].label);
    } else {
      TestValidator.equals(`overflow page empty data`)(res.data.length)(0);
    }
  }

  // 3. Test zero and negative page inputs
  for (const oddPage of [0, -1]) {
    const res = await api.functional.discussionBoard.admin.tags.search(
      connection,
      {
        body: {
          page: oddPage,
          limit: 1,
        } satisfies IDiscussionBoardTag.IRequest,
      },
    );
    typia.assert(res);
    TestValidator.equals(`records for page=${oddPage}`)(res.pagination.records)(
      3,
    );
    TestValidator.equals(`total pages for page=${oddPage}`)(
      res.pagination.pages,
    )(3);
    // Accepts varying implementation: either defaults to page 1 or simply returns 1 result or empty
    TestValidator.predicate(`valid current for page=${oddPage}`)(
      res.pagination.current === 1 || res.pagination.current === oddPage,
    );
    TestValidator.equals(`single or empty result for odd pages`)(
      res.data.length <= 1,
    )(true);
  }

  // 4. Test limit larger than total data (limit=4)
  const resLargeLimit = await api.functional.discussionBoard.admin.tags.search(
    connection,
    {
      body: { page: 1, limit: 4 } satisfies IDiscussionBoardTag.IRequest,
    },
  );
  typia.assert(resLargeLimit);
  TestValidator.equals("limit=4 (all tags)")(resLargeLimit.data.length)(3);
  TestValidator.equals("limit=4 records")(resLargeLimit.pagination.records)(3);
  TestValidator.equals("limit=4 pages")(resLargeLimit.pagination.pages)(1);
  TestValidator.equals("limit=4 current")(resLargeLimit.pagination.current)(1);

  // 5. Test limit=0 (API may throw error or return empty data per implementation)
  await TestValidator.error("limit=0 should not return data")(async () => {
    const res0 = await api.functional.discussionBoard.admin.tags.search(
      connection,
      {
        body: { page: 1, limit: 0 } satisfies IDiscussionBoardTag.IRequest,
      },
    );
    typia.assert(res0);
    TestValidator.equals("limit=0 returns nothing")(res0.data.length)(0);
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
