 * 1. Attempt a PATCH search using a non-integer for 'page' (e.g., 'one')
 * 2. Attempt a PATCH search using a negative number for 'limit' (e.g., -5)
 * 3. Use a malformatted date string for 'created_from' (e.g., 'not-a-date')
 * 4. Use an invalid type for label (e.g., array instead of string)
 * 5. Compose a request with multiple simultaneous invalid fields
 * 6. For each, verify an error is thrown and no tag data is returned
 */
export async function test_api_discussionBoard_test_search_moderator_tags_invalid_input_errors(
  connection: api.IConnection,
) {
  // 1. Non-integer value for 'page'
  await TestValidator.error("Non-integer 'page' value should fail")(
    async () => {
      await api.functional.discussionBoard.moderator.tags.search(connection, {
        body: {
          page: "one" as any, // forced invalid type, only for runtime E2E
