import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Validate admin updating a post edit event with new title, body, and
 * rationale.
 *
 * This test ensures that administrators can successfully update fields on an
 * existing post edit event, that the changes are visible in the returned
 * record, and that system audit-tracking and attribution are preserved.
 *
 * Steps:
 *
 * 1. Register a new member as post author.
 * 2. Create a new discussion post as that member.
 * 3. As admin, create an initial post edit event for that post.
 * 4. As admin, update the created post edit event, changing title, body, and
 *    rationale.
 * 5. Verify that the returned object reflects all updates and maintains the same
 *    edit, post, and member IDs.
 * 6. Check that audit fields (edit time, editor, rationale) are updated as
 *    expected.
 */
export async function test_api_discussionBoard_test_update_post_edit_event_with_valid_data_admin(
  connection: api.IConnection,
) {
  // 1. Register new member as post author
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 2. Create a new post as this member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
    // parent_id omitted for root post
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 3. Admin creates an initial post edit event
  const now = new Date().toISOString();
  const initialEditInput: IDiscussionBoardPostEdit.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: member.id,
    new_title: post.title + " (edited)",
    new_body: post.body + "\nEdit rationale: Initial typo fix.",
    edited_at: now,
    rationale: "Initial typo correction.",
  };
  const edit =
    await api.functional.discussionBoard.admin.posts.postEdits.create(
      connection,
      { postId: post.id, body: initialEditInput },
    );
  typia.assert(edit);

  // 4. Admin updates the post edit event
  const updatedEditInput: IDiscussionBoardPostEdit.IUpdate = {
    new_title: post.title + " (final edit)",
    new_body: post.body + "\nSecond audit: grammar fix.",
    rationale: "Additional grammar improvements and audit trail.",
  };
  const updatedEdit =
    await api.functional.discussionBoard.admin.posts.postEdits.update(
      connection,
      {
        postId: post.id,
        postEditId: edit.id,
        body: updatedEditInput,
      },
    );
  typia.assert(updatedEdit);

  // 5. Verify updates are reflected and IDs are unchanged
  TestValidator.equals("edit id unchanged")(updatedEdit.id)(edit.id);
  TestValidator.equals("post id unchanged")(
    updatedEdit.discussion_board_post_id,
  )(edit.discussion_board_post_id);
  TestValidator.equals("member id unchanged")(
    updatedEdit.discussion_board_member_id,
  )(edit.discussion_board_member_id);
  TestValidator.equals("new title updated")(updatedEdit.new_title)(
    updatedEditInput.new_title,
  );
  TestValidator.equals("new body updated")(updatedEdit.new_body)(
    updatedEditInput.new_body,
  );
  TestValidator.equals("rationale updated")(updatedEdit.rationale)(
    updatedEditInput.rationale,
  );

  // 6. Verify the audit timestamp is an ISO string and valid
  TestValidator.predicate("edited_at remains ISO date-time")(
    typeof updatedEdit.edited_at === "string" &&
      !isNaN(Date.parse(updatedEdit.edited_at)),
  );
}

