/**
 * Validate that moderators can retrieve the complete list of content moderation
 * reports.
 *
 * This test checks that after users file a content moderation/abuse report
 * (e.g., by reporting a post), a moderator can fetch all content reports in the
 * system with correct pagination and business fields.
 *
 * Steps:
 *
 * 1. Register two discussion board members (member1 and member2).
 * 2. Log in (implicitly, via API semantics) as member1 and create a post.
 * 3. Log in as member2 and file a content moderation report against member1's
 *    post.
 * 4. As a moderator, retrieve the list of all content moderation reports.
 * 5. Verify that the created report appears in the retrieved data, with correct
 *    metadata (target post ID, category, reason, reporter info, timestamps,
 *    etc.) and that pagination info is structurally valid.
 *
 * Edge cases:
 *
 * - Checks correct association of reporter and reported post.
 * - Verifies pagination fields are present and correctly structured even with a
 *   single report.
 * - Ensures only valid users can file reports and only moderators/admins can
 *   access contentReports.
 */
export async function test_api_discussionBoard_test_moderator_fetches_all_content_reports_successfully(
  connection: api.IConnection,
) {
  // 1. Register two members (member1 and member2)
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member2Email = typia.random<string & tags.Format<"email">>();

  const member1 = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: member1Email,
        password_hash: RandomGenerator.alphabets(30),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: member2Email,
        password_hash: RandomGenerator.alphabets(30),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member2);

  // 2. Log in as member1 and create a post
  // (Assume session context is managed automatically on create)
  // Switch to member1 'identity' for post creation
  // (in real system, e2e would swap tokens; here, use registration order)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Log in as member2 and file a report on the created post
  // (Switch context to member2; session handling is implied)
  const reportCategory = "offensive";
  const reportReason = RandomGenerator.paragraph()(1);
  const report =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: post.id,
          discussion_board_comment_id: null,
          content_type: "post",
          category: reportCategory,
          reason: reportReason,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(report);

  // 4. As a moderator, retrieve all content reports
  // (Assume moderator privilege in test env)
  const response =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
    );
  typia.assert(response);

  // 5. Verify the report we filed appears in the retrieved data
  //    and that pagination is correct
  // Find a report with the same reason and post ID (uniqueness is guaranteed for this test)
  const foundReport = response.data.find(
    (r) => r.reason === reportReason && r.discussion_board_post_id === post.id,
  );
  TestValidator.predicate("reported post is in moderator report list")(
    !!foundReport,
  );
  if (!foundReport)
    throw new Error("Filed report not found in moderator contentReports list");
  // Validate metadata
  TestValidator.equals("report links post ID")(
    foundReport.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("report has correct type")(foundReport.content_type)(
    "post",
  );
  TestValidator.equals("report has correct category")(foundReport.category)(
    reportCategory,
  );
  TestValidator.equals("report has correct reason")(foundReport.reason)(
    reportReason,
  );
  // Pagination fields should exist and be valid
  const pagination = response.pagination;
  TestValidator.predicate("pagination.current >= 1")(pagination.current >= 1);
  TestValidator.equals("pagination.limit is positive")(pagination.limit > 0)(
    true,
  );
  TestValidator.equals("pagination.pages is positive")(pagination.pages > 0)(
    true,
  );
  TestValidator.equals("pagination.records >= 1")(pagination.records >= 1)(
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
