/**
 * Validate that newly submitted member abuse/moderation reports appear in the
 * full admin content report list.
 *
 * This E2E test simulates the workflow from member registration, post creation,
 * filing an abuse report by the member, and then ensures the admin report
 * dashboard reflects the submitted report with correct status and fields for
 * audit/compliance.
 *
 * Steps:
 *
 * 1. Register a new discussion board member
 * 2. Create a new post as the member
 * 3. File an abuse/moderation report against that post as the member
 * 4. As admin, retrieve all content reports using the admin endpoint
 * 5. Assert the new report appears in the admin's report list, fields match
 *    expected IDs and status
 */
export async function test_api_discussionBoard_test_admin_reports_list_reflects_new_abuse_reports(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 2. Create a new post as the member
  const postInput = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 3. File an abuse/moderation report against that post
  const reportInput = {
    discussion_board_post_id: post.id,
    discussion_board_comment_id: null,
    content_type: "post",
    category: "spam",
    reason: RandomGenerator.paragraph()(1),
  } satisfies IDiscussionBoardContentReport.ICreate;
  const report =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      { body: reportInput },
    );
  typia.assert(report);

  // 4. As admin, retrieve all content reports
  const adminReportsPage =
    await api.functional.discussionBoard.admin.contentReports.index(connection);
  typia.assert(adminReportsPage);
  TestValidator.predicate("at least one report exists")(
    adminReportsPage.data.length > 0,
  );

  // 5. Assert the new report appears in the admin's report list, fields match expectations
  const found = adminReportsPage.data.find((item) => item.id === report.id);
  TestValidator.predicate("newly created report is listed in admin reports")(
    !!found,
  );
  if (!found)
    throw new Error(
      "Newly created report does not appear in admin content reports list",
    );
  TestValidator.equals("discussion_board_post_id matches")(
    found.discussion_board_post_id,
  )(reportInput.discussion_board_post_id);
  TestValidator.equals("reporter_member_id matches")(found.reporter_member_id)(
    member.id,
  );
  TestValidator.equals("content_type matches")(found.content_type)(
    reportInput.content_type,
  );
  TestValidator.equals("category matches")(found.category)(
    reportInput.category,
  );
  TestValidator.equals("reason matches")(found.reason)(reportInput.reason);
  TestValidator.equals("status is pending or under_review")(
    ["pending", "under_review"].includes(found.status),
  )(true);
  TestValidator.equals("discussion_board_comment_id is null")(
    found.discussion_board_comment_id,
  )(null);
}

