/**
 * Validate the successful update process of a discussion board settings record.
 *
 * This test simulates an admin performing typical board maintenance
 * tasks—changing properties such as title (for brand refresh), description (for
 * revised guidelines), logo URI (for new branding), and the enabled/disabled
 * flag (to toggle board availability). Ensures that PUT works, changes are
 * reflected, and audit timestamps are updated.
 *
 * Steps:
 *
 * 1. Create a board settings record to obtain a valid unique ID (dependency
 *    setup).
 * 2. Prepare new values for updatable fields (new title, description, logo_uri,
 *    new enabled status, potentially using null for nullable properties).
 * 3. Call the update endpoint with that ID and new data.
 * 4. Assert all returned properties (title, description, logo_uri, enabled) match
 *    the intended updates, with other properties (id, created_at) unchanged.
 * 5. Assert that the updated_at field differs from the original (i.e., was
 *    refreshed by the successful update).
 */
export async function test_api_discussionBoard_admin_boardSettings_test_update_board_setting_success(
  connection: api.IConnection,
) {
  // 1. Create an initial board settings record (dependency)
  const initialSetting =
    await api.functional.discussionBoard.admin.boardSettings.create(
      connection,
      {
        body: {
          title: "Test Board",
          enabled: true,
          description: "Original board description.",
          logo_uri: "https://cdn.example.com/original-logo.png",
        } satisfies IDiscussionBoardBoardSetting.ICreate,
      },
    );
  typia.assert(initialSetting);

  // 2. Prepare new values for update
  const newTitle = "Updated Board " + RandomGenerator.alphaNumeric(8);
  const newDescription = "Updated description for compliance refresh.";
  const newLogo = "https://cdn.example.com/updated-logo.png";
  const newEnabled = false;

  // 3. Perform the update call
  const updatedSetting =
    await api.functional.discussionBoard.admin.boardSettings.update(
      connection,
      {
        boardSettingId: initialSetting.id,
        body: {
          title: newTitle,
          description: newDescription,
          logo_uri: newLogo,
          enabled: newEnabled,
        } satisfies IDiscussionBoardBoardSetting.IUpdate,
      },
    );
  typia.assert(updatedSetting);

  // 4. Assert returned values: updated vs original
  TestValidator.equals("id unchanged")(updatedSetting.id)(initialSetting.id);
  TestValidator.equals("title updated")(updatedSetting.title)(newTitle);
  TestValidator.equals("enabled updated")(updatedSetting.enabled)(newEnabled);
  TestValidator.equals("description updated")(updatedSetting.description)(
    newDescription,
  );
  TestValidator.equals("logo_uri updated")(updatedSetting.logo_uri)(newLogo);
  TestValidator.equals("created_at unchanged")(updatedSetting.created_at)(
    initialSetting.created_at,
  );
  // 5. updated_at must be different (refreshed timestamp)
  TestValidator.notEquals("updated_at refreshed")(updatedSetting.updated_at)(
    initialSetting.updated_at,
  );
}

