/**
 * Validate moderator or admin updating a member suspension to 'expired'.
 *
 * Simulates a real moderation workflow:
 *
 * 1. Admin creates a suspension/ban for a member.
 * 2. Moderator updates the suspension's status to 'expired' (for an appeal or time
 *    lapse).
 * 3. Verifies the update succeeded and audit/compliance fields remain correct.
 * 4. Checks correct error handling for:
 *
 *    - Invalid status value
 *    - Update attempt of non-existent suspension ID
 *
 * Only API endpoints and DTO fields explicitly provided are used. Only runtime
 * business errors for invalid payloads/IDs are tested (no TS type errors).
 *
 * Steps:
 *
 * 1. Create a valid suspension as admin.
 * 2. Update its status to 'expired' as moderator.
 * 3. Assert status is updated, audit/actor references persist, and mutable fields
 *    behave.
 * 4. Negative: Updating with business-invalid status returns error.
 * 5. Negative: Updating with non-existent UUID returns error.
 */
export async function test_api_discussionBoard_moderator_suspensions_test_update_suspension_status_to_expired_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create a suspension record as admin (prerequisite)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const suspensionCreate: IDiscussionBoardSuspension.ICreate = {
    suspended_admin_id: null,
    suspended_moderator_id: null,
    suspended_member_id: memberId,
    suspended_guest_id: null,
    admin_id: adminId,
    moderator_id: null,
    related_report_id: null,
    related_action_id: null,
    suspended_at: new Date().toISOString(),
    ends_at: new Date(Date.now() + 3600_000).toISOString(),
    reason: "Serious violation of rules.",
    status: "active",
  };
  const created = await api.functional.discussionBoard.admin.suspensions.create(
    connection,
    { body: suspensionCreate },
  );
  typia.assert(created);

  // 2. Update suspension status to 'expired'
  const updateBody: IDiscussionBoardSuspension.IUpdate = {
    status: "expired",
    reason: "Ban ended after appeal.",
    ends_at: new Date().toISOString(),
  };
  const updated =
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: updateBody,
      },
    );
  typia.assert(updated);

  // 3. Audit & compliance field assertions
  TestValidator.equals("suspension id")(updated.id)(created.id);
  TestValidator.equals("member target")(updated.suspended_member_id)(memberId);
  TestValidator.equals("admin reference")(updated.admin_id)(adminId);
  TestValidator.equals("status is expired")(updated.status)("expired");
  TestValidator.equals("reason updated")(updated.reason)(
    "Ban ended after appeal.",
  );
  TestValidator.equals("ends_at updated")(typeof updated.ends_at === "string")(
    true,
  );

  // 4. Error: invalid status value (business rule, not TS error)
  await TestValidator.error("invalid status should fail")(async () => {
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: {
          status: "not_a_valid_status" as any,
        },
      },
    );
  });

  // 5. Error: update non-existent suspension
  await TestValidator.error("non-existent suspension id fails")(async () => {
    await api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: typia.random<string & tags.Format<"uuid">>(),
        body: { status: "expired" },
      },
    );
  });
}

