/**
 * Validate moderator update of suspension: forbid immutable/invalid fields
 *
 * This test ensures that attempts by moderators to update a suspension record
 * with fields not permitted by the mutation schema (such as immutable audit
 * fields, primary keys, or creation timestamps) or with invalid
 * (non-schema-compliant) values result in proper rejection: the request must be
 * rejected with a validation error, no system or audit fields are modified, and
 * the underlying data remains unchanged.
 *
 * Steps:
 *
 * 1. Precondition: Create a valid suspension record as admin (dependency).
 * 2. As moderator, attempt to update this suspension record but include:
 *
 *    - Forbidden/immutable fields in the body (e.g., id or suspended_at), which are
 *         not part of the allowed IUpdate body.
 *    - Invalid enum value for 'status', or date in wrong format for ends_at.
 * 3. Confirm that each update attempt is rejected (validation error).
 * 4. Confirm that permitted fields remain unaltered after failed updates.
 *
 * Note: Direct re-validation of the record after failed updates is not possible
 * here (there is no get-by-id endpoint for suspensions), so the test focuses on
 * error validation only.
 */
export async function test_api_discussionBoard_test_update_suspension_with_invalid_fields_as_moderator(
  connection: api.IConnection,
) {
  // 1. Precondition: create valid suspension via admin endpoint
  const created = await api.functional.discussionBoard.admin.suspensions.create(
    connection,
    {
      body: {
        suspended_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        suspended_admin_id: null,
        suspended_member_id: null,
        suspended_guest_id: null,
        admin_id: null,
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        related_action_id: null,
        related_report_id: null,
        suspended_at: new Date().toISOString(),
        ends_at: null,
        reason: "Test for invalid field update",
        status: "active",
      } satisfies IDiscussionBoardSuspension.ICreate,
    },
  );
  typia.assert(created);

  // 2a. Attempt forbidden field - supply id as body (should fail)
  await TestValidator.error("Attempting to update immutable id fails")(() => {
    return api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: {
          ...({ id: typia.random<string & tags.Format<"uuid">>() } as any),
          status: "expired",
        } as any,
      },
    );
  });

  // 2b. Attempt forbidden field - supply suspended_at (should fail)
  await TestValidator.error(
    "Attempting to update immutable suspended_at fails",
  )(() => {
    return api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: {
          ...({ suspended_at: new Date().toISOString() } as any),
          status: "expired",
        } as any,
      },
    );
  });

  // 2c. Attempt invalid enum - status (should fail)
  await TestValidator.error("Updating with invalid status enum fails")(() => {
    return api.functional.discussionBoard.moderator.suspensions.update(
      connection,
      {
        suspensionId: created.id,
        body: {
          status: "pending" as any, // invalid status not in allowed enum!
        } as any,
      },
    );
  });

  // 2d. Attempt wrong format date for ends_at (should fail)
  await TestValidator.error("Updating with wrongly formatted ends_at fails")(
    () => {
      return api.functional.discussionBoard.moderator.suspensions.update(
        connection,
        {
          suspensionId: created.id,
          body: {
            ends_at: "not-a-date" as any,
            status: "revoked",
          } as any,
        },
      );
    },
  );

  // 3. Note: Direct re-check to confirm record immutability is not possible as there is no get-by-id for suspensions.
}

