  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(20),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Member creates a new post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Admin creates two categories (A and B)
  const categoryA =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryA);
  const categoryB =
    await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.alphabets(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryB);

  // 4. Member assigns only category A to the post
  const assignment =
    await api.functional.discussionBoard.member.posts.postCategories.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_category_id: categoryA.id,
        } satisfies IDiscussionBoardPostCategory.ICreate,
      },
    );
  typia.assert(assignment);

  // 5. Search for category assignments filtered by unassigned category B
  const searchResult =
    await api.functional.discussionBoard.member.posts.postCategories.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_category_id: categoryB.id,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardPostCategory.IRequest,
      },
    );
  typia.assert(searchResult);

  // 6. Validate that the result set is empty
  TestValidator.equals("no category assignments for unassigned category")(
    searchResult.data,
  )([]);
}

