 * because authentication/authorization is required for admin notification APIs.
 * We create an admin user as a dependency and then attempt a search for
 * notifications using a deliberately invalid filter.
 *
 * The invalidity can be in the filter's `category` (e.g., a value that is not
 * recognized by business logic) or in malformed dates. Because the DTO
 * definition for `category` accepts any string or null, API-side validation is
 * responsible for rejecting unknown categories (beyond expected ones, e.g.,
 * 'vote', 'moderation_event', etc.). For malformed dates, the property accepts
 * only RFC3339 date-time strings or null, so sending a non-date string (e.g.,
 * 'not-a-date') should trigger a format validation error, which should be
 * surfaced as a validation failure in the response.
 *
 * The test will:
 *
 * 1. Create an admin user using the admin creation API (dependency).
 * 2. Attempt to search notifications with an unrecognized category string and
 *    expect a validation or business-rule error.
 * 3. Attempt to search notifications with a malformed date for the
 *    `created_at_from` property and expect a validation error.
 * 4. Assert that an error is thrown in both cases (do not check error message
 *    details per guidance).
 */
export async function test_api_discussionBoard_test_search_admin_notifications_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Create an admin user (dependency for authentication)
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(10),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2. Search notifications with an unsupported 'category' value
  await TestValidator.error(
    "invalid notification category triggers validation or business error",
  )(() =>
    api.functional.discussionBoard.admin.notifications.search(connection, {
      body: {
        category: "completely_invalid_category",
      } satisfies IDiscussionBoardNotification.IRequest,
    }),
  );

  // 3. Search notifications with a malformed 'created_at_from' property
  await TestValidator.error("malformed date string triggers validation error")(
    () =>
      api.functional.discussionBoard.admin.notifications.search(connection, {
        body: {
          created_at_from: "not-a-date" as any, // purposely providing an invalid date-time string
        } satisfies IDiscussionBoardNotification.IRequest,
      }),
  );
}

