 *    the auth model).
 * 3. Search notifications with a specific category filter (using PATCH).
 * 4. Confirm all returned notifications (if any) have category equal to the filter
 *    value, and check pagination.
 * 5. Optionally, repeat for an alternate category (potentially empty results) to
 *    validate the filter logic further.
 */
export async function test_api_discussionBoard_moderator_notifications_test_search_moderator_notifications_category_filter(
  connection: api.IConnection,
) {
  // 1. Create a moderator account via admin endpoint
  const moderatorInput: IDiscussionBoardModerator.ICreate = {
