import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test that validates member notification search with type filter and
 * pagination.
 *
 * Business context:
 *
 * - Discussion board members receive system/user notifications (e.g., replies,
 *   votes).
 * - Members may have a large set of notifications, so search/filter/pagination is
 *   critical for UI usability.
 *
 * Test workflow:
 *
 * 1. Create a new discussion board member account.
 * 2. (No public API to populate notifications, so we proceed directly to search.)
 * 3. Search notifications for the member, filtering by notification "type" (e.g.,
 *    "reply") with limit (page size) and page parameters.
 * 4. Assert pagination metadata and that each notification in the result matches
 *    the requested type.
 * 5. Repeat search for another notification type (e.g., "vote") with different
 *    page and limit.
 *
 * Notes:
 *
 * - No current API allows us to create test notifications; thus, we test the
 *   endpoint for type safety/pagination/filter correctness, even if zero
 *   notifications exist.
 * - The test asserts filtering, pagination, and type match logic on results (if
 *   present), exercising the intended business logic.\n
 */
export async function test_api_discussionBoard_member_notifications_test_search_member_notifications_by_type_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // --- No public API exists to create notification test data ---
  // Proceed to search for notifications anyway (type/pagination logic)

  // 2. Search by type (e.g., "reply") & pagination: limit = 10, page = 1
  const requestReply: IDiscussionBoardNotification.IRequest = {
    type: "reply",
    limit: 10,
    page: 1,
  };
  const responseReply =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      { body: requestReply },
    );
  typia.assert(responseReply);
  TestValidator.equals("pagination limit matches")(
    responseReply.pagination.limit,
  )(10);
  TestValidator.equals("pagination page matches")(
    responseReply.pagination.current,
  )(1);
  for (const n of responseReply.data) {
    TestValidator.equals("notification type matches")(n.type)("reply");
  }

  // 3. Search for type "vote", page = 2, limit = 5
  const requestVote: IDiscussionBoardNotification.IRequest = {
    type: "vote",
    limit: 5,
    page: 2,
  };
  const responseVote =
    await api.functional.discussionBoard.member.notifications.search(
      connection,
      { body: requestVote },
    );
  typia.assert(responseVote);
  TestValidator.equals("pagination limit matches")(
    responseVote.pagination.limit,
  )(5);
  TestValidator.equals("pagination page matches")(
    responseVote.pagination.current,
  )(2);
  for (const n of responseVote.data) {
    TestValidator.equals("notification type matches")(n.type)("vote");
  }
}
